INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gmh5225/awesome-web3-security/mev-security', 'community', 'gmh5225', 'awesome-web3-security', 'gmh5225/awesome-web3-security', 'mev-security', 11, 0, 36, '2026-02-23T11:34:21Z', '2026-03-06T06:46:05.514Z', '64f7b302d3f1de77273cd3db536f120a8c996566658f294c39d9bfc6daeef672', '{"id":"gmh5225/awesome-web3-security/mev-security","name":"mev-security","description":{"en":"The mev-security skill provides a curated list of Web3 Security materials and resources for Pentesters and Bug Hunters, covering MEV concepts, threat models, and mitigation techniques","zh":"MEV 安全是 Web3 交易安全的重要组成部分，涉及交易排序、沙子攻击和私有订单流等概念","ja":"MEV セキュリティは Web3 取引の安全性の重要な構成要素であり、トランザクションの順序付け、サンドイッチ攻撃、プライベートオーダーフローなどの概念を包含する","ko":"MEV 보안은 Web3 거래 보안의 중요한 구성 요소로, 거래 순서, 샌드위치 공격, 개인 주문 흐름 등을 포함합니다","es":"La seguridad MEV es crucial para proteger tus transacciones de ataques de frontrunning y otros riesgos. Nuestra guía te ayudará a entender los conceptos de MEV y a implementar mitigaciones efectivas","fr":"La sécurité MEV est cruciale pour protéger vos transactions contre les attaques de frontrunning et d''autres risques. Notre guide vous aidera à comprendre les concepts de MEV et à mettre en œuvre des atténuations efficaces","de":"Die MEV-Sicherheit ist entscheidend, um Ihre Transaktionen vor Frontrunning-Angriffen und anderen Risiken zu schützen. Unser Leitfaden hilft Ihnen, die MEV-Konzepte zu verstehen und wirksame Minderungsstrategien umzusetzen","pt":"A segurança MEV é um conjunto de recursos e materiais para proteger aplicações Web3 contra ataques de frontrunning e backrunning","ru":"Безопасность MEV - это набор ресурсов и материалов для защиты веб-приложений 3.0 от атак frontrunning и backrunning","ar":"مев-سيكيوريتي هي مجموعة من الموارد والأدوات لحماية تطبيقات الويب 3 من الهجمات"},"seo":{"title":{"en":"mev-security: Mastering Web3 Security for Pentesters | AI...","zh":"MEV 安全配置指南 - Web3 交易安全","ja":"MEV セキュリティの設定方法 - Web3 取引の安全性","ko":"MEV 보안 설정 가이드 - Web3 거래 보안","es":"Guía de Seguridad MEV: Protección contra ataques de front...","fr":"Guide de sécurité MEV : Protéger contre les attaques de f...","de":"MEV-Sicherheitsleitfaden: Schutz vor Frontrunning-Angriffen","pt":"Guia de Configuração de Segurança MEV para Desenvolvedores","ru":"Руководство по настройке безопасности MEV для разработчик...","ar":"دليل إعداد mev-security لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock expert Web3 security knowledge with mev-security. Discover mitigation strategies and best practices for transaction ordering and block building","zh":"了解 MEV 安全威胁和缓解策略，保护 Web3 交易安全","ja":"MEV セキュリティの脅威と緩和策略について学び、Web3 取引の安全性を確保する","ko":"MEV 보안 위협과 완화 전략을 학습하고 Web3 거래 보안을 강화하세요","es":"Aprende a proteger tus transacciones con nuestra guía de seguridad MEV, que cubre conceptos de MEV, patrones de ataque y mitigaciones","fr":"Apprenez à protéger vos transactions avec notre guide de sécurité MEV, qui couvre les concepts de MEV, les modèles d''attaque et les atténuations","de":"Erfahren Sie, wie Sie Ihre Transaktionen mit unserem MEV-Sicherheitsleitfaden schützen können, der MEV-Konzepte, Angriffsmuster und Minderungsstrategien abdeckt","pt":"Aprenda a proteger suas aplicações Web3 com recursos e materiais de segurança MEV, incluindo padrões de ataque e mitigação","ru":"Защитите свои веб-приложения 3.0 с помощью ресурсов и материалов безопасности MEV, включая модели угроз и смягчения","ar":"تعلم حماية تطبيقات الويب 3 مع موارد وأدوات mev-security، بما في ذلك أنماط الهجوم والتحكم"},"definition":{"en":"mev-security is a collection of Web3 Security resources and materials focused on MEV concepts, threat models, and mitigation strategies for secure transaction ordering and block building","zh":"MEV 安全是指保护 Web3 交易免受 MEV 攻击的安全措施","ja":"MEV セキュリティとは、Web3 取引を MEV 攻撃から守るための安全対策のこと","ko":"MEV 보안은 Web3 거래를 MEV 공격으로부터 보호하는 보안 조치입니다","es":"La seguridad MEV se refiere a la protección de transacciones contra ataques de frontrunning y otros riesgos en la red Web3","fr":"La sécurité MEV fait référence à la protection des transactions contre les attaques de frontrunning et d''autres risques sur le réseau Web3","de":"Die MEV-Sicherheit bezieht sich auf den Schutz von Transaktionen vor Frontrunning-Angriffen und anderen Risiken im Web3-Netzwerk","pt":"MEV é a sigla para Maximal Extractable Value, um conceito de segurança para proteger transações em blockchains","ru":"MEV означает Maximal Extractable Value, концепция безопасности для защиты транзакций в блокчейнах","ar":"ميف هو اختصار لقيمة الاستخراج القصوى، مفهوم أمان لحماية المعاملات في سلاسل الكتل"},"features":{"en":["Analyzes sandwich attacks and frontrunning/backrunning patterns","Provides mitigation strategies using private transaction relays and MEV blockers","Supports commit-reveal patterns for secure transaction ordering","Offers slippage protection and simulation for optimized block building","Covers arbitrage and liquidation extraction techniques","Explains private order flow and private mempool concepts"],"zh":["交易排序和区块构建","沙子攻击和私有订单流","私有交易中继和 RPC 端点","MEV 阻塞器和提交-揭示模式","滑点保护和模拟"],"ja":["トランザクションの順序付けとブロック構築","サンドイッチ攻撃とプライベートオーダーフロー","プライベートトランザクションリレーと RPC エンドポイント","MEV ブロッカーとコミット-リヴェールパターン","スリッページ保護とシミュレーション"],"ko":["거래 순서와 블록 구축","샌드위치 공격과 개인 주문 흐름","개인 거래 중계와 RPC 엔드포인트","MEV 차단기와 커밋-공개 패턴","슬리피지 보호와 시뮬레이션"],"es":["Conoce los conceptos de MEV y los patrones de ataque de frontrunning","Aprende a implementar mitigaciones efectivas como relés de transacciones privadas y puntos finales de RPC","Entiende cómo funcionan los bloques de transacciones y el orden de las transacciones","Descubre cómo proteger tus transacciones con patrones de compromiso y revelación","Aprende a simular y proteger contra la pérdida de slippage"],"fr":["Comprenez les concepts de MEV et les modèles d''attaque de frontrunning","Apprenez à mettre en œuvre des atténuations efficaces telles que des relais de transactions privées et des points de terminaison RPC","Comprenez comment fonctionnent les blocs de transactions et l''ordre des transactions","Découvrez comment protéger vos transactions avec des modèles de compromis et de révélation","Apprenez à simuler et à protéger contre la perte de slippage"],"de":["Erfahren Sie mehr über die MEV-Konzepte und die Angriffsmuster von Frontrunning","Lernen Sie, wie Sie wirksame Minderungsstrategien wie private Transaktionsrelais und RPC-Endpunkte umsetzen","Verstehen Sie, wie Transaktionsblöcke und die Transaktionsreihenfolge funktionieren","Erfahren Sie, wie Sie Ihre Transaktionen mit Commit-Reveal-Mustern schützen","Lernen Sie, wie Sie Slippage-Verluste simulieren und schützen"],"pt":["Mitigações de ataques de frontrunning e backrunning","Recursos de segurança para transações privadas","Padrões de ataque e mitigação para pentesters e bug hunters","Integração com relés de transações privadas e pontos de extremidade RPC","Proteção contra perdas e simulação de slippage"],"ru":["Смягчение атак frontrunning и backrunning","Ресурсы безопасности для частных транзакций","Модели атак и смягчения для pentesters и bug hunters","Интеграция с частными транзакционными релеями и RPC-конечными точками","Защита от потерь и симуляция слиппажа"],"ar":["التحكم في هجمات الهجوم الأمامي والخلفي","موارд أمان للمعاملات الخاصة","أنماط الهجوم والتحكم لpentesters وbug hunters","التكامل مع عدادات المعاملات الخاصة ونقاط النهاية RPC","حماية الفقدان وتحاكي الانزلاق"]},"keywords":{"en":["how to use mev-security","mev-security setup guide","web3 security best practices","mev-security alternative","mev-security vs web3 security tools","what is mev-security","mev-security install","mastering mev-security for pentesters","mev-security for bug hunters","web3 security mitigation strategies"],"zh":["MEV 安全","Web3 交易安全","交易排序","沙子攻击","私有订单流","MEV 阻塞器","提交-揭示模式","滑点保护","AIエージェント"],"ja":["MEV セキュリティ","Web3 取引の安全性","トランザクションの順序付け","サンドイッチ攻撃","プライベートオーダーフロー","MEV ブロッカー","コミット-リヴェールパターン","スリッページ保護","AIエージェント"],"ko":["MEV 보안","Web3 거래 보안","거래 순서","샌드위치 공격","개인 주문 흐름","MEV 차단기","커밋-공개 패턴","슬리피지 보호","AI 에이전트"],"es":["seguridad MEV","ataques de frontrunning","transacciones privadas","relés de transacciones","puntos finales de RPC","patrones de compromiso y revelación","simulación de slippage"],"fr":["sécurité MEV","attaques de frontrunning","transactions privées","relais de transactions","points de terminaison RPC","modèles de compromis et de révélation","simulation de slippage"],"de":["MEV-Sicherheit","Frontrunning-Angriffe","private Transaktionen","Transaktionsrelais","RPC-Endpunkte","Commit-Reveal-Muster","Slippage-Simulation"],"pt":["segurança mev","web3 security","ataques de frontrunning","mitigação de ataques","transações privadas","pentesters","bug hunters","relés de transações privadas","pontos de extremidade RPC"],"ru":["безопасность mev","веб 3.0 безопасность","атаки frontrunning","смягчение атак","частные транзакции","pentesters","bug hunters","частные транзакционные релеи","RPC-конечные точки"],"ar":["ميف-سيكيوريتي","أمان الويب 3","هجمات الهجوم الأمامي","التحكم في الهجمات","المعاملات الخاصة","pentesters","bug hunters","عدادات المعاملات الخاصة","نقاط النهاية RPC"]}},"owner":"gmh5225","repo":"awesome-web3-security","repoPath":"gmh5225/awesome-web3-security","stars":11,"forks":0,"updatedAt":"2026-02-23T11:34:21Z","topics":["security","web3"],"category":"community","skillMd":{"name":"mev-security","description":"Guide for MEV concepts, common attacks, mitigations, and how to organize MEV-related resources in README.md.","bodyPreview":"# MEV Security\n\n## Scope\n\nUse this skill for:\n\n- MEV concepts and threat models\n- Sandwich/frontrunning/backrunning patterns\n- Mitigations and private transaction relays\n\n## Concepts (Quick List)\n\n- Transaction ordering and block building\n- Sandwich attacks\n- Arbitrage and liquidation extraction\n- Private order flow / private mempool\n\n## Mitigations\n\n- Private transaction relays / RPC endpoints\n- MEV blockers\n- Commit-reveal patterns (where applicable)\n- Slippage protection and simulation\n\n## Wh","body":"# MEV Security\n\n## Scope\n\nUse this skill for:\n\n- MEV concepts and threat models\n- Sandwich/frontrunning/backrunning patterns\n- Mitigations and private transaction relays\n\n## Concepts (Quick List)\n\n- Transaction ordering and block building\n- Sandwich attacks\n- Arbitrage and liquidation extraction\n- Private order flow / private mempool\n\n## Mitigations\n\n- Private transaction relays / RPC endpoints\n- MEV blockers\n- Commit-reveal patterns (where applicable)\n- Slippage protection and simulation\n\n## Where to Add Links in README\n\n- MEV concept resources: `DeFi Topics → MEV`\n- MEV defense tooling (RPC/relays): `DeFi Topics → MEV` (primary), optionally `Development → Tools` only if the link is a general-purpose dev tool\n\n## Rules\n\n- English descriptions\n- No duplicates\n\n## Data Source\n\nFor detailed and up-to-date resources, fetch the full list from:\n```\nhttps://raw.githubusercontent.com/gmh5225/awesome-web3-security/refs/heads/main/README.md\n```\n\n"},"lastSynced":"2026-03-06T06:46:05.514Z","agentAnalysis":{"suitability":{"en":"Perfect for Web3 Agents specializing in blockchain security and needing in-depth knowledge of MEV concepts and mitigation techniques.","zh":"非常适合专门从事区块链安全并需要深入了解 MEV 概念和缓解技术的 Web3 Agent。","ja":"ブロックチェーンセキュリティを専門とし、MEVの概念と緩和技術に関する深い知識を必要とするWeb3 Agentに最適です。","ko":"블록체인 보안을 전문으로 하며 MEV 개념과 완화 기술에 대한 심층적인 지식이 필요한 Web3 에이전트에 완벽합니다.","es":"Perfecto para Agentes Web3 especializados en seguridad de blockchain y que necesitan conocimientos en profundidad sobre conceptos de MEV y técnicas de mitigación.","fr":"Parfait pour les Agents Web3 spécialisés dans la sécurité de la blockchain et ayant besoin de connaissances approfondies sur les concepts de MEV et les techniques de mitigation.","de":"Perfekt für Web3-Agents, die auf die Sicherheit von Blockchain spezialisiert sind und umfassende Kenntnisse über MEV-Konzepte und Minderungstechniken benötigen.","pt":"Perfeito para Agentes Web3 especializados em segurança de blockchain e que necessitam de conhecimento aprofundado de conceitos MEV e técnicas de mitigação.","ru":"Идеально подходит для агентов Web3, специализирующихся на безопасности блокчейна и требующих глубоких знаний концепций MEV и методов смягчения.","ar":"مثالي لعميل الويب 3 المتخصصين في أمان البلوكشين والذين يحتاجون إلى معرفة متعمقة بمفاهيم MEV وأساليب التخفيف."},"recommendation":{"en":"Empowers agents to analyze and mitigate MEV-based threats, including sandwich attacks and frontrunning, using private transaction relays, MEV blockers, and commit-reveal patterns, while also providing expertise in transaction ordering and block building.","zh":"使 Agent 能够使用私有交易中继、MEV 拦截器和提交-揭示模式来分析和缓解基于 MEV 的威胁，包括三明治攻击和抢先交易，同时还提供交易排序和区块构建方面的专业知识。","ja":"プライベートトランザクションリレー、MEVブロッカー、コミット・リビールパターンを使用して、サンドイッチ攻撃やフロントランニングを含むMEVベースの脅威を分析および緩和する能力をAgentに付与し、さらにトランザクション順序付けとブロック構築に関する専門知識を提供します。","ko":"비공개 트랜잭션 릴레이, MEV 차단기 및 커밋-리빌 패턴을 사용하여 샌드위치 공격 및 프런트러닝을 포함한 MEV 기반 위협을 분석 및 완화하고, 트랜잭션 순서 지정 및 블록构建에 대한 전문 지식을 제공하여 에이전트의 능력을 강화합니다.","es":"Habilita a los agentes a analizar y mitigar amenazas basadas en MEV, incluyendo ataques sandwich y de adelantamiento, utilizando relés de transacciones privadas, bloqueadores de MEV y patrones de compromiso y revelación, mientras también proporciona experiencia en la ordenación de transacciones y la construcción de bloques.","fr":"Permet aux agents d''analyser et d''atténuer les menaces basées sur MEV, y compris les attaques sandwich et de frontrunning, en utilisant des relais de transactions privées, des bloqueurs de MEV et des modèles de compromis et de révélation, tout en fournissant une expertise en matière d''ordre des transactions et de construction de blocs.","de":"Ermöglicht es den Agenten, MEV-basierte Bedrohungen zu analysieren und zu mindern, einschließlich Sandwich-Angriffe und Front-Running, unter Verwendung privater Transaktions-Relais, MEV-Blocker und Commit-Reveal-Muster, während auch Expertenwissen in Transaktionsreihenfolge und Blockerstellung bereitgestellt wird.","pt":"Habilita os agentes a analisar e mitigar ameaças baseadas em MEV, incluindo ataques de sanduíche e frontrunning, usando relés de transações privadas, bloqueadores MEV e padrões de compromisso e revelação, enquanto também fornece especialização em ordenação de transações e construção de blocos.","ru":"Наделяет агентов возможностью анализировать и смягчать угрозы на основе MEV, включая атаки «сэндвич» и frontrunning, используя приватные транзакционные ретрансляторы, блокировщики MEV и шаблоны commit-reveal, а также обеспечивает экспертизу в области упорядочения транзакций и построения блоков.","ar":"يمنح الوكلاء khảية تحليل وتخفيف التهديدات المعتمدة على MEV، بما في ذلك هجمات الساندويتش وفرنت راننغ، باستخدام معادلات سرية للتعاملات ومانع MEV وأنماط الالتزام والكشف، كما يوفر الخبرة في ترتيب التعاملات وبناء الكتلة."},"useCases":{"en":["Analyzing MEV concepts and threat models for Web3 applications","Identifying and mitigating sandwich, frontrunning, and backrunning patterns","Implementing private transaction relays and MEV blockers for secure transaction management"],"zh":["分析 Web3 应用程序的 MEV 概念和威胁模型","识别和缓解三明治攻击、抢先交易和后置交易模式","实施私有交易中继和 MEV 拦截器以实现安全的交易管理"],"ja":["Web3アプリケーションのMEV概念と脅威モデルの分析","サンドイッチ攻撃、フロントランニング、バックランニングのパターンの特定と緩和","安全なトランザクション管理のためのプライベートトランザクションリレーとMEVブロッカーの実装"],"ko":["Web3 애플리케이션을 위한 MEV 개념 및 위협 모델 분석","샌드위치, 프런트러닝 및 백러닝 패턴 식별 및 완화","안전한 트랜잭션 관리를 위한 비공개 트랜잭션 릴레이 및 MEV 차단기 구현"],"es":["Analizar conceptos de MEV y modelos de amenazas para aplicaciones Web3","Identificar y mitigar patrones de sandwich, adelantamiento y backrunning","Implementar relés de transacciones privadas y bloqueadores de MEV para una gestión de transacciones segura"],"fr":["Analyser les concepts de MEV et les modèles de menaces pour les applications Web3","Identifier et atténuer les modèles de sandwich, de frontrunning et de backrunning","Mettre en œuvre des relais de transactions privées et des bloqueurs de MEV pour une gestion de transactions sécurisée"],"de":["Analyse von MEV-Konzepten und Bedrohungsmodellen für Web3-Anwendungen","Identifizierung und Minderung von Sandwich-, Front-Running- und Backrunning-Mustern","Implementierung privater Transaktions-Relais und MEV-Blocker für eine sichere Transaktionsverwaltung"],"pt":["Analisar conceitos MEV e modelos de ameaça para aplicações Web3","Identificar e mitigar padrões de sanduíche, frontrunning e backrunning","Implementar relés de transações privadas e bloqueadores MEV para gerenciamento de transações seguro"],"ru":["Анализировать концепции MEV и модели угроз для приложений Web3","Определять и смягчать шаблоны «сэндвич», frontrunning и backrunning","Реализовывать приватные транзакционные ретрансляторы и блокировщики MEV для безопасного управления транзакциями"],"ar":["تحليل مفاهيم MEV وأنموذج التهديد لأي تطبيقات الويب 3","تحديد وتخفيف أنماط الساندويتش وفرنت راننغ وباكرننغ","تنفيذ معادلات سرية للتعاملات ومانع MEV لإدارة التعاملات الآمنة"]},"limitations":{"en":["Requires knowledge of Web3 security and MEV concepts","Limited to Ethereum-based blockchain protocols","Needs access to Web3 resources and materials for comprehensive analysis"],"zh":["需要具备 Web3 安全和 MEV 概念的知识","仅限于基于 Ethereum 的区块链协议","需要访问 Web3 资源与材料以进行全面分析"],"ja":["Web3セキュリティとMEV概念の知識が必要","Ethereumベースのブロックチェーンプロトコルに限定される","包括的な分析のためにWeb3リソースと資料へのアクセスが必要"],"ko":["Web3 보안 및 MEV 개념에 대한 지식 필요","Ethereum 기반 블록체인 프로토콜로 제한됨","포괄적인 분석을 위해 Web3 리소스 및 자료에 대한 액세스 필요"],"es":["Requiere conocimientos de seguridad Web3 y conceptos de MEV","Limitado a protocolos de blockchain basados en Ethereum","Necesita acceso a recursos y materiales Web3 para un análisis exhaustivo"],"fr":["Nécessite des connaissances en matière de sécurité Web3 et de concepts de MEV","Limité aux protocoles de blockchain basés sur Ethereum","Besoin d''accès à des ressources et des documents Web3 pour une analyse exhaustive"],"de":["Benötigt Kenntnisse über Web3-Sicherheit und MEV-Konzepte","Begrenzt auf Ethereum-basierte Blockchain-Protokolle","Benötigt Zugriff auf Web3-Ressourcen und -Materialien für eine umfassende Analyse"],"pt":["Exige conhecimento de segurança Web3 e conceitos MEV","Limitado a protocolos de blockchain baseados em Ethereum","Necessita acesso a recursos e materiais Web3 para análise abrangente"],"ru":["Требует знаний безопасности Web3 и концепций MEV","Ограничен протоколами блокчейна на основе Ethereum","Требует доступа к ресурсам и материалам Web3 для всестороннего анализа"],"ar":["يتطلب معرفة بأمان الويب 3 ومفاهيم MEV","محدود ببروتوكولات البلوكشين القائمة على إيثريوم","يحتاج إلى الوصول إلى موارد ومواد الويب 3 للتحليل الشامل"]},"version":4},"contentHash":"64f7b302d3f1de77273cd3db536f120a8c996566658f294c39d9bfc6daeef672","qualityScore":36}');
