INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gmh5225/awesome-web3-security/mev-security', 'mev-security', 'gmh5225', 'awesome-web3-security', 'community', 'mev-security gmh5225 awesome-web3-security community security web3 The mev-security skill provides a curated list of Web3 Security materials and resources for Pentesters and Bug Hunters, covering MEV concepts, threat models, and mitigation techniques MEV 安全是 Web3 交易安全的重要组成部分，涉及交易排序、沙子攻击和私有订单流等概念 MEV セキュリティは Web3 取引の安全性の重要な構成要素であり、トランザクションの順序付け、サンドイッチ攻撃、プライベートオーダーフローなどの概念を包含する MEV 보안은 Web3 거래 보안의 중요한 구성 요소로, 거래 순서, 샌드위치 공격, 개인 주문 흐름 등을 포함합니다 La seguridad MEV es crucial para proteger tus transacciones de ataques de frontrunning y otros riesgos. Nuestra guía te ayudará a entender los conceptos de MEV y a implementar mitigaciones efectivas La sécurité MEV est cruciale pour protéger vos transactions contre les attaques de frontrunning et d''autres risques. Notre guide vous aidera à comprendre les concepts de MEV et à mettre en œuvre des atténuations efficaces Die MEV-Sicherheit ist entscheidend, um Ihre Transaktionen vor Frontrunning-Angriffen und anderen Risiken zu schützen. Unser Leitfaden hilft Ihnen, die MEV-Konzepte zu verstehen und wirksame Minderungsstrategien umzusetzen A segurança MEV é um conjunto de recursos e materiais para proteger aplicações Web3 contra ataques de frontrunning e backrunning Безопасность MEV - это набор ресурсов и материалов для защиты веб-приложений 3.0 от атак frontrunning и backrunning مев-سيكيوريتي هي مجموعة من الموارد والأدوات لحماية تطبيقات الويب 3 من الهجمات how to use mev-security mev-security setup guide web3 security best practices mev-security alternative mev-security vs web3 security tools what is mev-security mev-security install mastering mev-security for pentesters mev-security for bug hunters web3 security mitigation strategies MEV 安全 Web3 交易安全 交易排序 沙子攻击 私有订单流 MEV 阻塞器 提交-揭示模式 滑点保护 AIエージェント Analyzes sandwich attacks and frontrunning/backrunning patterns Provides mitigation strategies using private transaction relays and MEV blockers Supports commit-reveal patterns for secure transaction ordering Offers slippage protection and simulation for optimized block building Covers arbitrage and liquidation extraction techniques Explains private order flow and private mempool concepts mev-security is a collection of Web3 Security resources and materials focused on MEV concepts, threat models, and mitigation strategies for secure transaction ordering and block building');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dlubom/Jaskiniowy-Kataster-Tatr-Zachodnich/add-cave', 'community', 'dlubom', 'Jaskiniowy-Kataster-Tatr-Zachodnich', 'dlubom/Jaskiniowy-Kataster-Tatr-Zachodnich', 'add-cave', 7, 1, 36, '2026-02-27T17:34:05Z', '2026-03-06T06:51:08.066Z', 'a0059087054fddaad07ff5cf65707140efb6313c63e3ae954b215162c586b188', '{"id":"dlubom/Jaskiniowy-Kataster-Tatr-Zachodnich/add-cave","name":"add-cave","description":{"en":"The add-cave skill allows developers to add new caves to the Tatra Cave Registry by parsing JSON data and using grep commands. It benefits developers working with cave surveys and registries.","zh":"add-cave是一种用于将新洞穴添加到Kataster项目的AI工具，支持查找洞穴数据和解析JSON","ja":"add-caveはケイブを登録するためのAIエージェントです。ケイブデータの検索とJSONの解析をサポートします","ko":"add-cave는 케이브 카타스터 프로젝트에 새로운 케이브를 추가하는 데 사용되는 AI 도구입니다. 케이브 데이터 검색과 JSON 解析을 지원합니다","es":"Add-cave es una herramienta para agregar nuevas cuevas al proyecto kataster. Utiliza grep para buscar datos de cuevas en la base de datos PIG","fr":"Add-cave est un outil pour ajouter de nouvelles grottes au projet kataster. Il utilise grep pour rechercher des données de grottes dans la base de données PIG","de":"Add-cave ist ein Tool zum Hinzufügen neuer Höhlen zum Kataster-Projekt. Es verwendet grep, um Höhlendaten in der PIG-Datenbank zu suchen","pt":"O add-cave é uma ferramenta de linha de comando que permite adicionar novas cavernas ao projeto kataster. Ele usa um formato de dados específico e pode ser integrado com o banco de dados PIG.","ru":"ИИ Агент add-cave является инструментом командной строки, который позволяет добавлять новые пещеры в проект kataster. Он использует específический формат данных и может быть интегрирован с базой данных PIG.","ar":"أداة الذكاء الاصطناعي add-cave هي أداة سطر أوامر تسمح بإضافة كهوف جديدة إلى مشروع kataster. تستخدم تنسيقًا محددًا للبيانات ويمكن دمجها مع قاعدة بيانات PIG."},"seo":{"title":{"en":"add-cave: Setup Guide for AI Agents | Tatra Cave Registry","zh":"添加洞穴到Kataster项目的设置指南 - add-cave","ja":"ケイブの登録方法 - add-cave AIエージェント","ko":"케이브 카타스터 프로젝트에 추가하는 방법 - add-cave 가이드","es":"Guía de configuración de add-cave para desarrolladores","fr":"Configurer add-cave : Guide pour les développeurs","de":"Add-cave Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do add-cave para Desenvolvedores","ru":"Настройка ИИ Агента add-cave: Руководство для Разработчиков","ar":"إعداد أداة الذكاء الاصطناعي add-cave: دليل للمطورين"},"description":{"en":"Discover how to add new caves to the kataster project with the add-cave skill. Learn to use grep, JSON parsing, and ASCII equivalents for diacritics. Get sta...","zh":"了解如何使用add-cave AI工具将新洞穴添加到Kataster项目中，包括查找洞穴数据和解析JSON","ja":"add-cave AIエージェントを使用してケイブを登録する方法を説明します。ケイブデータの検索とJSONの解析について学びましょう","ko":"케이브 카타스터 프로젝트에 새로운 케이브를 추가하는 방법을 알아보세요. add-cave 가이드를 따라 케이브 데이터를 검색하고 JSON을解析하세요","es":"Aprende a utilizar add-cave para agregar nuevas cuevas al proyecto kataster con nuestra guía paso a paso","fr":"Découvrez comment utiliser add-cave pour ajouter de nouvelles grottes au projet kataster avec notre guide étape par étape","de":"Erfahren Sie, wie Sie add-cave verwenden, um neue Höhlen zum Kataster-Projekt hinzuzufügen, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a adicionar novas cavernas ao projeto kataster com o add-cave. Descubra como usar a linha de comando e o formato de dados esperado.","ru":"Узнайте, как добавить новые пещеры в проект kataster с помощью ИИ Агента add-cave. Ознакомьтесь с командной строкой и ожидаемым форматом данных.","ar":"تعلم كيفية إضافة كهوف جديدة إلى مشروع kataster باستخدام أداة الذكاء الاصطناعي add-cave. اكتشف كيفية استخدام سطر الأوامر والتنسيق المتوقع للبيانات."},"definition":{"en":"add-cave is a skill that enables the addition of new caves to the kataster project by searching for cave IDs in the PIG database and parsing JSON data.","zh":"add-cave是一种AI工具，用于将新洞穴添加到Kataster项目中","ja":"add-caveはケイブを登録するためのAIエージェントです","ko":"add-cave는 케이브 카타스터 프로젝트에 새로운 케이브를 추가하는 데 사용되는 AI 도구입니다","es":"Add-cave es una herramienta de línea de comandos que permite agregar nuevas cuevas al proyecto kataster","fr":"Add-cave est un outil en ligne de commande qui permet d''ajouter de nouvelles grottes au projet kataster","de":"Add-cave ist ein Kommandozeilen-Tool, das das Hinzufügen neuer Höhlen zum Kataster-Projekt ermöglicht","pt":"O add-cave é uma ferramenta que adiciona cavernas ao projeto kataster.","ru":"ИИ Агент add-cave - это инструмент, который добавляет пещеры в проект kataster.","ar":"أداة الذكاء الاصطناعي add-cave هي أداة لإضافة الكهوف إلى مشروع kataster."},"features":{"en":["Uses grep commands to search for cave IDs in the PIG database","Parses JSON data from the doc/jaskinie_polski_pig_dump.jsonl file","Supports ASCII equivalents for diacritics in cave names","Accepts arguments in the format <cave-id> \"<valley/subdir/path>\" [/path/to/source.zip]","Enables the addition of new caves to the kataster project","Utilizes the Tatra Cave Registry database for cave data lookup"],"zh":["支持查找洞穴数据","解析JSON格式的数据","使用ASCII编码搜索洞穴ID","支持命令行接口（CLI）","使用grep命令搜索洞穴数据"],"ja":["ケイブデータの検索をサポート","JSON形式のデータを解析","ASCIIコードを使用してケイブIDを検索","コマンドラインインターフェース（CLI）をサポート","grepコマンドを使用してケイブデータを検索"],"ko":["케이브 데이터 검색을 지원","JSON 형식의 데이터를 해석","ASCII 코드를 사용하여 케이브 ID를 검색","명령줄 인터페이스（CLI）를 지원","grep 명령을 사용하여 케이브 데이터를 검색"],"es":["Búsqueda de datos de cuevas en la base de datos PIG utilizando grep","Soporte para formato de archivo JSONL","Compatibilidad con rutas de archivo y carpetas","Uso de ASCII para búsqueda de IDs de cuevas","Parseo de datos JSON para extraer información de cuevas"],"fr":["Recherche de données de grottes dans la base de données PIG à l''aide de grep","Prise en charge du format de fichier JSONL","Compatibilité avec les chemins de fichiers et les dossiers","Utilisation de l''ASCII pour la recherche d''IDs de grottes","Analyse de données JSON pour extraire des informations de grottes"],"de":["Suche nach Höhlendaten in der PIG-Datenbank mit grep","Unterstützung für das JSONL-Dateiformat","Kompatibilität mit Dateipfaden und -ordnern","Verwendung von ASCII für die Suche nach Höhlen-IDs","Parsing von JSON-Daten zum Extrahieren von Höhleninformationen"],"pt":["Uso de linha de comando para adicionar cavernas","Integração com o banco de dados PIG","Suporte a formato de dados específico","Capacidade de parsear JSON para extração de dados","Uso de ASCII para busca de dados"],"ru":["Использование командной строки для добавления пещер","Интеграция с базой данных PIG","Поддержка específического формата данных","Возможность парсинга JSON для извлечения данных","Использование ASCII для поиска данных"],"ar":["استخدام سطر الأوامر لإضافة الكهوف","التكامل مع قاعدة بيانات PIG","دعم تنسيق محدد للبيانات","قدرة على تحليل JSON لاستخراج البيانات","استخدام ASCII للبحث عن البيانات"]},"keywords":{"en":["how to use add-cave","add-cave setup guide","Tatra Cave Registry database","cave survey skills","add-cave alternative","add-cave vs cave registry software","install add-cave","add-cave documentation","cave registry management"],"zh":["add-cave","Kataster项目","洞穴注册","JSON解析","ASCII搜索","grep命令","命令行接口","AI工具"],"ja":["add-cave","ケイブ登録","Katasterプロジェクト","JSON解析","ASCII検索","grepコマンド","コマンドラインインターフェース","AIエージェント"],"ko":["add-cave","케이브 등록","케이브 카타스터 프로젝트","JSON 해석","ASCII 검색","grep 명령","명령줄 인터페이스","AI 도구"],"es":["add-cave","kataster","cuevas","grep","PIG","JSONL","ASCII","desarrollo de software","herramientas de línea de comandos","búsqueda de datos"],"fr":["add-cave","kataster","grottes","grep","PIG","JSONL","ASCII","développement de logiciels","outils de ligne de commande","recherche de données"],"de":["add-cave","kataster","Höhlen","grep","PIG","JSONL","ASCII","Software-Entwicklung","Kommandozeilen-Tools","Daten-Suche"],"pt":["add-cave","kataster","desenvolvimento de software","ferramentas de linha de comando","banco de dados PIG","JSON","ASCII","desenvolvedores"],"ru":["ИИ Агенты","add-cave","kataster","разработка программного обеспечения","инструменты командной строки","база данных PIG","JSON","ASCII","разработчики"],"ar":["أدوات الذكاء الاصطناعي","add-cave","kataster","تطوير البرمجيات","أدوات سطر الأوامر","قاعدة بيانات PIG","JSON","ASCII","المطورون"]}},"owner":"dlubom","repo":"Jaskiniowy-Kataster-Tatr-Zachodnich","repoPath":"dlubom/Jaskiniowy-Kataster-Tatr-Zachodnich","stars":7,"forks":1,"updatedAt":"2026-02-27T17:34:05Z","topics":["cave-survey","caves","jaskinie","tatry"],"category":"community","skillMd":{"name":"add-cave","description":"Add a new cave to the Jaskiniowy Kataster Tatr Zachodnich project. Creates the full directory structure, SRV files, _RAW/ folder, and KATASTER.wpj entry.","bodyPreview":"Add a new cave to the kataster project.\n\nArguments: $ARGUMENTS\nExpected format: `<cave-id> \"<valley/subdir/path>\" [/path/to/source.zip]`\nExample: `/add-cave T.D-08.07 \"Dolina Koscieliska/Organy\" /tmp/MROZN.SRV.zip`\n\n---\n\n## Step 1 — Look up cave data in PIG database (single call)\n\nThe cave ID is ASCII — search for it directly with a single grep:\n\n```bash\ngrep ''\"<cave-id>\"'' doc/jaskinie_polski_pig_dump.jsonl\n```\n\nParse the returned JSON for:\n- `name` → CAVE_NAME (use ASCII equivalents for diacrit","body":"Add a new cave to the kataster project.\n\nArguments: $ARGUMENTS\nExpected format: `<cave-id> \"<valley/subdir/path>\" [/path/to/source.zip]`\nExample: `/add-cave T.D-08.07 \"Dolina Koscieliska/Organy\" /tmp/MROZN.SRV.zip`\n\n---\n\n## Step 1 — Look up cave data in PIG database (single call)\n\nThe cave ID is ASCII — search for it directly with a single grep:\n\n```bash\ngrep ''\"<cave-id>\"'' doc/jaskinie_polski_pig_dump.jsonl\n```\n\nParse the returned JSON for:\n- `name` → CAVE_NAME (use ASCII equivalents for diacritics: ą→a, ć→c, ł→l, ó→o, ś→s, ź/ż→z, ę→e, ń→n)\n- `latitude`, `longitude`, `absolute_height_masl` → entrance coordinates\n- `other_names`, `authors_of_study`, `editorial` → for README and metadata\n\nIf not found by ID, try searching by partial ASCII name.\n\n## Step 2 — Convert coordinates to DMS (single Node.js call)\n\nRun one Node.js command to produce both the DMS string and verify the location:\n\n```bash\nnode -e \"\nconst lat = <latitude>; const lon = <longitude>;\nconst toDMS = (v) => {\n  const d = Math.floor(v), m = Math.floor((v-d)*60);\n  const s = (((v-d)*60-m)*60).toFixed(3).padStart(6,''0'');\n  return d+'':''+String(m).padStart(2,''0'')+'':''+s;\n};\nconsole.log(''N''+toDMS(lat)+''  E''+toDMS(lon));\n\"\n```\n\n## Step 3 — Determine directory path\n\nValley path from arguments (use ASCII, no diacritics in directory names):\n`Jaskinie-poligony/<valley-path>/<Cave Name ASCII>/`\n\nCheck if the valley subdirectory already exists. Match the style of neighbouring caves in that directory.\n\n## Step 4 — Handle source files\n\nIf a source ZIP was provided:\n1. Extract: `unzip -o <source.zip> -d /tmp/<cave_ascii>_raw/`\n2. List contents: `find /tmp/<cave_ascii>_raw -not -path \"*/__MACOSX*\" -type f`\n3. Read each survey file to understand its format (units, station naming, number of readings)\n\n## Step 5 — Create directory structure\n\n```bash\nmkdir -p \"Jaskinie-poligony/<valley-path>/<Cave Name>/_RAW\"\n```\n\nCopy source files to `_RAW/` preserving original names (never rename raw files):\n```bash\ncp /tmp/<cave_ascii>_raw/<file> \"Jaskinie-poligony/<valley-path>/<Cave Name>/_RAW/\"\n```\n\n## Step 6 — Create _RAW/README.md\n\nUse Polish language. Required fields:\n- **Źródło** — origin / who provided the data\n- **Autorzy pomiarów** — survey authors (from PIG `authors_of_study`)\n- **Data pomiaru** — survey date (from PIG or source file headers)\n- **Data pozyskania** — date the file was obtained (from file timestamp if unknown)\n- **Dodał** — who added it to _RAW/ (ask user if unknown)\n- **Kompletność** — completeness notes (format, number of files, missing data)\n- **## Pliki** — list every file in _RAW/ with a one-line description\n\nLeave any genuinely unknown fields as `nieznany` / `nieznane`.\n\n## Step 7 — Determine station prefix\n\nFrom cave ID `T.X-NN.MM` → prefix = `tXNNMM` (e.g., T.D-08.07 → `td0807`).\nOr use a short cave name abbreviation (e.g., MROZN) — check what style neighbouring caves use.\n\n## Step 8 — Create CAVE_M.SRV\n\n```\n#[\nCAVE_ID         \"T.X-NN.MM\"\nCAVE_NAME       \"Cave Name ASCII\"\nUPDATE_DATE     <today YYYY-MM-DD>\nPROJECT_NAME    \"Kataster jaskin tatrzanskich\"\nCOORDINATOR     \"Dariusz Lubomski\"\nCOORDINATOR_EMAIL \"darek.lubomski@gmail.com\"\nREFERENCE_SYSTEM \"WGS84\"\nCOORDINATE_SYSTEM \"UTM\"\nDATA_SOURCE     \"Panstwowy Instytut Geologiczny\"\nLICENSE         \"http://creativecommons.org/licenses/by-sa/2.0/\"\n#]\n\n#prefix <PREFIX>\n#flag   <STATION>   /<Cave Label>\n#note   <STATION>   /<Cave Label>\n#fix    <STATION>   E<lon-dms>  N<lat-dms>  <elevation>m\n```\n\n`<STATION>` is the entrance station name in the survey (e.g. `td0807.1.3`).\nIf the entrance station is unknown, comment out all three lines and add a TODO note:\n```\n; #flag  ???  /<Cave Label>\n; #note  ???  /<Cave Label>\n; #fix   ???  E<lon-dms>  N<lat-dms>  <elevation>m  ; TODO: uzupelnic numer stacji wejscia\n```\n\n## Step 9 — Create CAVE_S.SRV\n\n```\n#[\nCAVE_ID         \"T.X-NN.MM\"\nCAVE_NAME       \"Cave Name ASCII\"\nSURVEY_ID       <PREFIX>\nSURVEY_NAME     \"<Cave Name ASCII>\"\nUPDATE_DATE     <today YYYY-MM-DD>\nPROJECT_NAME    \"Kataster jaskin tatrzanskich\"\nCOORDINATOR     \"Dariusz Lubomski\"\nCOORDINATOR_EMAIL \"darek.lubomski@gmail.com\"\nDATA_SOURCE     \"<source or nieznane>\"\nLICENSE         \"http://creativecommons.org/licenses/by-sa/2.0/\"\n\nTEAM \"<authors from PIG or nieznany>\"\nINSTRUMENT \"<instrument or nieznany>\"\n#]\n\n#prefix <PREFIX>\n#date <YYYY-MM-DD>\n#units meters order=DAV\n#units A=D V=D\n\n;<Section description>\n\nFROM    TO      DISTANCE    AZIMUTH     INCLINATION\n0       1       4.61        293         2\n1       2       2.06        303         7\n\n;Splay shots (cross-sections)\n\n0       -       5.52        51          8\n0       -       5.47        265         76\n```\n\n`SURVEY_ID` and `SURVEY_NAME` are inside `#[...]` which is a block comment — Walls ignores it entirely. These fields are project convention only; omit them if unknown.\n\nIf the raw source file contains multiple readings per shot, note this and leave measurements as TODO:\n```\n; TODO: przetworzyc pomiary z _RAW/<filename>\n; Plik zrodlowy zawiera pomiary potrojne — wymagaja usrednienia lub konwersji.\n; Stacje numerowane od <first-station> — numer stacji otworu nieznany.\n```\n\n## Step 10 — Update KATASTER.wpj\n\n**IMPORTANT: Ask the user to close Walls before this step.** Walls overwrites the .wpj file when it saves, discarding any manually added entries.\n\nFind the correct `.BOOK` parent in KATASTER.wpj. The path hierarchy corresponds to the directory structure:\n- Each `.BOOK` with `.PATH <dir>` builds the cumulative path from the project root\n- Surveys without their own `.PATH` inherit the parent book''s path\n\nInsert a new `.BOOK` block for the cave in the correct location:\n\n```\n.BOOK\t<Cave Name ASCII>\n.NAME\t<SHORT_ID>\n.PATH\t<Cave Name ASCII>\n.STATUS\t8\n.SURVEY\t<Cave Name ASCII> meta\n.NAME\t<PREFIX>_M\n.STATUS\t8\n.SURVEY\t<Cave Name ASCII> pomiary\n.NAME\t<PREFIX>_S\n.STATUS\t8\n.ENDBOOK\n```\n\nUse `Edit` tool with sufficient surrounding context to make the match unique.\nVerify with: `grep -n \"<PREFIX>\" KATASTER.wpj`\n\n## Step 11 — Summary\n\nReport to the user:\n- Files created (list all paths)\n- Data filled in vs left as TODO/unknown\n- Any fields needing manual follow-up (entrance station, instrument, who added raw files)\n- Reminder: if Walls was open, it may overwrite the .wpj entry — check after reopening\n"},"lastSynced":"2026-03-06T06:51:08.066Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing cave registry management and JSON data parsing capabilities.","zh":"适合需要洞穴注册管理和JSON数据解析功能的数据分析代理。","ja":"洞窟登録管理およびJSONデータ解析機能を必要とするデータ分析エージェントに最適です。","ko":"동굴 등록 관리 및 JSON 데이터 파싱 기능이 필요한 데이터 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Datos que necesitan gestión de registros de cuevas y capacidades de análisis de datos JSON.","fr":"Parfait pour les Agents d''Analyse de Données nécessitant une gestion d''enregistrement de grottes et des capacités d''analyse de données JSON.","de":"Perfekt für Data Analysis Agents, die eine Höhlenverwaltung und JSON-Datenparsungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Dados que precisam de gerenciamento de registros de cavernas e capacidades de análise de dados JSON.","ru":"Идеально подходит для агентов анализа данных, которым необходимы возможности управления реестром пещер и парсинга данных JSON.","ar":"مثالي لعميل分析 البيانات الذي يحتاج إلى إدارة سجلات الكهوف وقدرات تحليل بيانات JSON."},"recommendation":{"en":"Empowers agents to add new caves to the Tatra Cave Registry by parsing JSON data and utilizing grep commands, providing seamless integration with the kataster project and support for ASCII cave IDs.","zh":"通过解析JSON数据和利用grep命令，赋予代理添加新洞穴到塔特拉洞窟注册表的能力，并提供与kataster项目的无缝集成和对ASCII洞窟ID的支持。","ja":"JSONデータを解析し、grepコマンドを利用することで、エージェントがタトラ洞窟登録簿に新しい洞窟を追加する能力を付与し、katasterプロジェクトとのシームレスな統合およびASCII洞窟IDのサポートを提供します。","ko":"JSON 데이터를 파싱하고 grep 명령을 활용하여 에이전트가 타트라 동굴 등록부에 새로운 동굴을 추가하는 기능을 제공하며, 카타스터 프로젝트와의无缝 통합 및 ASCII 동굴 ID 지원을 제공합니다.","es":"Habilita a los agentes para agregar nuevas cuevas al Registro de Cuevas de Tatra al analizar datos JSON y utilizar comandos grep, proporcionando una integración sin problemas con el proyecto kataster y soporte para IDs de cuevas ASCII.","fr":"Permet aux agents d''ajouter de nouvelles grottes au Registre des Grottes de Tatra en analysant des données JSON et en utilisant des commandes grep, offrant une intégration transparente avec le projet kataster et un support pour les IDs de grottes ASCII.","de":"Ermächtigt die Agenten, neue Höhlen zum Tatra-Höhlenregister hinzuzufügen, indem sie JSON-Daten analysieren und grep-Befehle nutzen, wodurch eine nahtlose Integration mit dem kataster-Projekt und Unterstützung für ASCII-Höhlen-IDs bereitgestellt wird.","pt":"Permite que os agentes adicionem novas cavernas ao Registro de Cavernas da Tatra, analisando dados JSON e utilizando comandos grep, proporcionando integração perfeita com o projeto kataster e suporte a IDs de cavernas ASCII.","ru":"Позволяет агентам добавлять новые пещеры в Реестр пещер Татры, парсируя данные JSON и используя команды grep, обеспечивая бесшовную интеграцию с проектом kataster и поддержку ASCII-идентификаторов пещер.","ar":"يمنح الوكيل إضافة كهوف جديدة إلى سجل كهوف تاترا من خلال تحليل بيانات JSON واستخدام أوامر grep، مما يوفر تكاملًا无 تشوّه مع مشروع kataster ودعمًا لمعرفات كهوف ASCII."},"useCases":{"en":["Adding new cave entries to the Tatra Cave Registry","Parsing JSON data for cave surveys","Utilizing grep commands for efficient cave data lookup"],"zh":["向塔特拉洞窟注册表添加新的洞穴条目","解析JSON数据用于洞穴调查","利用grep命令进行高效的洞穴数据查找"],"ja":["タトラ洞窟登録簿に新しい洞窟のエントリを追加する","JSONデータを解析して洞窟調査を行う","grepコマンドを利用して効率的な洞窟データ検索を行う"],"ko":["타트라 동굴 등록부에 새로운 동굴 항목 추가","JSON 데이터 파싱을 통한 동굴 조사지표 생성","grep 명령을 활용한 효율적인 동굴 데이터 조회"],"es":["Agregar nuevas entradas de cuevas al Registro de Cuevas de Tatra","Analizar datos JSON para encuestas de cuevas","Utilizar comandos grep para una búsqueda eficiente de datos de cuevas"],"fr":["Ajouter de nouvelles entrées de grottes au Registre des Grottes de Tatra","Analyser des données JSON pour les études de grottes","Utiliser des commandes grep pour une recherche efficace de données de grottes"],"de":["Hinzufügen neuer Höhleneinträge zum Tatra-Höhlenregister","Analysieren von JSON-Daten für Höhlenumfragen","Nutzen von grep-Befehlen für eine effiziente Höhlendatensuche"],"pt":["Adicionar novas entradas de cavernas ao Registro de Cavernas da Tatra","Analise de dados JSON para levantamentos de cavernas","Utilizar comandos grep para busca eficiente de dados de cavernas"],"ru":["Добавление новых записей пещер в Реестр пещер Татры","Парсинг данных JSON для обследования пещер","Использование команд grep для эффективного поиска данных пещер"],"ar":["إضافة مدخلات كهوف جديدة إلى سجل كهوف تاترا","تحليل بيانات JSON لمسح الكهوف","استخدام أوامر grep للبحث الفعال عن بيانات الكهوف"]},"limitations":{"en":["Requires access to the PIG database","Limited to ASCII cave IDs","Dependent on grep command functionality"],"zh":["需要访问PIG数据库","仅限ASCII洞窟ID","依赖grep命令功能"],"ja":["PIGデータベースへのアクセスが必要","ASCII洞窟IDのみ対応","grepコマンドの機能に依存"],"ko":["PIG 데이터베이스 접근이 필요","ASCII 동굴 ID만 지원","grep 명령의 기능에 의존"],"es":["Requiere acceso a la base de datos PIG","Limitado a IDs de cuevas ASCII","Dependiente de la funcionalidad del comando grep"],"fr":["Nécessite un accès à la base de données PIG","Limité aux IDs de grottes ASCII","Dépendant de la fonctionnalité de la commande grep"],"de":["Erfordert Zugriff auf die PIG-Datenbank","Begrenzt auf ASCII-Höhlen-IDs","Abhängig von der Funktionalität des grep-Befehls"],"pt":["Requer acesso ao banco de dados PIG","Limitado a IDs de cavernas ASCII","Dependente da funcionalidade do comando grep"],"ru":["Требуется доступ к базе данных PIG","Ограничен идентификаторами пещер ASCII","Зависит от функциональности команды grep"],"ar":["يتطلب الوصول إلى قاعدة بيانات PIG","محدود بمعرفات كهوف ASCII","يعتمد على وظائف أمر grep"]},"version":4},"contentHash":"a0059087054fddaad07ff5cf65707140efb6313c63e3ae954b215162c586b188","qualityScore":36}');
