INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dlubom/Jaskiniowy-Kataster-Tatr-Zachodnich/add-cave', 'add-cave', 'dlubom', 'Jaskiniowy-Kataster-Tatr-Zachodnich', 'community', 'add-cave dlubom Jaskiniowy-Kataster-Tatr-Zachodnich community cave-survey caves jaskinie tatry The add-cave skill allows developers to add new caves to the Tatra Cave Registry by parsing JSON data and using grep commands. It benefits developers working with cave surveys and registries. add-cave是一种用于将新洞穴添加到Kataster项目的AI工具，支持查找洞穴数据和解析JSON add-caveはケイブを登録するためのAIエージェントです。ケイブデータの検索とJSONの解析をサポートします add-cave는 케이브 카타스터 프로젝트에 새로운 케이브를 추가하는 데 사용되는 AI 도구입니다. 케이브 데이터 검색과 JSON 解析을 지원합니다 Add-cave es una herramienta para agregar nuevas cuevas al proyecto kataster. Utiliza grep para buscar datos de cuevas en la base de datos PIG Add-cave est un outil pour ajouter de nouvelles grottes au projet kataster. Il utilise grep pour rechercher des données de grottes dans la base de données PIG Add-cave ist ein Tool zum Hinzufügen neuer Höhlen zum Kataster-Projekt. Es verwendet grep, um Höhlendaten in der PIG-Datenbank zu suchen O add-cave é uma ferramenta de linha de comando que permite adicionar novas cavernas ao projeto kataster. Ele usa um formato de dados específico e pode ser integrado com o banco de dados PIG. ИИ Агент add-cave является инструментом командной строки, который позволяет добавлять новые пещеры в проект kataster. Он использует específический формат данных и может быть интегрирован с базой данных PIG. أداة الذكاء الاصطناعي add-cave هي أداة سطر أوامر تسمح بإضافة كهوف جديدة إلى مشروع kataster. تستخدم تنسيقًا محددًا للبيانات ويمكن دمجها مع قاعدة بيانات PIG. how to use add-cave add-cave setup guide Tatra Cave Registry database cave survey skills add-cave alternative add-cave vs cave registry software install add-cave add-cave documentation cave registry management add-cave Kataster项目 洞穴注册 JSON解析 ASCII搜索 grep命令 命令行接口 AI工具 Uses grep commands to search for cave IDs in the PIG database Parses JSON data from the doc/jaskinie_polski_pig_dump.jsonl file Supports ASCII equivalents for diacritics in cave names Accepts arguments in the format <cave-id> "<valley/subdir/path>" [/path/to/source.zip] Enables the addition of new caves to the kataster project Utilizes the Tatra Cave Registry database for cave data lookup add-cave is a skill that enables the addition of new caves to the kataster project by searching for cave IDs in the PIG database and parsing JSON data.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cwoodruff/morespeakers-com/sql-schema', 'community', 'cwoodruff', 'morespeakers-com', 'cwoodruff/morespeakers-com', 'sql-schema', 6, 3, 36, '2026-02-24T16:50:29Z', '2026-03-06T06:51:45.977Z', '4fd38b8c2b659a27afbb17d8a65f34183a5eb26f57eb88a742dee6fb2f83f16d', '{"id":"cwoodruff/morespeakers-com/sql-schema","name":"sql-schema","description":{"en":"The sql-schema skill enables developers to manage SQL Server containers using the Script-Load pattern via .NET Aspire. It helps developers initialize and manage database schema definitions.","zh":"SQL Schema Skill 提供了数据库模式管理的解决方案，使用脚本加载模式和 .NET Aspire","ja":"SQL スキーマ スキルは、データベース スキーマを管理するためのソリューションを提供します","ko":"SQL 스키마 스킬은 데이터베이스 스키마를 관리하는 솔루션을 제공합니다","es":"Sql-schema es una habilidad para la administración de esquemas de base de datos que utiliza patrones de carga y definición de esquemas para inicializar contenedores de SQL Server","fr":"Sql-schema est une compétence pour la gestion de schémas de base de données qui utilise des modèles de chargement et des définitions de schémas pour initialiser des conteneurs de serveur SQL","de":"Sql-schema ist eine Fähigkeit zur Verwaltung von Datenbankschemata, die LadeMuster und Schemadefinitionen verwendet, um SQL-Server-Container zu initialisieren","pt":"O sql-schema é um skill que gerencia esquemas de banco de dados SQL, permitindo a inicialização e gerenciamento de mudanças de forma eficiente","ru":"Sql-schema - это навык, который управляет схемами базы данных SQL, позволяя инициализировать и управлять изменениями эффективно","ar":"sql-schema هو مهارة لإدارة مخططات قواعد البيانات SQL، مما يسمح ببدء وتشغيل التغييرات بفعالية"},"seo":{"title":{"en":"sql-schema: SQL Server Container Setup Guide | AI Agent S...","zh":"SQL Schema 管理设置指南","ja":"SQL スキーマ管理のベストプラクティス","ko":"SQL 스키마 관리 설정 가이드","es":"Guía de configuración de sql-schema para administración d...","fr":"Guide de configuration de sql-schema pour la gestion de s...","de":"Konfigurationsleitfaden für sql-schema zur Verwaltung von...","pt":"Guia de Configuração do SQL Schema para Desenvolvedores","ru":"Руководство по настройке ИИ Агента SQL Schema","ar":"دليل إعداد مخطط قاعدة البيانات SQL لل(ai إيجنت)"},"description":{"en":"Discover how to manage SQL Server containers with sql-schema. Learn the Script-Load pattern and optimize your database schema management workflow today!","zh":"了解如何使用 SQL Schema Skill 管理数据库模式，包括脚本加载模式和 .NET Aspire","ja":"SQL スキーマ スキルを使用してデータベース スキーマを管理する方法について説明します","ko":"SQL 스키마 스킬을 사용하여 데이터베이스 스키마를 관리하는 방법을 알아보세요","es":"Aprende a administrar esquemas de base de datos con sql-schema, incluyendo patrones de carga y definición de esquemas","fr":"Découvrez comment gérer les schémas de base de données avec sql-schema, y compris les modèles de chargement et la définition de schémas","de":"Erfahren Sie, wie Sie Datenbankschemata mit sql-schema verwalten, einschließlich LadeMustern und Schemadefinitionen","pt":"Aprenda a gerenciar esquemas de banco de dados SQL com o skill sql-schema, incluindo padrões de inicialização e gerenciamento de mudanças","ru":"Узнайте, как управлять схемами базы данных SQL с помощью навыка sql-schema, включая шаблоны инициализации и управления изменениями","ar":"تعلم كيفية إدارة مخططات قواعد البيانات SQL مع مهارة sql-schema، بما في ذلك أنماط 초기 و إدارة التغييرات"},"definition":{"en":"sql-schema is a skill for managing SQL Server container initialization and database schema definitions using a Script-Load pattern","zh":"SQL Schema Skill 是一种管理数据库模式的 AI 工具","ja":"SQL スキーマ スキルは、データベース スキーマを管理する AI エージェントです","ko":"SQL 스키마 스킬은 데이터베이스 스키마를 관리하는 AI 도구입니다","es":"Sql-schema es una habilidad de administración de esquemas de base de datos que define la estructura de la base de datos","fr":"Sql-schema est une compétence de gestion de schémas de base de données qui définit la structure de la base de données","de":"Sql-schema ist eine Fähigkeit zur Verwaltung von Datenbankschemata, die die Struktur der Datenbank definiert","pt":"O sql-schema é um conjunto de regras e padrões para gerenciar esquemas de banco de dados SQL","ru":"Sql-schema - это набор правил и шаблонов для управления схемами базы данных SQL","ar":"sql-schema هو مجموعة من القواعد و الأنماط لإدارة مخططات قواعد البيانات SQL"},"features":{"en":["Uses .NET Aspire (MoreSpeakers.AppHost) for SQL Server container initialization","Defines database schema in scripts/database/","Follows a Script-Load pattern for database schema management","Modifies columns and adds new seed data as needed","Locates loading logic in src/MoreSpeakers.AppHost/AppHost.cs"],"zh":["使用脚本加载模式初始化 SQL Server 容器","支持 .NET Aspire (`MoreSpeakers.AppHost`)","定义数据库模式在 `scripts/database/` 中","提供修改列和添加新表的功能","支持新种子数据的添加"],"ja":["SQL Server コンテナを初期化するためのスクリプト ロード パターンを使用",".NET Aspire (`MoreSpeakers.AppHost`) をサポート","データベース スキーマを `scripts/database/` で定義","列の変更と新しいテーブルの追加をサポート","新しいシード データの追加をサポート"],"ko":["SQL Server 컨테이너를 초기화하는 스크립트 로드 패턴을 사용",".NET Aspire (`MoreSpeakers.AppHost`)를 지원","데이터베이스 스키마를 `scripts/database/`에서 정의","열의 변경과 새로운 테이블의 추가를 지원","新的 시드 데이터의 추가를 지원"],"es":["Patrón de carga de esquemas de base de datos","Definición de esquemas en scripts/database/","Inicialización de contenedores de SQL Server con .NET Aspire","No utiliza dotnet ef migrations","Gestión de cambios en la estructura de la base de datos"],"fr":["Modèle de chargement de schémas de base de données","Définition de schémas dans scripts/database/","Initialisation de conteneurs de serveur SQL avec .NET Aspire","N''utilise pas dotnet ef migrations","Gestion des modifications de la structure de la base de données"],"de":["LadeMuster für Datenbankschemata","Schemadefinitionen in scripts/database/","Initialisierung von SQL-Server-Containern mit .NET Aspire","Verwendet keine dotnet ef migrations","Verwaltung von Änderungen an der Datenbankstruktur"],"pt":["Iniciação de contêineres SQL Server via .NET Aspire","Gerenciamento de mudanças de esquema de banco de dados","Definição de esquema de banco de dados em scripts/database/","Uso de padrões de inicialização para carregar lógica de carga","Integração com o AppHost.cs para gerenciamento de mudanças"],"ru":["Инициализация контейнеров SQL Server через .NET Aspire","Управление изменениями схемы базы данных","Определение схемы базы данных в scripts/database/","Использование шаблонов инициализации для загрузки логики","Интеграция с AppHost.cs для управления изменениями"],"ar":["تشغيل حاويات قاعدة البيانات SQL Server عبر .NET Aspire","إدارة التغييرات في مخطط قاعدة البيانات","تعريف مخطط قاعدة البيانات في scripts/database/","استخدام أنماط التشغيل لتحميل منطق التحميل","التكامل مع AppHost.cs لإدارة التغييرات"]},"keywords":{"en":["how to use sql-schema","sql-schema setup guide","sql-schema alternative","sql-schema vs dotnet ef migrations","sql-schema install","what is sql-schema","sql-schema for AI agents","sql-schema best practices","sql-schema workflow optimization"],"zh":["SQL Schema 管理","AI 工具","数据库模式管理","脚本加载模式",".NET Aspire","MoreSpeakers.AppHost"],"ja":["SQL スキーマ管理","AI エージェント","データベース スキーマ管理","スクリプト ロード パターン",".NET Aspire","MoreSpeakers.AppHost"],"ko":["SQL 스키마 관리","AI 도구","데이터베이스 스키마 관리","스크립트 로드 패턴",".NET Aspire","MoreSpeakers.AppHost"],"es":["sql-schema","administración de esquemas de base de datos","patrón de carga","definición de esquemas","sql server","dotnet aspire","gestión de cambios","base de datos"],"fr":["sql-schema","gestion de schémas de base de données","modèle de chargement","définition de schémas","serveur sql","dotnet aspire","gestion des modifications","base de données"],"de":["sql-schema","verwaltung von datenbankschemata","lademuster","schemadefinitionen","sql-server","dotnet aspire","verwaltung von änderungen","datenbank"],"pt":["sql schema","gerenciamento de esquema de banco de dados","inicialização de contêineres sql server","dotnet aspire","apphost.cs","desenvolvimento de banco de dados","sql server","banco de dados relacional"],"ru":["sql схема","управление схемой базы данных","инициализация контейнеров sql server","dotnet aspire","apphost.cs","разработка базы данных","sql сервер","реляционная база данных"],"ar":["مخطط قاعدة البيانات sql","إدارة مخطط قاعدة البيانات","تشغيل حاويات قاعدة البيانات sql server","dotnet aspire","apphost.cs","تطوير قاعدة البيانات","خادم قاعدة البيانات sql","قاعدة بيانات متعلقة"]}},"owner":"cwoodruff","repo":"morespeakers-com","repoPath":"cwoodruff/morespeakers-com","stars":6,"forks":3,"updatedAt":"2026-02-24T16:50:29Z","topics":[],"category":"community","skillMd":{"name":"sql-schema","description":"Database Architect skill. Use this when you need to modify the database schema, add tables, or seed data. This project uses RAW SQL SCRIPTS orchestrated by .NET Aspire, NOT Entity Framework Migrations.","bodyPreview":"# SQL Schema Management Skill\n\n## Overview\n\nMoreSpeakers.com uses a \"Script-Load\" pattern via .NET Aspire (`MoreSpeakers.AppHost`) to initialize the SQL Server container. We **DO NOT** use `dotnet ef migrations`.\n\n## Source of Truth\n\nThe database schema is defined in `scripts/database/`.\n\n## Workflow\n\n### 1. Identify the Change\nDetermine if you need a new table, a modified column, or new seed data.\n\n### 2. Locate the Loading Logic\nCheck `src/MoreSpeakers.AppHost/AppHost.cs`. Look for the `sqlTex","body":"# SQL Schema Management Skill\n\n## Overview\n\nMoreSpeakers.com uses a \"Script-Load\" pattern via .NET Aspire (`MoreSpeakers.AppHost`) to initialize the SQL Server container. We **DO NOT** use `dotnet ef migrations`.\n\n## Source of Truth\n\nThe database schema is defined in `scripts/database/`.\n\n## Workflow\n\n### 1. Identify the Change\nDetermine if you need a new table, a modified column, or new seed data.\n\n### 2. Locate the Loading Logic\nCheck `src/MoreSpeakers.AppHost/AppHost.cs`. Look for the `sqlText` concatenation logic:\n\n```csharp\nvar sqlText = string.Concat(\n    File.ReadAllText(Path.Combine(path, @\"../../scripts/database/create-database.sql\")),\n    \" \",\n    File.ReadAllText(Path.Combine(path, @\"../../scripts/database/create-tables.sql\")),\n    // ... other files\n);\n```\n\n### 3. Apply the Change\n\n**Option A: Modify Existing Files (Preferred for clean slate)**\n-   If adding a core table, add T-SQL to `scripts/database/create-tables.sql`.\n-   If adding a view, use `scripts/database/create-views.sql`.\n\n**Option B: Create New Script (For specific updates)**\n1.  Create a new file, e.g., `scripts/database/update-schema-features.sql`.\n2.  **CRITICAL**: You MUST update `AppHost.cs` to include this new file in the `string.Concat` list, or it will be ignored.\n\n### 4. Writing SQL\n\n-   **Idempotency**: Always write idempotent SQL. The script may run on container startup.\n    ```sql\n    IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = ''MyTable'')\n    BEGIN\n        CREATE TABLE MyTable (...)\n    END\n    ```\n-   **Foreign Keys**: Ensure referenced tables are created *before* the table defining the key (check file order in `AppHost.cs`).\n\n### 5. Verification\n-   Run `dotnet run --project src/MoreSpeakers.AppHost`.\n-   The container will spin up and execute the concatenated SQL script.\n\n## PROHIBITED ACTIONS\n\n-   ❌ `dotnet ef migrations add`\n-   ❌ `dotnet ef database update`\n-   ❌ Modifying the DbContext `OnModelCreating` without adding corresponding SQL scripts.\n"},"lastSynced":"2026-03-06T06:51:45.977Z","agentAnalysis":{"suitability":{"en":"Perfect for Database Management Agents needing advanced SQL Server container management via .NET Aspire","zh":"适合需要通过 .NET Aspire 进行高级 SQL Server 容器管理的数据库管理代理","ja":".NET Aspire を使用した高度な SQL Server コンテナ管理が必要なデータベース管理エージェントに適しています","ko":".NET Aspire를 사용하여 고급 SQL Server 컨테이너 관리가 필요한 데이터베이스 관리 에이전트에 적합합니다","es":"Perfecto para agentes de gestión de bases de datos que necesitan una gestión avanzada de contenedores de SQL Server a través de .NET Aspire","fr":"Parfait pour les agents de gestion de bases de données nécessitant une gestion avancée de conteneurs SQL Server via .NET Aspire","de":"Perfekt für Datenbank-Management-Agents, die eine erweiterte SQL-Server-Container-Verwaltung über .NET Aspire benötigen","pt":"Perfeito para agentes de gerenciamento de banco de dados que necessitam de gerenciamento avançado de contêineres do SQL Server via .NET Aspire","ru":"Идеально подходит для агентов управления базами данных, требующих расширенного управления контейнерами SQL Server через .NET Aspire","ar":"مثالي لعميل إدارة قاعدة البيانات الذي يحتاج إلى إدارة متقدمة لحاويات خادم SQL عبر .NET Aspire"},"recommendation":{"en":"Empowers agents to manage SQL Server containers using the Script-Load pattern, providing database schema definitions and initialization capabilities via .NET Aspire and SQL Server containers, leveraging scripts from `scripts/database/`","zh":"使代理能够使用 Script-Load 模式管理 SQL Server 容器，通过 .NET Aspire 和 SQL Server 容器提供数据库模式定义和初始化功能，利用 `scripts/database/` 中的脚本","ja":"エージェントが Script-Load パターンを使用して SQL Server コンテナを管理できるようにし、.NET Aspire と SQL Server コンテナを使用してデータベース スキーマ定義と初期化機能を提供し、`scripts/database/` のスクリプトを利用します","ko":"에이전트가 Script-Load 패턴을 사용하여 SQL Server 컨테이너를 관리할 수 있도록 하며, .NET Aspire 및 SQL Server 컨테이너를 사용하여 데이터베이스 스키마 정의 및 초기화 기능을 제공하며, `scripts/database/`의 스크립트를 활용합니다","es":"Habilita a los agentes a gestionar contenedores de SQL Server utilizando el patrón Script-Load, proporcionando definiciones de esquemas de bases de datos y capacidades de inicialización a través de .NET Aspire y contenedores de SQL Server, aprovechando scripts de `scripts/database/`","fr":"Permet aux agents de gérer des conteneurs SQL Server en utilisant le modèle Script-Load, en fournissant des définitions de schémas de base de données et des capacités d''initialisation via .NET Aspire et des conteneurs SQL Server, en exploitant des scripts de `scripts/database/`","de":"Ermöglicht es Agenten, SQL-Server-Container mithilfe des Script-Load-Musters zu verwalten, wodurch Datenbank-Schema-Definitionen und Initialisierungsfunktionen über .NET Aspire und SQL-Server-Container bereitgestellt werden, indem Skripte aus `scripts/database/` genutzt werden","pt":"Habilita os agentes a gerenciar contêineres do SQL Server usando o padrão Script-Load, fornecendo definições de esquema de banco de dados e capacidades de inicialização via .NET Aspire e contêineres do SQL Server, aproveitando scripts de `scripts/database/`","ru":"Наделяет агентов возможностью управлять контейнерами SQL Server с помощью шаблона Script-Load, предоставляя определения схемы базы данных и возможности инициализации через .NET Aspire и контейнеры SQL Server, используя скрипты из `scripts/database/`","ar":"تمكّن العميل من إدارة حاويات خادم SQL باستخدام نمط تحميل البرامج النصية، وتوفير تعريفات مخطط قاعدة البيانات وقدرات التهيئة عبر .NET Aspire وحاويات خادم SQL، واستخدام البرامج النصية من `scripts/database/`"},"useCases":{"en":["Initializing database schema definitions","Managing SQL Server containers","Updating seed data and column modifications"],"zh":["初始化数据库模式定义","管理 SQL Server 容器","更新种子数据和列修改"],"ja":["データベース スキーマ定義の初期化","SQL Server コンテナの管理","シード データと列の変更の更新"],"ko":["데이터베이스 스키마 정의 초기화","SQL Server 컨테이너 관리","시드 데이터 및 열 수정 업데이트"],"es":["Inicialización de definiciones de esquemas de bases de datos","Gestión de contenedores de SQL Server","Actualización de datos iniciales y modificaciones de columnas"],"fr":["Initialisation des définitions de schémas de base de données","Gestion de conteneurs SQL Server","Mise à jour des données initiales et des modifications de colonnes"],"de":["Initialisierung von Datenbank-Schema-Definitionen","Verwaltung von SQL-Server-Containern","Aktualisierung von Startdaten und Spaltenänderungen"],"pt":["Inicialização de definições de esquema de banco de dados","Gerenciamento de contêineres do SQL Server","Atualização de dados de inicialização e modificações de coluna"],"ru":["Инициализация определений схемы базы данных","Управление контейнерами SQL Server","Обновление стартовых данных и изменений столбцов"],"ar":["تخضيع تعريفات مخطط قاعدة البيانات","إدارة حاويات خادم SQL","تحديث بيانات البذرة وتعديلات العمود"]},"limitations":{"en":["Does not use `dotnet ef migrations`","Requires .NET Aspire (`MoreSpeakers.AppHost`)","Specific to SQL Server containers"],"zh":["不使用 `dotnet ef migrations`","需要 .NET Aspire (`MoreSpeakers.AppHost`)","仅限 SQL Server 容器"],"ja":["`dotnet ef migrations` を使用しない",".NET Aspire (`MoreSpeakers.AppHost`) が必要","SQL Server コンテナ専用"],"ko":["`dotnet ef migrations`를 사용하지 않음",".NET Aspire (`MoreSpeakers.AppHost`)가 필요","SQL Server 컨테이너 전용"],"es":["No utiliza `dotnet ef migrations`","Requiere .NET Aspire (`MoreSpeakers.AppHost`)","Específico para contenedores de SQL Server"],"fr":["N''utilise pas `dotnet ef migrations`","Nécessite .NET Aspire (`MoreSpeakers.AppHost`)","Spécifique aux conteneurs SQL Server"],"de":["Verwendet nicht `dotnet ef migrations`","Benötigt .NET Aspire (`MoreSpeakers.AppHost`)","Spezifisch für SQL-Server-Container"],"pt":["Não usa `dotnet ef migrations`","Requer .NET Aspire (`MoreSpeakers.AppHost`)","Específico para contêineres do SQL Server"],"ru":["Не использует `dotnet ef migrations`","Требует .NET Aspire (`MoreSpeakers.AppHost`)","Конкретно для контейнеров SQL Server"],"ar":["لا يستخدم `dotnet ef migrations`","يتطلب .NET Aspire (`MoreSpeakers.AppHost`)","محدد لحاويات خادم SQL"]},"version":4},"contentHash":"4fd38b8c2b659a27afbb17d8a65f34183a5eb26f57eb88a742dee6fb2f83f16d","qualityScore":36}');
