gic in src/MoreSpeakers.AppHost/AppHost.cs sql-schema is a skill for managing SQL Server container initialization and database schema definitions using a Script-Load pattern');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rukikotoo/AutoRegMonkey/rag', 'community', 'rukikotoo', 'AutoRegMonkey', 'rukikotoo/AutoRegMonkey', 'rag', 6, 1, 36, '2025-12-10T07:44:13Z', '2026-03-06T06:52:05.844Z', '1fc5adf320da65a90498ce40143c5a48349cdbe79582fb07bc73646164b3658b', '{"id":"rukikotoo/AutoRegMonkey/rag","name":"rag","description":{"en":"The RAG skill enables AI agents to query the FAISS vector database, built on Bruce Hansen''s econometrics textbook. It benefits developers and data scientists working with econometric models.","zh":"RAG 查询技能允许代理查询计量经济学 RAG 知识库，使用 FAISS 向量数据库和 Python 脚本","ja":"RAG クエリ スキルは、FAISS ベクトル データベースと Python スクリプトを使用して、計量経済学の RAG 知識ベースを検索します","ko":"RAG 쿼리 스킬은 FAISS 벡터 데이터베이스와 Python 스크립트를 사용하여 계량 경제학 RAG 지식 베이스를 검색합니다","es":"RAG es una habilidad que permite consultar la base de conocimientos de econometría utilizando FAISS y Python.","fr":"RAG est une compétence qui permet d''interroger la base de connaissances d''économétrie en utilisant FAISS et Python.","de":"RAG ist eine Fähigkeit, die es ermöglicht, auf die Ökonometrie-Knowledge-Base mit FAISS und Python zuzugreifen.","pt":"A habilidade RAG permite a consulta de conhecimento de economia com base no livro de economia de Bruce Hansen","ru":"Навык RAG позволяет запрашивать знания в области экономики на основе книги по экономике Брюса Хансена","ar":"تمكن مهارة RAG من استعلام معرفة الاقتصاد على أساس كتاب الاقتصاد لبروس هانسن"},"seo":{"title":{"en":"RAG: FAISS Vector Database Query Guide | AI Agent Skill","zh":"RAG 查询技能设置指南","ja":"RAG クエリ スキルセットアップ ガイド - AIエージェント","ko":"RAG 쿼리 스킬 설정 가이드 - AI 도구","es":"Guía de configuración de RAG: Consulta de conocimientos d...","fr":"Guide de configuration RAG : Interrogation de la base de ...","de":"RAG-Konfigurationsleitfaden: Abfrage der Ökonometrie-Know...","pt":"Guia de Configuração RAG: Consulta de Conhecimento de Eco...","ru