INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('safdarayubpk/flow/kafka-producer-pattern', 'kafka-producer-pattern', 'safdarayubpk', 'flow', 'community', 'kafka-producer-pattern safdarayubpk flow community The kafka-producer-pattern skill provides an async Kafka producer for FastAPI with user isolation. It benefits developers building scalable and secure data pipelines. Kafka Producer Pattern是一种用于FastAPI的异步Kafka生产者，提供了用户隔离和高性能的消息生产能力 Kafka Producer Patternは、FastAPI用の非同期Kafkaプロデューサーであり、ユーザー分離と高性能のメッセージ生成機能を提供します Kafka Producer Pattern은 FastAPI용 비동기 Kafka 프로듀서로 사용자 분리 및 고성능 메시지 생성 기능을 제공합니다 El patrón de productor de Kafka es un modelo de producción asíncrona para FastAPI que proporciona aislamiento de usuario obligatorio Le modèle de producteur Kafka est un modèle de production asynchrone pour FastAPI qui fournit une isolation utilisateur obligatoire Das Kafka-Producer-Muster ist ein Modell für asynchrone Produktion in FastAPI, das eine obligatorische Benutzerisolierung bietet O padrão de produtor Kafka para FastAPI oferece isolamento de usuário obrigatório e produção assíncrona. Aprenda a configurá-lo Паттерн продюсера Kafka для FastAPI обеспечивает обязательную изоляцию пользователей и асинхронную производительность. Узнайте, как его настроить نمط منتج كافكا لأداء سريع مع FastAPI يوفر عزلة المستخدم الإلزامية و الإنتاج غير المتزامن. تعرف على كيفية إعدادها how to use kafka-producer-pattern kafka-producer-pattern setup guide async Kafka producer for FastAPI kafka-producer-pattern vs traditional Kafka producers install kafka-producer-pattern kafka-producer-pattern alternative solutions what is kafka-producer-pattern kafka-producer-pattern tutorial kafka-producer-pattern best practices Kafka Producer Pattern FastAPI 异步Kafka生产者 用户隔离 AIOKafkaProducer get_producer函数 Kafka消息生产 FastAPI开发 AIエージェント Utilizes aiokafka for asynchronous Kafka production Implements mandatory user isolation for secure data processing Compatible with FastAPI for building scalable web applications Supports singleton producer creation for efficient resource management Handles Kafka unavailability with a fallback mechanism kafka-producer-pattern is an asynchronous Kafka producer implementation for FastAPI, ensuring mandatory user isolation and efficient data processing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AndreHogberg/summit-ui/tunit', 'community', 'AndreHogberg', 'summit-ui', 'AndreHogberg/summit-ui', 'tunit', 5, 1, 36, '2026-02-11T18:28:11Z', '2026-03-06T06:54:01.843Z', 'b9248a14cde1fcc12414b042837c4574103a30bcc57048bd3eee99f2d1c124ab', '{"id":"AndreHogberg/summit-ui/tunit","name":"tunit","description":{"en":"tunit is a headless Blazor component library for testing, benefiting developers with efficient test execution. It utilizes TUnit with Playwright for reliable testing.","zh":"TUnit 是一个 Headless Blazor 组件库，使用 TUnit 和 Playwright 运行测试。测试位于 tests/SummitUI.Tests.Playwright/ 目录中","ja":"TUnit はヘッドレス Blazor コンポーネント ライブラリです。TUnit と Playwright を使用してテストを実行します。テストは tests/SummitUI.Tests.Playwright/ ディレクトリにあります","ko":"TUnit은 헤드리스 블라조르 컴포넌트 라이브러리입니다. TUnit과 Playwright를 사용하여 테스트를 실행합니다. 테스트는 tests/SummitUI.Tests.Playwright/ 디렉토리에 있습니다","es":"TUnit es una biblioteca de componentes Blazor headless que utiliza Playwright para testing. Puedes ejecutar tests con dotnet run y limitar la ejecución paralela para evitar sobrecargas del sistema","fr":"TUnit est une bibliothèque de composants Blazor headless qui utilise Playwright pour les tests. Vous pouvez exécuter des tests avec dotnet run et limiter l''exécution parallèle pour éviter les surcharges du système","de":"TUnit ist eine headless-Blazor-Komponentenbibliothek, die Playwright für Testing verwendet. Sie können Tests mit dotnet run ausführen und die parallele Ausführung begrenzen, um Systemüberlastungen zu vermeiden","pt":"TUnit é uma biblioteca de componentes headless Blazor que utiliza Playwright para testes. Execute testes com comando dotnet run.","ru":"TUnit — это библиотека компонентов headless Blazor, использующая Playwright для тестирования. Запустите тесты с помощью команды dotnet run.","ar":"TUnit هي مكتبة مكونات Blazor بدون رأس تستخدم Playwright للاختبارات. قم بتشغيل الاختبارات باستخدام الأمر dotnet run."},"seo":{"title":{"en":"tunit: Headless Blazor Component Library Setup Guide | AI...","zh":"TUnit 设置指南：Headless Blazor 组件库","ja":"TUnit セットアップガイド：ヘッドレス Blazor コンポーネント ライブラリ","ko":"TUnit 설정 가이드: 헤드리스 블라조르 컴포넌트 라이브러리","es":"Guía de configuración de TUnit: Biblioteca de componentes...","fr":"Guide de configuration de TUnit: Bibliothèque de composan...","de":"TUnit-Setup-Anleitung: Headless-Blazor-Komponentenbibliothek","pt":"Guia de Configuração do TUnit: Biblioteca de Componentes ...","ru":"Настройка TUnit: ИИ Агент для Headless Blazor Компонентов","ar":"دليل إعداد TUnit: مكتبة مكونات Blazor بدون رأس"},"description":{"en":"Discover how to run TUnit tests with Playwright and optimize parallel test execution - get started with tunit today!","zh":"了解 TUnit，一个 Headless Blazor 组件库，用于简化测试。使用 TUnit 和 Playwright 运行测试","ja":"TUnit について学ぶ：ヘッドレス Blazor コンポーネント ライブラリ。TUnit と Playwright を使用してテストを実行する","ko":"TUnit에 대해 알아보기: 헤드리스 블라조르 컴포넌트 라이브러리. TUnit과 Playwright를 사용하여 테스트를 실행","es":"Aprende a configurar y ejecutar tests con TUnit, una biblioteca de componentes Blazor headless, utilizando Playwright para testing","fr":"Découvrez comment configurer et exécuter des tests avec TUnit, une bibliothèque de composants Blazor headless, en utilisant Playwright pour les tests","de":"Erfahren Sie, wie Sie TUnit, eine headless-Blazor-Komponentenbibliothek, konfigurieren und Tests mit Playwright ausführen","pt":"Aprenda a configurar e executar testes com TUnit, uma biblioteca de componentes headless Blazor com Playwright","ru":"Узнайте, как настроить и запустить тесты с TUnit, библиотекой компонентов headless Blazor с Playwright","ar":"تعلم كيفية تكوين وتنفيذ الاختبارات باستخدام TUnit، مكتبة مكونات Blazor بدون رأس مع Playwright"},"definition":{"en":"tunit is a headless Blazor component library that uses TUnit with Playwright for testing purposes.","zh":"TUnit 是一个 Headless Blazor 组件库，用于简化测试","ja":"TUnit はヘッドレス Blazor コンポーネント ライブラリです","ko":"TUnit은 헤드리스 블라조르 컴포넌트 라이브러리입니다","es":"TUnit es una biblioteca de componentes Blazor headless que permite la ejecución de tests con Playwright","fr":"TUnit est une bibliothèque de composants Blazor headless qui permet l''exécution de tests avec Playwright","de":"TUnit ist eine headless-Blazor-Komponentenbibliothek, die die Ausführung von Tests mit Playwright ermöglicht","pt":"TUnit é uma biblioteca de componentes headless Blazor para testes automatizados","ru":"TUnit — это библиотека компонентов headless Blazor для автоматизированного тестирования","ar":"TUnit هي مكتبة مكونات Blazor بدون رأس للاختبارات الآلية"},"features":{"en":["Runs TUnit tests with Playwright for reliable testing","Supports running all tests with a single command using `dotnet run`","Allows running tests with limited parallelism using `--maximum-parallel-tests` flag","Stores tests in the `tests/SummitUI.Tests.Playwright/` directory","Utilizes `dotnet run` command for test execution"],"zh":["使用 TUnit 和 Playwright 运行测试","支持 Headless Blazor 组件","测试位于 tests/SummitUI.Tests.Playwright/ 目录中","支持限流并行测试执行","使用 dotnet run 命令运行测试"],"ja":["TUnit と Playwright を使用してテストを実行する","ヘッドレス Blazor コンポーネントをサポートする","テストは tests/SummitUI.Tests.Playwright/ ディレクトリにあります","限流並行テスト実行をサポートする","dotnet run コマンドを使用してテストを実行する"],"ko":["TUnit과 Playwright를 사용하여 테스트를 실행","헤드리스 블라조르 컴포넌트를 지원","테스트는 tests/SummitUI.Tests.Playwright/ 디렉토리에 있습니다","제한된 병렬 테스트 실행을 지원","dotnet run 명령을 사용하여 테스트를 실행"],"es":["Ejecución de tests con Playwright","Limitación de la ejecución paralela para evitar sobrecargas del sistema","Uso de dotnet run para ejecutar tests","Compatibilidad con Blazor headless","Integración con SummitUI.Tests.Playwright"],"fr":["Exécution de tests avec Playwright","Limitation de l''exécution parallèle pour éviter les surcharges du système","Utilisation de dotnet run pour exécuter des tests","Compatibilité avec Blazor headless","Intégration avec SummitUI.Tests.Playwright"],"de":["Ausführung von Tests mit Playwright","Begrenzung der parallelen Ausführung, um Systemüberlastungen zu vermeiden","Verwendung von dotnet run zur Ausführung von Tests","Kompatibilität mit Blazor headless","Integration mit SummitUI.Tests.Playwright"],"pt":["Utiliza Playwright para testes","Executa testes com comando dotnet run","Suporta testes com paralelismo limitado","Permite execução de testes sequenciais","Integração com Blazor para testes de componentes"],"ru":["Использует Playwright для тестирования","Запускает тесты с помощью команды dotnet run","Поддерживает тесты с ограниченным параллелизмом","Позволяет выполнять тесты последовательно","Интегрируется с Blazor для тестирования компонентов"],"ar":["تستخدم Playwright للاختبارات","تشغيل الاختبارات باستخدام الأمر dotnet run","دعم الاختبارات مع تعددية محدودة","السماح بتنفيذ الاختبارات بالتسلسل","التكامل مع Blazor لاختبارات المكونات"]},"keywords":{"en":["how to use tunit","tunit setup guide","tunit alternative","tunit vs Playwright","headless Blazor component library","TUnit testing with Playwright","running TUnit tests","tunit install","what is tunit"],"zh":["TUnit","Headless Blazor","Playwright","dotnet run","测试","限流并行测试","AIエージェント","Blazor 组件库"],"ja":["TUnit","ヘッドレス Blazor","Playwright","dotnet run","テスト","限流並行テスト","AIエージェント","Blazor コンポーネント ライブラリ"],"ko":["TUnit","헤드리스 블라조르","Playwright","dotnet run","테스트","제한된 병렬 테스트","AI 에이전트","블라조르 컴포넌트 라이브러리"],"es":["TUnit","Blazor headless","Playwright","testing","dotnet run","SummitUI.Tests.Playwright","biblioteca de componentes","herramientas de testing","desarrollo de software"],"fr":["TUnit","Blazor headless","Playwright","testing","dotnet run","SummitUI.Tests.Playwright","bibliothèque de composants","outils de testing","développement de logiciels"],"de":["TUnit","Blazor headless","Playwright","Testing","dotnet run","SummitUI.Tests.Playwright","Komponentenbibliothek","Testtools","Softwareentwicklung"],"pt":["tunit","blazor headless","playwright","testes automatizados","dotnet run","paralelismo limitado","testes sequenciais","desenvolvimento de software"],"ru":["tunit","blazor headless","playwright","автоматизированное тестирование","dotnet run","ограниченный параллелизм","последовательные тесты","разработка программного обеспечения"],"ar":["tunit","blazor بدون رأس","playwright","اختبارات آلية","dotnet run","تعددية محدودة","اختبارات متسلسلة","تطوير البرمجيات"]}},"owner":"AndreHogberg","repo":"summit-ui","repoPath":"AndreHogberg/summit-ui","stars":5,"forks":1,"updatedAt":"2026-02-11T18:28:11Z","topics":[],"category":"community","skillMd":{"name":"tunit","description":"Run TUnit tests with Playwright. Use when user asks to run tests, execute tests, or check if tests pass.","bodyPreview":"# Running TUnit Tests\n\nThis project uses TUnit with Playwright for testing. Tests are located in `tests/SummitUI.Tests.Playwright/`.\n\n## Run All Tests\n\n```bash\ndotnet run --project tests/SummitUI.Tests.Playwright\n```\n\n## Run Tests with Limited Parallelism (Recommended)\n\nTo prevent system overload when running Playwright tests, limit parallel test execution:\n\n```bash\n# Run with maximum 1 parallel test (sequential)\ndotnet run --project tests/SummitUI.Tests.Playwright -- --maximum-parallel-tests 1","body":"# Running TUnit Tests\n\nThis project uses TUnit with Playwright for testing. Tests are located in `tests/SummitUI.Tests.Playwright/`.\n\n## Run All Tests\n\n```bash\ndotnet run --project tests/SummitUI.Tests.Playwright\n```\n\n## Run Tests with Limited Parallelism (Recommended)\n\nTo prevent system overload when running Playwright tests, limit parallel test execution:\n\n```bash\n# Run with maximum 1 parallel test (sequential)\ndotnet run --project tests/SummitUI.Tests.Playwright -- --maximum-parallel-tests 1\n\n# Run with maximum 8 parallel tests\ndotnet run --project tests/SummitUI.Tests.Playwright -- --maximum-parallel-tests 8\n```\n## Run Tests with Filters\n\nTUnit uses `--treenode-filter` with path pattern: `/assembly/namespace/class/test`\n\nFilter by class name:\n```bash\ndotnet run --project SummitUI.Tests.Playwright -- --treenode-filter ''/*/*/ClassName/*''\n```\n\nFilter by exact test name:\n```bash\ndotnet run --project SummitUI.Tests.Playwright -- --treenode-filter ''/*/*/*/TestName''\n```\n\nExamples:\n```bash\n# Run all Select accessibility tests\ndotnet run --project tests/SummitUI.Tests.Playwright -- --treenode-filter ''/*/*/SelectAccessibilityTests/*''\n\n# Run specific test by name\ndotnet run --project tests/SummitUI.Tests.Playwright -- --treenode-filter ''/*/*/*/Trigger_ShouldHave_RoleCombobox''\n\n# Run tests matching pattern (wildcard in test name)\ndotnet run --project tests/SummitUI.Tests.Playwright -- --treenode-filter ''/*/*/*/Keyboard*''\n\n# Run all tests in namespace\ndotnet run --project tests/SummitUI.Tests.Playwright -- --treenode-filter ''/*/SummitUI.Tests.Playwright/*/*''\n```\n\n## Run Tests in Debug Mode\n\nWhen a debugger is attached, Playwright will run in debug mode (`PWDEBUG=1`) automatically via the `Hooks.cs` setup.\n\n## View Test Output\n\nAdd `--report` flags for different output formats:\n```bash\n# Console output with details\ndotnet run --project tests/SummitUI.Tests.Playwright -- --output-format console-detailed\n\n# Generate TRX report\ndotnet run --project tests/SummitUI.Tests.Playwright -- --report-trx\n```\n\n## Flakiness Mitigation\n\nThe test project includes several features to reduce flakiness:\n\n1. **Automatic Retries**: Tests are automatically retried up to 2 times on failure (`[Retry(2)]` in GlobalSetup.cs)\n2. **Fully Sequential Execution**: All tests run sequentially via `[assembly: NotInParallel]` in GlobalSetup.cs\n3. **Server Readiness Check**: `Hooks.cs` waits for the Blazor server to be fully ready before tests start\n4. **Extended Timeouts**: Configured via `tunit.json` for longer test and hook timeouts\n\n## Project Structure\n\n- `GlobalSetup.cs` - Assembly-level test configuration (retries, parallelism)\n- `Hooks.cs` - Test session setup/teardown (starts Blazor server)\n- `BlazorWebApplicationFactory.cs` - WebApplicationFactory for hosting the test server\n- `tunit.json` - TUnit configuration file\n- `*AccessibilityTests.cs` - Accessibility test classes inheriting from `PageTest`\n\n## Test Conventions\n\n- Tests inherit from `TUnit.Playwright.PageTest` to get `Page` access\n- Use `[Before(Test)]` for per-test setup\n- Use `[Before(TestSession)]` / `[After(TestSession)]` for session-wide setup\n- Access the running server via `Hooks.ServerUrl`\n"},"lastSynced":"2026-03-06T06:54:01.843Z","agentAnalysis":{"suitability":{"en":"Ideal for .NET Core Agents requiring efficient test execution and reliable testing with Playwright","zh":"适用于需要高效测试执行和可靠测试的 .NET Core Agents，搭配 Playwright","ja":".NET Core エージェントが効率的なテスト実行と信頼性の高いテストを必要とする場合に適しています。Playwright を使用します","ko":"효율적인 테스트 실행과 안정적인 테스트가 필요한 .NET Core 에이전트에 적합하며 Playwright를 사용합니다","es":"Ideal para agentes .NET Core que requieren una ejecución de pruebas eficiente y pruebas confiables con Playwright","fr":"Idéal pour les agents .NET Core nécessitant une exécution de tests efficace et des tests fiables avec Playwright","de":"Ideal für .NET Core-Agents, die eine effiziente Testausführung und zuverlässige Tests mit Playwright erfordern","pt":"Ideal para Agentes .NET Core que requerem execução de teste eficiente e testes confiáveis com Playwright","ru":"Идеально подходит для агентов .NET Core, требующих эффективного выполнения тестов и надежного тестирования с Playwright","ar":"مثالي لعميل .NET Core الذي يتطلب تنفيذاً 테ستياً فعالاً واختباراً موثوقاً مع Playwright"},"recommendation":{"en":"Empowers agents to run comprehensive tests with TUnit and Playwright, utilizing headless Blazor component libraries for efficient test execution and supporting limited parallelism to prevent system overload","zh":"赋予代理运行全面测试的能力，利用 TUnit 和 Playwright，并使用无头 Blazor 组件库以实现高效的测试执行，同时支持有限的并行性以防止系统过载","ja":"エージェントが TUnit と Playwright を使用して包括的なテストを実行できるようにし、ヘッドレス Blazor コンポーネント ライブラリを使用してテストの実行を効率化し、システムの過負荷を防ぐために限定的な並列性をサポートします","ko":"에이전트가 TUnit와 Playwright를 사용하여 종합적인 테스트를 실행할 수 있도록 하며, 헤드리스 Blazor 컴포넌트 라이브러리를 사용하여 테스트 실행을 효율화하고, 시스템 과부하를 방지하기 위해 제한된 병렬성을 지원합니다","es":"Habilita a los agentes a ejecutar pruebas integrales con TUnit y Playwright, utilizando bibliotecas de componentes Blazor sin cabeza para una ejecución de pruebas eficiente y soportando un paralelismo limitado para evitar la sobrecarga del sistema","fr":"Permet aux agents d''exécuter des tests complets avec TUnit et Playwright, en utilisant des bibliothèques de composants Blazor sans tête pour une exécution de tests efficace et en supportant un parallélisme limité pour éviter la surcharge du système","de":"Ermächtigt Agenten, umfassende Tests mit TUnit und Playwright durchzuführen, indem sie headless Blazor-Komponentenbibliotheken für eine effiziente Testausführung nutzen und einen begrenzten Parallelismus zur Vermeidung einer Systemüberlastung unterstützen","pt":"Habilita os agentes a executar testes abrangentes com TUnit e Playwright, utilizando bibliotecas de componentes Blazor headless para execução de teste eficiente e suportando paralelismo limitado para prevenir sobrecarga do sistema","ru":"Наделяет агентов возможностью выполнять комплексные тесты с помощью TUnit и Playwright, используя библиотеки компонентов Blazor headless для эффективного выполнения тестов и поддержки ограниченного параллелизма для предотвращения перегрузки системы","ar":"يمنح الوكلاء القدرة على تشغيل اختبارات شاملة مع TUnit و Playwright، وذلك باستخدام مكتبات مكونات Blazor headless لتنفيذ اختبارات فعالة ودعم تعامل محدود لمنع اِحْتِلال 系统"},"useCases":{"en":["Running automated tests with Playwright","Executing tests with limited parallelism to prevent system overload","Debugging Blazor component libraries with TUnit"],"zh":["使用 Playwright 运行自动化测试","使用有限的并行性执行测试以防止系统过载","使用 TUnit 调试 Blazor 组件库"],"ja":["Playwright を使用して自動テストを実行する","システムの過負荷を防ぐために限定的な並列性でテストを実行する","TUnit を使用して Blazor コンポーネント ライブラリをデバッグする"],"ko":["Playwright를 사용하여 자동화된 테스트를 실행하는 것","제한된 병렬성을 사용하여 시스템 과부하를 방지하면서 테스트를 실행하는 것","TUnit를 사용하여 Blazor 컴포넌트 라이브러리를 디버깅하는 것"],"es":["Ejecución de pruebas automatizadas con Playwright","Ejecución de pruebas con paralelismo limitado para evitar la sobrecarga del sistema","Depuración de bibliotecas de componentes Blazor con TUnit"],"fr":["Exécution de tests automatisés avec Playwright","Exécution de tests avec un parallélisme limité pour éviter la surcharge du système","Débogage de bibliothèques de composants Blazor avec TUnit"],"de":["Ausführen automatisierter Tests mit Playwright","Ausführen von Tests mit begrenztem Parallelismus, um eine Systemüberlastung zu vermeiden","Debuggen von Blazor-Komponentenbibliotheken mit TUnit"],"pt":["Execução de testes automatizados com Playwright","Execução de testes com paralelismo limitado para prevenir sobrecarga do sistema","Depuração de bibliotecas de componentes Blazor com TUnit"],"ru":["Выполнение автоматизированных тестов с Playwright","Выполнение тестов с ограниченным параллелизмом для предотвращения перегрузки системы","Отладка библиотек компонентов Blazor с TUnit"],"ar":["تشغيل الاختبارات الآلية مع Playwright","تنفيذ الاختبارات مع تعامل محدود لمنع اِحْتِلال سیستم","تصحيح أخطاء مكتبات مكونات Blazor مع TUnit"]},"limitations":{"en":["Requires .NET Core environment","Dependent on Playwright for testing","Limited parallelism recommended to prevent system overload"],"zh":[".NET Core 环境是必需的","依赖于 Playwright 进行测试","建议有限的并行性以防止系统过载"],"ja":[".NET Core 環境が必要","Playwright に依存してテストを実行する","システムの過負荷を防ぐために限定的な並列性が推奨される"],"ko":[".NET Core 환경이 필요합니다","Playwright에 의존하여 테스트를 실행합니다","시스템 과부하를 방지하기 위해 제한된 병렬성이 권장됩니다"],"es":["Requiere entorno .NET Core","Dependiente de Playwright para pruebas","Se recomienda un paralelismo limitado para evitar la sobrecarga del sistema"],"fr":["Nécessite un environnement .NET Core","Dépend de Playwright pour les tests","Un parallélisme limité est recommandé pour éviter la surcharge du système"],"de":["Benötigt .NET Core-Umgebung","Abhängig von Playwright für Tests","Ein begrenzter Parallelismus wird empfohlen, um eine Systemüberlastung zu vermeiden"],"pt":["Requer ambiente .NET Core","Dependente de Playwright para testes","Paralelismo limitado recomendado para prevenir sobrecarga do sistema"],"ru":["Требует среды .NET Core","Зависит от Playwright для тестирования","Рекомендуется ограниченный параллелизм для предотвращения перегрузки системы"],"ar":["يتطلب بيئة .NET Core","يعتمد على Playwright للاختبار","يوصى بتعامل محدود لمنع اِحْتِلال 系统"]},"version":4},"contentHash":"b9248a14cde1fcc12414b042837c4574103a30bcc57048bd3eee99f2d1c124ab","qualityScore":36}');
