INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AndreHogberg/summit-ui/tunit', 'tunit', 'AndreHogberg', 'summit-ui', 'community', 'tunit AndreHogberg summit-ui community tunit is a headless Blazor component library for testing, benefiting developers with efficient test execution. It utilizes TUnit with Playwright for reliable testing. TUnit 是一个 Headless Blazor 组件库，使用 TUnit 和 Playwright 运行测试。测试位于 tests/SummitUI.Tests.Playwright/ 目录中 TUnit はヘッドレス Blazor コンポーネント ライブラリです。TUnit と Playwright を使用してテストを実行します。テストは tests/SummitUI.Tests.Playwright/ ディレクトリにあります TUnit은 헤드리스 블라조르 컴포넌트 라이브러리입니다. TUnit과 Playwright를 사용하여 테스트를 실행합니다. 테스트는 tests/SummitUI.Tests.Playwright/ 디렉토리에 있습니다 TUnit es una biblioteca de componentes Blazor headless que utiliza Playwright para testing. Puedes ejecutar tests con dotnet run y limitar la ejecución paralela para evitar sobrecargas del sistema TUnit est une bibliothèque de composants Blazor headless qui utilise Playwright pour les tests. Vous pouvez exécuter des tests avec dotnet run et limiter l''exécution parallèle pour éviter les surcharges du système TUnit ist eine headless-Blazor-Komponentenbibliothek, die Playwright für Testing verwendet. Sie können Tests mit dotnet run ausführen und die parallele Ausführung begrenzen, um Systemüberlastungen zu vermeiden TUnit é uma biblioteca de componentes headless Blazor que utiliza Playwright para testes. Execute testes com comando dotnet run. TUnit — это библиотека компонентов headless Blazor, использующая Playwright для тестирования. Запустите тесты с помощью команды dotnet run. TUnit هي مكتبة مكونات Blazor بدون رأس تستخدم Playwright للاختبارات. قم بتشغيل الاختبارات باستخدام الأمر dotnet run. how to use tunit tunit setup guide tunit alternative tunit vs Playwright headless Blazor component library TUnit testing with Playwright running TUnit tests tunit install what is tunit TUnit Headless Blazor Playwright dotnet run 测试 限流并行测试 AIエージェント Blazor 组件库 Runs TUnit tests with Playwright for reliable testing Supports running all tests with a single command using `dotnet run` Allows running tests with limited parallelism using `--maximum-parallel-tests` flag Stores tests in the `tests/SummitUI.Tests.Playwright/` directory Utilizes `dotnet run` command for test execution tunit is a headless Blazor component library that uses TUnit with Playwright for testing purposes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jnealey-godaddy/designsetgo/lint', 'community', 'jnealey-godaddy', 'designsetgo', 'jnealey-godaddy/designsetgo', 'lint', 5, 6, 36, '2026-02-28T02:59:57Z', '2026-03-06T06:55:31.219Z', '3d50fd2c81f120c57d7a123e0b84de970eb63c649dd45ee4a05406dd4b938a55', '{"id":"jnealey-godaddy/designsetgo/lint","name":"lint","description":{"en":"The lint skill checks JavaScript, CSS, and PHP files for code quality and standards compliance, benefiting WordPress developers. It provides commands for auto-fixing issues and running all linters.","zh":"Lint 是一个代码质量检查工具，支持检查 JavaScript、CSS 和 PHP 代码。","ja":"Lint はコード品質チェックツールで、JavaScript、CSS、PHP コードをチェックします。","ko":"Lint는 코드 품질 관리를 위한 도구로 JavaScript, CSS, PHP 코드를 체크","es":"Lint es una herramienta para mejorar la calidad del código en proyectos WordPress. Permite comprobar y corregir errores en JavaScript, CSS y PHP","fr":"Lint est un outil pour améliorer la qualité du code dans les projets WordPress. Il permet de vérifier et de corriger les erreurs en JavaScript, CSS et PHP","de":"Lint ist ein Tool zur Verbesserung der Code-Qualität in WordPress-Projekten. Es ermöglicht die Überprüfung und Korrektur von Fehlern in JavaScript, CSS und PHP","pt":"O Lint é uma ferramenta de verificação de código que ajuda a garantir a qualidade e a conformidade com os padrões de codificação","ru":"Lint - это инструмент проверки кода, помогающий обеспечить качество и соответствие кодированию стандартам","ar":"Lint هو أداة فحص شفرة تساعد على ضمان جودة الشفرة وامتثالها لمعايير البرمجة"},"seo":{"title":{"en":"lint: Code Quality Setup Guide | AI Agent Skill","zh":"代码质量检查工具：Lint Setup Guide","ja":"AIエージェント：Lint ベストプラクティス","ko":"코드 품질 관리를 위한 Lint 설정 가이드","es":"Guía de configuración de Lint para WordPress","fr":"Guide de mise en place de Lint pour WordPress","de":"Lint-Setup-Anleitung für WordPress-Entwickler","pt":"Guia de Configuração do Lint para Desenvolvedores","ru":"ИИ Агент Lint: Руководство по Настройке","ar":"إعداد أداة الفحصLint للبرمجة"},"description":{"en":"Discover how to enforce coding standards with lint. Run lint commands for JavaScript, CSS, and PHP to ensure high-quality code. Get started now!","zh":"使用 Lint 检查 JavaScript、CSS 和 PHP 代码，确保代码质量和标准合规","ja":"Lint を使用して JavaScript、CSS、PHP コードをチェックし、コード品質と標準の遵守を確保する","ko":"Lint를 사용하여 JavaScript, CSS, PHP 코드를 체크하고 코드 품질 및 표준 준수를 보장","es":"Aprende a utilizar Lint para mejorar la calidad del código JavaScript, CSS y PHP en tus proyectos WordPress","fr":"Découvrez comment utiliser Lint pour améliorer la qualité du code JavaScript, CSS et PHP dans vos projets WordPress","de":"Erfahren Sie, wie Sie Lint nutzen können, um die Code-Qualität von JavaScript, CSS und PHP in Ihren WordPress-Projekten zu verbessern","pt":"Aprenda a configurar o Lint para melhorar a qualidade do código JavaScript, CSS e PHP com comandos personalizados","ru":"Узнайте, как настроить Lint для проверки качества кода JavaScript, CSS и PHP с помощью индивидуальных команд","ar":"تعلم كيفية ضبط أداة الفحص Lint لتحسين جودة التعليمات البرمجية JavaScript و CSS و PHP باستخدام أوامر مخصصة"},"definition":{"en":"lint is a code analysis tool that checks JavaScript, CSS, and PHP files for quality and standards compliance","zh":"Lint 是一个代码分析工具，用于检查代码质量和标准合规","ja":"Lint はコード分析ツールで、コード品質と標準の遵守をチェックする","ko":"Lint는 코드 분석 도구로 코드 품질 및 표준 준수를 체크","es":"Lint es una herramienta de análisis de código que verifica la calidad y los estándares de código en proyectos de software","fr":"Lint est un outil d''analyse de code qui vérifie la qualité et les normes de code dans les projets de logiciel","de":"Lint ist ein Code-Analyse-Tool, das die Code-Qualität und die Codestandards in Software-Projekten überprüft","pt":"O Lint é uma ferramenta de verificação de código que verifica a qualidade e a conformidade com os padrões de codificação","ru":"Lint - это инструмент проверки кода, который проверяет качество и соответствие кодированию стандартам","ar":"Lint هو أداة فحص شفرة التي تحقق من جودة الشفرة ومتطلبات البرمجة"},"features":{"en":["Runs lint commands for JavaScript using npm run lint:js","Auto-fixes JavaScript issues with npm run lint:js -- --fix","Checks CSS/SCSS files for quality and standards compliance with npm run lint:css","Supports PHP linting using WordPress Coding Standards with npm run lint:php","Allows running all linters with a single command: npm run lint:js && npm run lint:css && npm run lint:php"],"zh":["支持检查 JavaScript 代码","支持检查 CSS 和 SCSS 代码","支持检查 PHP 代码（WordPress 编码标准）","提供自动修复功能","支持运行所有 Lint 检查"],"ja":["JavaScript コードのチェックをサポート","CSS と SCSS コードのチェックをサポート","PHP コード（WordPress コーディング標準）のチェックをサポート","自動修復機能を提供","すべての Lint チェックの実行をサポート"],"ko":["JavaScript 코드 체크 지원","CSS 및 SCSS 코드 체크 지원","PHP 코드 체크 지원（WordPress 코딩 표준）","자동 수정 기능 제공","모든 Lint 체크 실행 지원"],"es":["Comprobación de código JavaScript con npm run lint:js","Corrección automática de errores en JavaScript con npm run lint:js -- --fix","Comprobación de código CSS y SCSS con npm run lint:css","Corrección automática de errores en CSS con npm run lint:css -- --fix","Comprobación de código PHP con npm run lint:php según las normas de codificación de WordPress"],"fr":["Vérification du code JavaScript avec npm run lint:js","Correction automatique des erreurs en JavaScript avec npm run lint:js -- --fix","Vérification du code CSS et SCSS avec npm run lint:css","Correction automatique des erreurs en CSS avec npm run lint:css -- --fix","Vérification du code PHP avec npm run lint:php selon les normes de codage de WordPress"],"de":["Überprüfung von JavaScript-Code mit npm run lint:js","Automatische Korrektur von Fehlern in JavaScript mit npm run lint:js -- --fix","Überprüfung von CSS- und SCSS-Code mit npm run lint:css","Automatische Korrektur von Fehlern in CSS mit npm run lint:css -- --fix","Überprüfung von PHP-Code mit npm run lint:php gemäß den WordPress-Codierungsstandards"],"pt":["Verificação de código JavaScript com npm run lint:js","Verificação de código CSS com npm run lint:css","Verificação de código PHP com npm run lint:php","Comandos personalizados para auto-correção de código","Compatibilidade com WordPress Coding Standards"],"ru":["Проверка кода JavaScript с помощью npm run lint:js","Проверка кода CSS с помощью npm run lint:css","Проверка кода PHP с помощью npm run lint:php","Индивидуальные команды для авто-исправления кода","Совместимость с WordPress Coding Standards"],"ar":["فحص شفرة JavaScript باستخدام npm run lint:js","فحص شفرة CSS باستخدام npm run lint:css","فحص شفرة PHP باستخدام npm run lint:php","أوامر مخصصة لتصحيح الشفرة تلقائيًا","التوافق مع معايير برمجة WordPress"]},"keywords":{"en":["how to use lint","what is lint","lint alternative","lint vs eslint","lint install","lint setup guide","wordpress linting","javascript linting","php linting"],"zh":["代码质量检查","Lint工具","JavaScript代码检查","CSS代码检查","PHP代码检查","代码标准合规","自动修复功能"],"ja":["AIエージェント","コード品質チェック","Lintツール","JavaScriptコードチェック","CSSコードチェック","PHPコードチェック","コード標準の遵守"],"ko":["코드 품질 관리","Lint 도구","JavaScript 코드 체크","CSS 코드 체크","PHP 코드 체크","코드 표준 준수","자동 수정 기능"],"es":["Lint para WordPress","análisis de código","mejora de la calidad del código","npm run lint:js","npm run lint:css","npm run lint:php","desarrollo de WordPress","herramientas de desarrollo"],"fr":["Lint pour WordPress","analyse de code","amélioration de la qualité du code","npm run lint:js","npm run lint:css","npm run lint:php","développement de WordPress","outils de développement"],"de":["Lint für WordPress","Code-Analyse","Verbesserung der Code-Qualität","npm run lint:js","npm run lint:css","npm run lint:php","WordPress-Entwicklung","Entwicklungstools"],"pt":["lint","ferramenta de verificação de código","qualidade de código","padrões de codificação","wordpress","javascript","css","php","desenvolvimento web"],"ru":["lint","инструмент проверки кода","качество кода","стандарты кодирования","wordpress","javascript","css","php","веб-разработка"],"ar":["lint","أداة فحص الشفرة","جودة الشفرة","معايير البرمجة","wordpress","javascript","css","php","تطوير الويب"]}},"owner":"jnealey-godaddy","repo":"designsetgo","repoPath":"jnealey-godaddy/designsetgo","stars":5,"forks":6,"updatedAt":"2026-02-28T02:59:57Z","topics":["block-editor","blocks","gutenberg","gutenberg-blocks","page-builder","wordpress","wordpress-blocks","wordpress-development","wordpress-plugin"],"category":"community","skillMd":{"name":"lint","description":"Lint and auto-fix JavaScript, CSS, and PHP files","bodyPreview":"Lint JavaScript, CSS, and PHP files for code quality and standards compliance.\n\n## Lint Commands\n\n**JavaScript:**\n\n```bash\nnpm run lint:js\n```\n\n**Auto-fix JavaScript:**\n\n```bash\nnpm run lint:js -- --fix\n```\n\n**CSS/SCSS:**\n\n```bash\nnpm run lint:css\n```\n\n**Auto-fix CSS:**\n\n```bash\nnpm run lint:css -- --fix\n```\n\n**PHP (WordPress Coding Standards):**\n\n```bash\nnpm run lint:php\n```\n\n**Run all linters:**\n\n```bash\nnpm run lint:js && npm run lint:css && npm run lint:php\n```\n\n## What Gets Checked\n\n**JavaS","body":"Lint JavaScript, CSS, and PHP files for code quality and standards compliance.\n\n## Lint Commands\n\n**JavaScript:**\n\n```bash\nnpm run lint:js\n```\n\n**Auto-fix JavaScript:**\n\n```bash\nnpm run lint:js -- --fix\n```\n\n**CSS/SCSS:**\n\n```bash\nnpm run lint:css\n```\n\n**Auto-fix CSS:**\n\n```bash\nnpm run lint:css -- --fix\n```\n\n**PHP (WordPress Coding Standards):**\n\n```bash\nnpm run lint:php\n```\n\n**Run all linters:**\n\n```bash\nnpm run lint:js && npm run lint:css && npm run lint:php\n```\n\n## What Gets Checked\n\n**JavaScript:**\n- ESLint with @wordpress/eslint-plugin\n- WordPress coding standards\n- No deprecated APIs\n- Proper i18n usage\n\n**CSS:**\n- Stylelint\n- BEM naming conventions\n- No duplicate selectors\n- Property ordering\n\n**PHP:**\n- WordPress PHP Coding Standards (WPCS)\n- Security best practices\n- Proper escaping and sanitization\n- Documentation standards\n\n## Before Committing\n\nAlways lint before committing:\n\n```bash\nnpm run lint:js -- --fix && npm run lint:css -- --fix\n```\n"},"lastSynced":"2026-03-06T06:55:31.219Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated JavaScript, CSS, and PHP linting capabilities.","zh":"非常适合需要自动化JavaScript、CSS和PHP linting功能的代码审查代理。","ja":"JavaScript、CSS、PHPのlinting機能を自動化する必要があるコードレビュー代理に最適です。","ko":"JavaScript, CSS, PHP 린팅 기능을 자동화해야 하는 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan capacidades de análisis automatizado de JavaScript, CSS y PHP.","fr":"Parfait pour les agents de révision de code nécessitant des capacités de analyse automatique de JavaScript, CSS et PHP.","de":"Perfekt für Code-Review-Agents, die automatisierte JavaScript-, CSS- und PHP-Linting-Funktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de capacidades de linting automatizadas para JavaScript, CSS e PHP.","ru":"Идеально подходит для агентов по проверке кода, которым необходимы автоматические возможности проверки JavaScript, CSS и PHP.","ar":"مثالي لعميل مراجعة الشفرة الذي يحتاج إلى قدرات التلين التلقائي لجافا سكريبت و CSS و PHP."},"recommendation":{"en":"Empowers agents to enforce code quality and standards compliance using npm scripts, checking JavaScript, CSS, and PHP files, and auto-fixing issues with protocols like npm run lint:js, npm run lint:css, and npm run lint:php.","zh":"赋予代理人使用npm脚本执行代码质量和标准合规性检查的能力，包括检查JavaScript、CSS和PHP文件，并使用npm run lint:js、npm run lint:css和npm run lint:php等协议自动修复问题。","ja":"npmスクリプトを使用してコードの品質と規格の準拠を強制するエージェントを可能にします。JavaScript、CSS、PHPファイルをチェックし、npm run lint:js、npm run lint:css、npm run lint:phpなどのプロトコルで問題を自動修復します。","ko":"에이전트가 npm 스크립트를 사용하여 코드 품질과 표준 준수를 강제할 수 있도록 합니다. JavaScript, CSS, PHP 파일을 확인하고 npm run lint:js, npm run lint:css, npm run lint:php 등의 프로토콜로 문제를 자동으로 수정합니다.","es":"Permite a los agentes aplicar la calidad del código y el cumplimiento de los estándares utilizando scripts de npm, comprobando archivos JavaScript, CSS y PHP, y solucionando problemas automáticamente con protocolos como npm run lint:js, npm run lint:css y npm run lint:php.","fr":"Permet aux agents d''appliquer la qualité du code et la conformité aux normes en utilisant des scripts npm, en vérifiant les fichiers JavaScript, CSS et PHP, et en corrigeant automatiquement les problèmes avec des protocoles tels que npm run lint:js, npm run lint:css et npm run lint:php.","de":"Ermächtigt Agents, die Codequalität und Standardskonformität mit npm-Skripten durchzusetzen, indem JavaScript-, CSS- und PHP-Dateien überprüft und Probleme mit Protokollen wie npm run lint:js, npm run lint:css und npm run lint:php automatisch behoben werden.","pt":"Habilite os agentes a impor a qualidade do código e o cumprimento dos padrões utilizando scripts npm, verificando arquivos JavaScript, CSS e PHP e corrigindo automaticamente problemas com protocolos como npm run lint:js, npm run lint:css e npm run lint:php.","ru":"Наделяет агентов возможностью обеспечивать качество кода и соблюдение стандартов с помощью скриптов npm, проверки файлов JavaScript, CSS и PHP, а также автоматического исправления проблем с помощью протоколов, таких как npm run lint:js, npm run lint:css и npm run lint:php.","ar":"تمكين العميل من فرض جودة الشفرة وموافقة المعايير باستخدام سكريبتات npm، وفحص الملفات جافا سكريبت و CSS و PHP، وتعديل الأخطاء تلقائيًا باستخدام بروتوكولات مثل npm run lint:js، و npm run lint:css، و npm run lint:php."},"useCases":{"en":["Automating code quality checks for WordPress projects","Debugging JavaScript syntax errors with npm run lint:js -- --fix","Validating CSS standards compliance with npm run lint:css"],"zh":["自动执行WordPress项目的代码质量检查","使用npm run lint:js -- --fix调试JavaScript语法错误","使用npm run lint:css验证CSS标准合规性"],"ja":["WordPressプロジェクトのコード品質チェックを自動化する","npm run lint:js -- --fixを使用してJavaScriptの構文エラーをデバッグする","npm run lint:cssを使用してCSS規格の準拠を検証する"],"ko":["WordPress 프로젝트의 코드 품질 확인을 자동화하는 것","npm run lint:js -- --fix를 사용하여 JavaScript 구문 오류를 디버깅하는 것","npm run lint:css를 사용하여 CSS 표준 준수를 확인하는 것"],"es":["Automatizar comprobaciones de calidad de código para proyectos de WordPress","Depurar errores de sintaxis de JavaScript con npm run lint:js -- --fix","Validar el cumplimiento de los estándares CSS con npm run lint:css"],"fr":["Automatiser les vérifications de la qualité du code pour les projets WordPress","Déboguer les erreurs de syntaxe JavaScript avec npm run lint:js -- --fix","Valider la conformité aux normes CSS avec npm run lint:css"],"de":["Automatisieren von Codequalitätsprüfungen für WordPress-Projekte","Debuggen von JavaScript-Syntaxfehlern mit npm run lint:js -- --fix","Validieren der CSS-Standardskonformität mit npm run lint:css"],"pt":["Automatizar verificações de qualidade de código para projetos WordPress","Depurar erros de sintaxe JavaScript com npm run lint:js -- --fix","Validar conformidade com os padrões CSS com npm run lint:css"],"ru":["Автоматизация проверок качества кода для проектов WordPress","Отладка ошибок синтаксиса JavaScript с помощью npm run lint:js -- --fix","Проверка соответствия стандартам CSS с помощью npm run lint:css"],"ar":["تأتمتة فحص جودة الشفرة لمشاريع ووردبريس","تصحيح أخطاء بناء جافا سكريبت باستخدام npm run lint:js -- --fix","التحقق من مطابقة معايير CSS باستخدام npm run lint:css"]},"limitations":{"en":["Requires npm installation","Limited to JavaScript, CSS, and PHP files","Dependent on WordPress Coding Standards for PHP linting"],"zh":["需要npm安装","仅限于JavaScript、CSS和PHP文件","依赖于WordPress编码标准进行PHP linting"],"ja":["npmのインストールが必要","JavaScript、CSS、PHPファイルのみ","PHPのlintingではWordPressコーディング規格に依存"],"ko":["npm 설치가 필요함","JavaScript, CSS, PHP 파일만 해당함","PHP 린팅은 WordPress 코딩 표준에 의존함"],"es":["Requiere la instalación de npm","Limitado a archivos JavaScript, CSS y PHP","Dependiente de los estándares de codificación de WordPress para el análisis de PHP"],"fr":["Nécessite l''installation de npm","Limité aux fichiers JavaScript, CSS et PHP","Dépendant des normes de codage WordPress pour l''analyse PHP"],"de":["Benötigt die Installation von npm","Begrenzt auf JavaScript-, CSS- und PHP-Dateien","Abhängig von den WordPress-Coding-Standards für die PHP-Analyse"],"pt":["Exige instalação do npm","Limitado a arquivos JavaScript, CSS e PHP","Dependente dos Padrões de Codificação do WordPress para linting PHP"],"ru":["Требует установки npm","Ограничен файлами JavaScript, CSS и PHP","Зависит от стандартов кодирования WordPress для проверки PHP"],"ar":["يتطلب تثبيت npm","محدود بالملفات جافا سكريبت و CSS و PHP","يعتمد على معايير الترميز في ووردبريس للتلين PHP"]},"version":4},"contentHash":"3d50fd2c81f120c57d7a123e0b84de970eb63c649dd45ee4a05406dd4b938a55","qualityScore":36}');
