INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zatsit-oss/zats-greenscore/dev', 'dev', 'zatsit-oss', 'zats-greenscore', 'community', 'dev zatsit-oss zats-greenscore community apigreenscore ecoconception eroom hacktoberfest openapi The dev skill enables developers to work on UI projects based on the API Green Score and Eroom initiatives, benefiting those who need to quickly develop and test eco-friendly conceptions. dev是基于API Green Score和Eroom Initiative的UI项目，使用npm run dev命令启动开发服务器 devはAPI Green ScoreとEroom Initiativeに基づくUIプロジェクトで、npm run devコマンドで開発サーバーを起動します dev는 API Green Score와 Eroom Initiative 기반의 UI 프로젝트입니다. npm run dev 명령어를 사용하여 개발 서버를 시작합니다 El proyecto de UI dev se basa en la iniciativa API Green Score y Eroom, permitiendo el desarrollo de aplicaciones sostenibles. Inicia el servidor de desarrollo con npm run dev Le projet UI dev repose sur l''initiative API Green Score et Eroom, permettant le développement d''applications durables. Lancez le serveur de développement avec npm run dev Das UI-Projekt dev basiert auf der API Green Score- und Eroom-Initiative, ermöglicht die Entwicklung nachhaltiger Anwendungen. Starten Sie den Entwicklungsserver mit npm run dev O dev é uma ferramenta de desenvolvimento que permite iniciar o servidor de desenvolvimento com o comando npm run dev, habilitando o recarregamento quente para desenvolvimento rápido. Dev - это инструмент разработки, который позволяет запустить сервер разработки с помощью команды npm run dev, включая горячую перезагрузку для быстрой разработки. أداة Dev هي أداة تطوير تتيح تشغيل خادم التطوير باستخدام الأمر npm run dev، مع تمكين إعادة التحميل السريع لتحقيق تطوير سريع how to use dev dev setup guide what is dev dev alternative dev vs OpenAPI install dev dev for API Green Score dev for Eroom initiative npm run dev command dev开发环境 AIエージェント开发 npm run dev 热重载 API Green Score Eroom Initiative OpenAPI Hacktoberfest Starts the development server with the command npm run dev Enables hot reload for rapid development via http://localhost:4321 Utilizes OpenAPI for API development and integration Supports the API Green Score initiative for eco-friendly conceptions Compatible with the Eroom initiative for collaborative development Runs on the next available port if 4321 is occupied dev is a UI project based on the API Green Score initiative and Eroom initiative, utilizing npm and OpenAPI for development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JimScope/ender/sqlmodel-expert', 'community', 'JimScope', 'ender', 'JimScope/ender', 'sqlmodel-expert', 4, 0, 36, '2026-03-02T20:38:52Z', '2026-03-06T06:59:32.352Z', '4c1b3b67958c4b955390798c98278f482f9569a6f2608023654ef065950e57ab', '{"id":"JimScope/ender/sqlmodel-expert","name":"sqlmodel-expert","description":{"en":"sqlmodel-expert is a SaaS solution that enables developers to send SMS using advanced SQLModel patterns and comprehensive Alembic migrations. It benefits developers working with production databases.","zh":"SQLModel Expert 提供高级 SQLModel 模式和 Alembic 迁移功能，用于优化生产数据库性能","ja":"SQLModel Expert は AIエージェントの実装と生産性向上を支援するツールです","ko":"SQLModel Expert는 생산성 향상을 위한 고급 SQLModel 패턴과 Alembic 마이그레이션 기능을 제공합니다","es":"SQLModel Expert es una herramienta para crear modelos de datos avanzados y migraciones de base de datos con Alembic. Permite definir modelos de datos con campos personalizados y migrar bases de datos de producción de manera eficiente.","fr":"SQLModel Expert est un outil pour créer des modèles de données avancés et des migrations de base de données avec Alembic. Il permet de définir des modèles de données avec des champs personnalisés et de migrer des bases de données de production de manière efficace.","de":"SQLModel Expert ist ein Tool zum Erstellen erweiterter Datenmodelle und Datenbankmigrationen mit Alembic. Es ermöglicht die Definition von Datenmodellen mit benutzerdefinierten Feldern und die Migration von Produktionsdatenbanken auf effiziente Weise.","pt":"O SQLModel Expert é uma ferramenta para criar modelos de dados avançados e migrações Alembic para bancos de dados de produção","ru":"SQLModel Expert - это инструмент для создания продвинутых моделей данных и миграций Alembic для производственных баз данных","ar":"SQLModel Expert هو أداة لإنشاء نماذج بيانات متقدمة وعمليات نقل Alembic لبيانات