INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JimScope/vendel/sqlmodel-expert', 'sqlmodel-expert', 'JimScope', 'vendel', 'community', 'sqlmodel-expert JimScope vendel community sqlmodel-expert provides advanced SQLModel patterns and comprehensive Alembic migrations for production databases, benefiting developers working with Python and SQLModel. SQLModel Expert提供高级SQLModel模式和综合Alembic迁移，用于生产数据库管理 SQLModel Expertは、生産性の高いデータベース管理のための高度なSQLModelパターンと包括的なAlembicマイグレーションを提供します SQLModel Expert는 생산성 높은 데이터베이스 관리를 위한 고급 SQLModel 패턴과 전체적인 Alembic 마이그레이션을 제공합니다 SQLModel Expert es una herramienta para crear modelos de datos avanzados y migraciones de base de datos con Alembic para bases de datos de producción SQLModel Expert est un outil pour créer des modèles de données avancés et des migrations de base de données avec Alembic pour les bases de données de production SQLModel Expert ist ein Tool für die Erstellung von erweiterten Datenmodellen und Datenbankmigrationen mit Alembic für Produktionsdatenbanken O SQLModel Expert é uma ferramenta para criar padrões avançados de SQLModel e migrações Alembic para bases de dados de produção SQLModel Expert - это инструмент для создания продвинутых шаблонов SQLModel и миграций Alembic для баз данных производственного уровня SQLModel Expert هو أداة لإنشاء أنماط متقدمة من SQLModel وعمليات نقل Alembic للبيانات الإنتاجية how to use sqlmodel-expert sqlmodel-expert alternative sqlmodel-expert install what is sqlmodel-expert sqlmodel-expert vs Alembic sqlmodel-expert setup guide sqlmodel-expert python sqlmodel-expert SQLModel patterns sqlmodel-expert production databases SQLModel Expert AIエージェント Python开发 数据库管理 Alembic迁移 SQLModel模式 生产数据库 数据模型定义 Defines basic models using SQLModel and Field Utilizes Alembic migrations for production databases Supports table definition using SQLModel''s table=True parameter Includes indexing capabilities using Field''s index=True parameter Handles optional fields using Optional from typing Integrates datetime fields using datetime from datetime module sqlmodel-expert is an advanced SQLModel skill that provides comprehensive patterns and migrations for production databases using Python and Alembic.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CofficLab/GitOK/i18n-translate', 'community', 'CofficLab', 'GitOK', 'CofficLab/GitOK', 'i18n-translate', 3, 0, 36, '2026-03-01T01:50:10Z', '2026-03-06T07:02:50.802Z', '435cfc71862d989a0d52bf28a637e0b7ba0bb4c04c53c54800dab2db450e6cbc', '{"id":"CofficLab/GitOK/i18n-translate","name":"i18n-translate","description":{"en":"i18n-translate is a project management tool designed for iOS and macOS developers, simplifying the localization process by managing .xcstrings files and supporting Chinese translations.","zh":"i18n-translate是一个综合的项目管理工具，用于管理iOS/macOS项目中的本地化翻译","ja":"i18n-translateは、iOS/macOSプロジェクトのローカライズ翻訳を管理するための総合的なプロジェクト管理ツールです","ko":"i18n-translate는 iOS/macOS 프로젝트의 현지화 번역을 관리하는総合的な 프로젝트 관리 도구입니다","es":"i18n-translate es una herramienta de gestión de proyectos que administra los archivos .xcstrings para la traducción de proyectos iOS y macOS","fr":"i18n-translate est un outil de gestion de projets qui gère les fichiers .xcstrings pour la traduction de projets iOS et macOS","de":"i18n-translate ist ein Projektmanagement-Tool, das die Verwaltung von .xcstrings-Dateien für die Übersetzung von iOS- und macOS-Projekten übernimmt","pt":"O i18n-translate é uma ferramenta de gerenciamento de traduções para projetos iOS e macOS, que suporta arquivos .xcstrings e traduções em chinês simplificado e tradicional","ru":"ИИ Агент i18n-translate - это инструмент для управления переводами в проектах iOS и macOS, который поддерживает файлы .xcstrings и переводы на упрощенный и традиционный китайский","ar":"وحدة i18n-translate هي أداة لإدارة الترجمات في مشاريع iOS وmacOS، تدعم ملفات .xcstrings والترجمة للصينية المبسطة والتقليدية"},"seo":{"title":{"en":"i18n-translate: Simplify iOS Localization | AI Agent Skill","zh":"i18n-translate 本地化翻译管理设置指南","ja":"i18n-translate AIエージェントのセットアップガイド","ko":"i18n-translate 현지화 번역 관리 설정 가이드","es":"Guía de configuración de i18n-translate para proyectos iO...","fr":"Guide de démarrage pour i18n-translate dans les projets i...","de":"Einrichtungsleitfaden für i18n-translate in iOS- und macO...","pt":"Guia de Configuração do i18n-translate para Desenvolvedores","ru":"Настройка ИИ Агентов: i18n-translate для Разработчиков","ar":"دليل إعداد i18n-translate للأدوات الذكية للطورين"},"description":{"en":"Streamline your iOS project''s localization with i18n-translate. Discover how to manage .xcstrings files and automate translation tasks. Get started now!","zh":"使用i18n-translate管理iOS/macOS项目的本地化翻译，支持简体中文和繁体中文","ja":"i18n-translate AIエージェントを使用してiOS/macOSプロジェクトのローカライズ翻訳を管理する","ko":"i18n-translate를 사용하여 iOS/macOS 프로젝트의 현지화 번역을 관리합니다","es":"Aprende a usar i18n-translate para administrar tus archivos .xcstrings y simplificar la traducción de tus proyectos iOS y macOS","fr":"Découvrez comment utiliser i18n-translate pour gérer vos fichiers .xcstrings et simplifier la traduction de vos projets iOS et macOS","de":"Erfahren Sie, wie Sie i18n-translate verwenden, um Ihre .xcstrings-Dateien zu verwalten und die Übersetzung Ihrer iOS- und macOS-Projekte zu vereinfachen","pt":"Aprenda a usar o i18n-translate para gerenciar arquivos .xcstrings e traduções em projetos iOS e macOS, com suporte a chinês simplificado e tradicional","ru":"Узнайте, как использовать i18n-translate для управления файлами .xcstrings и переводами в проектах iOS и macOS, с поддержкой упрощенного и традиционного кита...","ar":"تعلم كيفية استخدام i18n-translate لإدارة ملفات .xcstrings والترجمة في مشاريع iOS وmacOS، مع دعم الصينية المبسطة والتقليدية"},"definition":{"en":"i18n-translate is a comprehensive tool for managing iOS and macOS localization, handling .xcstrings files and translations for simplified and traditional Chinese.","zh":"i18n-translate是一种用于管理iOS/macOS项目中本地化翻译的工具","ja":"i18n-translateは、iOS/macOSプロジェクトのローカライズ翻訳を管理するためのツールです","ko":"i18n-translate는 iOS/macOS 프로젝트의 현지화 번역을 관리하는 도구입니다","es":"i18n-translate es una herramienta para administrar la traducción de proyectos iOS y macOS mediante la gestión de archivos .xcstrings","fr":"i18n-translate est un outil pour gérer la traduction de projets iOS et macOS via la gestion de fichiers .xcstrings","de":"i18n-translate ist ein Tool zur Verwaltung von Übersetzungen in iOS- und macOS-Projekten durch die Verwaltung von .xcstrings-Dateien","pt":"O i18n-translate é uma ferramenta de gerenciamento de traduções para projetos iOS e macOS","ru":"ИИ Агент i18n-translate - это инструмент для управления переводами в проектах iOS и macOS","ar":"وحدة i18n-translate هي أداة لإدارة الترجمات في مشاريع iOS وmacOS"},"features":{"en":["Manages all .xcstrings files for iOS and macOS projects","Supports simplified Chinese (zh-Hans) and traditional Chinese (zh-HK) translations","Automates cleaning of stale entries using the clean_stale.py script","Checks for missing translations using the check_missing.py script","Integrates with Git for seamless version control"],"zh":["支持简体中文和繁体中文","自动清理过期条目","批量处理所有.xcstrings文件","检查缺失翻译","使用Python脚本进行翻译管理"],"ja":["簡体中文と繁体中文をサポート","期限切れのエントリを自動的にクリーンアップ","バッチ処理ですべての.xcstringsファイルを処理","欠落している翻訳をチェック","Pythonスクリプトを使用して翻訳を管理"],"ko":["简体中文과繁体中文을 지원","기한 만료 항목을 자동으로 정리","일괄 처리로 모든 .xcstrings 파일을 처리","누락된 번역을 확인","Python스크립트를 사용하여 번역을 관리"],"es":["Administración de archivos .xcstrings para la traducción","Soporte para Swift y SwiftUI","Limpieza de entradas obsoletas con Python","Comprobación de traducciones faltantes","Compatibilidad con Git para el control de versiones","Soporte para chino simplificado (zh-Hans) y chino tradicional (zh-HK)"],"fr":["Gestion des fichiers .xcstrings pour la traduction","Prise en charge de Swift et SwiftUI","Nettoyage des entrées obsolètes avec Python","Vérification des traductions manquantes","Compatibilité avec Git pour le contrôle de version","Prise en charge du chinois simplifié (zh-Hans) et du chinois traditionnel (zh-HK)"],"de":["Verwaltung von .xcstrings-Dateien für die Übersetzung","Unterstützung für Swift und SwiftUI","Bereinigung von veralteten Einträgen mit Python","Überprüfung von fehlenden Übersetzungen","Kompatibilität mit Git für die Versionskontrolle","Unterstützung für vereinfachtes Chinesisch (zh-Hans) und traditionelles Chinesisch (zh-HK)"],"pt":["Gerenciamento de arquivos .xcstrings","Suporte a traduções em chinês simplificado e tradicional","Limpeza de entradas obsoletas com o script clean_stale.py","Verificação de traduções ausentes com o script check_missing.py","Integração com o Git para controle de versão","Suporte a SwiftUI e Swift"],"ru":["Управление файлами .xcstrings","Поддержка переводов на упрощенный и традиционный китайский","Очистка устаревших записей с помощью скрипта clean_stale.py","Проверка отсутствующих переводов с помощью скрипта check_missing.py","Интеграция с Git для контроля версий","Поддержка SwiftUI и Swift"],"ar":["إدارة ملفات .xcstrings","دعم الترجمة للصينية المبسطة والتقليدية","تنظيف الإدخالات القديمة باستخدام سكريبت clean_stale.py","فحص الترجمات الناقصة باستخدام سكريبت check_missing.py","التكامل مع Git لمراقبة الإصدارات","دعم SwiftUI وSwift"]},"keywords":{"en":["how to use i18n-translate","i18n-translate alternative","i18n-translate setup guide","ios localization tool","macos localization management","xcstrings file management","swift localization","swiftui internationalization"],"zh":["i18n-translate","iOS本地化","macOS本地化","swift本地化","swiftui本地化","xcstrings文件管理"],"ja":["i18n-translate","iOSローカライズ","macOSローカライズ","swiftローカライズ","swiftuiローカライズ","xcstringsファイル管理","AIエージェント"],"ko":["i18n-translate","iOS현지화","macOS현지화","swift현지화","swiftui현지화","xcstrings파일 관리","AI도구"],"es":["i18n-translate","traducción de proyectos iOS","gestión de archivos .xcstrings","Swift","SwiftUI","Git","traducción al chino","herramientas de traducción","desarrollo de aplicaciones móviles"],"fr":["i18n-translate","traduction de projets iOS","gestion de fichiers .xcstrings","Swift","SwiftUI","Git","traduction en chinois","outils de traduction","développement d''applications mobiles"],"de":["i18n-translate","Übersetzung von iOS-Projekten","Verwaltung von .xcstrings-Dateien","Swift","SwiftUI","Git","Übersetzung ins Chinesische","ÜbersetzungsTools","Mobile App-Entwicklung"],"pt":["i18n-translate","gerenciamento de traduções","arquivos .xcstrings","traduções em chinês","SwiftUI","Swift","Git","controle de versão","desenvolvimento de aplicativos"],"ru":["ИИ Агент i18n-translate","управление переводами","файлы .xcstrings","переводы на китайский","SwiftUI","Swift","Git","контроль версий","разработка приложений"],"ar":["وحدة i18n-translate","إدارة الترجمات","ملفات .xcstrings","ترجمة الصينية","SwiftUI","Swift","Git","مراقبة الإصدارات","تطوير التطبيقات"]}},"owner":"CofficLab","repo":"GitOK","repoPath":"CofficLab/GitOK","stars":3,"forks":0,"updatedAt":"2026-03-01T01:50:10Z","topics":["git","swift","swiftui"],"category":"community","skillMd":{"name":"i18n-translate","description":"管理 iOS/macOS 应用的 *.xcstrings 本地化翻译文件。自动清理过期条目、检测缺失翻译、添加简繁体中文翻译。当用户需要处理翻译、补充缺失的 zh-Hans/zh-HK 翻译、或清理 *.xcstrings 文件时使用此 skill。","bodyPreview":"# iOS/macOS 本地化翻译管理\n\n管理项目中所有 `*.xcstrings` 文件的中文翻译，支持简体中文 (zh-Hans) 和繁体中文 (zh-HK)。\n\n## 工作流程\n\n处理翻译请求时，首先查找所有 .xcstrings 文件，然后按以下顺序执行：\n\n### 0. 查找所有 .xcstrings 文件\n\n```bash\nfind . -name \"*.xcstrings\" -not -path \".*\" | head -20\n```\n\n### 1. 清理过期条目\n\n```bash\npython3 scripts/clean_stale.py <文件路径>.xcstrings\n```\n\n删除所有 `extractionState` 为 `stale` 的条目。可批量处理所有文件：\n\n```bash\nfind . -name \"*.xcstrings\" -not -path \".*\" -exec python3 scripts/clean_stale.py {} \\;\n```\n\n### 2. 检查缺失翻译\n\n```bash\npython3 scripts/check_mis","body":"# iOS/macOS 本地化翻译管理\n\n管理项目中所有 `*.xcstrings` 文件的中文翻译，支持简体中文 (zh-Hans) 和繁体中文 (zh-HK)。\n\n## 工作流程\n\n处理翻译请求时，首先查找所有 .xcstrings 文件，然后按以下顺序执行：\n\n### 0. 查找所有 .xcstrings 文件\n\n```bash\nfind . -name \"*.xcstrings\" -not -path \".*\" | head -20\n```\n\n### 1. 清理过期条目\n\n```bash\npython3 scripts/clean_stale.py <文件路径>.xcstrings\n```\n\n删除所有 `extractionState` 为 `stale` 的条目。可批量处理所有文件：\n\n```bash\nfind . -name \"*.xcstrings\" -not -path \".*\" -exec python3 scripts/clean_stale.py {} \\;\n```\n\n### 2. 检查缺失翻译\n\n```bash\npython3 scripts/check_missing.py <文件路径>.xcstrings\n```\n\n输出缺失的 zh-Hans 和 zh-HK 翻译统计。可批量检查：\n\n```bash\nfor f in $(find . -name \"*.xcstrings\" -not -path \".*\"); do\n    echo \"=== $f ===\"\n    python3 scripts/check_missing.py \"$f\"\ndone\n```\n\n### 3. 添加翻译\n\n```bash\npython3 scripts/add_translation.py <文件路径>.xcstrings \"Key\" \"简体中文翻译\" \"繁體中文翻譯\"\n```\n\n- `<文件路径>.xcstrings`: 目标文件路径（必需）\n- `Key`: 条目的 key（必需）\n- `zh-Hans`: 简体中文翻译（必需）\n- `zh-HK`: 繁体中文翻译（可选，未提供时自动转换）\n\n### 4. 验证文件\n\n```bash\npython3 scripts/validate.py <文件路径>.xcstrings\n```\n\n验证 JSON 格式正确性并统计翻译完成度。可批量验证：\n\n```bash\nfor f in $(find . -name \"*.xcstrings\" -not -path \".*\"); do\n    echo \"=== $f ===\"\n    python3 scripts/validate.py \"$f\"\ndone\n```\n\n### 批量处理所有文件\n\n使用 `batch_process.py` 脚本一次性处理所有 .xcstrings 文件：\n\n```bash\n# 列出所有 .xcstrings 文件\npython3 scripts/batch_process.py list\n\n# 批量清理所有文件的过期条目\npython3 scripts/batch_process.py clean\n\n# 批量检查所有文件的缺失翻译\npython3 scripts/batch_process.py check\n\n# 批量验证所有文件的格式\npython3 scripts/batch_process.py validate\n\n# 指定项目目录\npython3 scripts/batch_process.py validate --dir /path/to/project\n```\n\n## 翻译原则\n\n- **占位符保持不变**: `%@`, `%lld`, `%1$@`, `%d` 等格式化占位符必须原样保留\n- **技术术语**: API, SQLite, Host 等专有名词可保持英文\n- **UI 文本**: 简洁明了，符合 macOS/iOS 应用习惯\n- **简繁转换**: `add_translation.py` 包含常见词汇的简繁转换映射\n\n## 使用示例\n\n```\n用户: 检查项目所有 xcstrings 文件缺少的翻译\n→ 运行 batch_process.py list 查看所有文件\n→ 运行 batch_process.py check 检查所有文件\n\n用户: 为 Core.xcstrings 中的 \"Copy\" 添加翻译\n→ 运行 add_translation.py Core/Core.xcstrings \"Copy\" \"拷贝\" \"拷貝\"\n\n用户: 清理所有 xcstrings 文件中过期的翻译条目\n→ 运行 batch_process.py clean\n\n用户: 验证所有翻译文件的格式和完成度\n→ 运行 batch_process.py validate\n\n用户: 处理特定目录下的翻译文件\n→ 运行 batch_process.py check --dir ./Modules\n```\n\n## 注意事项\n\n- 所有操作会直接修改指定的 `.xcstrings` 文件\n- 修改前建议先备份文件\n- JSON 缩进使用 2 个空格\n- 编码必须是 UTF-8\n- 批量处理时使用 `find` 命令过滤掉隐藏文件（`.*/.*`）\n"},"lastSynced":"2026-03-06T07:02:50.802Z","agentAnalysis":{"suitability":{"en":"Ideal for iOS/macOS Development Agents automating Xcode project localization workflows.","zh":"适用于iOS/macOS开发代理自动化Xcode项目本地化工作流程。","ja":"iOS/macOS開発エージェントのXcodeプロジェクトのローカライズワークフローを自動化するのに理想的です。","ko":"iOS/macOS 개발 에이전트의 Xcode 프로젝트 현지화 워크플로를 자동화하는 데 적합합니다.","es":"Ideal para agentes de desarrollo de iOS/macOS que automatizan flujos de trabajo de localización de proyectos de Xcode.","fr":"Idéal pour les agents de développement iOS/macOS qui automatisent les flux de travail de localisation de projets Xcode.","de":"Ideal für iOS/macOS-Entwicklungsagenten, die Xcode-Projekt-Übersetzungs-Workflows automatisieren.","pt":"Ideal para Agentes de Desenvolvimento do iOS/macOS que automatizam fluxos de trabalho de localização de projetos do Xcode.","ru":"Идеально подходит для агентов разработки iOS/macOS, автоматизирующих рабочие процессы локализации проектов Xcode.","ar":"مثالي لعميل التطوير لنظامي iOS/macOS الذي يقوم بتحويل سير عمل تحويل مشاريع Xcode إلى لغة محلية."},"recommendation":{"en":"Enables automated management of .xcstrings files for Chinese localization, including stale entry cleanup with extractionState filtering and missing translation detection for zh-Hans and zh-HK variants. Directly integrates with Xcode''s string catalog system through Python scripting.","zh":"实现了对.xcstrings文件的自动化管理，包括使用extractionState过滤清除过时条目和检测zh-Hans和zh-HK变体的缺失翻译。直接通过Python脚本集成到Xcode的字符串目录系统中。","ja":"extractionStateフィルタを使用した古いエントリのクリーンアップやzh-Hansとzh-HKバリアントの欠落翻訳の検出を含む.xcstringsファイルの自動化された管理を実現します。Pythonスクリプトを介してXcodeの文字列カタログシステムに直接統合します。","ko":"extractionState 필터를 사용하여 오래된 항목을 정리하고 zh-Hans 및 zh-HK 변형의 누락 번역을 감지하는 것을 포함한 .xcstrings 파일의 자동화된 관리를 구현합니다. Python 스크립트를 통해 Xcode의 문자열 카탈로그 시스템에 직접 통합됩니다.","es":"Habilita la gestión automatizada de archivos .xcstrings para la localización china, incluida la limpieza de entradas obsoletas con filtrado de extractionState y detección de traducciones perdidas para las variantes zh-Hans y zh-HK. Se integra directamente con el sistema de catálogo de cadenas de Xcode a través de scripting de Python.","fr":"Permet la gestion automatisée des fichiers .xcstrings pour la localisation chinoise, y compris le nettoyage des entrées obsolètes avec un filtrage extractionState et la détection des traductions manquantes pour les variantes zh-Hans et zh-HK. S''intègre directement au système de catalogue de chaînes de Xcode via le scripting Python.","de":"Ermöglicht die automatisierte Verwaltung von .xcstrings-Dateien für die chinesische Lokalisierung, einschließlich der Bereinigung veralteter Einträge mit extractionState-Filterung und Erkennung fehlender Übersetzungen für die Varianten zh-Hans und zh-HK. Integriert sich direkt in das Xcode-String-Katalog-System über Python-Skripting.","pt":"Permite a gestão automatizada de arquivos .xcstrings para localização chinesa, incluindo a limpeza de entradas obsoletas com filtragem de extractionState e detecção de traduções ausentes para as variantes zh-Hans e zh-HK. Integra-se diretamente com o sistema de catálogo de strings do Xcode por meio de script em Python.","ru":"Позволяет автоматизировать управление файлами .xcstrings для китайской локализации, включая очистку устаревших записей с помощью фильтрации extractionState и обнаружение отсутствующих переводов для вариантов zh-Hans и zh-HK. Прямо интегрируется с системой каталога строк Xcode через скрипты Python.","ar":"يسمح بإدارة آليّة لملفات .xcstrings من أجل الترجمة الصينيّة، بما في ذلك تنظيف الإدخالات القديمة مع مرشّح extractionState وتكتيك ترجمات مفقودة للطرز zh-Hans وzh-HK. يتكامل مباشرة مع نظام فهرس السلاسل في Xcode عبر البرمجة النصية Python."},"useCases":{"en":["Cleaning stale localization entries from .xcstrings files","Identifying missing Chinese translations in Xcode projects","Batch processing multiple .xcstrings files simultaneously","Maintaining translation consistency across iOS/macOS apps"],"zh":["从.xcstrings文件中清除过时的本地化条目","在Xcode项目中识别缺失的中文翻译","同时批量处理多个.xcstrings文件","在iOS/macOS应用程序中保持翻译的一致性"],"ja":["Xcodeプロジェクトの古いローカライズエントリを.xcstringsファイルからクリーンアップする","Xcodeプロジェクトで欠落した中国語翻訳を識別する","複数の.xcstringsファイルを同時にバッチ処理する","iOS/macOSアプリケーションで翻訳の一貫性を維持する"],"ko":["Xcode 프로젝트의 오래된 현지화 항목을 .xcstrings 파일에서 정리하는 것","Xcode 프로젝트에서 누락된 중국어 번역을 식별하는 것","동시에 여러 개의 .xcstrings 파일을 일괄 처리하는 것","iOS/macOS 애플리케이션에서 번역의 일관성을 유지하는 것"],"es":["Limpieza de entradas de localización obsoletas de archivos .xcstrings","Identificación de traducciones chinas perdidas en proyectos de Xcode","Procesamiento por lotes de múltiples archivos .xcstrings simultáneamente","Mantenimiento de la consistencia de la traducción en aplicaciones iOS/macOS"],"fr":["Nettoyage des entrées de localisation obsolètes des fichiers .xcstrings","Identification des traductions chinoises manquantes dans les projets Xcode","Traitement par lot de plusieurs fichiers .xcstrings simultanément","Maintien de la cohérence des traductions dans les applications iOS/macOS"],"de":["Bereinigung veralteter Lokalisierungseinträge von .xcstrings-Dateien","Erkennung fehlender chinesischer Übersetzungen in Xcode-Projekten","Stückweise Verarbeitung mehrerer .xcstrings-Dateien gleichzeitig","Beibehaltung der Übersetzungskonsistenz in iOS/macOS-Apps"],"pt":["Limpeza de entradas de localização obsoletas de arquivos .xcstrings","Identificação de traduções chinesas ausentes em projetos Xcode","Processamento em lote de vários arquivos .xcstrings simultaneamente","Manutenção da consistência de traduções em aplicativos iOS/macOS"],"ru":["Очистка устаревших записей локализации из файлов .xcstrings","Обнаружение отсутствующих китайских переводов в проектах Xcode","Пакетная обработка нескольких файлов .xcstrings одновременно","Поддержание согласованности переводов в приложениях iOS/macOS"],"ar":["تنظيف الإدخالات القديمة للترجمة من ملفات .xcstrings","تحديد الترجمات الصينيّة المفقودة في مشاريع Xcode","معالجة دفعة من ملفات .xcstrings متعددة في نفس الوقت","الحفاظ على اتساق الترجمات عبر تطبيقات iOS/macOS"]},"limitations":{"en":["Exclusively handles .xcstrings file format","Limited to Chinese translations (zh-Hans/zh-HK only)","Requires Python 3 environment","Dependent on Xcode project structure"],"zh":[".xcstrings文件格式専用","仅限于中文翻译（仅支持zh-Hans/zh-HK）","需要Python 3环境","依赖于Xcode项目结构"],"ja":[".xcstringsファイル形式のみを処理する","中国語翻訳のみをサポートする（zh-Hans/zh-HKのみ）","Python 3環境が必要","Xcodeプロジェクト構造に依存する"],"ko":[".xcstrings 파일 형식만専用","중국어 번역만 지원（zh-Hans/zh-HK만）","Python 3 환경 필요","Xcode 프로젝트 구조에 의존"],"es":["Exclusivamente maneja el formato de archivo .xcstrings","Limitado a traducciones chinas (solo zh-Hans/zh-HK)","Requiere entorno Python 3","Dependiente de la estructura del proyecto Xcode"],"fr":["Ne prend en charge que le format de fichier .xcstrings","Limité aux traductions chinoises (seulement zh-Hans/zh-HK)","Nécessite un environnement Python 3","Dépend de la structure du projet Xcode"],"de":["Behandelt ausschließlich das .xcstrings-Dateiformat","Begrenzt auf chinesische Übersetzungen (nur zh-Hans/zh-HK)","Benötigt Python-3-Umgebung","Abhängig von der Xcode-Projektstruktur"],"pt":["Lida exclusivamente com o formato de arquivo .xcstrings","Limitado a traduções chinesas (somente zh-Hans/zh-HK)","Exige ambiente Python 3","Dependente da estrutura do projeto Xcode"],"ru":["Использует исключительно формат файла .xcstrings","Ограничен китайскими переводами (только zh-Hans/zh-HK)","Требует среды Python 3","Зависит от структуры проекта Xcode"],"ar":["يتعلق حصريًا بتنسيق ملف .xcstrings","محدود بالترجمات الصينيّة (zh-Hans/zh-HK فقط)","يحتاج إلى بيئة Python 3","يعتمد على هيكل مشروع Xcode"]},"version":4},"contentHash":"435cfc71862d989a0d52bf28a637e0b7ba0bb4c04c53c54800dab2db450e6cbc","qualityScore":36}');
