INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CofficLab/GitOK/i18n-translate', 'i18n-translate', 'CofficLab', 'GitOK', 'community', 'i18n-translate CofficLab GitOK community git swift swiftui i18n-translate is a project management tool designed for iOS and macOS developers, simplifying the localization process by managing .xcstrings files and supporting Chinese translations. i18n-translate是一个综合的项目管理工具，用于管理iOS/macOS项目中的本地化翻译 i18n-translateは、iOS/macOSプロジェクトのローカライズ翻訳を管理するための総合的なプロジェクト管理ツールです i18n-translate는 iOS/macOS 프로젝트의 현지화 번역을 관리하는総合的な 프로젝트 관리 도구입니다 i18n-translate es una herramienta de gestión de proyectos que administra los archivos .xcstrings para la traducción de proyectos iOS y macOS i18n-translate est un outil de gestion de projets qui gère les fichiers .xcstrings pour la traduction de projets iOS et macOS i18n-translate ist ein Projektmanagement-Tool, das die Verwaltung von .xcstrings-Dateien für die Übersetzung von iOS- und macOS-Projekten übernimmt O i18n-translate é uma ferramenta de gerenciamento de traduções para projetos iOS e macOS, que suporta arquivos .xcstrings e traduções em chinês simplificado e tradicional ИИ Агент i18n-translate - это инструмент для управления переводами в проектах iOS и macOS, который поддерживает файлы .xcstrings и переводы на упрощенный и традиционный китайский وحدة i18n-translate هي أداة لإدارة الترجمات في مشاريع iOS وmacOS، تدعم ملفات .xcstrings والترجمة للصينية المبسطة والتقليدية how to use i18n-translate i18n-translate alternative i18n-translate setup guide ios localization tool macos localization management xcstrings file management swift localization swiftui internationalization i18n-translate iOS本地化 macOS本地化 swift本地化 swiftui本地化 xcstrings文件管理 Manages all .xcstrings files for iOS and macOS projects Supports simplified Chinese (zh-Hans) and traditional Chinese (zh-HK) translations Automates cleaning of stale entries using the clean_stale.py script Checks for missing translations using the check_missing.py script Integrates with Git for seamless version control i18n-translate is a comprehensive tool for managing iOS and macOS localization, handling .xcstrings files and translations for simplified and traditional Chinese.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xu-cell/ai-engineering-init/leniu-java-mq', 'community', 'xu-cell', 'ai-engineering-init', 'xu-cell/ai-engineering-init', 'leniu-java-mq', 3, 0, 36, '2026-03-03T05:25:40Z', '2026-03-06T07:03:22.582Z', '73ef4124d91f7c06d76306a9402700e445844a400a339f94bc8586e7d90310ed', '{"id":"xu-cell/ai-engineering-init/leniu-java-mq","name":"leniu-java-mq","description":{"en":"The leniu-java-mq AI Agent skill provides a standardized Java message queue implementation for event-driven architectures. It offers developers a structured framework built on JDK 21 with a `MqUtil` tool class and a `@MQMessageListener` annotation for consuming messages.","zh":"leniu-java-mq 是一个 Java 消息队列解决方案，提供了 AI 工程化的能力，包括消息发送、接收和处理等功能。它支持 JDK 21 版本，使用 MqUtil 作为消息工具","ja":"leniu-java-mq は Java メッセージキューソリューションで、AIエージェントによるメッセージ送信、受信、処理などの機能を提供します。JDK 21 版本をサポートし、MqUtil をメッセージツールとして使用します","ko":"leniu-java-mq는 자바 메시지 큐 솔루션으로 AI 에이전트를 이용한 메시지 전송, 수신, 처리 등의 기능을 제공합니다. JDK 21 버전을 지원하며, MqUtil를 메시지 툴로 사용합니다","es":"leniu-java-mq es una herramienta de cola de mensajes que facilita la integración de servicios en tus proyectos de desarrollo. Ofrece características como MqUtil y LeMqConstant.","fr":"leniu-java-mq est un outil de file d''attente qui facilite l''intégration de services dans vos projets de développement. Il propose des fonctionnalités comme MqUtil et LeMqConstant.","de":"leniu-java-mq ist ein Nachrichtenwarteschlangen-Tool, das die Integration von Diensten in Ihren Entwicklungsprojekten erleichtert. Es bietet Funktionen wie MqUtil und LeMqConstant.","pt":"O leniu-java-mq é uma ferramenta de mensagens que utiliza a arquitetura de três camadas para enviar e receber mensagens","ru":"leniu-java-mq - это инструмент для работы с сообщениями, использующий трехслойную архитектуру для отправки и приема сообщений","ar":"leniu-java-mq هو أداة رسائل تستخدم بنية من ثلاث طبقات لإرسال واستقبال الرسائل"},"seo":{"title":{"en":"leniu-java-mq: Java Message Queue Setup Guide | AI Agent ...","zh":"leniu-java-mq 设置指南：AI 工程化消息队列解决方案","ja":"leniu-java-mq Setup Guide: AIエージェントによるメッセージキューソリューション","ko":"leniu-java-mq 설정 가이드: AI 에이전트를 이용한 메시지 큐 솔루션","es":"leniu-java-mq: Guía de Configuración de Colas de Mensajes","fr":"leniu-java-mq: Guide de Mise en Place de Files d''Attente","de":"leniu-java-mq: Einrichtungsanleitung für Nachrichtenwarte...","pt":"Guia de Configuração leniu-java-mq para Desenvolvedores","ru":"Настройка leniu-java-mq: Лучшие Практики для Разработчиков","ar":"دليل إعداد leniu-java-mq لمنصة الإي الأجنت"},"description":{"en":"Implement a Java 21 message queue system using the leniu-java-mq AI Agent skill. Features MqUtil, @MQMessageListener annotation, and a three-layer core archi...","zh":"leniu-java-mq 是一个基于 Java 的消息队列解决方案，提供了 AI 工程化的能力，包括消息发送、接收和处理等功能","ja":"leniu-java-mq は Java ベースのメッセージキューソリューションで、AIエージェントによるメッセージ送信、受信、処理などの機能を提供します","ko":"leniu-java-mq는 자바 기반의 메시지 큐 솔루션으로 AI 에이전트를 이용한 메시지 전송, 수신, 처리 등의 기능을 제공합니다","es":"Descubre cómo configurar leniu-java-mq para una integración de colas de mensajes eficiente en tus proyectos de desarrollo","fr":"Découvrez comment configurer leniu-java-mq pour une intégration efficace de files d''attente dans vos projets de développement","de":"Erfahren Sie, wie Sie leniu-java-mq für eine effiziente Nachrichtenwarteschlangen-Integration in Ihren Entwicklungsprojekten einrichten","pt":"Aprenda a configurar e utilizar o leniu-java-mq com nossas dicas e práticas recomendadas para desenvolvedores","ru":"Узнайте, как настроить и использовать leniu-java-mq с нашими советами и лучшими практиками для разработчиков","ar":"تعرف على كيفية إعداد وتشغيل leniu-java-mq باستخدام نصائحنا وأفضل الممارسات لمنصة الإي الأجنت"},"definition":{"en":"leniu-java-mq is an AI Agent skill that codifies a Java message queue implementation standard. It provides a three-layer architecture (MsgSend→Listener→Handler), uses JDK 21, and includes the `@MQMessageListener` annotation and `MqUtil` class for sending and receiving messages.","zh":"leniu-java-mq 是一个 Java 消息队列解决方案，提供了 AI 工程化的能力","ja":"leniu-java-mq は Java メッセージキューソリューションで、AIエージェントによるメッセージ送信、受信、処理などの機能を提供します","ko":"leniu-java-mq는 자바 메시지 큐 솔루션으로 AI 에이전트를 이용한 메시지 전송, 수신, 처리 등의 기능을 제공합니다","es":"leniu-java-mq es un agente de inteligencia artificial para la gestión de colas de mensajes en aplicaciones Java","fr":"leniu-java-mq est un agent d''intelligence artificielle pour la gestion de files d''attente dans les applications Java","de":"leniu-java-mq ist ein künstlicher Intelligenz-Agent für die Verwaltung von Nachrichtenwarteschlangen in Java-Anwendungen","pt":"leniu-java-mq é uma ferramenta de mensagens em Java que fornece uma arquitetura de três camadas para enviar e receber mensagens","ru":"leniu-java-mq - это инструмент для работы с сообщениями в Java, обеспечивающий трехслойную архитектуру для отправки и приема сообщений","ar":"leniu-java-mq هو أداة رسائل في جافا توفر بنية من ثلاث طبقات لإرسال واستقبال الرسائل"},"features":{"en":["Uses the `MqUtil` static utility class for sending messages","Leverages the `@MQMessageListener(group, topic, tag)` annotation for consumers","Implements the `MQListener<MqPayload<String>>` interface for message handling","Provides `LeMqConstant.Topic` and `LeMqConstant.DelayDuration` for configuration","Employs a three-layer `MsgSend → Listener → Handler` core architecture","Uses `JacksonUtil` for JSON serialization/deserialization"],"zh":["支持 JDK 21 版本","使用 MqUtil 作为消息工具","提供 @MQMessageListener 注解用于消费者接口","支持 LeMqConstant.Topic 和 LeMqConstant.DelayDuration","使用 JacksonUtil 作为 JSON 工具","提供 LeException 异常类"],"ja":["JDK 21 版本をサポート","MqUtil をメッセージツールとして使用","消费者インターフェイスに @MQMessageListener 注解を提供","LeMqConstant.Topic と LeMqConstant.DelayDuration をサポート","JacksonUtil を JSON ツールとして使用","LeException 例外クラスを提供"],"ko":["JDK 21 버전을 지원","MqUtil를 메시지 툴로 사용","소비자 인터페이스에 @MQMessageListener 어노테이션을 제공","LeMqConstant.Topic과 LeMqConstant.DelayDuration을 지원","JacksonUtil을 JSON 툴로 사용","LeException 예외 클래스를 제공"],"es":["Soporte para JDK 21","Herramienta de mensajes MqUtil","Annotación de consumidor @MQMessageListener","Interfaz de consumidor MQListener","Constantes de tema LeMqConstant.Topic","Enumeración de retraso LeMqConstant.DelayDuration"],"fr":["Prise en charge de JDK 21","Outil de messages MqUtil","Annotation de consommateur @MQMessageListener","Interface de consommateur MQListener","Constantes de sujet LeMqConstant.Topic","Énumération de retard LeMqConstant.DelayDuration"],"de":["Unterstützung für JDK 21","Nachrichten-Tool MqUtil","Verbraucher-Annotation @MQMessageListener","Verbraucher-Schnittstelle MQListener","Themen-Konstanten LeMqConstant.Topic","Verzögerungs-Enumeration LeMqConstant.DelayDuration"],"pt":["Arquitetura de três camadas: MsgSend, Listener e Handler","Utiliza JDK 21 e a ferramenta de mensagens MqUtil","Suporta anotações de consumidor @MQMessageListener","Fornece interface de consumidor que implementa MQListener","Inclui constantes de tópico e enumeração de atraso","Utiliza a ferramenta de JSON JacksonUtil"],"ru":["Трехслойная архитектура: MsgSend, Listener и Handler","Использует JDK 21 и инструмент для работы с сообщениями MqUtil","Поддерживает аннотации потребителя @MQMessageListener","Предоставляет интерфейс потребителя, реализующий MQListener","Включает константы темы и перечисление задержки","Использует инструмент для работы с JSON JacksonUtil"],"ar":["بنية من ثلاث طبقات: MsgSend و Listener و Handler","يستخدم JDK 21 وأداة الرسائل MqUtil","يدعم تعليقات المستهلك @MQMessageListener","يوفر واجهة المستهلك التي تنفذ MQListener","يشمل ثوابت الموضوع وتعريف التأخير","يستخدم أداة JSON JacksonUtil"]},"keywords":{"en":["leniu-java-mq setup guide","how to use @MQMessageListener","leniu-java-mq vs spring amqp","MqUtil Java message queue","install leniu-java-mq","what is leniu-java-mq","leniu-java-mq alternative","LeMqConstant.Topic usage","Java 21 message queue implementation"],"zh":["leniu-java-mq","Java 消息队列","AI 工程化","JDK 21","MqUtil","MQMessageListener","LeMqConstant","JacksonUtil","LeException"],"ja":["leniu-java-mq","Java メッセージキューソリューション","AIエージェント","JDK 21","MqUtil","MQMessageListener","LeMqConstant","JacksonUtil","LeException"],"ko":["leniu-java-mq","자바 메시지 큐","AI 에이전트","JDK 21","MqUtil","MQMessageListener","LeMqConstant","JacksonUtil","LeException"],"es":["leniu-java-mq","cola de mensajes","integración de servicios","MqUtil","LeMqConstant","JDK 21","desarrollo de aplicaciones","agente de inteligencia artificial","herramientas de desarrollo"],"fr":["leniu-java-mq","file d''attente","intégration de services","MqUtil","LeMqConstant","JDK 21","développement d''applications","agent d''intelligence artificielle","outils de développement"],"de":["leniu-java-mq","Nachrichtenwarteschlangen","Dienstintegration","MqUtil","LeMqConstant","JDK 21","Anwendungsentwicklung","künstlicher Intelligenz-Agent","Entwicklertools"],"pt":["leniu-java-mq","ferramenta de mensagens em Java","arquitetura de três camadas","JDK 21","MqUtil","anotações de consumidor","MQListener","constantes de tópico","enumeração de atraso","JacksonUtil"],"ru":["leniu-java-mq","инструмент для работы с сообщениями в Java","трехслойная архитектура","JDK 21","MqUtil","аннотации потребителя","MQListener","константы темы","перечисление задержки","JacksonUtil"],"ar":["leniu-java-mq","أداة رسائل في جافا","بنية من ثلاث طبقات","JDK 21","MqUtil","تعليقات المستهلك","MQListener","ثوابت الموضوع","تعريف التأخير","JacksonUtil"]}},"owner":"xu-cell","repo":"ai-engineering-init","repoPath":"xu-cell/ai-engineering-init","stars":3,"forks":0,"updatedAt":"2026-03-03T05:25:40Z","topics":[],"category":"community","skillMd":{"name":"leniu-java-mq","description":"|","bodyPreview":"# leniu-tengyun-core 消息队列规范\n\n## 项目特征\n\n| 特征 | 说明 |\n|------|------|\n| **包名前缀** | `net.xnzn.core.*` |\n| **JDK 版本** | 21 |\n| **消息工具** | `MqUtil` |\n| **消费者注解** | `@MQMessageListener(group, topic, tag)` |\n| **消费者接口** | `implements MQListener<MqPayload<String>>` |\n| **主题常量** | `LeMqConstant.Topic` |\n| **延迟枚举** | `LeMqConstant.DelayDuration` |\n| **JSON工具** | `JacksonUtil` |\n| **异常类** | `LeException` |\n\n## 核心架构：三层分工\n\n```\nMsgSend（静态工具类）→ Listener（接收消息）→ Handler（分发处理）\n```\n\n| 层 | 职责 | 示例 |\n|----|------|----","body":"# leniu-tengyun-core 消息队列规范\n\n## 项目特征\n\n| 特征 | 说明 |\n|------|------|\n| **包名前缀** | `net.xnzn.core.*` |\n| **JDK 版本** | 21 |\n| **消息工具** | `MqUtil` |\n| **消费者注解** | `@MQMessageListener(group, topic, tag)` |\n| **消费者接口** | `implements MQListener<MqPayload<String>>` |\n| **主题常量** | `LeMqConstant.Topic` |\n| **延迟枚举** | `LeMqConstant.DelayDuration` |\n| **JSON工具** | `JacksonUtil` |\n| **异常类** | `LeException` |\n\n## 核心架构：三层分工\n\n```\nMsgSend（静态工具类）→ Listener（接收消息）→ Handler（分发处理）\n```\n\n| 层 | 职责 | 示例 |\n|----|------|------|\n| **XxxMessageSend** | 静态工具类，封装消息发送逻辑 | `OrderMessageSend` |\n| **XxxMqListenerYyy** | 消费者，接收 MQ 消息并分发到 Handler | `OrderMqListenerAsyncSave` |\n| **XxxMqHandler** | 业务处理，统一处理各类消息 | `OrderMqHandler` |\n\n## 消息发送\n\n### 三种发送方式\n\n```java\nimport net.xnzn.core.common.mq.MqUtil;\nimport net.xnzn.core.common.constant.LeMqConstant;\nimport net.xnzn.core.common.utils.JacksonUtil;\n\n// 1. 普通消息（立即发送）\nMqUtil.send(JacksonUtil.writeValueAsString(po), LeMqConstant.Topic.XXX_TOPIC);\n\n// 2. 事务消息（在 DB 事务提交后发送，保证一致性）\nMqUtil.sendByTxEnd(JacksonUtil.writeValueAsString(po), LeMqConstant.Topic.XXX_TOPIC);\n\n// 3. 延迟消息（指定延迟时长后触发）\nMqUtil.sendDelay(JacksonUtil.writeValueAsString(po), LeMqConstant.Topic.XXX_TOPIC, LeMqConstant.DelayDuration.ONE_MINUTE);\n```\n\n**关键点**：\n- 消息体必须用 `JacksonUtil.writeValueAsString()` 序列化为 **String** 再发送\n- 事务消息用 `sendByTxEnd()`（如 DB 事务回滚则不发送）\n- 延迟时间用 `LeMqConstant.DelayDuration` 枚举（不用 `Duration.ofMinutes()`）\n\n### DelayDuration 枚举（常用值）\n\n```java\nLeMqConstant.DelayDuration.ONE_MINUTE      // 1分钟\nLeMqConstant.DelayDuration.THIRTY_MINUTES  // 30分钟\n// 其他枚举值参见 LeMqConstant.DelayDuration\n```\n\n### 消息发送类（静态工具类模式）\n\n```java\n/**\n * 订单消息发送\n * 关键特征：\n * 1. 不是 @Component，是纯静态工具类\n * 2. 私有构造器\n * 3. PO 中包含 traceId 和 tenantId（用于跨线程追踪）\n */\n@Slf4j\npublic class XxxMessageSend {\n\n    private XxxMessageSend() {}  // 禁止实例化\n\n    private static final String MQ_ERROR_LOG = \"发送MQ消息失败\";\n\n    /**\n     * 普通消息（适用于非事务性发送）\n     */\n    public static void sendXxxEvent(XxxPO po) {\n        log.info(\"[XxxMQ]发送xxx事件\");\n        po.setTraceId(LogUtil.getCurrentTraceId());\n        po.setTenantId(TenantContextHolder.getTenantId());\n        MqUtil.send(JacksonUtil.writeValueAsString(po), LeMqConstant.Topic.XXX_TOPIC);\n    }\n\n    /**\n     * 事务消息（在 @Transactional 方法中使用，事务提交后才发送）\n     */\n    public static void sendXxxEventByTx(XxxPO po) {\n        log.info(\"[XxxMQ]发送xxx事务消息\");\n        po.setTraceId(LogUtil.getCurrentTraceId());\n        po.setTenantId(TenantContextHolder.getTenantId());\n        try {\n            MqUtil.sendByTxEnd(JacksonUtil.writeValueAsString(po), LeMqConstant.Topic.XXX_TOPIC);\n        } catch (Exception e) {\n            log.error(MQ_ERROR_LOG, e);\n        }\n    }\n\n    /**\n     * 延迟消息（超时取消等场景）\n     */\n    public static void sendXxxDelay(XxxPO po, LeMqConstant.DelayDuration delayDuration) {\n        log.info(\"[XxxMQ]发送xxx延迟消息\");\n        po.setTraceId(LogUtil.getCurrentTraceId());\n        po.setTenantId(TenantContextHolder.getTenantId());\n        MqUtil.sendDelay(JacksonUtil.writeValueAsString(po), LeMqConstant.Topic.XXX_TOPIC, delayDuration);\n    }\n}\n```\n\n### PO 消息体规范\n\n```java\nimport lombok.Data;\n\n/**\n * MQ 消息 PO（Message Payload Object）\n * 必须包含 traceId 和 tenantId 字段\n */\n@Data\npublic class XxxPO {\n\n    /** 链路追踪ID */\n    private String traceId;\n\n    /** 租户ID */\n    private String tenantId;\n\n    /** 业务字段 */\n    private Long orderId;\n    private String outTradeNo;\n    // 其他字段...\n}\n```\n\n## 消息消费\n\n### Listener 类（真实代码模式）\n\n```java\nimport lombok.extern.slf4j.Slf4j;\nimport net.xnzn.core.common.mq.MqPayload;\nimport net.xnzn.framework.mq.MQListener;\nimport net.xnzn.framework.mq.MQMessageListener;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.context.annotation.Lazy;\n\n/**\n * MQ 消费者 Listener\n * @see LeMqConstant.Topic#XXX_TOPIC\n */\n@Slf4j\n@MQMessageListener(\n    group = \"module-xxx-topic-name\",   // 消费组，格式：模块名-topic-tag\n    topic = \"xxx\",                     // Topic 名称\n    tag = \"xxx-topic-name\"             // Tag 名称（对应 LeMqConstant.Topic）\n)\npublic class XxxMqListenerYyy implements MQListener<MqPayload<String>> {\n\n    @Autowired\n    @Lazy   // ⚠️ 必须 @Lazy，避免循环依赖\n    private XxxMqHandler xxxMqHandler;\n\n    @Override\n    public void onMessage(MqPayload<String> payload) {\n        // 委托给 Handler 处理，使用方法引用\n        xxxMqHandler.handleMessage(payload, XxxPO.class, XxxMqHandler::handleXxx);\n    }\n}\n```\n\n### Handler 类（统一处理消息）\n\n```java\nimport cn.hutool.core.text.CharSequenceUtil;\nimport com.pig4cloud.pigx.common.core.exception.LeException;\nimport lombok.extern.slf4j.Slf4j;\nimport net.xnzn.core.common.export.util.I18nUtil;\nimport net.xnzn.core.common.mq.MqPayload;\nimport net.xnzn.core.common.utils.JacksonUtil;\nimport net.xnzn.framework.data.tenant.TenantContextHolder;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.context.annotation.Lazy;\nimport org.springframework.stereotype.Service;\n\nimport java.util.function.BiConsumer;\n\n@Slf4j\n@Service\npublic class XxxMqHandler {\n\n    @Lazy\n    @Autowired\n    private XxxService xxxService;\n\n    /**\n     * 统一处理调用（核心模板方法）\n     * 负责：反序列化、设置租户上下文、异常兜底\n     */\n    public <T> void handleMessage(MqPayload<String> payload, Class<T> clz, BiConsumer<XxxMqHandler, T> handleFunc) {\n        I18nUtil.loadDefaultLocale();\n        try {\n            log.info(\"[Xxx消息]收到消息 {}\", payload);\n            T payloadData = JacksonUtil.readValue(payload.getData(), clz);\n            if (payloadData != null) {\n                TenantContextHolder.setTenantId(payload.getTenantId());  // 设置租户上下文\n                handleFunc.accept(this, payloadData);\n            } else {\n                log.error(\"[Xxx消息]解析失败\");\n            }\n        } catch (Exception e) {\n            log.error(\"[Xxx消息]处理异常\", e);\n        }\n    }\n\n    /**\n     * 处理 xxx 事件\n     */\n    public void handleXxx(XxxPO payload) {\n        try {\n            log.info(\"[Xxx事件]MQ消费：开始\");\n            xxxService.processXxx(payload);\n            log.info(\"[Xxx事件]MQ消费：消息消费完成\");\n        } catch (Exception e) {\n            log.error(\"[Xxx事件]MQ消费：处理异常\", e);\n        }\n    }\n}\n```\n\n## 常见场景\n\n### 场景1：事务消息（下单后通知）\n\n```java\n@Transactional(rollbackFor = Exception.class)\npublic void createOrder(OrderParam param) {\n    // 1. 保存订单\n    OrderInfo order = OrderInfo.newDefaultInstance();\n    order.setCanteenId(param.getCanteenId());\n    orderMapper.insert(order);\n\n    // 2. 事务提交后发送消息（保证一致性）\n    OrderPlacedPO po = new OrderPlacedPO();\n    po.setOrderInfo(order);\n    OrderMessageSend.sendOrderPlacedByTx(po);  // 内部使用 sendByTxEnd\n\n    log.info(\"订单创建成功，orderId:{}\", order.getId());\n}\n```\n\n### 场景2：延迟消息（订单超时取消）\n\n```java\npublic static LocalDateTime sendOrderTimeout(String macOrderId, LeMqConstant.DelayDuration delayDuration) {\n    log.info(\"[订单MQv3]发送未支付订单异步支付超时通知\");\n    OrderCancelPO po = new OrderCancelPO();\n    po.setMacOrderId(macOrderId);\n    po.setTenantId(TenantContextHolder.getTenantId());\n    po.setTraceId(LogUtil.getCurrentTraceId());\n\n    // 延迟发送\n    MqUtil.sendDelay(JacksonUtil.writeValueAsString(po), LeMqConstant.Topic.ORDER_V3_ASYNC_TIMEOUT, delayDuration);\n\n    // 返回预计触发时间\n    return LocalDateTime.now().plusSeconds(delayDuration.getMilliseconds() / 1000);\n}\n```\n\n### 场景3：带 Redisson 分布式锁的 MQ 消费\n\n```java\npublic void orderAsyncSave(OrderSavePO payload) {\n    // 消费时加分布式锁（防止并发处理同一订单）\n    RLock lock = RedisUtil.getLock(OrderCacheConstants.orderCacheSaveLockKey(payload.getMacOrderId()));\n    lock.lock();\n    try {\n        log.info(\"[订单异步保存]MQ消费：开始\");\n        doSaveOrder(payload);\n        log.info(\"[订单异步保存]MQ消费：消息消费完成\");\n    } catch (Exception e) {\n        log.error(\"[订单异步保存]MQ消费：处理异常\", e);\n    } finally {\n        // 安全释放锁\n        try {\n            if (lock.isHeldByCurrentThread() && lock.isLocked()) {\n                lock.unlock();\n            }\n        } catch (Exception e) {\n            log.error(\"解锁异常\", e);\n        }\n    }\n}\n```\n\n## 日志规范\n\n```java\n// 发送端日志格式\nlog.info(\"[模块MQv3]发送xxx事件\");\n\n// 消费端日志格式\nlog.info(\"[xxx事件]MQ消费：开始\");\nlog.info(\"[xxx事件]MQ消费：消息消费完成\");\nlog.error(\"[xxx事件]MQ消费：处理异常\", e);\n```\n\n## 常见错误\n\n| 错误写法 | 正确写法 | 说明 |\n|---------|---------|------|\n| `MqUtil.send(dto, topic)` 直接传对象 | `MqUtil.send(JacksonUtil.writeValueAsString(dto), topic)` | 必须先序列化为 String |\n| `@MqConsumer(topic = ...)` | `@MQMessageListener(group, topic, tag)` + `implements MQListener<MqPayload<String>>` | 实际框架注解不同 |\n| `Duration.ofMinutes(30)` | `LeMqConstant.DelayDuration.THIRTY_MINUTES` | 延迟枚举不是 Duration |\n| 忘记在 PO 中设置 `traceId`/`tenantId` | `po.setTraceId(LogUtil.getCurrentTraceId())` | 多租户追踪必须设置 |\n| 消费方法直接 `@Autowired` 服务 | `@Autowired @Lazy` | 避免循环依赖 |\n| 在 MQ 发送类上加 `@Component` | 纯静态工具类（私有构造器，不注入 Spring） | 发送类是静态工具 |\n"},"lastSynced":"2026-03-06T07:03:22.582Z","agentAnalysis":{"suitability":{"en":"Ideal for Java-based AI Agents requiring standardized message queue implementations for event-driven architectures.","zh":"适用于需要标准化消息队列实现的基于Java的AI代理，用于事件驱动架构。","ja":"JavaベースのAIエージェントに標準化されたメッセージキューアーキテクチャを必要とするイベント駆動型アーキテクチャに最適です。","ko":"이벤트 주도형 아키텍처를 위한 표준화된 메시지 큐 구현이 필요한 Java 기반 AI 에이전트에 적합합니다.","es":"Ideal para agentes de inteligencia artificial basados en Java que requieren implementaciones de cola de mensajes estandarizadas para arquitecturas orientadas a eventos.","fr":"Idéal pour les agents d''intelligence artificielle basés sur Java nécessitant des implémentations de files d''attente de messages standardisées pour les architectures orientées événement.","de":"Ideal für Java-basierte KI-Agents, die standardisierte Nachrichtenwarteschlangen-Implementierungen für ereignisgesteuerte Architekturen benötigen.","pt":"Ideal para agentes de IA baseados em Java que exigem implementações de filas de mensagens padronizadas para arquiteturas orientadas a eventos.","ru":"Идеально подходит для агентов ИИ на основе Java, требующих стандартизированных реализаций очередей сообщений для событийно-ориентированных архитектур.","ar":"مثالي لعميل الوكيل الذكي القائم على جافا الذي يتطلب تنفيذًا موحدًا لطوابير الرسائل لعمارة مدفوعة بالأحداث."},"recommendation":{"en":"Empowers agents to consume messages using the @MQMessageListener annotation and process them with the MqUtil tool class, leveraging JDK 21 for robust event handling and JacksonUtil for efficient JSON processing.","zh":"赋予代理使用@MQMessageListener注释来消费消息，并使用MqUtil工具类处理它们，利用JDK 21进行强大的事件处理，并使用JacksonUtil进行高效的JSON处理。","ja":"@MQMessageListener注釈を使用してメッセージを消費し、MqUtilツールクラスを使用してそれらを処理することでエージェントに権限を与え、JDK 21を使用して堅牢なイベント処理を行い、JacksonUtilを使用して効率的なJSON処理を行う。","ko":"에이전트가 @MQMessageListener 주석을 사용하여 메시지를 사용하고 MqUtil 툴 클래스를 사용하여 처리할 수 있도록 하여 JDK 21을 사용하여 강력한 이벤트 처리와 JacksonUtil을 사용하여 효율적인 JSON 처리를 수행합니다.","es":"Habilita a los agentes a consumir mensajes utilizando la anotación @MQMessageListener y procesarlos con la clase de herramientas MqUtil, aprovechando JDK 21 para un control de eventos robusto y JacksonUtil para un procesamiento eficiente de JSON.","fr":"Permet aux agents de consommer des messages en utilisant l''annotation @MQMessageListener et de les traiter avec la classe d''outils MqUtil, en exploitant JDK 21 pour une gestion d''événements robuste et JacksonUtil pour un traitement efficace de JSON.","de":"Ermöglicht es Agents, Nachrichten mithilfe der @MQMessageListener-Annotation zu konsumieren und mit der MqUtil-Werkzeugklasse zu verarbeiten, indem JDK 21 für eine robuste Ereignisverarbeitung und JacksonUtil für eine effiziente JSON-Verarbeitung genutzt wird.","pt":"Habilita os agentes a consumir mensagens usando a anotação @MQMessageListener e processá-las com a classe de ferramenta MqUtil, aproveitando o JDK 21 para tratamento de eventos robusto e JacksonUtil para processamento eficiente de JSON.","ru":"Наделяет агентов возможностью消费ировать сообщения с помощью аннотации @MQMessageListener и обрабатывать их с помощью утилитного класса MqUtil, используя JDK 21 для надёжной обработки событий и JacksonUtil для эффективной обработки JSON.","ar":"يمنح الوكلاء القدرة على استهلاك الرسائل باستخدام التعليمة البرمجية @MQMessageListener ومعالجتها باستخدام فئة أداة MqUtil، وتحقيق JDK 21 لمعالجة الأحداث القوية و JacksonUtil لمعالجة JSON الفعالة."},"useCases":{"en":["Implementing event-driven architectures with JDK 21","Consuming messages from queues using the @MQMessageListener annotation","Processing messages with the MqUtil tool class and LeMqConstant.Topic"],"zh":["使用JDK 21实现事件驱动架构","使用@MQMessageListener注释从队列中消费消息","使用MqUtil工具类和LeMqConstant.Topic处理消息"],"ja":["JDK 21を使用したイベント駆動型アーキテクチャの実装","@MQMessageListener注釈を使用したキューよりメッセージの消費","MqUtilツールクラスとLeMqConstant.Topicを使用したメッセージ処理"],"ko":["JDK 21을 사용한 이벤트 주도형 아키텍처 구현","@MQMessageListener 주석을 사용한 큐에서 메시지 소비","MqUtil 툴 클래스 및 LeMqConstant.Topic를 사용한 메시지 처리"],"es":["Implementación de arquitecturas orientadas a eventos con JDK 21","Consumo de mensajes de colas utilizando la anotación @MQMessageListener","Procesamiento de mensajes con la clase de herramientas MqUtil y LeMqConstant.Topic"],"fr":["Mise en œuvre d''architectures orientées événement avec JDK 21","Consommation de messages de files d''attente en utilisant l''annotation @MQMessageListener","Traitement de messages avec la classe d''outils MqUtil et LeMqConstant.Topic"],"de":["Implementierung von ereignisgesteuerten Architekturen mit JDK 21","Konsum von Nachrichten aus Warteschlangen unter Verwendung der @MQMessageListener-Annotation","Verarbeitung von Nachrichten mit der MqUtil-Werkzeugklasse und LeMqConstant.Topic"],"pt":["Implementação de arquiteturas orientadas a eventos com JDK 21","Consumo de mensagens de filas usando a anotação @MQMessageListener","Processamento de mensagens com a classe de ferramenta MqUtil e LeMqConstant.Topic"],"ru":["Реализация событийно-ориентированных архитектур с помощью JDK 21","Потребление сообщений из очередей с помощью аннотации @MQMessageListener","Обработка сообщений с помощью утилитного класса MqUtil и LeMqConstant.Topic"],"ar":["تنفيذ عمارة مدفوعة بالأحداث مع JDK 21","استهلاك الرسائل من الطوابير باستخدام التعليمة البرمجية @MQMessageListener","معالجة الرسائل باستخدام فئة أداة MqUtil و LeMqConstant.Topic"]},"limitations":{"en":["Requires JDK 21 or higher","Limited to Java-based agents","Dependent on JacksonUtil for JSON processing"],"zh":["需要JDK 21或更高版本","仅限Java基于代理","依赖于JacksonUtil进行JSON处理"],"ja":["JDK 21以上が必要","Javaベースのエージェントのみ","JSON処理にはJacksonUtilに依存"],"ko":["JDK 21 이상이 필요합니다","Java 기반 에이전트만 해당","JSON 처리는 JacksonUtil에 의존"],"es":["Requiere JDK 21 o superior","Limitado a agentes basados en Java","Dependiente de JacksonUtil para el procesamiento de JSON"],"fr":["Nécessite JDK 21 ou supérieur","Limité aux agents basés sur Java","Dépendant de JacksonUtil pour le traitement de JSON"],"de":["Benötigt JDK 21 oder höher","Begrenzt auf Java-basierte Agents","Abhängig von JacksonUtil für die JSON-Verarbeitung"],"pt":["Exige JDK 21 ou superior","Limitado a agentes baseados em Java","Dependente de JacksonUtil para processamento de JSON"],"ru":["Требует JDK 21 или выше","Ограничен агентами на основе Java","Зависит от JacksonUtil для обработки JSON"],"ar":["يتطلب JDK 21 أو أعلى","محدود بالوكلاء القائمين على جافا","يعتمد على JacksonUtil لمعالجة JSON"]},"version":4},"contentHash":"73ef4124d91f7c06d76306a9402700e445844a400a339f94bc8586e7d90310ed","qualityScore":36}');
