INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xu-cell/ai-engineering-init/leniu-java-mq', 'leniu-java-mq', 'xu-cell', 'ai-engineering-init', 'community', 'leniu-java-mq xu-cell ai-engineering-init community The leniu-java-mq AI Agent skill provides a standardized Java message queue implementation for event-driven architectures. It offers developers a structured framework built on JDK 21 with a `MqUtil` tool class and a `@MQMessageListener` annotation for consuming messages. leniu-java-mq 是一个 Java 消息队列解决方案，提供了 AI 工程化的能力，包括消息发送、接收和处理等功能。它支持 JDK 21 版本，使用 MqUtil 作为消息工具 leniu-java-mq は Java メッセージキューソリューションで、AIエージェントによるメッセージ送信、受信、処理などの機能を提供します。JDK 21 版本をサポートし、MqUtil をメッセージツールとして使用します leniu-java-mq는 자바 메시지 큐 솔루션으로 AI 에이전트를 이용한 메시지 전송, 수신, 처리 등의 기능을 제공합니다. JDK 21 버전을 지원하며, MqUtil를 메시지 툴로 사용합니다 leniu-java-mq es una herramienta de cola de mensajes que facilita la integración de servicios en tus proyectos de desarrollo. Ofrece características como MqUtil y LeMqConstant. leniu-java-mq est un outil de file d''attente qui facilite l''intégration de services dans vos projets de développement. Il propose des fonctionnalités comme MqUtil et LeMqConstant. leniu-java-mq ist ein Nachrichtenwarteschlangen-Tool, das die Integration von Diensten in Ihren Entwicklungsprojekten erleichtert. Es bietet Funktionen wie MqUtil und LeMqConstant. O leniu-java-mq é uma ferramenta de mensagens que utiliza a arquitetura de três camadas para enviar e receber mensagens leniu-java-mq - это инструмент для работы с сообщениями, использующий трехслойную архитектуру для отправки и приема сообщений leniu-java-mq هو أداة رسائل تستخدم بنية من ثلاث طبقات لإرسال واستقبال الرسائل leniu-java-mq setup guide how to use @MQMessageListener leniu-java-mq vs spring amqp MqUtil Java message queue install leniu-java-mq what is leniu-java-mq leniu-java-mq alternative LeMqConstant.Topic usage Java 21 message queue implementation leniu-java-mq Java 消息队列 AI 工程化 JDK 21 MqUtil MQMessageListener LeMqConstant JacksonUtil LeException Uses the `MqUtil` static utility class for sending messages Leverages the `@MQMessageListener(group, topic, tag)` annotation for consumers Implements the `MQListener<MqPayload<String>>` interface for message handling Provides `LeMqConstant.Topic` and `LeMqConstant.DelayDuration` for configuration Employs a three-layer `MsgSend → Listener → Handler` core architecture Uses `JacksonUtil` for JSON serialization/deserialization leniu-java-mq is an AI Agent skill that codifies a Java message queue implementation standard. It provides a three-layer architecture (MsgSend→Listener→Handler), uses JDK 21, and includes the `@MQMessageListener` annotation and `MqUtil` class for sending and receiving messages.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('common-member/NighTrip/implement-feature', 'community', 'common-member', 'NighTrip', 'common-member/NighTrip', 'implement-feature', 2, 0, 36, '2026-02-20T00:21:24Z', '2026-03-06T07:04:52.835Z', 'd9f4514b683df1e423b20da3a1d9a421af86b5eb8e9a66a1e01988c72c421333', '{"id":"common-member/NighTrip/implement-feature","name":"implement-feature","description":{"en":"The implement-feature skill enables developers to follow a strict Spec Driven Development workflow. It benefits developers by guiding them through a step-by-step process to understand the codebase and implement new features.","zh":"实现功能需要遵循Spec Driven Development工作流，包括探索代码库、阅读相关模型和existing specs等步骤","ja":"機能を実装するには、Spec Driven Developmentワークフローに従う必要があります。コードベースの探索、関連モデルと既存のspecの読み方など","ko":"기능 구현을 위해서는 Spec Driven Development 워크플로우를 따라야 합니다. 코드베이스 탐색, 관련 모델 및 기존 spec 읽기 등","es":"Implementar características con SDD implica seguir un flujo de trabajo estricto para entender el código y escribir specs efectivas.","fr":"La mise en œuvre de fonctionnalités avec SDD implique de suivre un flux de travail strict pour comprendre le code et écrire des specs efficaces.","de":"Das Implementieren von Funktionen mit SDD beinhaltet die Befolgung eines strengen Arbeitsflusses, um den Code zu verstehen und effektive Specs zu schreiben.","pt":"Implemente recursos com Spec Driven Development, seguindo o workflow estritamente e entendendo o código antes de escrever","ru":"Реализуйте функции с помощью SDD, следуя строгому рабочему процессу и изучая кодовую базу перед написанием кода","ar":"نفذ ميزات مع SDD، اتبع 워크فلو стрicktly و افهم الكود قبل الكتابة"},"seo":{"title":{"en":"Implement-Feature: Spec Driven Development Setup Guide | ...","zh":"AI工具：实现功能的Spec Driven Development设置指南","ja":"AIエージェント：機能を実装するためのSpec Driven Developmentベストプラクティス","ko":"AI 도구: 기능 구현을 위한 Spec Driven D