INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('devil666face/.dotfiles/obsidian-cli', 'obsidian-cli', 'devil666face', '.dotfiles', 'community', 'obsidian-cli devil666face .dotfiles community The obsidian-cli skill allows developers to interact with a running Obsidian instance using the `obsidian` command. It provides a range of features for automating tasks and workflows. Obsidian CLI 是一个命令行工具，用于与运行中的 Obsidian 实例交互 Obsidian CLI は、実行中の Obsidian インスタンスとやり取りするためのコマンドラインツールです Obsidian CLI는 실행 중인 Obsidian 인스턴스와 상호 작용하는 명령줄 도구입니다 La CLI de Obsidian permite interactuar con una instancia de Obsidian en ejecución. Ofrece una referencia de comandos y una sintaxis para crear notas y más. La CLI Obsidian permet d''interagir avec une instance Obsidian en cours d''exécution. Elle propose une référence de commandes et une syntaxe pour créer des notes et plus. Die Obsidian-CLI ermöglicht die Interaktion mit einer laufenden Obsidian-Instanz. Sie bietet eine Befehlsreferenz und eine Syntax, um Notizen zu erstellen und mehr. O Obsidian CLI é uma ferramenta para interagir com instâncias em execução. Veja como usá-lo com comandos e parâmetros. Obsidian CLI - это инструмент для взаимодействия с запущенными экземплярами. Узнайте, как им пользоваться с командами и параметрами. Obsidian CLI هو أداة للتفاعل مع الحالات التي يتم تشغيلها. تعلم كيفية استخدامه مع الأوامر والمعاملات how to use obsidian-cli obsidian-cli setup guide obsidian-cli alternative obsidian-cli vs other note-taking tools obsidian-cli install what is obsidian-cli obsidian-cli documentation obsidian-cli commands obsidian-cli syntax Obsidian CLI AI工具 命令行工具 Obsidian 实例 命令参考 语法 参数 标志 Run `obsidian help` to see all available commands Use `obsidian create` to create new notes with custom names and content Supports parameters with values using `=` and quoted values with spaces Includes boolean flags for silent and overwrite operations Access full documentation at https://help.obsidian.md/cli obsidian-cli is a command-line interface for interacting with Obsidian instances, providing features such as command referencing and syntax support.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('1a35e1/sonar-cli/release', 'community', '1a35e1', 'sonar-cli', '1a35e1/sonar-cli', 'release', 2, 1, 36, '2026-03-04T22:01:45Z', '2026-03-07T12:50:08.588Z', 'bf59bf951195f61376852259dedc4a829171b3eee04e8043de642815b3a8705d', '{"id":"1a35e1/sonar-cli/release","name":"release","description":{"en":"The Release skill executes the full release pipeline for @1a35e1/sonar-cli, allowing developers to invoke it with semver bump types, and benefits developers working with OpenClaw and Twitter API.","zh":"Release 工作流是一个使用 Experimental X CLI 实现的自动化流程，支持 patch、minor 和 major 语义版本升级","ja":"リリース ワークフローは、Experimental X CLI を使用して実装された自動化プロセスです。パッチ、ミノール、マジョーなセマンティック バージョニングをサポートします","ko":"릴리즈 워크플로우는 Experimental X CLI를 사용하여 구현된 자동화 프로세스입니다. 패치, 마이너, 메이저 시맨틱 버저닝을 지원합니다","es":"La habilidad de release de OpenClaw es una herramienta experimental de CLI para automatizar el flujo de trabajo de lanzamiento","fr":"La compétence de release d''OpenClaw est un outil de CLI expérimental pour automatiser le flux de travail de lancement","de":"Die Release-Fähigkeit von OpenClaw ist ein experimentelles CLI-Tool zur Automatisierung des Release-Workflows","pt":"O Release é um fluxo de trabalho de lançamento experimental com OpenClaw. Ele executa o pipeline de lançamento completo para @1a35e1/sonar-cli com semver","ru":"Релиз - это экспериментальный flux работы выпуска с помощью OpenClaw. Он выполняет полный pipeline выпуска для @1a35e1/sonar-cli с помощью semver и ИИ Агентов","ar":"الإصدار هو تدفق عمل إصدار تجريبي مع OpenClaw. يقوم بتنفيذ خط أنابيب الإصدار الكامل لـ @1a35e1/sonar-cli مع semver وأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Release: Setup Guide for AI Agents | AI Agent Skill","zh":"Release 工作流 Setup 指南 - Experimental X CLI","ja":"リリース ワークフロー設定ガイド - Experimental X CLI for OpenClaw","ko":"릴리즈 워크플로우 설정 가이드 - Experimental X CLI",