INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('1a35e1/sonar-cli/release', 'release', '1a35e1', 'sonar-cli', 'community', 'release 1a35e1 sonar-cli community openclaw skill twitter-api The Release skill executes the full release pipeline for @1a35e1/sonar-cli, allowing developers to invoke it with semver bump types, and benefits developers working with OpenClaw and Twitter API. Release 工作流是一个使用 Experimental X CLI 实现的自动化流程，支持 patch、minor 和 major 语义版本升级 リリース ワークフローは、Experimental X CLI を使用して実装された自動化プロセスです。パッチ、ミノール、マジョーなセマンティック バージョニングをサポートします 릴리즈 워크플로우는 Experimental X CLI를 사용하여 구현된 자동화 프로세스입니다. 패치, 마이너, 메이저 시맨틱 버저닝을 지원합니다 La habilidad de release de OpenClaw es una herramienta experimental de CLI para automatizar el flujo de trabajo de lanzamiento La compétence de release d''OpenClaw est un outil de CLI expérimental pour automatiser le flux de travail de lancement Die Release-Fähigkeit von OpenClaw ist ein experimentelles CLI-Tool zur Automatisierung des Release-Workflows O Release é um fluxo de trabalho de lançamento experimental com OpenClaw. Ele executa o pipeline de lançamento completo para @1a35e1/sonar-cli com semver Релиз - это экспериментальный flux работы выпуска с помощью OpenClaw. Он выполняет полный pipeline выпуска для @1a35e1/sonar-cli с помощью semver и ИИ Агентов الإصدار هو تدفق عمل إصدار تجريبي مع OpenClaw. يقوم بتنفيذ خط أنابيب الإصدار الكامل لـ @1a35e1/sonar-cli مع semver وأدوات الذكاء الاصطناعي how to use release skill release skill setup guide openclaw release workflow twitter api release pipeline release skill vs github actions release skill install what is release skill release skill alternative release skill for ai agents Release 工作流 Experimental X CLI OpenClaw 语义版本升级 自动化流程 Git 工作树清理 预检检查 Executes the full release pipeline for @1a35e1/sonar-cli Supports semver bump types: patch, minor, and major Runs pre-flight checks, including clean working tree with git status --porcelain Performs argument validation with usage printing for invalid inputs Aborts on first failure with a clear message Release is an Experimental X CLI for OpenClaw that automates the release workflow with pre-flight checks and argument validation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('s-morgan-jeffries/omnifocus-mcp/release', 'community', 's-morgan-jeffries', 'omnifocus-mcp', 's-morgan-jeffries/omnifocus-mcp', 'release', 2, 1, 36, '2026-03-06T12:59:25Z', '2026-03-07T12:50:06.433Z', '60ae980c5dd4b5dd4b705a45e42e569fe35007bf13a6731925f69f96c74469ad', '{"id":"s-morgan-jeffries/omnifocus-mcp/release","name":"release","description":{"en":"The release skill enables MCP server integration with OmniFocus projects, allowing Claude and other MCP clients to interact with projects. It orchestrates a complete release workflow.","zh":"Release技能通过MCP服务器实现OmniFocus项目的自动化交互，提高开发效率。该技能包括多个阶段，例如里程碑检查和release分支创建","ja":"ReleaseスキルはMCPサーバーを使用してOmniFocusプロジェクトとの自動化インタラクションを実現し、開発効率を向上させます。このスキルには、里程碑の確認やリリースブランチの作成などの複数のフェーズが含まれます","ko":"릴리스 스킬은 MCP 서버를 사용하여 OmniFocus 프로젝트와의 자동화 상호 작용을 구현하여 개발 효율성을 향상시킵니다. 이 스킬에는 마일스톤 확인 및 릴리스 분기 생성などの 여러 단계가 포함됩니다","es":"El lanzamiento de MCP permite a los clientes como Claude interactuar con proyectos de OmniFocus. Este skill orquesta un lanzamiento completo.","fr":"La sortie MCP permet aux clients tels que Claude d''interagir avec des projets OmniFocus. Ce skill orchestre une sortie complète.","de":"Das MCP-Release ermöglicht es Clients wie Claude, mit OmniFocus-Projekten zu interagieren. Diese Fähigkeit orchestriert eine vollständige Veröffentlichung.","pt":"O release é uma habilidade que orquestra a integração com OmniFocus, permitindo que clientes como Claude interajam com projetos.","ru":"Релиз - это навык, который обеспечивает интеграцию с OmniFocus, позволяя клиентам như Claude взаимодействовать с проектами - ИИ Агенты","ar":"الإصدار هو مهارة تركيبية لدمج OmniFocus، مما يسمح للعملاء مثل Claude بالتفاعل مع المشاريع - أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Release: MCP Server Setup Guide for AI Agents","zh":"Release 工作流程设置指南 - OmniFocus集成","ja":"Release ワークフロー設定ガイド - OmniFocusとの統合","ko":"릴리스 워크플로우 설정 가이드 - OmniFocus 통합","es":"Guía de Configuración de Lanzamiento de MCP para OmniFocus","fr":"Guide d''Installation de la Sortie MCP pour OmniFocus","de":"Einrichtungsleitfaden für MCP-Release für OmniFocus","pt":"Guia de Configuração do Release para Integração com OmniF...","ru":"Руководство по настройке релиза для интеграции с OmniFocu...","ar":"دليل إعداد الإصدار للدمج مع OmniFocus - أدوات الذكاء الاص..."},"description":{"en":"Discover how to integrate OmniFocus projects with Claude and other MCP clients using the release skill - learn more and get started today!","zh":"了解Release技能如何通过MCP服务器实现OmniFocus项目的自动化交互，并提高您的开发效率","ja":"ReleaseスキルがMCPサーバーを使用してOmniFocusプロジェクトとの自動化インタラクションを実現し、開発効率を向上させる方法を学びます","ko":"릴리스 스킬이 MCP 서버를 사용하여 OmniFocus 프로젝트와의 자동화 상호 작용을 구현하고 개발 효율성을 향상시키는 방법에 대해 알아보세요","es":"Automatice el lanzamiento de proyectos con MCP y OmniFocus. Aprenda a configurar el servidor MCP para una integración sin problemas.","fr":"Automatisez la sortie de projets avec MCP et OmniFocus. Découvrez comment configurer le serveur MCP pour une intégration sans problème.","de":"Automatisieren Sie die Veröffentlichung von Projekten mit MCP und OmniFocus. Erfahren Sie, wie Sie den MCP-Server für eine reibungslose Integration einrichten.","pt":"Aprenda a configurar o release para integração com OmniFocus e melhore a produtividade com o MCP server e clientes como Claude","ru":"Узнайте, как настроить релиз для интеграции с OmniFocus и повысьте производительность с помощью MCP сервера и клиентов như Claude - ИИ Агенты","ar":"تعرف على كيفية إعداد الإصدار للدمج مع OmniFocus وเพิ่م الإنتاجية باستخدام MCP server وعميل Claude - أدوات الذكاء الاصطناعي"},"definition":{"en":"Release is a skill that enables MCP server integration with OmniFocus projects, automating release workflows using GitHub API and bash commands.","zh":"Release技能是一种通过MCP服务器实现OmniFocus项目自动化交互的技术","ja":"Releaseスキルは、MCPサーバーを使用してOmniFocusプロジェクトとの自動化インタラクションを実現する技術です","ko":"릴리스 스킬은 MCP 서버를 사용하여 OmniFocus 프로젝트와의 자동화 상호 작용을 구현하는 기술입니다","es":"Un lanzamiento de MCP es una función que permite la integración de proyectos de OmniFocus con clientes como Claude.","fr":"Une sortie MCP est une fonctionnalité qui permet l''intégration de projets OmniFocus avec des clients tels que Claude.","de":"Ein MCP-Release ist eine Funktion, die die Integration von OmniFocus-Projekten mit Clients wie Claude ermöglicht.","pt":"O que é release? É uma habilidade que automatiza a integração com OmniFocus","ru":"Что такое релиз? Это навык, который автоматизирует интеграцию с OmniFocus - ИИ Агенты","ar":"ما هو الإصدار? هو مهارة تتيح 자동 لدمج OmniFocus - أدوات الذكاء الاصطناعي"},"features":{"en":["Verifies milestone readiness using GitHub API and jq commands","Determines target milestone by sorting open milestones by due date","Creates a release branch after verifying milestone readiness","Supports interaction with OmniFocus projects using MCP clients","Orchestrates a complete release workflow using phased execution"],"zh":["MCP服务器集成","OmniFocus项目自动化交互","里程碑检查","release分支创建","多阶段工作流程"],"ja":["MCPサーバー統合","OmniFocusプロジェクトの自動化インタラクション","里程碑の確認","リリースブランチの作成","マルチステージワークフロー"],"ko":["MCP 서버 통합","OmniFocus 프로젝트 자동화 상호 작용","마일스톤 확인","릴리스 분기 생성","다중 단계 워크플로"],"es":["Verificación de hitos antes de crear una rama de lanzamiento","Uso de la API de GitHub para recuperar información de hitos","Integración con proyectos de OmniFocus","Compatibilidad con múltiples hitos abiertos","Notificación en caso de fallo en cualquier fase del lanzamiento"],"fr":["Vérification des jalons avant de créer une branche de sortie","Utilisation de l''API GitHub pour récupérer des informations de jalon","Intégration avec des projets OmniFocus","Prise en charge de plusieurs jalons ouverts","Notification en cas d''échec à une étape quelconque de la sortie"],"de":["Überprüfung von Meilensteinen vor der Erstellung einer Release-Zweig","Verwendung der GitHub-API zum Abrufen von Meilensteininformationen","Integration mit OmniFocus-Projekten","Unterstützung für mehrere offene Meilensteine","Benachrichtigung im Falle eines Fehlers in einer beliebigen Phase der Veröffentlichung"],"pt":["Integração com OmniFocus","Suporte a clientes como Claude","Verificação de marcos antes da criação de branch de release","Uso de CLI para interação com o repositório","Suporte a múltiplos marcos abertos"],"ru":["Интеграция с OmniFocus","Поддержка клиентов как Claude","Проверка вех перед созданием ветки релиза","Использование CLI для взаимодействия с репозиторием","Поддержка нескольких открытых вех - ИИ Агенты"],"ar":["دمج OmniFocus","دعم العملاء مثل Claude","التحقق من المراحل قبل إنشاء فرع الإصدار","استخدام CLI للتفاعل مع المستودع","دعم المراحل المتعددة المفتوحة - أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use release skill","release alternative to manual workflows","release vs zapier","release install guide","release setup for omnfocus","what is release skill","release workflow automation","github api release management"],"zh":["Release技能","MCP服务器","OmniFocus集成","自动化交互","里程碑检查","release分支创建","开发效率","AIエージェント"],"ja":["Releaseスキル","MCPサーバー","OmniFocus統合","自動化インタラクション","里程碑の確認","リリースブランチの作成","開発効率","AIエージェント"],"ko":["릴리스 스킬","MCP 서버","OmniFocus 통합","자동화 상호 작용","마일스톤 확인","릴리스 분기 생성","개발 효율성","AI 에이전트"],"es":["lanzamiento de MCP","integración de OmniFocus","clientes de MCP","automatización de lanzamiento","API de GitHub","hitos de proyecto","gestión de proyectos","herramientas de desarrollo","Agentes de IA para desarrollo"],"fr":["sortie MCP","intégration OmniFocus","clients MCP","automatisation de sortie","API GitHub","jalons de projet","gestion de projets","outils de développement","Agents IA pour le développement"],"de":["MCP-Release","OmniFocus-Integration","MCP-Clients","Automatisierung der Veröffentlichung","GitHub-API","Projektmeilensteine","Projektmanagement","Entwicklungstools","KI-Agents für die Entwicklung"],"pt":["release","OmniFocus","MCP server","Claude","integração","automatização","CLI","repositório","marcos"],"ru":["релиз","OmniFocus","MCP сервер","Claude","интеграция","автоматизация","CLI","репозиторий","вехи","ИИ Агенты"],"ar":["الإصدار","OmniFocus","MCP server","Claude","دمج","آلي","CLI","مستودع","مراحل","أدوات الذكاء الاصطناعي"]}},"owner":"s-morgan-jeffries","repo":"omnifocus-mcp","repoPath":"s-morgan-jeffries/omnifocus-mcp","stars":2,"forks":1,"updatedAt":"2026-03-06T12:59:25Z","topics":[],"category":"community","skillMd":{"name":"release","description":"Use when the user wants to release a new version, says time to release, lets release, cut a release, version bump, or similar. Orchestrates the full release workflow including milestone check, version bump, changelog generation, validation, tagging, and PR creation. Also invocable as /release.","bodyPreview":"# Release Workflow\n\nThis skill orchestrates a complete release. Follow each phase in order. Stop and report if any phase fails.\n\n## Phase 1: Milestone Check\n\nBefore creating a release branch, verify the milestone is ready.\n\n1. Determine the target milestone. Look at open milestones:\n   ```bash\n   gh api \"repos/{owner}/{repo}/milestones?state=open&sort=due_on\" --jq ''.[] | \"\\(.number) \\(.title) open:\\(.open_issues) closed:\\(.closed_issues)\"''\n   ```\n\n2. If there are multiple open milestones, ask th","body":"# Release Workflow\n\nThis skill orchestrates a complete release. Follow each phase in order. Stop and report if any phase fails.\n\n## Phase 1: Milestone Check\n\nBefore creating a release branch, verify the milestone is ready.\n\n1. Determine the target milestone. Look at open milestones:\n   ```bash\n   gh api \"repos/{owner}/{repo}/milestones?state=open&sort=due_on\" --jq ''.[] | \"\\(.number) \\(.title) open:\\(.open_issues) closed:\\(.closed_issues)\"''\n   ```\n\n2. If there are multiple open milestones, ask the user which one to release.\n\n3. If the target milestone has open issues, **stop and ask the user**:\n   - List the open issues: `gh api \"repos/{owner}/{repo}/milestones/{number}/issues?state=open\" --jq ...` (or use `gh issue list --milestone`)\n   - Present options:\n     a. Move open issues to the next milestone (specify or create it)\n     b. Pause to work on the open issues first\n     c. Close the issues if they''re no longer relevant\n   - Do NOT proceed until all issues in the target milestone are closed or moved.\n\n4. Once the milestone is clean (0 open issues), proceed.\n\n## Phase 2: Version Number\n\n1. Read the current version from `pyproject.toml` (authoritative source).\n2. The milestone title tells you the target version (e.g., `v0.7.3` means version `0.7.3`).\n3. Validate it''s a valid semver bump from the current version.\n4. Present the version to the user for confirmation: \"Release version X.Y.Z? (current: A.B.C)\"\n5. Wait for confirmation before proceeding.\n\n## Phase 3: Create Release Branch\n\n```bash\ngit checkout main\ngit pull origin main\ngit checkout -b release/vX.Y.Z\n```\n\n## Phase 4: Bump Version\n\nUpdate version in ALL of these files (pyproject.toml is authoritative):\n\n1. **pyproject.toml** - `version = \"X.Y.Z\"`\n2. **src/omnifocus_mcp/__init__.py** - `__version__ = \"X.Y.Z\"`\n3. **CLAUDE.md** (.claude/CLAUDE.md) - `**Version:** vX.Y.Z` in the header line\n4. **README.md** - All references to the old version (check with grep for old version string)\n\nUse the Edit tool for each file. Be precise about what to change.\n\n## Phase 5: Generate CHANGELOG\n\n1. Get all commits since the last tag:\n   ```bash\n   git log $(git describe --tags --abbrev=0)..HEAD --oneline\n   ```\n\n2. Get merged PRs since the last tag:\n   ```bash\n   gh pr list --state merged --base main --search \"merged:>YYYY-MM-DD\" --json number,title,labels\n   ```\n   (Use the date of the last tag)\n\n3. Generate a CHANGELOG entry following the existing format in CHANGELOG.md:\n   - Use Keep a Changelog format: `## [X.Y.Z] - YYYY-MM-DD`\n   - Categorize changes: Added, Changed, Fixed, Removed\n   - Reference PR/issue numbers with (#N)\n   - Be concise but descriptive\n   - Include today''s date\n\n4. Insert the new entry at the top of CHANGELOG.md (after the header, before the previous version).\n\n## Phase 6: Validation\n\nRun ALL validation checks. Stop on any failure.\n\n1. **Version sync check:**\n   ```bash\n   ./scripts/check_version_sync.sh\n   ```\n\n2. **Client-server parity:**\n   ```bash\n   ./scripts/check_client_server_parity.sh\n   ```\n\n3. **Complexity check:**\n   ```bash\n   ./scripts/check_complexity.sh\n   ```\n\n4. **Unit tests:**\n   ```bash\n   make test\n   ```\n\nIf any check fails, fix the issue and re-run. Do not proceed with failures.\n\n## Phase 7: Commit, Tag, Push, and PR\n\n1. **Commit** the version bump and changelog:\n   ```bash\n   git add -A\n   git commit -m \"release: vX.Y.Z\"\n   ```\n\n2. **Create the tag** on the release branch:\n   ```bash\n   ./scripts/create_tag.sh vX.Y.Z\n   ```\n\n3. **Push** the branch and tag:\n   ```bash\n   git push -u origin release/vX.Y.Z\n   git push origin vX.Y.Z\n   ```\n\n4. **Create the PR** to main:\n   ```bash\n   gh pr create --title \"release: vX.Y.Z\" --body \"...\"\n   ```\n   Use a merge commit (not squash) for release PRs — the individual commits are meaningful.\n\n5. Tell the user the PR is ready for review. Do NOT merge it automatically.\n\n## Phase 8: Close Milestone\n\nAfter the PR is created (not merged), close the milestone:\n\n```bash\ngh api -X PATCH \"repos/{owner}/{repo}/milestones/{number}\" -f state=closed\n```\n\n## Notes\n\n- CHANGELOG is only updated on release branches, never on feature branches.\n- The pre-tag hook validates that final release tags are on main and that CHANGELOG dates are set. Since we tag on the release branch and merge to main, the tag is created here before merging.\n- If `create_tag.sh` fails due to the pre-tag hook requiring main branch, create the tag after the PR is merged instead. Adjust the workflow accordingly and inform the user.\n- Integration tests (`make test-integration`, `make test-e2e`) require a real OmniFocus test database. Ask the user if they want to run them — they''re optional for the release validation.\n"},"lastSynced":"2026-03-07T12:50:06.433Z","agentAnalysis":{"suitability":{"en":"Perfect for Project Management Agents needing integrated release workflow automation with OmniFocus and GitHub milestones.","zh":"非常适合需要将 OmniFocus 和 GitHub 里程碑集成到发布工作流自动化的项目管理代理。","ja":"OmniFocus と GitHub のマイルストーンを統合したリリースワークフローの自動化が必要なプロジェクト管理エージェントに最適です。","ko":"OmniFocus와 GitHub 마일스톤을 통합한 릴리스 워크플로 자동화가 필요한 프로젝트 관리 에이전트에게 적합합니다.","es":"Perfecto para agentes de gestión de proyectos que necesitan automatización de flujo de trabajo de lanzamiento integrado con OmniFocus y GitHub milestones.","fr":"Parfait pour les agents de gestion de projet ayant besoin d''une automatisation de workflow de version intégrée avec OmniFocus et GitHub milestones.","de":"Perfekt für Projektmanagement-Agents, die eine integrierte Release-Workflow-Automatisierung mit OmniFocus und GitHub-Meilensteinen benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Projetos que necessitam de automação de fluxo de trabalho de lançamento integrado com OmniFocus e marcos do GitHub.","ru":"Идеально подходит для агентов по управлению проектами, которым требуется интегрированная автоматизация рабочего процесса выпуска с OmniFocus и вехами GitHub.","ar":"مثالي لعميل إدارة المشروع الذي يحتاج إلى أتمتة تدفق العمل الإطلاق المتكامل مع OmniFocus وآلات العلامة الخاصة بـ GitHub."},"recommendation":{"en":"Empowers agents to orchestrate complete releases, verifying milestone readiness and creating release branches using GitHub API and OmniFocus project integration, streamlining the release workflow with bash scripting and JSON parsing.","zh":"赋予代理编排完整的发布，验证里程碑的准备情况，并使用 GitHub API 和 OmniFocus 项目集成创建发布分支，通过 bash 脚本和 JSON 解析简化发布工作流。","ja":"エージェントに、GitHub API と OmniFocus プロジェクト統合を使用して、マイルストーンの準備状況を確認し、リリースブランチを作成し、bash スクリプトと JSON パーシングでリリースワークフローをストリームライン化することによって、完全なリリースをオーケストレートする能力を付与します。","ko":"에이전트에게 GitHub API와 OmniFocus 프로젝트 통합을 사용하여 마일스톤 준비状況을 확인하고 릴리스 분기를 생성하고 bash 스크립트와 JSON 파싱으로 릴리스 워크플ロー를 간소화하여 완전한 릴리스를 오케스트레이션 할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a orquestar lanzamientos completos, verificando la preparación de los hitos y creando ramas de lanzamiento utilizando GitHub API y la integración de proyectos de OmniFocus, simplificando el flujo de trabajo de lanzamiento con scripting de bash y análisis de JSON.","fr":"Permet aux agents d''orchestrer des versions complètes, en vérifiant la préparation des jalons et en créant des branches de version à l''aide de GitHub API et de l''intégration de projet OmniFocus, en simplifiant le flux de travail de version avec un scripting bash et un parsing JSON.","de":"Ermächtigt Agents, komplette Releases zu orchestrieren, indem sie die Bereitschaft von Meilensteinen überprüfen und Release-Branches mithilfe von GitHub API und OmniFocus-Projektintegration erstellen, wodurch der Release-Workflow mit Bash-Scripting und JSON-Parsing gestreamlined wird.","pt":"Permite que os agentes orquestrem lançamentos completos, verificando a prontidão do marco e criando branches de lançamento usando a API do GitHub e a integração do projeto OmniFocus, simplificando o fluxo de trabalho de lançamento com script bash e análise JSON.","ru":"Позволяет агентам оркестрировать полные выпуски, проверяя готовность вехи и создавая ветки выпуска с помощью API GitHub и интеграции проекта OmniFocus, оптимизируя рабочий процесс выпуска с помощью скриптов bash и парсинга JSON.","ar":"تمكّن العملاء من تنسيق إصدارات كاملة، والتحقق من جاهزية العلامة، وإنشاء فروع الإصدار باستخدام واجهة برمجة تطبيقات GitHub وتكامل مشروع OmniFocus، وبذلك يُبسط تدفق العمل للإصدار باستخدام برمجة bash وتحليل JSON."},"useCases":{"en":["Automating release branch creation","Verifying milestone readiness","Debugging failed release phases"],"zh":["自动创建发布分支","验证里程碑准备情况","调试发布失败阶段"],"ja":["リリースブランチの自動作成","マイルストーンの準備状況の確認","リリース失敗フェーズのデバッグ"],"ko":["릴리스 분기 자동 생성","마일스톤 준비 상황 확인","릴리스 실패 단계 디버깅"],"es":["Automatización de la creación de ramas de lanzamiento","Verificación de la preparación de los hitos","Depuración de fases de lanzamiento fallidas"],"fr":["Automatisation de la création de branches de version","Vérification de la préparation des jalons","Débogage des phases de version échouées"],"de":["Automatisierung der Erstellung von Release-Branches","Überprüfung der Bereitschaft von Meilensteinen","Fehlerbehebung bei fehlgeschlagenen Release-Phasen"],"pt":["Criação automática de branch de lançamento","Verificação da prontidão do marco","Depuração de fases de lançamento com falha"],"ru":["Автоматическое создание ветки выпуска","Проверка готовности вехи","Отладка неудавшихся фаз выпуска"],"ar":["إنشاء تلقائي لفرع الإصدار","التحقق من جاهزية العلامة","تصحيح مشاكل المراحل الفاشلة من الإصدار"]},"limitations":{"en":["Requires GitHub API access","OmniFocus project integration needed","Bash scripting and JSON parsing capabilities required"],"zh":["需要 GitHub API 访问","需要 OmniFocus 项目集成","需要 bash 脚本和 JSON 解析能力"],"ja":["GitHub API アクセスが必要","OmniFocus プロジェクト統合が必要","bash スクリプトと JSON パーシング機能が必要"],"ko":["GitHub API 접근이 필요","OmniFocus 프로젝트 통합이 필요","bash 스크립트와 JSON 파싱 기능이 필요"],"es":["Se requiere acceso a GitHub API","Se necesita integración de proyecto de OmniFocus","Se requieren capacidades de scripting de bash y análisis de JSON"],"fr":["L''accès à GitHub API est requis","L''intégration de projet OmniFocus est nécessaire","Les capacités de scripting bash et d''analyse JSON sont requises"],"de":["GitHub API-Zugriff ist erforderlich","OmniFocus-Projektintegration ist erforderlich","Bash-Scripting- und JSON-Parsing-Fähigkeiten sind erforderlich"],"pt":["Requer acesso à API do GitHub","Integração do projeto OmniFocus necessária","Capacidades de script bash e análise JSON necessárias"],"ru":["Требуется доступ к API GitHub","Необходима интеграция проекта OmniFocus","Требуются возможности скриптов bash и парсинга JSON"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات GitHub","يتطلب تكامل مشروع OmniFocus","مطلوب قدرات برمجة bash وتحليل JSON"]},"version":4},"contentHash":"60ae980c5dd4b5dd4b705a45e42e569fe35007bf13a6731925f69f96c74469ad","qualityScore":36}');
DELETE FROM skills_fts WHERE id = 's-morgan-jeffries/omnifocus-mcp/release';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('s-morgan-jeffries/omnifocus-mcp/release', 'release', 's-morgan-jeffries', 'omnifocus-mcp', 'community', 'release s-morgan-jeffries omnifocus-mcp community The release skill enables MCP server integration with OmniFocus projects, allowing Claude and other MCP clients to interact with projects. It orchestrates a complete release workflow. Release技能通过MCP服务器实现OmniFocus项目的自动化交互，提高开发效率。该技能包括多个阶段，例如里程碑检查和release分支创建 ReleaseスキルはMCPサーバーを使用してOmniFocusプロジェクトとの自動化インタラクションを実現し、開発効率を向上させます。このスキルには、里程碑の確認やリリースブランチの作成などの複数のフェーズが含まれます 릴리스 스킬은 MCP 서버를 사용하여 OmniFocus 프로젝트와의 자동화 상호 작용을 구현하여 개발 효율성을 향상시킵니다. 이 스킬에는 마일스톤 확인 및 릴리스 분기 생성などの 여러 단계가 포함됩니다 El lanzamiento de MCP permite a los clientes como Claude interactuar con proyectos de OmniFocus. Este skill orquesta un lanzamiento completo. La sortie MCP permet aux clients tels que Claude d''interagir avec des projets OmniFocus. Ce skill orchestre une sortie complète. Das MCP-Release ermöglicht es Clients wie Claude, mit OmniFocus-Projekten zu interagieren. Diese Fähigkeit orchestriert eine vollständige Veröffentlichung. O release é uma habilidade que orquestra a integração com OmniFocus, permitindo que clientes como Claude interajam com projetos. Релиз - это навык, который обеспечивает интеграцию с OmniFocus, позволяя клиентам như Claude взаимодействовать с проектами - ИИ Агенты الإصدار هو مهارة تركيبية لدمج OmniFocus، مما يسمح للعملاء مثل Claude بالتفاعل مع المشاريع - أدوات الذكاء الاصطناعي how to use release skill release alternative to manual workflows release vs zapier release install guide release setup for omnfocus what is release skill release workflow automation github api release management Release技能 MCP服务器 OmniFocus集成 自动化交互 里程碑检查 release分支创建 开发效率 AIエージェント Verifies milestone readiness using GitHub API and jq commands Determines target milestone by sorting open milestones by due date Creates a release branch after verifying milestone readiness Supports interaction with OmniFocus projects using MCP clients Orchestrates a complete release workflow using phased execution Release is a skill that enables MCP server integration with OmniFocus projects, automating release workflows using GitHub API and bash commands.');
