INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('7hinkDifferent/agent-cracker/update-repo', 'community', '7hinkDifferent', 'agent-cracker', '7hinkDifferent/agent-cracker', 'update-repo', 1, 0, 36, '2026-02-25T10:29:27Z', '2026-03-06T07:11:41.286Z', 'd505ac7e2f1847475e5b04166f4f11939715a9bf946494ff6c8d67c98dffa988', '{"id":"7hinkDifferent/agent-cracker/update-repo","name":"update-repo","description":{"en":"The update-repo skill updates the repository''s agent data by pulling latest submodule commits and refreshing star counts from GitHub, benefiting AI agent developers.","zh":"Update Repo是用于更新仓库的AI代理数据，包括拉取最新的子模块提交、刷新GitHub星数和重新生成README代理表","ja":"Update Repoは、リポジトリのAIエージェントデータを更新するために使用され、最新のサブモジュールコミットをプルし、GitHubのスター数を更新し、READMEエージェントテーブルを再生成する","ko":"Update Repo는 저장소의 AI 에이전트 데이터를 업데이트하는 데 사용되며 최신 서브모듈 커밋을 가져오고 GitHub 스타 수를 업데이트하고 README 에이전트 테이블을 다시 생성","es":"La habilidad update-repo actualiza el repositorio de agentes de código, extrayendo los últimos commits de submódulos y regenerando la tabla de agentes en el README","fr":"La compétence update-repo met à jour le référentiel d''agents de code, en extrayant les derniers commits de sous-modules et en régénérant le tableau d''agents dans le README","de":"Die Fähigkeit update-repo aktualisiert das Repository von Code-Agents, indem sie die neuesten Commits von Submodulen extrahiert und die Agententabelle im README regeneriert","pt":"O update-repo atualiza o repositório com submodule commits e contagem de estrelas do GitHub.","ru":"ИИ Агент update-repo обновляет репозиторий с помощью submodule commits и счетчика звезд на GitHub.","ar":"يحدث update-repo المعلومات الوكيل في المستودع باستخدام submodule commits وعدد النجوم على GitHub."},"seo":{"title":{"en":"update-repo: Repository Update Setup Guide | AI Agent Skill","zh":"Update Repo Setup Guide: AIエージェント仓库更新","ja":"Update Repo ベストプラクティス: AIエージェントのリポジトリ更新",