INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('breferrari/obsidian-mind/obsidian-cli', 'obsidian-cli', 'breferrari', 'obsidian-mind', 'community', 'obsidian-cli breferrari obsidian-mind community The obsidian-cli skill allows engineers to interact with a running Obsidian instance using the command line. It provides a set of commands to create notes, view help, and more. Obsidian CLI 是一个为工程师提供的 Obsidian Vault 模板，用于与 Claude Code 进行思考合作 Obsidian CLI は、エンジニア向けの Obsidian Vault テンプレートで、Claude Code との思考パートナーシップを実現します Obsidian CLI는 엔지니어를 위한 Obsidian Vault 템플릿으로 Claude Code와의思考 파트너십을 실현합니다 El comando obsidian-cli permite a los desarrolladores interactuar con instancias de Obsidian en ejecución de manera eficiente La commande obsidian-cli permet aux développeurs d''interagir avec des instances Obsidian en cours d''exécution de manière efficace Der Befehl obsidian-cli ermöglicht es Entwicklern, mit ausführbaren Obsidian-Instanzen auf effiziente Weise zu interagieren O Obsidian-CLI é uma ferramenta de linha de comando para interagir com o Obsidian. Veja como usá-lo para criar notas e mais. Obsidian-CLI — это инструмент командной строки для взаимодействия с Obsidian. Узнайте, как им пользоваться для создания заметок и больше. Obsidian-CLI هو أداة سطر أوامر للتفاعل مع Obsidian. تعرف على كيفية استخدامه لإنشاء الملاحظات والمزيد. how to use obsidian-cli obsidian-cli setup guide obsidian-cli alternative obsidian-cli vs claude code obsidian-cli install what is obsidian-cli obsidian-cli command reference obsidian-cli note creation Obsidian CLI AI 工具 Claude Code 命令行接口 Obsidian Vault 工程师工具 开发效率 AI 集成 Run `obsidian help` to see all available commands Create notes using the `obsidian create` command with parameters like `name` and `content` Use flags like `silent` and `overwrite` to customize command behavior Quote values with spaces using the `=` operator Access full documentation at https://help.obsidian.md/cli obsidian-cli is a command-line interface for interacting with Obsidian instances, providing features like note creation and command reference.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nnsi/hono-practice/browser-check', 'community', 'nnsi', 'hono-practice', 'nnsi/hono-practice', 'browser-check', 1, 0, 36, '2026-02-28T12:56:56Z', '2026-03-06T07:14:28.576Z', 'af3d16d233c5712b3b3b085a2bf076f19e72e762acc4c2237f650e71a1391ab6', '{"id":"nnsi/hono-practice/browser-check","name":"browser-check","description":{"en":"The browser-check skill enables AI agents to verify app functionality through Chrome MCP, ensuring accurate operation checks. It benefits developers by streamlining the testing process.","zh":"浏览器检查工具使用Chrome MCP接口进行动作检查，确保应用程序在不同浏览器中正常运行。","ja":"ブラウザ動作確認ツールはChrome MCP接続を使用して動作を確認し、Webアプリケーションのブラウザ間の互換性を確保します。","ko":"브라우저 검사 도구는 크롬 MCP 연결을 사용하여 동작을 확인하고 웹 애플리케이션의 브라우저 간 호환성을 보장합니다.","es":"Browser-check es una herramienta para pruebas de rendimiento que utiliza Chrome MCP para verificar el funcionamiento de aplicaciones en diferentes entornos","fr":"Browser-check est un outil de test de performance qui utilise Chrome MCP pour vérifier le fonctionnement des applications dans différents environnements","de":"Browser-check ist ein Tool für Leistungsprüfungen, das Chrome MCP verwendet, um das Funktionieren von Anwendungen in verschiedenen Umgebungen zu überprüfen","pt":"O browser-check é uma ferramenta que utiliza o Chrome MCP para verificar a compatibilidade de aplicativos em diferentes navegadores.","ru":"Browser-check - это инструмент, который использует Chrome MCP для проверки совместимости приложений в разных браузерах.","ar":"browser-check هي أداة تستخدم Chrome MCP للتحقق من توافق التطبيقات في متصفحات مختلفة."},"seo":{"title":{"en":"browser-check: Setup Guide for AI Agents","zh":"浏览器检查工具：Chrome MCP接口设置指南","ja":"ブラウザ動作確認ツール：Chrome MCP接続のベストプラクティス","ko":"브라우저 검사 도구: 크롬 MCP 연결 설정 가이드","es":"Guía de configuración de browser-check para pruebas de re...","fr":"Guide de configuration de browser-check pour les tests de...","de":"Konfigurationsleitfaden für browser-check zur Leistungspr...","pt":"Guia de Configuração do browser-check: Verificação de Nav...","ru":"Настройка browser-check: Проверка Браузера с ИИ Агентами","ar":"دليل إعداد browser-check: التحقق من المتصفح"},"description":{"en":"Discover how to leverage browser-check for seamless Chrome MCP connections and efficient app testing - get started now!","zh":"了解如何使用Chrome MCP接口进行浏览器动作检查，确保您的应用程序在不同浏览器中正常运行","ja":"Chrome MCP接続を使用したブラウザ動作確認の方法を学び、Webアプリケーションのブラウザ間の互換性を確保する","ko":"크롬 MCP 연결을 사용하여 브라우저 동작을 확인하고 웹 애플리케이션의 브라우저 간 호환성을 보장하는 방법을 알아보세요","es":"Aprende a configurar browser-check para pruebas de rendimiento y asegúrate de que tus aplicaciones funcionen correctamente en diferentes navegadores","fr":"Découvrez comment configurer browser-check pour les tests de performance et assurez-vous que vos applications fonctionnent correctement sur différents naviga...","de":"Erfahren Sie, wie Sie browser-check für Leistungsprüfungen konfigurieren und sicherstellen, dass Ihre Anwendungen auf verschiedenen Browsern einwandfrei funk...","pt":"Aprenda a configurar o browser-check para verificar a compatibilidade do seu aplicativo em diferentes navegadores com o auxílio de ferramentas de IA.","ru":"Узнайте, как настроить browser-check для проверки совместимости вашего приложения в разных браузерах с помощью ИИ Агентов.","ar":"تعرف على كيفية إعداد browser-check للتحقق من توافق تطبيقك في متصفحات مختلفة باستخدام أدوات الذكاء الاصطناعي."},"definition":{"en":"browser-check is a skill that facilitates Chrome MCP-based app testing, verifying not just display but also operation accuracy.","zh":"浏览器检查工具是一种使用Chrome MCP接口进行动作检查的AIエージェント，确保Web应用程序的浏览器间互兼性。","ja":"ブラウザ動作確認ツールは、Chrome MCP接続を使用して動作を確認するAIエージェントで、Webアプリケーションのブラウザ間の互換性を確保します。","ko":"브라우저 검사 도구는 크롬 MCP 연결을 사용하여 동작을 확인하는 AI 도구로, 웹 애플리케이션의 브라우저 간 호환성을 보장합니다.","es":"Browser-check es una herramienta de prueba de rendimiento que verifica el funcionamiento de aplicaciones en diferentes navegadores","fr":"Browser-check est un outil de test de performance qui vérifie le fonctionnement des applications sur différents navigateurs","de":"Browser-check ist ein Tool für Leistungsprüfungen, das das Funktionieren von Anwendungen auf verschiedenen Browsern überprüft","pt":"O browser-check é uma técnica de verificação de navegador que utiliza o Chrome MCP para garantir a compatibilidade de aplicativos.","ru":"Browser-check - это техника проверки браузера, которая использует Chrome MCP для обеспечения совместимости приложений.","ar":"browser-check هي تقنية للتحقق من المتصفح التي تستخدم Chrome MCP لضمان توافق التطبيقات."},"features":{"en":["Verifies app functionality using Chrome MCP","Connects to target apps via mcp__claude-in-chrome__tabs_context_mcp","Creates new tabs with mcp__claude-in-chrome__tabs_create_mcp","Navigates to target URLs using mcp__claude-in-chrome__navigate","Supports port confirmation for apps like frontend (v1) and backend API"],"zh":["使用Chrome MCP接口进行动作检查","自动创建新标签页并访问目标URL","支持多个应用程序和端口号","提供详细的动作检查结果"],"ja":["Chrome MCP接続を使用した動作確認","新しいタブを作成して対象URLにアクセス","複数のアプリケーションとポート番号をサポート","詳細な動作確認結果を提供"],"ko":["크롬 MCP 연결을 사용하여 동작을 확인","새 탭을 생성하고 대상 URL에 액세스","여러 애플리케이션과 포트 번호를 지원","자세한 동작 확인 결과를 제공"],"es":["Utiliza Chrome MCP para la prueba de rendimiento","Verifica el funcionamiento de aplicaciones en diferentes puertos","Crea nuevos tabs para la prueba de rendimiento","Navega a la URL de destino para la prueba","Obtiene información del tab actual","Gestiona la conexión con Chrome MCP"],"fr":["Utilise Chrome MCP pour les tests de performance","Vérifie le fonctionnement des applications sur différents ports","Crée de nouveaux onglets pour les tests de performance","Navigue vers l''URL de destination pour les tests","Obtient des informations sur l''onglet actuel","Gère la connexion avec Chrome MCP"],"de":["Verwendet Chrome MCP für Leistungsprüfungen","Überprüft das Funktionieren von Anwendungen auf verschiedenen Ports","Erstellt neue Tabs für Leistungsprüfungen","Navigiert zur Ziel-URL für die Prüfung","Erfährt Informationen über das aktuelle Tab","Verwaltet die Verbindung mit Chrome MCP"],"pt":["Utiliza o Chrome MCP para verificar a compatibilidade de aplicativos","Cria um novo tab com o mcp__claude-in-chrome__tabs_create_mcp","Navega para a URL do aplicativo com o mcp__claude-in-chrome__navigate","Verifica a porta do aplicativo com o vite.config.ts","Suporta múltiplos aplicativos, incluindo frontend e backend"],"ru":["Использует Chrome MCP для проверки совместимости приложений","Создает новый таб с помощью mcp__claude-in-chrome__tabs_create_mcp","Переходит к URL приложения с помощью mcp__claude-in-chrome__navigate","Проверяет порт приложения с помощью vite.config.ts","Поддерживает несколько приложений, включая frontend и backend"],"ar":["تستخدم Chrome MCP للتحقق من توافق التطبيقات","تخلق علامة تبويب جديدة مع mcp__claude-in-chrome__tabs_create_mcp","تنتقل إلى عنوان URL للتطبيق مع mcp__claude-in-chrome__navigate","تتحقق من منفذ التطبيق مع vite.config.ts","تدعم تطبيقات متعددة، بما في ذلك frontend و backend"]},"keywords":{"en":["how to use browser-check","browser-check setup guide","browser-check alternative","browser-check vs Selenium","what is browser-check","browser-check install","Chrome MCP connection","app testing with browser-check"],"zh":["浏览器检查工具","Chrome MCP接口","AIエージェント","Web应用程序","浏览器间互兼性","动作检查","自动化测试"],"ja":["ブラウザ動作確認ツール","Chrome MCP接続","AIエージェント","Webアプリケーション","ブラウザ間の互換性","動作確認","自動テスト"],"ko":["브라우저 검사 도구","크롬 MCP 연결","AI 도구","웹 애플리케이션","브라우저 간 호환성","동작 확인","자동화 테스트"],"es":["browser-check","pruebas de rendimiento","Chrome MCP","herramientas de prueba","navegadores","puertos","tabs","URL de destino","conexión con Chrome MCP"],"fr":["browser-check","tests de performance","Chrome MCP","outils de test","navigateurs","ports","onglets","URL de destination","connexion avec Chrome MCP"],"de":["browser-check","Leistungsprüfungen","Chrome MCP","Testtools","Browser","Ports","Tabs","Ziel-URL","Verbindung mit Chrome MCP"],"pt":["browser-check","verificação de navegador","Chrome MCP","compatibilidade de aplicativos","vite.config.ts","mcp__claude-in-chrome__tabs_create_mcp","mcp__claude-in-chrome__navigate","ferramentas de IA","desenvolvimento de aplicativos"],"ru":["browser-check","проверка браузера","Chrome MCP","совместимость приложений","vite.config.ts","mcp__claude-in-chrome__tabs_create_mcp","mcp__claude-in-chrome__navigate","ИИ Агенты","разработка приложений"],"ar":["browser-check","التحقق من المتصفح","Chrome MCP","توافق التطبيقات","vite.config.ts","mcp__claude-in-chrome__tabs_create_mcp","mcp__claude-in-chrome__navigate","أدوات الذكاء الاصطناعي","تطوير التطبيقات"]}},"owner":"nnsi","repo":"hono-practice","repoPath":"nnsi/hono-practice","stars":1,"forks":0,"updatedAt":"2026-02-28T12:56:56Z","topics":[],"category":"community","skillMd":{"name":"browser-check","description":"Chrome MCPでブラウザ動作確認を標準化された手順で実施する。","bodyPreview":"# ブラウザ動作確認\r\n\r\nChrome MCPを使った動作確認の標準手順。「表示されている」だけでなく「操作が正しく動く」まで検証する。\r\n\r\n## 手順\r\n\r\n### Step 1: 対象アプリのポート確認\r\n\r\n確認対象のvite.config.tsを読んでポートを特定する。推測しない。\r\n\r\n| アプリ | ポート |\r\n|--------|--------|\r\n| frontend (v1) | 1357 |\r\n| frontend-v2 | 2460 |\r\n| backend API | 3456 |\r\n\r\n### Step 2: Chrome MCP接続\r\n\r\n```\r\n1. mcp__claude-in-chrome__tabs_context_mcp で現在のタブ情報を取得\r\n2. 接続失敗時はユーザーに「Chrome拡張の再接続をお願いします」と依頼\r\n3. mcp__claude-in-chrome__tabs_create_mcp で新しいタブを作成\r\n4. mcp__claude-in-chrome__navigate で対象URLにアクセス\r\n```","body":"# ブラウザ動作確認\r\n\r\nChrome MCPを使った動作確認の標準手順。「表示されている」だけでなく「操作が正しく動く」まで検証する。\r\n\r\n## 手順\r\n\r\n### Step 1: 対象アプリのポート確認\r\n\r\n確認対象のvite.config.tsを読んでポートを特定する。推測しない。\r\n\r\n| アプリ | ポート |\r\n|--------|--------|\r\n| frontend (v1) | 1357 |\r\n| frontend-v2 | 2460 |\r\n| backend API | 3456 |\r\n\r\n### Step 2: Chrome MCP接続\r\n\r\n```\r\n1. mcp__claude-in-chrome__tabs_context_mcp で現在のタブ情報を取得\r\n2. 接続失敗時はユーザーに「Chrome拡張の再接続をお願いします」と依頼\r\n3. mcp__claude-in-chrome__tabs_create_mcp で新しいタブを作成\r\n4. mcp__claude-in-chrome__navigate で対象URLにアクセス\r\n```\r\n\r\n### Step 3: ページ表示確認\r\n\r\n```\r\n1. mcp__claude-in-chrome__computer action=screenshot でスクリーンショット取得\r\n2. mcp__claude-in-chrome__read_page で要素の存在を確認\r\n3. mcp__claude-in-chrome__read_console_messages pattern=\"error|Error|ERR\" でコンソールエラーチェック\r\n```\r\n\r\n### Step 3.5: モバイルビューポート確認（UI変更時は必須）\r\n\r\nUI変更を含む場合、375px幅でのレイアウトを確認する:\r\n\r\n1. `mcp__claude-in-chrome__resize_window` で幅375px、高さ812pxにリサイズ\r\n2. スクリーンショットで表示確認\r\n3. 特に注意: ヘッダの中央寄せ、モーダル表示位置、フォームボタンの可視性、`autoFocus`によるキーボード占有\r\n\r\n### Step 4: 操作検証（これが重要）\r\n\r\n「表示されている」だけでは動作確認とは言えない。以下を実施する:\r\n\r\n1. **作成フロー**: ボタンクリック → フォーム入力 → 送信 → 結果表示を確認\r\n2. **編集フロー**: 既存データの編集 → 保存 → 反映を確認\r\n3. **削除フロー**: 削除ボタン → 確認UI表示 → 実行 → 一覧から消えることを確認\r\n4. **ネットワーク確認**: `mcp__claude-in-chrome__read_network_requests` でAPIコールの成否を確認\r\n\r\n### Step 5: 結果報告\r\n\r\n各ページ/フローごとに以下を報告:\r\n- スクリーンショット（成功時）\r\n- コンソールエラーの有無\r\n- ネットワークリクエストの成否\r\n- 操作検証の結果\r\n\r\n### Step 4補足: 空データだけで確認しない\r\n\r\n- 新規ユーザー（データ0件）だけでなく、**既存データがある状態**でも確認する\r\n- 特にグラフ・統計・プログレス表示は、データがないと正常に見えてバグを見逃す\r\n- フォーム系は送信まで確認する（表示されている≠動く）\r\n\r\n## 注意事項\r\n\r\n- ポートを間違えない（v1: 1357, v2: 2460）。必ずStep 1で確認する\r\n- 小さい要素はzoomで拡大して確認する\r\n- フォーム送信ボタンのクリックが効かない場合はEnterキーで代替\r\n- confirm()は使っていないはずだが、もし出たらセッションがブロックされるので注意\r\n- サブエージェントにはChrome MCPのアクセス権がない。ブラウザ確認は並列化できない\r\n"},"lastSynced":"2026-03-06T07:14:28.576Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing automated browser functionality checks through Chrome MCP.","zh":"非常适合需要通过 Chrome MCP 进行自动浏览器功能检查的前端代理","ja":"Chrome MCP 経由で自動ブラウザ機能チェックを必要とするフロントエンドエージェントに最適","ko":"Chrome MCP를 통해 자동 브라우저 기능 확인이 필요한 프론트엔드 에이전트에 적합","es":"Perfecto para agentes frontend que necesitan comprobaciones de funcionalidad automatizadas del navegador a través de Chrome MCP.","fr":"Parfait pour les agents frontend ayant besoin de vérifications de fonctionnalité de navigateur automatisées via Chrome MCP.","de":"Perfekt für Frontend-Agents, die automatisierte Browser-Funktionsprüfungen über Chrome MCP benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de funcionalidades de navegador automatizadas por meio do Chrome MCP.","ru":"Идеально подходит для агентов Frontend, которым требуются автоматизированные функции браузера через Chrome MCP.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى وظائف متصفح أوتوماتيكية من خلال Chrome MCP."},"recommendation":{"en":"Empowers agents to verify app functionality by leveraging Chrome MCP for accurate operation checks, streamlining the testing process with vite.config.ts port identification and automated tab creation using mcp__claude-in-chrome__tabs_context_mcp and mcp__claude-in-chrome__tabs_create_mcp.","zh":"赋予代理验证应用功能的能力，通过 Chrome MCP 进行准确的操作检查，并通过 vite.config.ts 端口识别和使用 mcp__claude-in-chrome__tabs_context_mcp 及 mcp__claude-in-chrome__tabs_create_mcp 的自动标签创建来简化测试过程","ja":"エージェントにアプリケーションの機能を検証する能力を与え、Chrome MCP を使用して正確な操作チェックを実行し、vite.config.ts ポート識別と mcp__claude-in-chrome__tabs_context_mcp および mcp__claude-in-chrome__tabs_create_mcp の自動タブ作成を使用してテストプロセスを簡素化する","ko":"에이전트가 애플리케이션 기능을 확인할 수 있는 기능을 제공하여 Chrome MCP를 사용하여 정확한 작업 확인을 수행하고 vite.config.ts 포트 식별 및 mcp__claude-in-chrome__tabs_context_mcp 및 mcp__claude-in-chrome__tabs_create_mcp의 자동 탭 생성을 사용하여 테스트 프로세스를 단순화","es":"Habilita a los agentes a verificar la funcionalidad de la aplicación aprovechando Chrome MCP para comprobaciones de operación precisas, simplificando el proceso de prueba con identificación de puerto vite.config.ts y creación de pestañas automatizada usando mcp__claude-in-chrome__tabs_context_mcp y mcp__claude-in-chrome__tabs_create_mcp.","fr":"Permet aux agents de vérifier la fonctionnalité de l''application en exploitant Chrome MCP pour des vérifications d''opération précises, simplifiant le processus de test avec l''identification de port vite.config.ts et la création de onglets automatisée à l''aide de mcp__claude-in-chrome__tabs_context_mcp et mcp__claude-in-chrome__tabs_create_mcp.","de":"Ermächtigt die Agenten, die Funktionalität der App zu überprüfen, indem sie Chrome MCP für genaue Funktionsprüfungen nutzen, den Testprozess mit vite.config.ts-Porterkennung und automatischer Tab-Erstellung mithilfe von mcp__claude-in-chrome__tabs_context_mcp und mcp__claude-in-chrome__tabs_create_mcp zu rationalisieren.","pt":"Habilita os agentes a verificar a funcionalidade do aplicativo aproveitando o Chrome MCP para verificações de operação precisas, racionalizando o processo de teste com identificação de porta vite.config.ts e criação automática de guias usando mcp__claude-in-chrome__tabs_context_mcp e mcp__claude-in-chrome__tabs_create_mcp.","ru":"Наделяет агентов возможностью проверять функциональность приложения, используя Chrome MCP для точных проверок операций, оптимизируя процесс тестирования с помощью идентификации порта vite.config.ts и автоматического создания вкладок с использованием mcp__claude-in-chrome__tabs_context_mcp и mcp__claude-in-chrome__tabs_create_mcp.","ar":"يمنح الوكلاء القدرة على التحقق من وظائف التطبيق من خلال الاستفادة من Chrome MCP للتحقق الدقيق من العمليات ، وتبسيط عملية الاختبار مع تحديد منفذ vite.config.ts والإنشاء التلقائي للفصول باستخدام mcp__claude-in-chrome__tabs_context_mcp و mcp__claude-in-chrome__tabs_create_mcp."},"useCases":{"en":["Automating browser checks for frontend applications","Validating app functionality through Chrome MCP","Streamlining testing processes with automated port identification and tab creation"],"zh":["前端应用程序的自动浏览器检查","通过 Chrome MCP 验证应用功能","使用自动端口识别和标签创建简化测试过程"],"ja":["フロントエンドアプリケーションの自動ブラウザチェック","Chrome MCP を使用したアプリケーションの機能の検証","自動ポート識別とタブ作成を使用したテストプロセスの簡素化"],"ko":["프론트엔드 애플리케이션의 자동 브라우저 확인","Chrome MCP를 사용한 애플리케이션 기능 확인","자동 포트 식별 및 탭 생성을 사용한 테스트 프로세스 단순화"],"es":["Automatización de comprobaciones de navegador para aplicaciones frontend","Validación de la funcionalidad de la aplicación a través de Chrome MCP","Racionalización de los procesos de prueba con identificación de puerto automatizada y creación de pestañas"],"fr":["Automatisation des vérifications de navigateur pour les applications frontend","Validation de la fonctionnalité de l''application via Chrome MCP","Rationalisation des processus de test avec identification de port automatisée et création d''onglets"],"de":["Automatisierung von Browser-Checks für Frontend-Anwendungen","Überprüfung der Funktionalität der App über Chrome MCP","Rationalisierung der Testprozesse mit automatisierter Porterkennung und Tab-Erstellung"],"pt":["Automatizar verificações de navegador para aplicações frontend","Validar a funcionalidade do aplicativo por meio do Chrome MCP","Otimizar processos de teste com identificação automática de porta e criação de guias"],"ru":["Автоматизировать проверки браузера для frontend-приложений","Проверять функциональность приложения с помощью Chrome MCP","Оптимизировать процессы тестирования с автоматической идентификацией порта и созданием вкладок"],"ar":["أتمتة فحص المتصفحات لبرامج الأمامية","التحقق من وظائف التطبيق من خلال Chrome MCP","تبسيط عمليات الاختبار مع تحديد منفذ أوتوماتيكي وإنشاء فصول"]},"limitations":{"en":["Requires Chrome MCP setup","Limited to Chrome browser","Needs access to vite.config.ts for port confirmation"],"zh":["需要 Chrome MCP 设置","仅限 Chrome 浏览器","需要访问 vite.config.ts 以确认端口"],"ja":["Chrome MCP の設定が必要","Chrome ブラウザのみ対応","vite.config.ts にアクセスしてポートを確認する必要がある"],"ko":["Chrome MCP 설정이 필요","Chrome 브라우저만 해당","vite.config.ts에 접근하여 포트를 확인해야 함"],"es":["Requiere configuración de Chrome MCP","Limitado al navegador Chrome","Requiere acceso a vite.config.ts para confirmación de puerto"],"fr":["Nécessite une configuration de Chrome MCP","Limité au navigateur Chrome","Nécessite un accès à vite.config.ts pour confirmation de port"],"de":["Benötigt Chrome MCP-Konfiguration","Begrenzt auf Chrome-Browser","Benötigt Zugriff auf vite.config.ts für Portbestätigung"],"pt":["Requer configuração do Chrome MCP","Limitado ao navegador Chrome","Necessita acesso ao vite.config.ts para confirmação de porta"],"ru":["Требует настройки Chrome MCP","Ограничен браузером Chrome","Требует доступа к vite.config.ts для подтверждения порта"],"ar":["يتطلب إعداد Chrome MCP","محدود بالمتصفح Chrome","يحتاج إلى الوصول إلى vite.config.ts للتأكيد على المنفذ"]},"version":4},"contentHash":"af3d16d233c5712b3b3b085a2bf076f19e72e762acc4c2237f650e71a1391ab6","qualityScore":36}');
