INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nnsi/hono-practice/browser-check', 'browser-check', 'nnsi', 'hono-practice', 'community', 'browser-check nnsi hono-practice community The browser-check skill enables AI agents to verify app functionality through Chrome MCP, ensuring accurate operation checks. It benefits developers by streamlining the testing process. 浏览器检查工具使用Chrome MCP接口进行动作检查，确保应用程序在不同浏览器中正常运行。 ブラウザ動作確認ツールはChrome MCP接続を使用して動作を確認し、Webアプリケーションのブラウザ間の互換性を確保します。 브라우저 검사 도구는 크롬 MCP 연결을 사용하여 동작을 확인하고 웹 애플리케이션의 브라우저 간 호환성을 보장합니다. Browser-check es una herramienta para pruebas de rendimiento que utiliza Chrome MCP para verificar el funcionamiento de aplicaciones en diferentes entornos Browser-check est un outil de test de performance qui utilise Chrome MCP pour vérifier le fonctionnement des applications dans différents environnements Browser-check ist ein Tool für Leistungsprüfungen, das Chrome MCP verwendet, um das Funktionieren von Anwendungen in verschiedenen Umgebungen zu überprüfen O browser-check é uma ferramenta que utiliza o Chrome MCP para verificar a compatibilidade de aplicativos em diferentes navegadores. Browser-check - это инструмент, который использует Chrome MCP для проверки совместимости приложений в разных браузерах. browser-check هي أداة تستخدم Chrome MCP للتحقق من توافق التطبيقات في متصفحات مختلفة. how to use browser-check browser-check setup guide browser-check alternative browser-check vs Selenium what is browser-check browser-check install Chrome MCP connection app testing with browser-check 浏览器检查工具 Chrome MCP接口 AIエージェント Web应用程序 浏览器间互兼性 动作检查 自动化测试 Verifies app functionality using Chrome MCP Connects to target apps via mcp__claude-in-chrome__tabs_context_mcp Creates new tabs with mcp__claude-in-chrome__tabs_create_mcp Navigates to target URLs using mcp__claude-in-chrome__navigate Supports port confirmation for apps like frontend (v1) and backend API browser-check is a skill that facilitates Chrome MCP-based app testing, verifying not just display but also operation accuracy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danburonline/public-notes/obsidian-cli', 'community', 'danburonline', 'public-notes', 'danburonline/public-notes', 'obsidian-cli', 1, 0, 36, '2026-02-28T21:10:45Z', '2026-03-07T01:54:37.063Z', 'b54257cdc0e5d04488b35b0c797bfe427b24359f0848d3c73924dcacf8da6358', '{"id":"danburonline/public-notes/obsidian-cli","name":"obsidian-cli","description":{"en":"The obsidian-cli skill allows developers to interact with a running Obsidian instance using the `obsidian` command. It provides a command reference guide and supports parameters and flags.","zh":"Obsidian CLI 是一个用于与运行中的 Obsidian 实例交互的命令行工具，需要 Obsidian 已经打开","ja":"Obsidian CLI は、実行中の Obsidian インスタンスとやり取りするためのコマンドラインツールです。Obsidian が既に開いている必要があります","ko":"Obsidian CLI는 실행 중인 Obsidian 인스턴스와 상호 작용하는 명령줄 도구로 Obsidian이 이미 열려 있는 경우에 필요합니다","es":"Obsidian CLI es una herramienta de línea de comandos para interactuar con instancias de Obsidian. Ofrece comandos como create y soporte para parámetros y flags.","fr":"Obsidian CLI est un outil de ligne de commande pour interagir avec les instances d''Obsidian. Il propose des commandes telles que create et prend en charge les paramètres et les flags.","de":"Obsidian CLI ist ein Befehlszeilentool zur Interaktion mit Obsidian-Instanzen. Es bietet Befehle wie create und unterstützt Parameter und Flags.","pt":"O Obsidian-CLI é uma ferramenta de linha de comando para interagir com instâncias do Obsidian. Veja a documentação completa para mais informações.","ru":"Obsidian-CLI - это инструмент командной строки для взаимодействия с экземплярами Obsidian. Посмотрите полную документацию для более подробной информации.","ar":"Obsidian-CLI هو أداة سطر الأوامر للتفاعل مع مثيلات Obsidian. راجع الوثائق الكاملة لمزيد من المعلومات."},"seo":{"title":{"en":"obsidian-cli: Command Reference Guide | AI Agent Skill","zh":"Obsidian CLI 快速入门指南","ja":"Obsidian CLI の設定とベストプラクティス - AIエージェント","ko":"Obsidian CLI 사용자 가이드 - AI 도구","es":"Guía de configuración de Obsidian CLI para desarrolladores","fr":"Guide d''installation d''Obsidian CLI pour les développeurs","de":"Einrichtungsleitfaden für Obsidian CLI-Entwickler","pt":"Guia de Configuração do Obsidian-CLI: Ferramenta de Linha...","ru":"Настройка Obsidian-CLI: Инструмент командной строки для И...","ar":"دليل إعداد Obsidian-CLI: أداة سطر الأوامر للوكلاء الذكيين"},"description":{"en":"Unlock the full potential of Obsidian with the obsidian-cli skill. Learn how to use the `obsidian` command to interact with your instance and discover the la...","zh":"了解 Obsidian CLI 的命令参考和语法，包括参数和标志的使用方法","ja":"Obsidian CLI のコマンドリファレンスとシンタックスをマスターし、AIエージェントの機能を最大限に活用する","ko":"Obsidian CLI의 기능과 사용법을 익히고 AI 도구의 잠재력을 최대한 활용하십시오","es":"Aprende a utilizar la línea de comandos de Obsidian para interactuar con instancias de Obsidian. Descubre los comandos y la sintaxis disponibles.","fr":"Découvrez comment utiliser la ligne de commande d''Obsidian pour interagir avec les instances d''Obsidian. Consultez les commandes et la syntaxe disponibles.","de":"Erfahren Sie, wie Sie die Befehlszeile von Obsidian verwenden, um mit Obsidian-Instanzen zu interagieren. Stöbern Sie durch die verfügbaren Befehle und Syntax.","pt":"Aprenda a usar o Obsidian-CLI para interagir com instâncias do Obsidian. Veja a documentação completa e os comandos disponíveis.","ru":"Узнайте, как использовать Obsidian-CLI для взаимодействия с экземплярами Obsidian. Посмотрите полную документацию и доступные команды.","ar":"تعلم كيفية استخدام Obsidian-CLI للتفاعل مع مثيلات Obsidian. راجع الوثائق الكاملة والأوامر المتاحة."},"definition":{"en":"obsidian-cli is a command-line interface for interacting with Obsidian instances, providing a syntax for running commands with parameters and flags.","zh":"Obsidian CLI 是一个命令行工具，用于与 Obsidian 实例交互","ja":"Obsidian CLI は、Obsidian インスタンスとやり取りするためのコマンドラインツールです","ko":"Obsidian CLI는 Obsidian 인스턴스와 상호 작용하는 명령줄 도구입니다","es":"Obsidian CLI es una interfaz de línea de comandos para interactuar con Obsidian","fr":"Obsidian CLI est une interface de ligne de commande pour interagir avec Obsidian","de":"Obsidian CLI ist eine Befehlszeilen-Schnittstelle zur Interaktion mit Obsidian","pt":"O Obsidian-CLI é uma ferramenta de linha de comando que permite interagir com instâncias do Obsidian.","ru":"Obsidian-CLI - это инструмент командной строки, который позволяет взаимодействовать с экземплярами Obsidian.","ar":"Obsidian-CLI هو أداة سطر الأوامر التي تسمح بالتفاعل مع مثيلات Obsidian."},"features":{"en":["Runs `obsidian help` to display all available commands","Supports parameters with values using the `=` syntax","Allows quoting values with spaces for commands like `obsidian create`","Includes boolean switches with no value using flags like `silent` and `overwrite`","Provides full documentation at https://help.obsidian.md/cli"],"zh":["支持参数和标志的使用","可以创建新笔记","可以使用 silent 和 overwrit 标志","提供命令参考和语法指导"],"ja":["パラメータとフラグの使用をサポート","新しいノートを作成できます","silent と overwrit フラグを使用できます","コマンドリファレンスとシンタックスガイドを提供"],"ko":["매개변수와 플래그의 사용을 지원","새 노트를 만들 수 있습니다","silent 및 overwrit 플래그를 사용할 수 있습니다","명령어 参考 및 구문 가이드를 제공"],"es":["Soporte para parámetros con valores","Uso de flags booleanos sin valor","Comando create para crear notas","Sintaxis de comandos personalizable","Compatibilidad con Obsidian MD","Acceso a documentación en línea"],"fr":["Prise en charge des paramètres avec des valeurs","Utilisation de flags booléens sans valeur","Commande create pour créer des notes","Syntaxe de commande personnalisable","Compatibilité avec Obsidian MD","Accès à la documentation en ligne"],"de":["Unterstützung für Parameter mit Werten","Verwendung von booleschen Flags ohne Wert","Befehl create zum Erstellen von Notizen","Anpassbare Befehlssyntax","Kompatibilität mit Obsidian MD","Zugriff auf Online-Dokumentation"],"pt":["Suporte a parâmetros com valores","Suporte a flags booleanos","Comando de ajuda para ver todos os comandos disponíveis","Documentação completa disponível em https://help.obsidian.md/cli","Suporte a criar notas com conteúdo personalizado"],"ru":["Поддержка параметров с значениями","Поддержка булевых флагов","Команда помощи для просмотра всех доступных команд","Полная документация доступна на https://help.obsidian.md/cli","Поддержка создания заметок с пользовательским содержимым"],"ar":["دعم المعلمات بقيم","دعم الأعلام المنطقية","أمر المساعدة لعرض جميع الأوامر المتاحة","الوثائق الكاملة متاحة على https://help.obsidian.md/cli","دعم إنشاء الملاحظات بمحتوى مخصص"]},"keywords":{"en":["how to use obsidian-cli","obsidian-cli command reference","obsidian-cli vs other note-taking tools","obsidian-cli install guide","obsidian-cli setup tutorial","what is obsidian-cli","obsidian-cli alternative","obsidian-cli documentation"],"zh":["Obsidian CLI","命令行工具","Obsidian 实例","参数和标志","创建新笔记","silent 和 overwrit 标志","命令参考","语法指导"],"ja":["Obsidian CLI","コマンドラインツール","Obsidian インスタンス","パラメータとフラグ","新しいノートを作成","silent と overwrit フラグ","コマンドリファレンス","シンタックスガイド","AIエージェント"],"ko":["Obsidian CLI","명령줄 도구","Obsidian 인스턴스","매개변수와 플래그","새 노트 만들기","silent 및 overwrit 플래그","명령어 参考","구문 가이드","AI 도구"],"es":["Obsidian CLI","Herramientas de línea de comandos","Integración con Obsidian","Desarrollo de software","Automatización de tareas","Guías de configuración","Documentación de Obsidian","Herramientas de productividad","Tecnologías de desarrollo"],"fr":["Obsidian CLI","Outils de ligne de commande","Intégration avec Obsidian","Développement de logiciels","Automatisation de tâches","Guides de configuration","Documentation d''Obsidian","Outils de productivité","Technologies de développement"],"de":["Obsidian CLI","Befehlszeilentools","Integration mit Obsidian","Software-Entwicklung","Automatisierung von Aufgaben","Einrichtungsleitfäden","Dokumentation von Obsidian","Produktivitätstools","Entwicklungstechnologien"],"pt":["Obsidian-CLI","ferramenta de linha de comando","interagir com instâncias do Obsidian","parâmetros com valores","flags booleanos","comando de ajuda","documentação completa","criar notas personalizadas"],"ru":["Obsidian-CLI","инструмент командной строки","взаимодействие с экземплярами Obsidian","параметры с значениями","булевые флаги","команда помощи","полная документация","создание заметок с пользовательским содержимым"],"ar":["Obsidian-CLI","أداة سطر الأوامر","التفاعل مع مثيلات Obsidian","معلمات بقيم","أعلام منطقية","أمر المساعدة","الوثائق الكاملة","إنشاء الملاحظات بمحتوى مخصص"]}},"owner":"danburonline","repo":"public-notes","repoPath":"danburonline/public-notes","stars":1,"forks":0,"updatedAt":"2026-02-28T21:10:45Z","topics":[],"category":"community","skillMd":{"name":"obsidian-cli","description":"Interact with Obsidian vaults using the Obsidian CLI to read, create, search, and manage notes, tasks, properties, and more. Also supports plugin and theme development with commands to reload plugins, run JavaScript, capture errors, take screenshots, and inspect the DOM. Use when the user asks to interact with their Obsidian vault, manage notes, search vault content, perform vault operations from the command line, or develop and debug Obsidian plugins and themes.","bodyPreview":"# Obsidian CLI\n\nUse the `obsidian` CLI to interact with a running Obsidian instance. Requires Obsidian to be open.\n\n## Command reference\n\nRun `obsidian help` to see all available commands. This is always up to date. Full docs: https://help.obsidian.md/cli\n\n## Syntax\n\n**Parameters** take a value with `=`. Quote values with spaces:\n\n```bash\nobsidian create name=\"My Note\" content=\"Hello world\"\n```\n\n**Flags** are boolean switches with no value:\n\n```bash\nobsidian create name=\"My Note\" silent overwrit","body":"# Obsidian CLI\n\nUse the `obsidian` CLI to interact with a running Obsidian instance. Requires Obsidian to be open.\n\n## Command reference\n\nRun `obsidian help` to see all available commands. This is always up to date. Full docs: https://help.obsidian.md/cli\n\n## Syntax\n\n**Parameters** take a value with `=`. Quote values with spaces:\n\n```bash\nobsidian create name=\"My Note\" content=\"Hello world\"\n```\n\n**Flags** are boolean switches with no value:\n\n```bash\nobsidian create name=\"My Note\" silent overwrite\n```\n\nFor multiline content use `\\n` for newline and `\\t` for tab.\n\n## File targeting\n\nMany commands accept `file` or `path` to target a file. Without either, the active file is used.\n\n- `file=<name>` — resolves like a wikilink (name only, no path or extension needed)\n- `path=<path>` — exact path from vault root, e.g. `folder/note.md`\n\n## Vault targeting\n\nCommands target the most recently focused vault by default. Use `vault=<name>` as the first parameter to target a specific vault:\n\n```bash\nobsidian vault=\"My Vault\" search query=\"test\"\n```\n\n## Common patterns\n\n```bash\nobsidian read file=\"My Note\"\nobsidian create name=\"New Note\" content=\"# Hello\" template=\"Template\" silent\nobsidian append file=\"My Note\" content=\"New line\"\nobsidian search query=\"search term\" limit=10\nobsidian daily:read\nobsidian daily:append content=\"- [ ] New task\"\nobsidian property:set name=\"status\" value=\"done\" file=\"My Note\"\nobsidian tasks daily todo\nobsidian tags sort=count counts\nobsidian backlinks file=\"My Note\"\n```\n\nUse `--copy` on any command to copy output to clipboard. Use `silent` to prevent files from opening. Use `total` on list commands to get a count.\n\n## Plugin development\n\n### Develop/test cycle\n\nAfter making code changes to a plugin or theme, follow this workflow:\n\n1. **Reload** the plugin to pick up changes:\n   ```bash\n   obsidian plugin:reload id=my-plugin\n   ```\n2. **Check for errors** — if errors appear, fix and repeat from step 1:\n   ```bash\n   obsidian dev:errors\n   ```\n3. **Verify visually** with a screenshot or DOM inspection:\n   ```bash\n   obsidian dev:screenshot path=screenshot.png\n   obsidian dev:dom selector=\".workspace-leaf\" text\n   ```\n4. **Check console output** for warnings or unexpected logs:\n   ```bash\n   obsidian dev:console level=error\n   ```\n\n### Additional developer commands\n\nRun JavaScript in the app context:\n\n```bash\nobsidian eval code=\"app.vault.getFiles().length\"\n```\n\nInspect CSS values:\n\n```bash\nobsidian dev:css selector=\".workspace-leaf\" prop=background-color\n```\n\nToggle mobile emulation:\n\n```bash\nobsidian dev:mobile on\n```\n\nRun `obsidian help` to see additional developer commands including CDP and debugger controls.\n"},"lastSynced":"2026-03-07T01:54:37.063Z","agentAnalysis":{"suitability":{"en":"Perfect for Note-Taking Agents needing seamless integration with Obsidian instances via command-line interfaces.","zh":"非常适合需要与Obsidian实例通过命令行接口实现无缝集成的笔记记录代理。","ja":"Obsidianインスタンスとのシームレスな統合が必要なノートテイクエージェントに最適です。","ko":"Obsidian 인스턴스와 명령행 인터페이스를 통해 무중단 통합이 필요한 노트 작성 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Notas que necesitan una integración perfecta con instancias de Obsidian a través de interfaces de línea de comandos.","fr":"Parfait pour les Agents de prise de notes nécessitant une intégration transparente avec des instances Obsidian via des interfaces de ligne de commande.","de":"Perfekt für Notiz-Agents, die eine nahtlose Integration mit Obsidian-Instanzen über Kommandozeilenoberflächen benötigen.","pt":"Perfeito para Agentes de Notas que precisam de integração perfeita com instâncias do Obsidian via interfaces de linha de comando.","ru":"Идеально подходит для агентов заметок, требующих бесшовной интеграции с экземплярами Obsidian через командную строку.","ar":"مثالي للوكلاء ملاحظة التي تحتاج إلى التكامل السلس مع مثيلات Obsidian من خلال واجهات سطر الأوامر."},"recommendation":{"en":"Empowers agents to interact with running Obsidian instances using the `obsidian` command, supporting parameters and flags for advanced note management, including creating notes with specific names and content using syntax like `obsidian create name=\"My Note\" content=\"Hello world\"`.","zh":"赋予代理与运行中的Obsidian实例交互的能力，使用`obsidian`命令，并支持高级笔记管理的参数和标志，包括使用语法如`obsidian create name=\"我的笔记\" content=\"你好，世界\"`创建具有特定名称和内容的笔记。","ja":"エージェントに、`obsidian` コマンドを使用して実行中の Obsidian インスタンスとやり取りする能力を与え、パラメータとフラグをサポートして高度なノート管理を実現します。たとえば、`obsidian create name=\"マイノート\" content=\"ハローワールド\"` のような構文を使用して、特定の名前と内容を持つノートを作成します。","ko":"실행 중인 Obsidian 인스턴스와 상호 작용할 수 있는 기능을 에이전트에 부여하여 `obsidian` 명령을 사용하고, 고급 노트 관리를 위한 매개 변수 및 플래그를 지원합니다. 예를 들어 `obsidian create name=\"나의 노트\" content=\"안녕하세요, 세계\"`와 같은 구문을 사용하여 특정 이름과 내용을 가진 노트를 생성합니다.","es":"Habilita a los agentes a interactuar con instancias de Obsidian en ejecución utilizando el comando `obsidian`, que admite parámetros y opciones para una gestión de notas avanzada, incluida la creación de notas con nombres y contenido específicos utilizando una sintaxis como `obsidian create name=\"My Note\" content=\"Hello world\"`.","fr":"Permet aux agents d''interagir avec des instances Obsidian en cours d''exécution en utilisant la commande `obsidian`, qui prend en charge les paramètres et les options pour une gestion de notes avancée, notamment la création de notes avec des noms et un contenu spécifiques en utilisant une syntaxe telle que `obsidian create name=\"My Note\" content=\"Hello world\"`.","de":"Ermöglicht es Agents, mit laufenden Obsidian-Instanzen über das `obsidian`-Kommando zu interagieren, das Parameter und Optionen für eine erweiterte Notizverwaltung unterstützt, einschließlich der Erstellung von Notizen mit spezifischen Namen und Inhalten unter Verwendung einer Syntax wie `obsidian create name=\"My Note\" content=\"Hello world\"`.","pt":"Habilita os agentes a interagir com instâncias do Obsidian em execução usando o comando `obsidian`, que suporta parâmetros e flags para gerenciamento avançado de notas, incluindo a criação de notas com nomes e conteúdo específicos usando sintaxe como `obsidian create name=\"Minha Nota\" content=\"Olá mundo\"`.","ru":"Наделяет агентов возможностью взаимодействовать с запущенными экземплярами Obsidian, используя команду `obsidian`, поддерживающую параметры и флаги для продвинутого управления заметками, включая создание заметок с конкретными именами и содержимым, используя синтаксис, такой как `obsidian create name=\"Моя Заметка\" content=\"Привет мир\"`.","ar":"يمنح الوكلاء القدرة على التفاعل مع مثيلات Obsidian التي تعمل باستخدام الأمر `obsidian` ، الذي يدعم المعلمات والأعلام لإدارة الملاحظات المتقدمة ، بما في ذلك إنشاء ملاحظات بأسماء ومحتوى محددين باستخدام بناء جملة مثل `obsidian create name=\"ملاحظتي\" content=\"مرحبا بالعالم\"`."},"useCases":{"en":["Automating note creation with custom names and content","Debugging Obsidian instance configurations using the `obsidian help` command","Integrating Obsidian with other tools using command-line parameters and flags"],"zh":["使用自定义名称和内容自动创建笔记","使用`obsidian help`命令调试Obsidian实例配置","使用命令行参数和标志将Obsidian与其他工具集成"],"ja":["カスタム名と内容でノートを作成するための自動化","`obsidian help` コマンドを使用して Obsidian インスタンスの構成をデバッグする","コマンドライン パラメータとフラグを使用して Obsidian を他のツールと統合する"],"ko":["사용자 지정 이름 및 내용으로 노트를 자동으로 생성하는 것"," `obsidian help` 명령을 사용하여 Obsidian 인스턴스 구성 디버깅","명령행 매개 변수 및 플래그를 사용하여 Obsidian을 다른 도구와 통합"],"es":["Automatización de la creación de notas con nombres y contenido personalizados","Depuración de configuraciones de instancias de Obsidian utilizando el comando `obsidian help`","Integración de Obsidian con otras herramientas utilizando parámetros y opciones de la línea de comandos"],"fr":["Automatisation de la création de notes avec des noms et un contenu personnalisés","Débogage des configurations d''instances Obsidian en utilisant la commande `obsidian help`","Intégration d''Obsidian avec d''autres outils en utilisant des paramètres et des options de ligne de commande"],"de":["Automatisierung der Notizerstellung mit benutzerdefinierten Namen und Inhalten","Fehlerbehebung bei Obsidian-Instanzkonfigurationen mit dem `obsidian help`-Kommando","Integration von Obsidian mit anderen Tools unter Verwendung von Kommandozeilenparametern und -optionen"],"pt":["Automatizar a criação de notas com nomes e conteúdo personalizados","Depurar configurações de instâncias do Obsidian usando o comando `obsidian help`","Integrar o Obsidian com outras ferramentas usando parâmetros e flags de linha de comando"],"ru":["Автоматизировать создание заметок с индивидуальными именами и содержимым","Отлаживать конфигурации экземпляров Obsidian, используя команду `obsidian help`","Интегрировать Obsidian с другими инструментами, используя параметры и флаги командной строки"],"ar":["السماح بالتخصيص لإنشاء الملاحظات بأسماء ومحتوى مخصصين","تصحيح أخطاء cấuture المثيلات من Obsidian باستخدام الأمر `obsidian help`","دمج Obsidian مع أدوات أخرى باستخدام معلمات وأعلام سطر الأوامر"]},"limitations":{"en":["Requires Obsidian to be open","Command-line interface only"],"zh":["需要Obsidian打开","仅命令行接口"],"ja":["Obsidianが開いている必要がある","コマンドラインインターフェイスのみ"],"ko":["Obsidian이 열려 있어야 함","명령행 인터페이스만"],"es":["Requiere que Obsidian esté abierto","Sólo interfaz de línea de comandos"],"fr":["Nécessite que Obsidian soit ouvert","Interface de ligne de commande uniquement"],"de":["Benötigt, dass Obsidian geöffnet ist","Nur Kommandozeilenoberfläche"],"pt":["Requer que o Obsidian esteja aberto","Interface de linha de comando apenas"],"ru":["Требует, чтобы Obsidian был открыт","Только командная строка"],"ar":["يحتاج إلى أن يكون Obsidian مفتوحا","واجهة سطر الأوامر فقط"]},"version":4},"contentHash":"b54257cdc0e5d04488b35b0c797bfe427b24359f0848d3c73924dcacf8da6358","qualityScore":36}');
