INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danburonline/public-notes/obsidian-cli', 'obsidian-cli', 'danburonline', 'public-notes', 'community', 'obsidian-cli danburonline public-notes community The obsidian-cli skill allows developers to interact with a running Obsidian instance using the `obsidian` command. It provides a command reference guide and supports parameters and flags. Obsidian CLI 是一个用于与运行中的 Obsidian 实例交互的命令行工具，需要 Obsidian 已经打开 Obsidian CLI は、実行中の Obsidian インスタンスとやり取りするためのコマンドラインツールです。Obsidian が既に開いている必要があります Obsidian CLI는 실행 중인 Obsidian 인스턴스와 상호 작용하는 명령줄 도구로 Obsidian이 이미 열려 있는 경우에 필요합니다 Obsidian CLI es una herramienta de línea de comandos para interactuar con instancias de Obsidian. Ofrece comandos como create y soporte para parámetros y flags. Obsidian CLI est un outil de ligne de commande pour interagir avec les instances d''Obsidian. Il propose des commandes telles que create et prend en charge les paramètres et les flags. Obsidian CLI ist ein Befehlszeilentool zur Interaktion mit Obsidian-Instanzen. Es bietet Befehle wie create und unterstützt Parameter und Flags. O Obsidian-CLI é uma ferramenta de linha de comando para interagir com instâncias do Obsidian. Veja a documentação completa para mais informações. Obsidian-CLI - это инструмент командной строки для взаимодействия с экземплярами Obsidian. Посмотрите полную документацию для более подробной информации. Obsidian-CLI هو أداة سطر الأوامر للتفاعل مع مثيلات Obsidian. راجع الوثائق الكاملة لمزيد من المعلومات. how to use obsidian-cli obsidian-cli command reference obsidian-cli vs other note-taking tools obsidian-cli install guide obsidian-cli setup tutorial what is obsidian-cli obsidian-cli alternative obsidian-cli documentation Obsidian CLI 命令行工具 Obsidian 实例 参数和标志 创建新笔记 silent 和 overwrit 标志 命令参考 语法指导 Runs `obsidian help` to display all available commands Supports parameters with values using the `=` syntax Allows quoting values with spaces for commands like `obsidian create` Includes boolean switches with no value using flags like `silent` and `overwrite` Provides full documentation at https://help.obsidian.md/cli obsidian-cli is a command-line interface for interacting with Obsidian instances, providing a syntax for running commands with parameters and flags.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('buurguees/av-tech-p-gina-de-inicio/nexo-brand-guidelines', 'community', 'buurguees', 'av-tech-p-gina-de-inicio', 'buurguees/av-tech-p-gina-de-inicio', 'nexo-brand-guidelines', 1, 0, 36, '2026-03-02T23:59:53Z', '2026-03-06T13:10:09.645Z', '7b0423e315c48d373421b5183ed46b20053009820a180caac4b452defa315bec', '{"id":"buurguees/av-tech-p-gina-de-inicio/nexo-brand-guidelines","name":"nexo-brand-guidelines","description":{"en":"The nexo-brand-guidelines skill provides a comprehensive brand and visual system for generating professional documents and interfaces, including proposals, reports, and UI designs.","zh":"NEXO品牌指南提供了一致的UI和文档样式，适用于ERP、营销材料和技术文档","ja":"NEXOブランドガイドラインは、ERP、マーケティング資料、テクニカルドキュメント向けの一貫したUIとドキュメントスタイルを提供します","ko":"NEXO 브랜드 가이드라인은 ERP, 마케팅 자료, 기술 문서를 위한 일관된 UI와 문서 스타일을 제공합니다","es":"El skill nexo-brand-guidelines ofrece una guía para mantener la consistencia de la marca en documentos y presentaciones, incluyendo propuestas comerciales, informes financieros y documentación técnica","fr":"Le skill nexo-brand-guidelines propose un guide pour maintenir la cohérence de la marque dans les documents et les présentations, y compris les propositions commerciales, les rapports financiers et la documentation technique","de":"Das Skill nexo-brand-guidelines bietet einen Leitfaden, um die Markenkonstistenz in Dokumenten und Präsentationen zu gewährleisten, einschließlich Geschäftsproposalen, Finanzberichten und technischer Dokumentation","pt":"O Nexo Brand Guidelines é um skill que ajuda a manter a consistência visual em relatórios e documentação","ru":"Nexo Brand Guidelines - это навык, который помогает поддерживать визуальную согласованность в отчетах и документации","ar":"نيكسو دليل العلامة التجارية هو مهارة تساعد على الحفاظ على التماسك البصري في التقارير والتوثيق"},"seo":{"title":{"en":"nexo-brand-guidelines: Branding Setup Guide for AI Agents","zh":"NEXO品牌指南设置指南 - AIエージェント","ja":"NEXOブランドガイドラインベストプラクティス - AIエージェント","ko":"NEXO 브랜드 가이드라인 설정 가이드 - AI 에이전트","es":"Guía de configuración de nexo-brand-guidelines para desar...","fr":"Mise en place des directives de marque nexo-brand-guideli...","de":"Einrichtungsleitfaden für nexo-brand-guidelines für Entwi...","pt":"Nexo Brand Guidelines: Configuração de Identidade Visual","ru":"ИИ Агенты: Nexo Brand Guidelines для ERP и UI","ar":"نيكسو دليل العلامة التجارية: إرشادات لتحقيق التوافق البصري"},"description":{"en":"Discover how to implement consistent branding with nexo-brand-guidelines. Learn to generate professional proposals, reports, and UI designs with ease.","zh":"了解如何使用NEXO品牌指南创建一致的UI和文档，提高您的ERP和营销材料的专业性","ja":"NEXOブランドガイドラインを使用して一貫したUIとドキュメントを作成し、ERPとマーケティング資料のプロフェッショナル性を高める方法を学びます","ko":"NEXO 브랜드 가이드라인을 사용하여 일관된 UI와 문서를 만들고 ERP 및 마케팅 자료의 전문성을 높이는 방법을 알아보세요","es":"Descubre cómo implementar las directrices de marca nexo-brand-guidelines en tus proyectos de desarrollo con nuestra guía paso a paso","fr":"Découvrez comment mettre en œuvre les directives de marque nexo-brand-guidelines dans vos projets de développement avec notre guide étape par étape","de":"Erfahren Sie, wie Sie die Markenrichtlinien von nexo-brand-guidelines in Ihren Entwicklungsprojekten mit unserem Schritt-für-Schritt-Leitfaden umsetzen","pt":"Aprenda a configurar a identidade visual da Nexo para relatórios financeiros, documentação técnica e interfaces ERP","ru":"Используйте ИИ Агенты для создания единого бренда Nexo в ваших проектах ERP, UI и документации","ar":"تعرف على إرشادات العلامة التجارية لنيكسو لإنشاء هوية بصرية متسقة في تقاريرك المالية وتوثيقك الفني وواجهات ERP"},"definition":{"en":"nexo-brand-guidelines is a skill that ensures consistent branding and visual identity across various documents and interfaces, including Propuestas comerciales, Informes financieros, and Documentacion tecnica.","zh":"NEXO品牌指南是一套用于创建一致的UI和文档的指南，用于AV TECH和NEXO AI品牌","ja":"NEXOブランドガイドラインは、AV TECHとNEXO AIブランド向けの一貫したUIとドキュメントを作成するためのガイドラインです","ko":"NEXO 브랜드 가이드라인은 AV TECH와 NEXO AI 브랜드를 위한 일관된 UI와 문서를 만들기 위한 가이드라인입니다","es":"Nexo-brand-guidelines es un skill que proporciona directrices para mantener la identidad de marca en documentos y presentaciones","fr":"Nexo-brand-guidelines est un skill qui fournit des directives pour maintenir l''identité de marque dans les documents et les présentations","de":"Nexo-brand-guidelines ist ein Skill, der Richtlinien zur Aufrechterhaltung der Markenidentität in Dokumenten und Präsentationen bietet","pt":"O que é Nexo Brand Guidelines? É um conjunto de regras para manter a identidade visual da Nexo","ru":"Что такое Nexo Brand Guidelines? Это набор правил для поддержания визуальной идентичности Nexo","ar":"ما هو نيكسو دليل العلامة التجارية؟ هو مجموعة من القواعد لتحقيق هوية بصرية متسقة لنيكسو"},"features":{"en":["Generates consistent branding for Propuestas comerciales and Informes financieros","Supports Documentacion tecnica and Presentaciones internas formatting","Ensures UI consistency for Interfaces ERP and Dashboards","Provides Material marketing and Documentos para clientes styling","Facilitates Documentacion GitHub and SOPs y manuales creation"],"zh":["支持一致的UI样式","提供标准的文档模板","适用于ERP和营销材料","提高技术文档的专业性","支持AV TECH和NEXO AI品牌"],"ja":["一貫したUIスタイルをサポート","標準のドキュメントテンプレートを提供","ERPとマーケティング資料向け","テクニカルドキュメントのプロフェッショナル性を高める","AV TECHとNEXO AIブランドをサポート"],"ko":["일관된 UI 스타일을 지원","표준 문서 템플릿을 제공","ERP 및 마케팅 자료를 위한","기술 문서의 전문성을 높여","AV TECH 및 NEXO AI 브랜드를 지원"],"es":["Propuestas comerciales personalizadas","Informes financieros con formato consistente","Documentación técnica con estilo uniforme","Presentaciones internas con diseño coherente","Interfaz de usuario (UI) consistente en aplicaciones ERP","Dashboards personalizados para análisis de datos"],"fr":["Propositions commerciales personnalisées","Rapports financiers avec formatage cohérent","Documentation technique avec style uniforme","Présentations internes avec design cohérent","Interface utilisateur (UI) cohérente dans les applications ERP","Tableaux de bord personnalisés pour l''analyse de données"],"de":["Maßgeschneiderte Geschäftsproposalen","Finanzberichte mit konsistentem Format","Technische Dokumentation mit einheitlichem Stil","Interne Präsentationen mit kohärentem Design","Benutzeroberfläche (UI) in ERP-Anwendungen","Maßgeschneiderte Dashboards für Datenanalyse"],"pt":["Configuração de identidade visual para relatórios financeiros","Estilo de documentação técnica","Interfaces ERP personalizadas","Consistência de UI em apresentações internas","Material de marketing personalizado","Documentação GitHub com padrão de marca"],"ru":["Настройка визуальной идентичности для финансовых отчетов","Стиль технической документации","Пользовательские интерфейсы ERP","Согласованность UI в内部них презентациях","Пользовательский маркетинговый материал","Документация GitHub с стандартом бренда"],"ar":["تكوين الهوية البصرية لتقارير مالية","أسلوب توثيق فني","واجهات إدارة علاقات العملاء المخصصة","اتساق واجهة المستخدم في العروض التقديمية الداخلية","مادة تسويقية مخصصة","توثيق GitHub مع معيار العلامة التجارية"]},"keywords":{"en":["how to use nexo-brand-guidelines","nexo-brand-guidelines alternative","nexo-brand-guidelines setup guide","branding for AI agents","AV TECH branding","NEXO AI visual identity","proposal formatting guidelines","internal documentation styling best practices"],"zh":["NEXO品牌指南","AIエージェント","一致的UI","文档模板","ERP","营销材料","技术文档","AV TECH","NEXO AI"],"ja":["NEXOブランドガイドライン","AIエージェント","一貫したUI","ドキュメントテンプレート","ERP","マーケティング資料","テクニカルドキュメント","AV TECH","NEXO AI"],"ko":["NEXO 브랜드 가이드라인","AI 에이전트","일관된 UI","문서 템플릿","ERP","마케팅 자료","기술 문서","AV TECH","NEXO AI"],"es":["directrices de marca","nexo-brand-guidelines","desarrollo de software","propuestas comerciales","informes financieros","documentación técnica","presentaciones internas","interfaces de usuario","dashboards personalizados","Herramientas de inteligencia artificial para desarrolladores"],"fr":["directives de marque","nexo-brand-guidelines","développement de logiciels","propositions commerciales","rapports financiers","documentation technique","présentations internes","interfaces utilisateur","tableaux de bord personnalisés","Outils d''intelligence artificielle pour les développeurs"],"de":["Markenrichtlinien","nexo-brand-guidelines","Software-Entwicklung","Geschäftsproposalen","Finanzberichte","technische Dokumentation","interne Präsentationen","Benutzeroberflächen","maßgeschneiderte Dashboards","Künstliche Intelligenz-Tools für Entwickler"],"pt":["Nexo Brand Guidelines","identidade visual","relatórios financeiros","documentação técnica","interfaces ERP","UI consistency","material de marketing","documentação GitHub"],"ru":["Nexo Brand Guidelines","визуальная идентичность","финансовые отчеты","техническая документация","интерфейсы ERP","согласованность UI","маркетинговый материал","документация GitHub"],"ar":["نيكسو دليل العلامة التجارية","الهوية البصرية","تقارير مالية","توثيق فني","واجهات إدارة علاقات العملاء","اتساق واجهة المستخدم","مادة تسويقية","توثيق GitHub"]}},"owner":"buurguees","repo":"av-tech-p-gina-de-inicio","repoPath":"buurguees/av-tech-p-gina-de-inicio","stars":1,"forks":0,"updatedAt":"2026-03-02T23:59:53Z","topics":[],"category":"community","skillMd":{"name":"nexo-brand-guidelines","description":"Applies AV TECH Esdeveniments and NEXO AI official brand identity, visual system, and formatting standards to any document, UI artifact, presentation, or proposal generated inside the ERP ecosystem.","bodyPreview":"# NEXO AI - Brand & Visual System\n\n## 1) Overview\nUse this skill whenever generating:\n- Propuestas comerciales\n- Informes financieros\n- Documentacion tecnica\n- Presentaciones internas\n- Interfaces ERP\n- Dashboards\n- Material marketing\n- Documentos para clientes\n- Documentacion GitHub\n- SOPs y manuales\n\nKeywords: branding, NEXO AV, AV TECH, ERP, proposal formatting, internal documentation styling, UI consistency, corporate identity.\n\n## 2) Brand Identity - AV TECH & NEXO AI\n\n### 2.1 Brand persona","body":"# NEXO AI - Brand & Visual System\n\n## 1) Overview\nUse this skill whenever generating:\n- Propuestas comerciales\n- Informes financieros\n- Documentacion tecnica\n- Presentaciones internas\n- Interfaces ERP\n- Dashboards\n- Material marketing\n- Documentos para clientes\n- Documentacion GitHub\n- SOPs y manuales\n\nKeywords: branding, NEXO AV, AV TECH, ERP, proposal formatting, internal documentation styling, UI consistency, corporate identity.\n\n## 2) Brand Identity - AV TECH & NEXO AI\n\n### 2.1 Brand personality\n- Profesional\n- Tecnologico\n- Minimalista\n- Estrategico\n- Preciso\n- Sin exageraciones de marketing vacias\n- Orientado a datos\n\nTono:\n- Professional + direct + intelligent clarity\n\n## 3) Color system\n\n### 3.1 Core colors\n| Name | Hex | Usage |\n|---|---|---|\n| Deep Graphite | `#0F1115` | Primary dark background |\n| NEXO Black | `#141413` | Text on light surfaces |\n| Off White | `#F5F6F8` | Light backgrounds |\n| Soft Gray | `#B8BCC5` | Secondary text |\n| Neutral Divider | `#E6E8EC` | Lines, separators |\n\n### 3.2 Accent colors\n| Name | Hex | Usage |\n|---|---|---|\n| Electric Blue | `#2D6BFF` | Primary action / links |\n| Signal Cyan | `#00B3FF` | Tech highlights |\n| Strategic Orange | `#F97316` | Alerts / emphasis |\n| Performance Green | `#16A34A` | Financial positive metrics |\n| Alert Red | `#DC2626` | Critical alerts |\n\n## 4) Typography system\n\n### Headings\n- Primary: Inter (bold / semibold)\n- Fallback: Arial / Helvetica\n\n### Body\n- Primary: Inter / system-ui\n- Fallback: Arial\n\n### Technical docs\n- Code blocks: JetBrains Mono (fallback monospace)\n\n## 5) Visual formatting rules\n\n### 5.1 Layout principles\n- Much white space\n- Clear separation of sections\n- Strong hierarchy\n- No decorative noise\n- No gradients unless explicitly requested\n- No heavy shadows\n\n### 5.2 Headings hierarchy\n| Level | Style |\n|---|---|\n| H1 | Large, bold, strong spacing |\n| H2 | Medium bold |\n| H3 | Semibold |\n| Body | Clean, 1.5 line spacing |\n| Lists | Structured, no emoji unless marketing context |\n\n### 5.3 Icon usage\n- Lucide icons preferred\n- Minimal stroke style\n- No cartoon icons\n- No emoji in technical documents\n\n## 6) Financial formatting rules (very important)\nAligned with base agent config (`base`):\n- Currency: EUR\n- Symbol: `€`\n- Format: `1.234,56 €`\n- Thousands separator: `.`\n- Decimal separator: `,`\n- Always show currency on financial outputs\n- Never mix USD or other currencies unless explicitly required\n\n## 7) Document styling behavior\nWhen this skill is applied:\n\n### 7.1 In proposals\n- Executive summary first\n- Clear pricing breakdown\n- No over-marketing\n- ROI section\n- Visual separation between sections\n\n### 7.2 In technical docs\n- Architecture diagram explanation\n- Table of contents if > 2 pages\n- Clear code blocks\n- Version number\n- Change log\n\n### 7.3 In ERP outputs\n- Clean tables\n- KPI summary cards\n- Color-coded metrics\n- No excessive text\n- Clear decision prompts\n\n### 7.4 In SharePoint documents\n- Use explicit, human-readable titles.\n- Prioritize period-based clarity for accounting and admin workflows.\n- Keep section headers predictable for non-technical readers.\n- Do not use decorative language in fiscal/legal support documents.\n- Keep naming and structure aligned with `docs/sharepoint/SHAREPOINT_ERP_SITE_ESTRUCTURA_DOCUMENTAL.md`.\n\n## 8) Smart accent behavior\n- Financial gains -> Green\n- Risks / alerts -> Orange or Red\n- Technical elements -> Blue or Cyan\n- Strategic highlights -> Blue\n- Internal process steps -> Neutral tones\n\n## 9) What this skill avoids\n- Overuse of emojis\n- Marketing hype language\n- Decorative gradients\n- Inconsistent spacing\n- Random typography\n- Unstructured long paragraphs\n- Mixing financial formats\n\n## 10) Integration with NEXO AI architecture\nThis skill must:\n- Respect role-based output limits (see profiles): `management`, `financial`, `technical`, `commercial`, `full`.\n- Never override access restrictions.\n- Never reveal restricted financial data.\n- Always follow locale rules from base agent config (`base`).\n\n## 11) Optional mode variants\nThis skill can be extended with internal flags:\n\n```json\n{\n  \"mode\": \"proposal | internal_doc | dashboard | marketing | financial_report\"\n}\n```\n\nBehavior by mode:\n- Proposal -> More structured persuasion\n- Internal_doc -> Structured clarity\n- Dashboard -> Visual KPI-first layout\n- Marketing -> Slightly more dynamic tone\n- Financial_report -> Conservative + data-first\n\n## 12) Advanced version (optional roadmap)\n- Create `nexo-dark-ui-skin` skill for interfaces.\n- Create `nexo-investor-format` for investor material.\n- Create `nexo-sop-format` for internal documentation.\n- Create `nexo-client-presentation-format` for B2B proposals.\n"},"lastSynced":"2026-03-06T13:10:09.645Z","agentAnalysis":{"suitability":{"en":"Essential for corporate document generation agents requiring strict brand compliance across proposals, reports, and UI designs.","zh":"对于需要严格遵守品牌规范、跨提案、报告和UI设计的公司文档生成AI代理而言，此技能至关重要。","ja":"提案書、レポート、UIデザインにおいて厳格なブランドコンプライアンスを必要とする企業文書生成エージェントにとって不可欠です。","ko":"제안서, 보고서 및 UI 디자인에 걸쳐 엄격한 브랜드 준수가 필요한 기업 문서 생성 에이전트에게 필수적입니다.","es":"Esencial para los agentes de generación de documentos corporativos que requieren un cumplimiento estricto de la marca en propuestas, informes y diseños de UI.","fr":"Essentiel pour les agents de génération de documents d''entreprise nécessitant un respect strict de la marque sur les propositions, les rapports et les conceptions d''UI.","de":"Wesentlich für corporate Dokumentenerstellungsagenten, die eine strenge Markenkonformität über Angebote, Berichte und UI-Designs hinweg erfordern.","pt":"Essencial para agentes de geração de documentos corporativos que exigem estrita conformidade com a marca em propostas, relatórios e designs de UI.","ru":"Необходим для агентов создания корпоративных документов, требующих строгого соответствия бренду в предложениях, отчетах и UI-дизайне.","ar":"أساسي لوكلاء إنشاء المستندات المؤسسية التي تتطلب الامتثال الصارم للعلامة التجارية عبر العروض والتقارير وتصميمات واجهة المستخدم."},"recommendation":{"en":"Enforces comprehensive visual consistency across AV TECH & NEXO AI corporate materials including ERP interfaces, financial reports, and GitHub documentation through standardized branding protocols. Provides deterministic formatting rules for professional document generation across multiple output types including dashboards, SOPs, and marketing materials.","zh":"通过标准化的品牌协议，在包括ERP界面、财务报告和GitHub文档在内的AV TECH & NEXO AI公司材料上强制执行全面的视觉一致性。为包括仪表板、SOP和营销材料在内的多种输出类型提供确定性的格式化规则，以实现专业的文档生成。","ja":"標準化されたブランディングプロトコルを通じて、ERPインターフェース、財務レポート、GitHubドキュメントを含むAV TECH & NEXO AIの企業資料全体で包括的なビジュアル一貫性を強制します。ダッシュボード、SOP、マーケティング資料を含む複数の出力タイプにおけるプロフェッショナルな文書生成のための確定的なフォーマットルールを提供します。","ko":"표준화된 브랜딩 프로토콜을 통해 ERP 인터페이스, 재무 보고서 및 GitHub 문서를 포함한 AV TECH & NEXO AI 기업 자료 전반에 걸쳐 포괄적인 시각적 일관성을 강제합니다. 대시보드, SOP 및 마케팅 자료를 포함한 여러 출력 유형에서 전문적인 문서 생성을 위한 결정론적 포맷팅 규칙을 제공합니다.","es":"Aplica una consistencia visual integral en los materiales corporativos de AV TECH y NEXO AI, incluidas las interfaces de ERP, los informes financieros y la documentación de GitHub, a través de protocolos de marca estandarizados. Proporciona reglas de formato deterministas para la generación de documentos profesionales en varios tipos de salida, incluidos paneles de control, SOP y materiales de marketing.","fr":"Assure une cohérence visuelle globale dans les supports de communication d''entreprise d''AV TECH et NEXO AI, y compris les interfaces de ERP, les rapports financiers et la documentation de GitHub, grâce à des protocoles de marca standardisés. Fournit des règles de mise en forme déterministes pour la génération de documents professionnels sur plusieurs types de sortie, y compris les tableaux de bord, les SOP et les supports de marketing.","de":"Durchsetzt eine umfassende visuelle Konsistenz in den corporate Materialien von AV TECH und NEXO AI, einschließlich ERP-Schnittstellen, Finanzberichten und GitHub-Dokumentation, durch standardisierte Markenprotokolle. Bietet deterministische Formatierungsregeln für die professionelle Dokumentenerstellung in verschiedenen Ausgabetypen, einschließlich Dashboards, SOP und Marketingmaterialien.","pt":"Impõe uma consistência visual abrangente em materiais corporativos da AV TECH & NEXO AI, incluindo interfaces de ERP, relatórios financeiros e documentação do GitHub, por meio de protocolos de branding padronizados. Fornece regras de formatação determinísticas para geração profissional de documentos em vários tipos de saída, incluindo dashboards, POPs e materiais de marketing.","ru":"Обеспечивает всеобъемлющее визуальное единообразие корпоративных материалов AV TECH & NEXO AI, включая интерфейсы ERP, финансовые отчеты и документацию GitHub, через стандартизированные бренд-протоколы. Предоставляет детерминированные правила форматирования для профессионального создания документов различных типов, включая дашборды, СОПы и маркетинговые материалы.","ar":"يفرض اتساقًا مرئيًا شاملاً عبر المواد المؤسسية لشركة AV TECH & NEXO AI بما في ذلك واجهات ERP والتقارير المالية ووثائق GitHub من خلال بروتوكولات العلامة التجارية الموحدة. يوفر قواعد تنسيق حتمية لإنشاء المستندات المهنية عبر أنواع متعددة من المخرجات بما في ذلك لوحات التحكم وإجراءات التشغيل القياسية والمواد التسويقية."},"useCases":{"en":["Generating brand-compliant commercial proposals","Formatting internal technical documentation","Designing consistent ERP interfaces and dashboards","Producing standardized client-facing financial reports","Creating marketing materials with corporate identity"],"zh":["生成符合品牌规范的商业提案","格式化内部技术文档","设计一致的ERP界面和仪表板","制作面向客户的标准化财务报告","创建具有企业形象的营销材料"],"ja":["ブランド準拠の商業提案書の生成","内部技術文書のフォーマット","一貫性のあるERPインターフェースとダッシュボードの設計","クライアント向け標準化財務レポートの作成","企業アイデンティティを備えたマーケティング資料の作成"],"ko":["브랜드 규정을 준수하는 상업 제안서 생성","내부 기술 문서 포맷팅","일관된 ERP 인터페이스 및 대시보드 설계","고객 대상 표준화된 재무 보고서 제작","기업 아이덴티티를 갖춘 마케팅 자료 생성"],"es":["Generación de propuestas comerciales compatibles con la marca","Formato de documentación técnica interna","Diseño de interfaces de ERP y paneles de control coherentes","Producción de informes financieros estandarizados para clientes","Creación de materiales de marketing con identidad corporativa"],"fr":["Génération de propositions commerciales conformes à la marque","Mise en forme de la documentation technique interne","Conception d''interfaces de ERP et de tableaux de bord cohérents","Production de rapports financiers standardisés pour les clients","Création de supports de marketing avec identité d''entreprise"],"de":["Erstellung von markenkonformen kommerziellen Angeboten","Formatierung interner technischer Dokumentation","Entwurf konsistenter ERP-Schnittstellen und Dashboards","Erstellung standardisierter Finanzberichte für Kunden","Erstellung von Marketingmaterialien mit corporate Identität"],"pt":["Geração de propostas comerciais em conformidade com a marca","Formatação de documentação técnica interna","Design de interfaces de ERP e dashboards consistentes","Produção de relatórios financeiros padronizados para clientes","Criação de materiais de marketing com identidade corporativa"],"ru":["Генерация коммерческих предложений, соответствующих бренду","Форматирование внутренней технической документации","Проектирование единообразных интерфейсов ERP и дашбордов","Создание стандартизированных финансовых отчетов для клиентов","Разработка маркетинговых материалов с корпоративной идентичностью"],"ar":["إنشاء العروض التجارية الممتثلة للعلامة التجارية","تنسيق الوثائق التقنية الداخلية","تصميم واجهات ERP ولوحات التحكم المتسقة","إنتاج التقارير المالية الموحدة الموجهة للعملاء","إنشاء المواد التسويقية بهوية مؤسسية"]},"limitations":{"en":["Specific to NEXO AV and AV TECH brand guidelines only","Requires adherence to predefined visual system parameters","Limited to document types specified in overview section"],"zh":["仅适用于NEXO AV和AV TECH品牌指南","需要遵守预定义的视觉系统参数","仅限于概述部分中指定的文档类型"],"ja":["NEXO AVおよびAV TECHのブランドガイドラインにのみ特定","事前定義されたビジュアルシステムパラメータの遵守が必要","概要セクションで指定された文書タイプに限定"],"ko":["NEXO AV 및 AV TECH 브랜드 가이드라인에만 해당됨","미리 정의된 시각 시스템 매개변수를 준수해야 함","개요 섹션에 지정된 문서 유형으로만 제한됨"],"es":["Específico para las directrices de marca de NEXO AV y AV TECH solamente","Requiere adherencia a parámetros de sistema visual predefinidos","Limitado a los tipos de documentos especificados en la sección de descripción general"],"fr":["Spécifique aux directives de marque de NEXO AV et AV TECH uniquement","Nécessite l''adhésion à des paramètres de système visuel prédéfinis","Limité aux types de documents spécifiés dans la section de présentation générale"],"de":["Spezifisch für die Markenrichtlinien von NEXO AV und AV TECH nur","Erfordert die Einhaltung vordefinierter visueller Systemsparameter","Begrenzt auf die in der Überblickssection angegebenen Dokumententypen"],"pt":["Específico apenas para as diretrizes de marca da NEXO AV e AV TECH","Requer adesão a parâmetros predefinidos do sistema visual","Limitado aos tipos de documento especificados na seção de visão geral"],"ru":["Применимо только к гайдлайнам брендов NEXO AV и AV TECH","Требует соблюдения предопределенных параметров визуальной системы","Ограничено типами документов, указанными в разделе обзора"],"ar":["مخصص لإرشادات العلامة التجارية لشركة NEXO AV وAV TECH فقط","يتطلب الالتزام بمعلمات النظام المرئي المحددة مسبقًا","مقتصر على أنواع المستندات المحددة في قسم النظرة العامة"]},"version":4},"contentHash":"7b0423e315c48d373421b5183ed46b20053009820a180caac4b452defa315bec","qualityScore":36}');
