INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('buurguees/av-tech-p-gina-de-inicio/nexo-brand-guidelines', 'nexo-brand-guidelines', 'buurguees', 'av-tech-p-gina-de-inicio', 'community', 'nexo-brand-guidelines buurguees av-tech-p-gina-de-inicio community The nexo-brand-guidelines skill provides a comprehensive brand and visual system for generating professional documents and interfaces, including proposals, reports, and UI designs. NEXO品牌指南提供了一致的UI和文档样式，适用于ERP、营销材料和技术文档 NEXOブランドガイドラインは、ERP、マーケティング資料、テクニカルドキュメント向けの一貫したUIとドキュメントスタイルを提供します NEXO 브랜드 가이드라인은 ERP, 마케팅 자료, 기술 문서를 위한 일관된 UI와 문서 스타일을 제공합니다 El skill nexo-brand-guidelines ofrece una guía para mantener la consistencia de la marca en documentos y presentaciones, incluyendo propuestas comerciales, informes financieros y documentación técnica Le skill nexo-brand-guidelines propose un guide pour maintenir la cohérence de la marque dans les documents et les présentations, y compris les propositions commerciales, les rapports financiers et la documentation technique Das Skill nexo-brand-guidelines bietet einen Leitfaden, um die Markenkonstistenz in Dokumenten und Präsentationen zu gewährleisten, einschließlich Geschäftsproposalen, Finanzberichten und technischer Dokumentation O Nexo Brand Guidelines é um skill que ajuda a manter a consistência visual em relatórios e documentação Nexo Brand Guidelines - это навык, который помогает поддерживать визуальную согласованность в отчетах и документации نيكسو دليل العلامة التجارية هو مهارة تساعد على الحفاظ على التماسك البصري في التقارير والتوثيق how to use nexo-brand-guidelines nexo-brand-guidelines alternative nexo-brand-guidelines setup guide branding for AI agents AV TECH branding NEXO AI visual identity proposal formatting guidelines internal documentation styling best practices NEXO品牌指南 AIエージェント 一致的UI 文档模板 ERP 营销材料 技术文档 AV TECH NEXO AI Generates consistent branding for Propuestas comerciales and Informes financieros Supports Documentacion tecnica and Presentaciones internas formatting Ensures UI consistency for Interfaces ERP and Dashboards Provides Material marketing and Documentos para clientes styling Facilitates Documentacion GitHub and SOPs y manuales creation nexo-brand-guidelines is a skill that ensures consistent branding and visual identity across various documents and interfaces, including Propuestas comerciales, Informes financieros, and Documentacion tecnica.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('juandaniel190/personal-projects/answering-natural-language-questions-with-dbt', 'community', 'juandaniel190', 'personal-projects', 'juandaniel190/personal-projects', 'answering-natural-language-questions-with-dbt', 1, 0, 36, '2026-03-03T12:04:14Z', '2026-03-06T07:19:37.176Z', '5b179af61bc8450c32ae8c7113da64bde907032bddffcf527713131a1b31e5db', '{"id":"juandaniel190/personal-projects/answering-natural-language-questions-with-dbt","name":"answering-natural-language-questions-with-dbt","description":{"en":"The answering-natural-language-questions-with-dbt skill enables AI agents to answer data questions using a semantic layer, SQL modification, and model discovery. It benefits business users who need data answers to questions like total sales or active customers.","zh":"利用dbt的语义层、SQL修改、模型发现和清单分析来回答业务问题","ja":"dbtのセマンティック層、SQL修正、モデル発見、 マニフェスト分析を使用してビジネス質問に回答します","ko":"dbt의 의미 계층, SQL 수정, 모델 발견, 매니페스트 분석을 사용하여 사업 질문에 답변합니다","es":"Responde preguntas de lenguaje natural utilizando dbt con una capa semántica, modificaciones SQL y análisis de manifestos","fr":"Répondez aux questions de langage naturel en utilisant dbt avec une couche sémantique, des modifications SQL et une analyse de manifestes","de":"Beantworten Sie natürliche Sprachfragen mithilfe von dbt mit einer semantischen Ebene, SQL-Modifikationen und Manifestanalysen","pt":"O skill de resposta a perguntas de linguagem natural com dbt permite responder a perguntas de negócios usando a camada semântica, SQL e modelos de dados.","ru":"Навык ответов на естественные языковые вопросы с dbt позволяет отвечать на бизнес-вопросы, используя семантический слой, SQL и модели данных.","ar":"مهارة الإجابة على الأسئلة الطبيعية مع dbt تمكن من الإجابة على أسئلة الأعمال باستخدام الطبقة الدلالية واللغة البرمجية SQL والنماذج البيانية."},"seo":{"title":{"en":"answering-natural-language-questions-with-dbt: Setup Guid...","zh":"利用dbt回答自然语言问题的Setup Guide","ja":"dbtを使用した自然言語質問への回答Best Practices","ko":"dbt로 자연어 질문에 답변하는 방법","es":"Guía de configuración para responder preguntas de lenguaj...","fr":"Guide de configuration pour répondre aux questions de lan...","de":"Konfigurationsleitfaden für die Beantwortung von natürlic...","pt":"Guia de Configuração de Perguntas de Linguagem Natural co...","ru":"ИИ Агенты: Настройка Ответов на Естественные Языковые Воп...","ar":"دليل إعداد الإجابات على الأسئلة الطبيعية مع dbt"},"description":{"en":"Unlock the power of dbt for answering business questions with this AI agent skill - learn how to setup and use it effectively","zh":"使用dbt的语义层、SQL修改、模型发现和清单分析来回答业务问题，AIエージェント","ja":"ビジネス質問に回答するためにdbtのセマンティック層、SQL修正、モデル発見、マニフェスト分析を使用します。AIエージェント","ko":"사업 질문에 답변하려면 dbt의 의미 계층, SQL 수정, 모델 발견, 매니페스트 분석을 사용합니다. AI Tools","es":"Aprende a configurar dbt para responder preguntas de lenguaje natural y obtener respuestas precisas a preguntas comerciales","fr":"Découvrez comment configurer dbt pour répondre aux questions de langage naturel et obtenir des réponses précises aux questions commerciales","de":"Erfahren Sie, wie Sie dbt konfigurieren, um natürliche Sprachfragen zu beantworten und präzise Antworten auf Geschäftsfragen zu erhalten","pt":"Aprenda a configurar perguntas de linguagem natural com dbt para obter respostas precisas de dados. Descubra como usar a camada semântica e SQL para responde...","ru":"Узнайте, как настроить ответы на естественные языковые вопросы с dbt, чтобы получить точные данные. Откройте для себя, как использовать семантический слой и ...","ar":"تعرف على كيفية إعداد الإجابات على الأسئلة الطبيعية مع dbt للحصول على إجابات دقيقة للبيانات. اكتشف كيفية استخدام الطبقة الدلالية واللغة البرمجية SQL للاستجابة..."},"definition":{"en":"answering-natural-language-questions-with-dbt is a skill that enables AI agents to answer natural language questions using dbt, a data build tool, to provide data-driven answers","zh":"dbt的自然语言问题回答是利用语义层、SQL修改、模型发现和清单分析来回答业务问题的方法","ja":"dbtの自然言語質問への回答は、セマンティック層、SQL修正、モデル発見、 マニフェスト分析を使用してビジネス質問に回答する方法です","ko":"dbt의 자연어 질문에 대한 답변은 의미 계층, SQL 수정, 모델 발견, 매니페스트 분석을 사용하여 사업 질문에 답변하는 방법입니다","es":"Un agente de IA que utiliza dbt para responder preguntas de lenguaje natural","fr":"Un outil d''IA qui utilise dbt pour répondre aux questions de langage naturel","de":"Ein AI-Tool, das dbt verwendet, um natürliche Sprachfragen zu beantworten","pt":"Resposta a perguntas de linguagem natural com dbt é uma técnica que usa a camada semântica e SQL para responder a perguntas de negócios.","ru":"Ответы на естественные языковые вопросы с dbt - это техника, которая использует семантический слой и SQL для ответов на бизнес-вопросы.","ar":"الإجابة على الأسئلة الطبيعية مع dbt هي تقنية تستخدم الطبقة الدلالية واللغة البرمجية SQL للاستجابة لأسئلة الأعمال."},"features":{"en":["Uses a semantic layer to answer data questions","Modifies SQL to provide accurate answers","Employs model discovery to find relevant data models","Analyzes manifests to provide detailed answers","Exhausts all options before indicating inability to answer"],"zh":["利用语义层回答业务问题","使用SQL修改来回答复杂问题","模型发现功能用于回答未知问题","清单分析用于回答数据相关问题","支持多种数据源和格式"],"ja":["セマンティック層を使用してビジネス質問に回答","SQL修正を使用して複雑な質問に回答","モデル発見機能を使用して未知の質問に回答","マニフェスト分析を使用してデータ関連の質問に回答","複数のデータソースとフォーマットをサポート"],"ko":["의미 계층을 사용하여 사업 질문에 답변","SQL 수정을 사용하여 복잡한 질문에 답변","모델 발견 기능을 사용하여 неизвест的问题에 답변","매니페스트 분석을 사용하여 데이터 관련 질문에 답변","다수의 데이터 소스와 형식을 지원"],"es":["Capa semántica para respuestas precisas","Modificaciones SQL para personalizar las consultas","Análisis de manifestos para descubrir modelos","Soporte para preguntas comerciales como \"¿Cuáles fueron las ventas totales del mes pasado?\"","Integración con dbt para obtener respuestas precisas"],"fr":["Couche sémantique pour des réponses précises","Modifications SQL pour personnaliser les requêtes","Analyse de manifestes pour découvrir des modèles","Prise en charge de questions commerciales comme \"Quelles étaient les ventes totales du mois dernier ?\"","Intégration avec dbt pour obtenir des réponses précises"],"de":["Semantische Ebene für präzise Antworten","SQL-Modifikationen für personalisierte Abfragen","Manifestanalyse zum Entdecken von Modellen","Unterstützung für Geschäftsfragen wie \"Wie hoch waren die Gesamtverkäufe des letzten Monats?\"","Integration mit dbt für präzise Antworten"],"pt":["Uso da camada semântica para responder a perguntas de negócios","Modificação de SQL para obter respostas precisas","Descoberta de modelos de dados para responder a perguntas complexas","Análise de manifestos para obter informações adicionais"],"ru":["Использование семантического слоя для ответов на бизнес-вопросы","Модификация SQL для получения точных ответов","Обнаружение моделей данных для ответов на сложные вопросы","Анализ манифестов для получения дополнительной информации"],"ar":["استخدام الطبقة الدلالية للاستجابة لأسئلة الأعمال","تحوير اللغة البرمجية SQL للحصول على إجابات دقيقة","اكتشاف نماذج البيانات للاستجابة لأسئلة معقدة","تحليل الملفات التعريفية للحصول على معلومات إضافية"]},"keywords":{"en":["how to use answering-natural-language-questions-with-dbt","what is answering-natural-language-questions-with-dbt","answering-natural-language-questions-with-dbt alternative","answering-natural-language-questions-with-dbt vs sql","answering-natural-language-questions-with-dbt install","answering-natural-language-questions-with-dbt setup guide","dbt for business questions","natural language questioning with dbt"],"zh":["dbt自然语言问题回答","AIエージェント","语义层","SQL修改","模型发现","清单分析","数据分析","业务智能"],"ja":["dbt自然言語質問への回答","AIエージェント","セマンティック層","SQL修正","モデル発見","マニフェスト分析","データ分析","ビジネスインテリジェンス"],"ko":["dbt자연어질문에답변","AI Tools","의미계층","SQL수정","모델발견","매니페스트분석","데이터분석","事業지능"],"es":["dbt","preguntas de lenguaje natural","agente de IA","capa semántica","modificaciones SQL","análisis de manifestos","preguntas comerciales","ventas totales","clientes activos"],"fr":["dbt","questions de langage naturel","outil d''IA","couche sémantique","modifications SQL","analyse de manifestes","questions commerciales","ventes totales","clients actifs"],"de":["dbt","natürliche Sprachfragen","AI-Tool","semantische Ebene","SQL-Modifikationen","Manifestanalyse","Geschäftsfragen","Gesamtverkäufe","aktive Kunden"],"pt":["perguntas de linguagem natural","dbt","camada semântica","SQL","modelos de dados","respostas precisas","negócios","análise de dados"],"ru":["естественные языковые вопросы","dbt","семантический слой","SQL","модели данных","точные ответы","бизнес","анализ данных"],"ar":["الأسئلة الطبيعية","dbt","الطبقة الدلالية","اللغة البرمجية SQL","نماذج البيانات","إجابات دقيقة","أعمال","تحليل البيانات"]}},"owner":"juandaniel190","repo":"personal-projects","repoPath":"juandaniel190/personal-projects","stars":1,"forks":0,"updatedAt":"2026-03-03T12:04:14Z","topics":[],"category":"community","skillMd":{"name":"answering-natural-language-questions-with-dbt","description":"Use when a user asks a business question that requires querying data (e.g., What were total sales last quarter?). NOT for validating, testing, or building dbt models during development.","bodyPreview":"# Answering Natural Language Questions with dbt\n\n## Overview\n\nAnswer data questions using the best available method: semantic layer first, then SQL modification, then model discovery, then manifest analysis. Always exhaust options before saying \"cannot answer.\"\n\n**Use for:** Business questions from users that need data answers\n- \"What were total sales last month?\"\n- \"How many active customers do we have?\"\n- \"Show me revenue by region\"\n\n**Not for:**\n- Validating model logic during development\n- T","body":"# Answering Natural Language Questions with dbt\n\n## Overview\n\nAnswer data questions using the best available method: semantic layer first, then SQL modification, then model discovery, then manifest analysis. Always exhaust options before saying \"cannot answer.\"\n\n**Use for:** Business questions from users that need data answers\n- \"What were total sales last month?\"\n- \"How many active customers do we have?\"\n- \"Show me revenue by region\"\n\n**Not for:**\n- Validating model logic during development\n- Testing dbt models or semantic layer definitions\n- Building or modifying dbt models\n- `dbt run`, `dbt test`, or `dbt build` workflows\n\n## Decision Flow\n\n```mermaid\nflowchart TD\n    start([Business question received])\n    check_sl{Semantic layer tools available?}\n    list_metrics[list_metrics]\n    metric_exists{Relevant metric exists?}\n    get_dims[get_dimensions]\n    sl_sufficient{SL can answer directly?}\n    query_metrics[query_metrics]\n    answer([Return answer])\n    try_compiled[get_metrics_compiled_sql<br/>Modify SQL, execute_sql]\n    check_discovery{Model discovery tools available?}\n    try_discovery[get_mart_models<br/>get_model_details<br/>Write SQL, execute]\n    check_manifest{In dbt project?}\n    try_manifest[Analyze manifest/catalog<br/>Write SQL]\n    cannot([Cannot answer])\n    suggest{In dbt project?}\n    improvements[Suggest semantic layer changes]\n    done([Done])\n\n    start --> check_sl\n    check_sl -->|yes| list_metrics\n    check_sl -->|no| check_discovery\n    list_metrics --> metric_exists\n    metric_exists -->|yes| get_dims\n    metric_exists -->|no| check_discovery\n    get_dims --> sl_sufficient\n    sl_sufficient -->|yes| query_metrics\n    sl_sufficient -->|no| try_compiled\n    query_metrics --> answer\n    try_compiled -->|success| answer\n    try_compiled -->|fail| check_discovery\n    check_discovery -->|yes| try_discovery\n    check_discovery -->|no| check_manifest\n    try_discovery -->|success| answer\n    try_discovery -->|fail| check_manifest\n    check_manifest -->|yes| try_manifest\n    check_manifest -->|no| cannot\n    try_manifest -->|SQL ready| answer\n    answer --> suggest\n    cannot --> done\n    suggest -->|yes| improvements\n    suggest -->|no| done\n    improvements --> done\n```\n\n## Quick Reference\n\n| Priority | Condition | Approach | Tools |\n|----------|-----------|----------|-------|\n| 1 | Semantic layer active | Query metrics directly | `list_metrics`, `get_dimensions`, `query_metrics` |\n| 2 | SL active but minor modifications needed (missing dimension, custom filter, case when, different aggregation) | Modify compiled SQL | `get_metrics_compiled_sql`, then `execute_sql` |\n| 3 | No SL, discovery tools active | Explore models, write SQL | `get_mart_models`, `get_model_details`, then `show`/`execute_sql` |\n| 4 | No MCP, in dbt project | Analyze artifacts, write SQL | Read `target/manifest.json`, `target/catalog.json` |\n\n## Approach 1: Semantic Layer Query\n\nWhen `list_metrics` and `query_metrics` are available:\n\n1. `list_metrics` - find relevant metric\n2. `get_dimensions` - verify required dimensions exist\n3. `query_metrics` - execute with appropriate filters\n\nIf semantic layer can''t answer directly (missing dimension, need custom logic) → go to Approach 2.\n\n## Approach 2: Modified Compiled SQL\n\nWhen semantic layer has the metric but needs minor modifications:\n\n- Missing dimension (join + group by)\n- Custom filter not available as a dimension\n- Case when logic for custom categorization\n- Different aggregation than what''s defined\n\n1. `get_metrics_compiled_sql` - get the SQL that would run (returns raw SQL, not Jinja)\n2. Modify SQL to add what''s needed\n3. `execute_sql` to run the raw SQL\n4. **Always suggest** updating the semantic model if the modification would be reusable\n\n```sql\n-- Example: Adding sales_rep dimension\nWITH base AS (\n    -- ... compiled metric logic (already resolved to table names) ...\n)\nSELECT base.*, reps.sales_rep_name\nFROM base\nJOIN analytics.dim_sales_reps reps ON base.rep_id = reps.id\nGROUP BY ...\n\n-- Example: Custom filter\nSELECT * FROM (compiled_metric_sql) WHERE region = ''EMEA''\n\n-- Example: Case when categorization\nSELECT\n    CASE WHEN amount > 1000 THEN ''large'' ELSE ''small'' END as deal_size,\n    SUM(amount)\nFROM (compiled_metric_sql)\nGROUP BY 1\n```\n\n**Note:** The compiled SQL contains resolved table names, not `{{ ref() }}`. Work with the raw SQL as returned.\n\n## Approach 3: Model Discovery\n\nWhen no semantic layer but `get_all_models`/`get_model_details` available:\n\n1. `get_mart_models` - start with marts, not staging\n2. `get_model_details` for relevant models - understand schema\n3. Write SQL using `{{ ref(''model_name'') }}`\n4. `show --inline \"...\"` or `execute_sql`\n\n**Prefer marts over staging** - marts have business logic applied.\n\n## Approach 4: Manifest/Catalog Analysis\n\nWhen in a dbt project but no MCP server:\n\n1. Check for `target/manifest.json` and `target/catalog.json`\n2. **Filter before reading** - these files can be large\n\n```bash\n# Find mart models in manifest\njq ''.nodes | to_entries | map(select(.key | startswith(\"model.\") and contains(\"mart\"))) | .[].value | {name: .name, schema: .schema, columns: .columns}'' target/manifest.json\n\n# Get column info from catalog\njq ''.nodes[\"model.project_name.model_name\"].columns'' target/catalog.json\n```\n\n3. Write SQL based on discovered schema\n4. Explain: \"This SQL should run in your warehouse. I cannot execute it without database access.\"\n\n## Suggesting Improvements\n\n**When in a dbt project**, suggest semantic layer changes after answering (or when cannot answer):\n\n| Gap | Suggestion |\n|-----|------------|\n| Metric doesn''t exist | \"Add a metric definition to your semantic model\" |\n| Dimension missing | \"Add `dimension_name` to the dimensions list in the semantic model\" |\n| No semantic layer | \"Consider adding a semantic layer for this data\" |\n\n**Stay at semantic layer level.** Do NOT suggest:\n- Database schema changes\n- ETL pipeline modifications\n- \"Ask your data engineering team to...\"\n\n## Rationalizations to Resist\n\n| You''re Thinking... | Reality |\n|--------------------|---------|\n| \"Semantic layer doesn''t support this exact query\" | Get compiled SQL and modify it (Approach 2) |\n| \"No MCP tools, can''t help\" | Check for manifest/catalog locally |\n| \"User needs this quickly, skip the systematic check\" | Systematic approach IS the fastest path |\n| \"Just write SQL, it''s faster\" | Semantic layer exists for a reason - use it first |\n| \"The dimension doesn''t exist in the data\" | Maybe it exists but not in semantic layer config |\n\n## Red Flags - STOP\n\n- Writing SQL without checking if semantic layer can answer\n- Saying \"cannot answer\" without trying all 4 approaches\n- Suggesting database-level fixes for semantic layer gaps\n- Reading entire manifest.json without filtering\n- Using staging models when mart models exist\n- Using this to validate model correctness rather than answer business questions\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Giving up when SL can''t answer directly | Get compiled SQL and modify it |\n| Querying staging models | Use `get_mart_models` first |\n| Reading full manifest.json | Use jq to filter |\n| Suggesting ETL changes | Keep suggestions at semantic layer |\n| Not checking tool availability | List available tools before choosing approach |\n"},"lastSynced":"2026-03-06T07:19:37.176Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Analysis Agents requiring advanced semantic layer and SQL modification capabilities to answer natural language questions with dbt","zh":"适合需要高级语义层和SQL修改功能的数据分析代理，以使用dbt回答自然语言问题","ja":"dbtを使用して自然言語の質問に答えるために高度なセマンティック層とSQL修正機能を必要とするデータ分析エージェントに適しています","ko":"dbt를 사용하여 자연어 질문에 대답하기 위해 고급 의미 체계 계층 및 SQL 수정 기능을 필요로 하는 데이터 분석 에이전트에 적합합니다","es":"Ideal para Agentes de Análisis de Datos que requieren una capa semántica avanzada y capacidades de modificación de SQL para responder preguntas en lenguaje natural con dbt","fr":"Idéal pour les Agents d''Analyse de Données nécessitant une couche sémantique avancée et des capacités de modification de SQL pour répondre à des questions en langage naturel avec dbt","de":"Ideal für Data-Analytics-Agents, die eine erweiterte semantische Ebene und SQL-Modifikationsfunktionen benötigen, um natürliche Sprachfragen mit dbt zu beantworten","pt":"Ideal para Agentes de Análise de Dados que requerem uma camada semântica avançada e capacidades de modificação SQL para responder a perguntas de linguagem natural com dbt","ru":"Идеально для Агентов Анализа Данных, требующих продвинутого семантического слоя и возможностей модификации SQL для ответов на естественно-языковые вопросы с dbt","ar":"مثالي لعميل تحليل البيانات الذي يتطلب طبقة семантиكية متقدمة وقدرات تعديل SQL للإجابة على أسئلة اللغة الطبيعية مع dbt"},"recommendation":{"en":"Empowers agents to answer complex business questions using a layered approach, starting with semantic layer analysis, followed by SQL modification, model discovery, and manifest analysis, leveraging dbt for data transformation and analysis","zh":"使代理能够使用分层方法回答复杂的商业问题，从语义层分析开始，接着是SQL修改、模型发现和清单分析，利用dbt进行数据转换和分析","ja":"エージェントがセマンティック層分析、SQL修正、モデル発見、マニフェスト分析の層別アプローチを使用して複雑なビジネス質問に答えることを可能にし、データ変換と分析のためにdbtを利用する","ko":"에이전트가 세분화된 방법을 사용하여 복잡한 비즈니스 질문에 대답할 수 있도록 하며, 의미 체계 계층 분석, SQL 수정, 모델 검색 및 매니페스트 분석을 시작하여 dbt를 사용하여 데이터 변환 및 분석을 수행합니다","es":"Habilita a los agentes a responder preguntas comerciales complejas utilizando un enfoque en capas, comenzando con el análisis de la capa semántica, seguido de la modificación de SQL, el descubrimiento de modelos y el análisis de manifiestos, aprovechando dbt para la transformación y análisis de datos","fr":"Permet aux agents de répondre à des questions commerciales complexes en utilisant une approche en couches, en commençant par l''analyse de la couche sémantique, suivie de la modification de SQL, de la découverte de modèles et de l''analyse de manifestes, en exploitant dbt pour la transformation et l''analyse de données","de":"Ermächtigt Agenten, komplexe Geschäftsfragen mithilfe eines schichtbasierten Ansatzes zu beantworten, beginnend mit der Analyse der semantischen Ebene, gefolgt von SQL-Modifikation, Modellentdeckung und Manifestanalyse, unter Nutzung von dbt für DatenTransformation und -Analyse","pt":"Habilita os agentes a responderem a perguntas comerciais complexas usando uma abordagem em camadas, começando com a análise da camada semântica, seguida de modificação SQL, descoberta de modelo e análise de manifesto, utilizando dbt para transformação e análise de dados","ru":"Наделяет агентов возможностью отвечать на сложные бизнес-вопросы, используя слоистый подход, начиная с анализа семантического слоя, за которым следует модификация SQL, обнаружение модели и анализ манифеста, используя dbt для трансформации и анализа данных","ar":"تمكّن الوكيل من الإجابة على أسئلة الأعمال المعقدة باستخدام نهج متدرج، يبدأ بتحليل الطبقة الدلالية، متبوعًا بتعديل SQL واكتشاف النموذج و تحليل المظهر، مع استخدام dbt لتحويل البيانات وتحليلها"},"useCases":{"en":["Answering natural language questions about total sales or revenue","Providing data insights on active customers or regional sales performance","Generating reports on key business metrics using dbt models and semantic layers"],"zh":["回答关于总销售额或收入的自然语言问题","提供有关活跃客户或地区销售业绩的数据洞察","使用dbt模型和语义层生成关键业务指标报告"],"ja":["総売上または収益についての自然言語の質問に答える","アクティブな顧客または地域の販売業績に関するデータ洞察を提供する","dbtモデルとセマンティック層を使用して主要ビジネスメトリックのレポートを生成する"],"ko":["총 판매 또는 매출에 대한 자연어 질문에 대답하기","활성 고객 또는 지역 판매 성과에 대한 데이터 통찰력을 제공하기","dbt 모델 및 의미 체계 계층을 사용하여 주요 비즈니스 메트릭 보고서 생성하기"],"es":["Responder preguntas en lenguaje natural sobre ventas totales o ingresos","Proporcionar información de datos sobre clientes activos o desempeño de ventas regionales","Generar informes sobre métricas comerciales clave utilizando modelos dbt y capas semánticas"],"fr":["Répondre à des questions en langage naturel sur les ventes totales ou les revenus","Fournir des informations de données sur les clients actifs ou la performance des ventes régionales","Générer des rapports sur les métriques commerciale