INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('juandaniel190/personal-projects/answering-natural-language-questions-with-dbt', 'answering-natural-language-questions-with-dbt', 'juandaniel190', 'personal-projects', 'community', 'answering-natural-language-questions-with-dbt juandaniel190 personal-projects community The answering-natural-language-questions-with-dbt skill enables AI agents to answer data questions using a semantic layer, SQL modification, and model discovery. It benefits business users who need data answers to questions like total sales or active customers. 利用dbt的语义层、SQL修改、模型发现和清单分析来回答业务问题 dbtのセマンティック層、SQL修正、モデル発見、 マニフェスト分析を使用してビジネス質問に回答します dbt의 의미 계층, SQL 수정, 모델 발견, 매니페스트 분석을 사용하여 사업 질문에 답변합니다 Responde preguntas de lenguaje natural utilizando dbt con una capa semántica, modificaciones SQL y análisis de manifestos Répondez aux questions de langage naturel en utilisant dbt avec une couche sémantique, des modifications SQL et une analyse de manifestes Beantworten Sie natürliche Sprachfragen mithilfe von dbt mit einer semantischen Ebene, SQL-Modifikationen und Manifestanalysen O skill de resposta a perguntas de linguagem natural com dbt permite responder a perguntas de negócios usando a camada semântica, SQL e modelos de dados. Навык ответов на естественные языковые вопросы с dbt позволяет отвечать на бизнес-вопросы, используя семантический слой, SQL и модели данных. مهارة الإجابة على الأسئلة الطبيعية مع dbt تمكن من الإجابة على أسئلة الأعمال باستخدام الطبقة الدلالية واللغة البرمجية SQL والنماذج البيانية. how to use answering-natural-language-questions-with-dbt what is answering-natural-language-questions-with-dbt answering-natural-language-questions-with-dbt alternative answering-natural-language-questions-with-dbt vs sql answering-natural-language-questions-with-dbt install answering-natural-language-questions-with-dbt setup guide dbt for business questions natural language questioning with dbt dbt自然语言问题回答 AIエージェント 语义层 SQL修改 模型发现 清单分析 数据分析 业务智能 Uses a semantic layer to answer data questions Modifies SQL to provide accurate answers Employs model discovery to find relevant data models Analyzes manifests to provide detailed answers Exhausts all options before indicating inability to answer answering-natural-language-questions-with-dbt is a skill that enables AI agents to answer natural language questions using dbt, a data build tool, to provide data-driven answers');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('phni3j9a/ccmobile/team-implement', 'community', 'phni3j9a', 'ccmobile', 'phni3j9a/ccmobile', 'team-implement', 1, 1, 36, '2026-03-03T11:41:15Z', '2026-03-07T01:55:38.038Z', '7fe33fc4d52074c7fbcc4b5d928b5583ee28400d8794f198ceb33b477cfbb37e', '{"id":"phni3j9a/ccmobile/team-implement","name":"team-implement","description":{"en":"The team-implement skill enables parallel implementation for AI agents, streamlining workflow execution based on approved plans and designs. It benefits developers and teams working with Claude Code on mobile applications.","zh":"Team Implement是一种AIエージェント并行实现技术，用于提高开发效率","ja":"Team Implementは、AIエージェントによる並列実装技術で、開発効率を向上させる","ko":"Team Implement는 AI 에이전트 병렬 구현 기술로 개발 효율성을 높입니다","es":"El skill team-implement permite la implementación de equipos de AI Agent en paralelo, basándose en un plan previamente aprobado","fr":"Le skill team-implement permet l''implémentation d''équipes d''Outil IA en parallèle, sur la base d''un plan préalablement approuvé","de":"Der Skill team-implement ermöglicht die Implementierung von KI-Agenten-Teams in Parallelschritten, basierend auf einem zuvor genehmigten Plan","pt":"O Team Implement é uma aplicação para utilizar Claude Code em dispositivos móveis, permitindo a implementação paralela de projetos","ru":"Team Implement - приложение для использования Claude Code на мобильных устройствах, обеспечивающее параллельную реализацию проектов","ar":"تطبيق الفريق هو تطبيق لاستخدام Claude Code على الأجهزة المحمولة، مما يسمح بتنفيذ مشاريع متوازية"},"seo":{"title":{"en":"team-implement: Parallel Implementation Setup Guide | AI ...","zh":"Team Implement Setup Guide - AIエージェント并行实现","ja":"Team Implement Setup Guide - AIエージェントによる並列実装","ko":"Team Implement Setup Guide - AI 에이전트 병렬 구현","es":"Guía de implementación de equipo para AI Agent","fr":"Guide d''implémentation d''équipe pour Outil IA","de":"Team-Implementierungsleitfaden für KI-Agenten","pt":"Guia de Configuração do Team Implement para Ferramentas d...","ru":"Настройка Team Implement для ИИ Агентов","ar":"إعداد تطبيق الفريق لآلات الدعم الإلكتروني"},"description":{"en":"Discover how team-implement streamlines parallel execution for AI agents. Learn to set up and optimize your workflow with our expert guide.","zh":"了解Team Implement的技术细节，并行实现和AIエージェント的集成","ja":"Team Implementの技術的詳細を学び、並列実装とAIエージェントの統合を理解する","ko":"Team Implement의 기술적 세부 정보를 학습하고, 병렬 구현 및 AI 에이전트의 통합을 이해","es":"Aprenda a implementar equipos de AI Agent de manera efectiva con nuestra guía paso a paso","fr":"Découvrez comment implémenter des équipes d''Outil IA de manière efficace avec notre guide étape par étape","de":"Erfahren Sie, wie Sie KI-Agenten-Teams effektiv implementieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o Team Implement para otimizar o uso de ferramentas de IA em projetos de desenvolvimento","ru":"Узнайте, как настроить Team Implement для эффективного использования ИИ Агентов в разработке","ar":"تعرف على كيفية إعداد تطبيق الفريق لتحسين استخدام آلات الدعم الإلكتروني في مشاريع التطوير"},"definition":{"en":"team-implement is a skill that facilitates parallel implementation for AI agents, executing plans approved via /startproject and recorded in .claude/docs/DESIGN.md","zh":"Team Implement是一种通过AIエージェント实现并行开发的技术","ja":"Team Implementは、AIエージェントを用いて並列開発を実現する技術","ko":"Team Implement는 AI 에이전트를 이용하여 병렬 개발을 구현하는 기술","es":"Team-implement es un skill que permite la implementación de equipos de AI Agent de manera paralela","fr":"Team-implement est un skill qui permet l''implémentation d''équipes d''Outil IA de manière parallèle","de":"Team-implement ist ein Skill, der die Implementierung von KI-Agenten-Teams in Parallelschritten ermöglicht","pt":"Team Implement é uma aplicação que permite a implementação paralela de projetos de desenvolvimento utilizando Claude Code","ru":"Team Implement - это приложение, обеспечивающее параллельную реализацию проектов разработки с помощью Claude Code","ar":"تطبيق الفريق هو تطبيق يسمح بتنفيذ مشاريع متوازية باستخدام Claude Code"},"features":{"en":["Analyzes plan and design to determine task dependencies and team composition","Spawns agent teams on a module/layer basis using the /startproject command","Monitors and coordinates team activities, ensuring integration and quality control","Executes integration tests upon completion of all tasks","Utilizes .claude/docs/DESIGN.md for architecture documentation"],"zh":["并行实现技术","AIエージェント集成","模块/层级单元的Teammate启动","Lead监控和统合","任务依存关系分析"],"ja":["並列実装技術","AIエージェントの統合","モジュール/レイヤー単位のTeammate起動","Leadによるモニタリングと統合","タスク依存関係の分析"],"ko":["병렬 구현 기술","AI 에이전트 통합","모듈/레이어 단위의 Teammate启动","Lead에 의한 모니터링과 통합","작업 의존 관계 분석"],"es":["Análisis de dependencias de tareas en paralelo","Determinación de la estructura del equipo basada en el plan","Implementación de teammates en unidades de módulos o capas","Monitoreo y coordinación por parte del líder","Ejecución de pruebas de integración después de la finalización de todas las tareas"],"fr":["Analyse des dépendances de tâches en parallèle","Détermination de la structure de l''équipe basée sur le plan","Implémentation de teammates en unités de modules ou de couches","Surveillance et coordination par le leader","Exécution de tests d''intégration après l''achèvement de toutes les tâches"],"de":["Analyse von Aufgabenabhängigkeiten in Parallelschritten","Bestimmung der Teamstruktur basierend auf dem Plan","Implementierung von Teammitgliedern in Modul- oder Schichteneinheiten","Überwachung und Koordination durch den Leiter","Ausführung von Integrations-tests nach Abschluss aller Aufgaben"],"pt":["Análise de plano e design de equipe","Criação de lista de tarefas","Spawn de equipe de agentes","Monitoramento e coordenação de tarefas","Integração e verificação de resultados"],"ru":["Анализ плана и дизайна команды","Создание списка задач","Запуск команды агентов","Мониторинг и координация задач","Интеграция и проверка результатов"],"ar":["تحليل الخطة وتصميم الفريق","إنشاء قائمة المهام","تشغيل فريق العمل","مراقبة وتنسيق المهام","دمج وتحقق النتائج"]},"keywords":{"en":["how to use team-implement","team-implement setup guide","parallel implementation for AI agents","Claude Code mobile application development","team-implement vs traditional workflow management","installing team-implement for AI agents","what is team-implement","team-implement alternative solutions","team-implement workflow optimization"],"zh":["AIエージェント","并行实现","Team Implement","开发效率","AI工具","并行开发","技术集成","模块开发"],"ja":["AIエージェント","並列実装","Team Implement","開発効率","AIツール","並列開発","技術統合","モジュール開発"],"ko":["AI 에이전트","병렬 구현","Team Implement","개발 효율성","AI 도구","병렬 개발","기술 통합","모듈 개발"],"es":["AI Agent implementación","equipo de implementación de IA","desarrollo de equipo de AI","herramientas de implementación de equipo","guias de implementación de AI","mejores prácticas de implementación de equipo de IA"],"fr":["Implémentation d''Outil IA","équipe d''implémentation d''IA","développement d''équipe d''Outil IA","outils d''implémentation d''équipe","guides d''implémentation d''IA","meilleures pratiques d''implémentation d''équipe d''Outil IA"],"de":["KI-Agenten-Implementierung","Implementierungsteam für KI","Entwicklung von KI-Agenten-Teams","Werkzeuge für Team-Implementierung","Anleitungen für KI-Implementierung","Best Practices für KI-Team-Implementierung"],"pt":["ferramentas de IA","desenvolvimento de projetos","Claude Code","aplicação móvel","implementação paralela","análise de plano","criação de lista de tarefas"],"ru":["ИИ Агенты","разработка проектов","Claude Code","мобильное приложение","параллельная реализация","анализ плана","создание списка задач"],"ar":["آلات الدعم الإلكتروني","تطوير المشاريع","Claude Code","تطبيق محمول","تنفيذ متوازي","تحليل الخطة","إنشاء قائمة المهام"]}},"owner":"phni3j9a","repo":"ccmobile","repoPath":"phni3j9a/ccmobile","stars":1,"forks":1,"updatedAt":"2026-03-03T11:41:15Z","topics":[],"category":"community","skillMd":{"name":"team-implement","description":"|","bodyPreview":"# Team Implement\n\n**Agent Teams による並列実装。`/startproject` で承認された計画に基づいて実行する。**\n\n## Prerequisites\n\n- `/startproject` が完了し、計画がユーザーに承認されていること\n- `.claude/docs/DESIGN.md` にアーキテクチャが記録されていること\n- タスクリストが作成されていること\n\n## Workflow\n\n```\nStep 1: Analyze Plan & Design Team\n  計画からタスク依存関係を分析し、チーム構成を決定\n    ↓\nStep 2: Spawn Agent Team\n  モジュール/レイヤー単位でTeammateを起動\n    ↓\nStep 3: Monitor & Coordinate\n  Lead がモニタリング、統合、品質管理\n    ↓\nStep 4: Integration & Verification\n  全タスク完了後、統合テスト実行\n```\n\n---\n\n## Step 1: Analyze Plan & Design","body":"# Team Implement\n\n**Agent Teams による並列実装。`/startproject` で承認された計画に基づいて実行する。**\n\n## Prerequisites\n\n- `/startproject` が完了し、計画がユーザーに承認されていること\n- `.claude/docs/DESIGN.md` にアーキテクチャが記録されていること\n- タスクリストが作成されていること\n\n## Workflow\n\n```\nStep 1: Analyze Plan & Design Team\n  計画からタスク依存関係を分析し、チーム構成を決定\n    ↓\nStep 2: Spawn Agent Team\n  モジュール/レイヤー単位でTeammateを起動\n    ↓\nStep 3: Monitor & Coordinate\n  Lead がモニタリング、統合、品質管理\n    ↓\nStep 4: Integration & Verification\n  全タスク完了後、統合テスト実行\n```\n\n---\n\n## Step 1: Analyze Plan & Design Team\n\n**タスクリストから並列化可能なワークストリームを特定する。**\n\n### Team Design Principles\n\n1. **ファイル所有権の分離**: 各Teammateが異なるファイルセットを所有\n2. **依存関係の尊重**: 依存タスクは同一Teammateか、依存順で実行\n3. **適切な粒度**: Teammate あたり 5-6 タスクが目安\n\n### Common Team Patterns\n\n**Pattern A: Module-Based (推奨)**\n```\nTeammate 1: Module A (models, core logic)\nTeammate 2: Module B (API, endpoints)\nTeammate 3: Tests (unit + integration)\n```\n\n**Pattern B: Layer-Based**\n```\nTeammate 1: Data layer (models, DB)\nTeammate 2: Business logic (services)\nTeammate 3: Interface layer (API/CLI)\n```\n\n**Pattern C: Feature-Based**\n```\nTeammate 1: Feature X (all layers)\nTeammate 2: Feature Y (all layers)\nTeammate 3: Shared infrastructure\n```\n\n### Anti-patterns\n\n- 2つの Teammate が同じファイルを編集 → 上書きリスク\n- Teammate あたりのタスクが多すぎる → 長時間放置リスク\n- 依存関係が複雑すぎる → 調整コストが利益を上回る\n\n---\n\n## Step 2: Spawn Agent Team\n\n**計画に基づいてチームを起動する。**\n\n```\nCreate an agent team for implementing: {feature}\n\nEach teammate receives:\n- Project Brief from CLAUDE.md\n- Architecture from .claude/docs/DESIGN.md\n- Library constraints from .claude/docs/libraries/\n- Their specific task assignments\n\nSpawn teammates:\n\n1. **Implementer-{module}** for each module/workstream\n   Prompt: \"You are implementing {module} for project: {feature}.\n\n   Read these files for context:\n   - CLAUDE.md (project context)\n   - .claude/docs/DESIGN.md (architecture)\n   - .claude/docs/libraries/ (library constraints)\n\n   Your assigned tasks:\n   {task list for this teammate}\n\n   Your file ownership:\n   {list of files this teammate owns}\n\n   Rules:\n   - ONLY edit files in your ownership set\n   - Follow existing codebase patterns\n   - Write type hints on all functions\n   - Run ruff check after each file change\n   - Communicate with other teammates if you need interface changes\n\n   When done with each task, mark it completed in the task list.\n\n   IMPORTANT — Work Log:\n   When ALL your assigned tasks are complete, write a work log file to:\n     .claude/logs/agent-teams/{team-name}/{your-teammate-name}.md\n\n   Use this format:\n   # Work Log: {your-teammate-name}\n   ## Summary\n   (1-2 sentence summary of what you accomplished)\n   ## Tasks Completed\n   - [x] {task}: {brief description of what was done}\n   ## Files Modified\n   - `{file path}`: {what was changed and why}\n   ## Key Decisions\n   - {decision made during implementation and rationale}\n   ## Communication with Teammates\n   - → {recipient}: {summary of message sent}\n   - ← {sender}: {summary of message received}\n   ## Issues Encountered\n   - {issue}: {how it was resolved}\n   (If none, write ''None'')\n   \"\n\n2. **Tester** (optional but recommended)\n   Prompt: \"You are the Tester for project: {feature}.\n\n   Read:\n   - CLAUDE.md, .claude/docs/DESIGN.md\n   - Existing test patterns in tests/\n\n   Your tasks:\n   - Write tests for each module as implementers complete them\n   - Follow TDD where possible (write test stubs first)\n   - Run uv run pytest after each test file\n   - Report failing tests to the relevant implementer\n\n   Test coverage target: 80%+\n\n   IMPORTANT — Work Log:\n   When ALL your assigned tasks are complete, write a work log file to:\n     .claude/logs/agent-teams/{team-name}/{your-teammate-name}.md\n\n   Use this format:\n   # Work Log: {your-teammate-name}\n   ## Summary\n   (1-2 sentence summary of what you accomplished)\n   ## Tasks Completed\n   - [x] {task}: {brief description of what was done}\n   ## Files Modified\n   - `{file path}`: {what was changed and why}\n   ## Key Decisions\n   - {decision made during implementation and rationale}\n   ## Communication with Teammates\n   - → {recipient}: {summary of message sent}\n   - ← {sender}: {summary of message received}\n   ## Issues Encountered\n   - {issue}: {how it was resolved}\n   (If none, write ''None'')\n   \"\n\nUse delegate mode (Shift+Tab) to prevent Lead from implementing directly.\nWait for all teammates to complete their tasks.\n```\n\n---\n\n## Step 3: Monitor & Coordinate\n\n**Lead は実装せず、モニタリングと統合に専念する。**\n\n### Monitoring Checklist\n\n- [ ] タスクリストの進捗を確認（Ctrl+T）\n- [ ] 各 Teammate の出力を確認（Shift+Up/Down）\n- [ ] ファイル競合がないか確認\n- [ ] 行き詰まっている Teammate がいないか確認\n\n### Intervention Triggers\n\n| 状況 | 対応 |\n|------|------|\n| Teammate が長時間タスクを進めない | メッセージで確認、必要なら再指示 |\n| ファイル競合が発生 | 所有権を再配分 |\n| テストが失敗し続ける | 関連する Implementer にメッセージ |\n| 想定外の技術的問題 | Codex に相談（サブエージェント経由） |\n\n### Quality Gates (via Hooks)\n\n`TeammateIdle` hook と `TaskCompleted` hook が自動で品質チェック：\n\n- lint チェック（ruff）\n- テスト実行（pytest）\n- 型チェック（ty）\n\n---\n\n## Step 4: Integration & Verification\n\n**全タスク完了後、統合検証を行う。**\n\n```bash\n# All quality checks\nuv run ruff check .\nuv run ruff format --check .\nuv run ty check src/\nuv run pytest -v\n\n# Or via poe\npoe all\n```\n\n### Integration Report\n\n```markdown\n## 実装完了: {feature}\n\n### 完了タスク\n- [x] {task 1}\n- [x] {task 2}\n...\n\n### 品質チェック\n- ruff: ✓ / ✗\n- ty: ✓ / ✗\n- pytest: ✓ ({N} tests passed)\n- coverage: {N}%\n\n### 次のステップ\n`/team-review` で並列レビューを実行してください\n```\n\n### Cleanup\n\n```\nClean up the team\n```\n\n---\n\n## Tips\n\n- **Delegate mode**: Shift+Tab で Lead が実装を避ける\n- **タスク粒度**: Teammate あたり 5-6 タスクが最適\n- **ファイル競合回避**: モジュール単位の所有権分離が最重要\n- **Tester 分離**: Implementer とは別に Tester を立てるとTDD的に回る\n- **コスト意識**: 各 Teammate は独立した Claude インスタンス（トークン消費大）\n"},"lastSynced":"2026-03-07T01:55:38.038Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude Code needing parallel implementation for streamlined workflow execution.","zh":"适合于像 Claude Code 这样的 AI Agents，需要并行实现以实现工作流的简化执行。","ja":"Claude Code のような AI エージェントに適しており、ストリームライン化されたワークフロー実行のための並列実装が必要です。","ko":"클라우드 코드와 같은 AI 에이전트에 적합하며, 워크플로우 실행을 간소화하기 위한 병렬 구현이 필요합니다.","es":"Perfecto para Agentes de IA como Claude Code que necesitan una implementación paralela para la ejecución de flujos de trabajo optimizados.","fr":"Parfait pour les agents IA comme Claude Code nécessitant une mise en œuvre parallèle pour l''exécution de flux de travail rationalisés.","de":"Perfekt für KI-Agents wie Claude Code, die eine parallele Implementierung für die Ausführung von optimierten Workflows benötigen.","pt":"Perfeito para Agentes de IA como Claude Code que necessitam de implementação paralela para execução de fluxo de trabalho otimizado.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code, требующих параллельной реализации для оптимизированной выполнения рабочего процесса.","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Claude Code الذي يحتاج إلى تنفيذ متوازي لتنفيذ تدفق العمل الم्ُरवّض"},"recommendation":{"en":"Empowers agents to execute approved plans and designs in parallel, utilizing Agent Teams for modular implementation and lead monitoring for quality control, all based on recorded architecture in `.claude/docs/DESIGN.md` and predefined task lists.","zh":"赋予代理执行批准的计划和设计，并利用代理团队进行模块化实现和监控，以确保质量控制，所有这些都是基于记录的架构 `.claude/docs/DESIGN.md` 和预定义的任务列表。","ja":"エージェントに、承認された計画と設計を実行する権限を与え、エージェントチームを使用してモジュラー化された実装と監視を行い、品質管理を実施します。すべてのアーキテクチャは `.claude/docs/DESIGN.md` に記録され、事前に定義されたタスクリストに基づいています。","ko":"에이전트가 승인된 계획 및 설계를 실행하도록 허용하고 에이전트 팀을 사용하여 모듈화된 구현 및 모니터링을 수행하며 품질 관리를 수행합니다. 모든 아키텍처는 `.claude/docs/DESIGN.md`에 기록되고 사전 정의된 작업 목록을 기반으로 합니다.","es":"Permite a los agentes ejecutar planes y diseños aprobados en paralelo, utilizando Equipos de Agentes para implementación modular y seguimiento de liderazgo para control de calidad, todo basado en la arquitectura registrada en `.claude/docs/DESIGN.md` y listas de tareas predefinidas.","fr":"Permet aux agents d''exécuter des plans et des conceptions approuvés en parallèle, en utilisant des Équipes d''Agents pour une mise en œuvre modulaire et un suivi de liderazgo pour le contrôle de la qualité, le tout basé sur l''architecture enregistrée dans `.claude/docs/DESIGN.md` et des listes de tâches prédéfinies.","de":"Ermöglicht es Agenten, genehmigte Pläne und Designs parallel auszuführen, indem sie Agent-Teams für modulare Implementierung und Leiterüberwachung für Qualitätskontrolle verwenden, alles basierend auf der in `.claude/docs/DESIGN.md` aufgezeichneten Architektur und vordefinierten Aufgabenlisten.","pt":"Habilita os agentes a executar planos e projetos aprovados em paralelo, utilizando Equipes de Agentes para implementação modular e monitoramento de liderança para controle de qualidade, tudo com base na arquitetura registrada em `.claude/docs/DESIGN.md` e listas de tarefas predefinidas.","ru":"Позволяет агентам выполнять утвержденные планы и проекты параллельно, используя команды агентов для модульной реализации и мониторинг руководства для контроля качества, все на основе записанной архитектуры в `.claude/docs/DESIGN.md` и предопределенных списков задач.","ar":"يُمكنّ Agents من تنفيذ الخطط والمخططات المُصادق عليها بالتوازي، باستخدام فرق الوكلاء للتنفيذ المُتقطّع ومراقبة القيادة لضمان الجودة، وكل ذلك استناداً إلى الهيكل المسجّل في `.claude/docs/DESIGN.md` وقوائم المهام المُسبقة التعريف."},"useCases":{"en":["Automating mobile application development workflows","Implementing modular code structures with Agent Teams","Streamlining task execution based on approved project plans"],"zh":["自动化移动应用程序开发工作流程","使用代理团队实现模块化代码结构","根据批准的项目计划简化任务执行"],"ja":["モバイルアプリケーション開発ワークフローの自動化","エージェントチームを使用したモジュラー化されたコード構造の実装","承認されたプロジェクトプランに基づいたタスク実行のストリームライン化"],"ko":["모바일 애플리케이션 개발 워크플로 자동화","에이전트 팀을 사용한 모듈화된 코드 구조 구현","승인된 프로젝트 계획을 기반으로任务 실행의 간소화"],"es":["Automatización de flujos de trabajo de desarrollo de aplicaciones móviles","Implementación de estructuras de código modulares con Equipos de Agentes","Optimización de la ejecución de tareas basada en planes de proyecto aprobados"],"fr":["Automatisation des flux de travail de développement d''applications mobiles","Mise en œuvre de structures de code modulaires avec des Équipes d''Agents","Optimisation de l''exécution des tâches basée sur des plans de projet approuvés"],"de":["Automatisierung von Workflows für die Entwicklung mobiler Anwendungen","Implementierung modularer Code-Strukturen mit Agent-Teams","Optimierung der Aufgabenausführung basierend auf genehmigten Projektplänen"],"pt":["Automatizar fluxos de trabalho de desenvolvimento de aplicativos móveis","Implementar estruturas de código modulares com Equipes de Agentes","Otimizar a execução de tarefas com base em planos de projeto aprovados"],"ru":["Автоматизировать рабочие процессы разработки мобильных приложений","Реализовать модульные структуры кода с командами агентов","Оптимизировать выполнение задач на основе утвержденных проектных планов"],"ar":["تأتميم سير العمل لتطوير تطبيقات الهاتف المحمول","تنفيذ هياكل متقطعة للرمز مع فرق الوكلاء","جعل تنفيذ المهام أكثر كفاءة بناءً على خطط المشروع المُصادق عليها"]},"limitations":{"en":["Requires `/startproject` completion and user-approved plans","Needs `.claude/docs/DESIGN.md` for architecture records","Dependent on predefined task lists"],"zh":["/startproject 完成是必需的，且需要用户批准的计划",".claude/docs/DESIGN.md 中需要架构记录","依赖于预定义的任务列表"],"ja":["/startproject の完了が必要であり、ユーザーが承認した計画が必要",".claude/docs/DESIGN.md にアーキテクチャの記録が必要","事前に定義されたタスクリストに依存"],"ko":["/startproject 완료가 필요하며 사용자 승인된 계획이 필요",".claude/docs/DESIGN.md에 아키텍처 기록이 필요","사전 정의된 작업 목록에 의존"],"es":["Requiere la finalización de `/startproject` y planes aprobados por el usuario","Necesita `.claude/docs/DESIGN.md` para registros de arquitectura","Dependiente de listas de tareas predefinidas"],"fr":["Nécessite la completion de `/startproject` et des plans approuvés par l''utilisateur","A besoin de `.claude/docs/DESIGN.md` pour les enregistrements d''architecture","Dépendant de listes de tâches prédéfinies"],"de":["Benötigt die Vervollständigung von `/startproject` und benutzer-genehmigte Pläne","Benötigt `.claude/docs/DESIGN.md` für Architektur-Aufzeichnungen","Abhängig von vordefinierten Aufgabenlisten"],"pt":["Exige a conclusão de `/startproject` e planos aprovados pelo usuário","Necessita de `.claude/docs/DESIGN.md` para registros de arquitetura","Depende de listas de tarefas predefinidas"],"ru":["Требует завершения `/startproject` и планов, утвержденных пользователем","Требует `.claude/docs/DESIGN.md` для записей архитектуры","Зависит от предопределенных списков задач"],"ar":["يتطلب إكمال `/startproject` وخطط مُصادق عليها من قبل المستخدم","يحتاج إلى `.claude/docs/DESIGN.md` لتسجيل الهيكل","يعتمد على قوائم المهام المُسبقة التعريف"]},"version":4},"contentHash":"7fe33fc4d52074c7fbcc4b5d928b5583ee28400d8794f198ceb33b477cfbb37e","qualityScore":36}');
