INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('phni3j9a/ccmobile/team-implement', 'team-implement', 'phni3j9a', 'ccmobile', 'community', 'team-implement phni3j9a ccmobile community The team-implement skill enables parallel implementation for AI agents, streamlining workflow execution based on approved plans and designs. It benefits developers and teams working with Claude Code on mobile applications. Team Implement是一种AIエージェント并行实现技术，用于提高开发效率 Team Implementは、AIエージェントによる並列実装技術で、開発効率を向上させる Team Implement는 AI 에이전트 병렬 구현 기술로 개발 효율성을 높입니다 El skill team-implement permite la implementación de equipos de AI Agent en paralelo, basándose en un plan previamente aprobado Le skill team-implement permet l''implémentation d''équipes d''Outil IA en parallèle, sur la base d''un plan préalablement approuvé Der Skill team-implement ermöglicht die Implementierung von KI-Agenten-Teams in Parallelschritten, basierend auf einem zuvor genehmigten Plan O Team Implement é uma aplicação para utilizar Claude Code em dispositivos móveis, permitindo a implementação paralela de projetos Team Implement - приложение для использования Claude Code на мобильных устройствах, обеспечивающее параллельную реализацию проектов تطبيق الفريق هو تطبيق لاستخدام Claude Code على الأجهزة المحمولة، مما يسمح بتنفيذ مشاريع متوازية how to use team-implement team-implement setup guide parallel implementation for AI agents Claude Code mobile application development team-implement vs traditional workflow management installing team-implement for AI agents what is team-implement team-implement alternative solutions team-implement workflow optimization AIエージェント 并行实现 Team Implement 开发效率 AI工具 并行开发 技术集成 模块开发 Analyzes plan and design to determine task dependencies and team composition Spawns agent teams on a module/layer basis using the /startproject command Monitors and coordinates team activities, ensuring integration and quality control Executes integration tests upon completion of all tasks Utilizes .claude/docs/DESIGN.md for architecture documentation team-implement is a skill that facilitates parallel implementation for AI agents, executing plans approved via /startproject and recorded in .claude/docs/DESIGN.md');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jhb-software/website/intl', 'community', 'jhb-software', 'website', 'jhb-software/website', 'intl', 1, 0, 36, '2026-02-13T07:21:20Z', '2026-03-07T12:50:35.920Z', '8870f03ffe5e0449c2e66aaff76cad849be7b769792159f5e15bad2698eb3371', '{"id":"jhb-software/website/intl","name":"intl","description":{"en":"The intl skill provides a monorepository for the JHB Website frontend and content management system, enabling developers to manage localized fields and translations efficiently.","zh":"intl 是一个多语言支持和本地化解决方案，适用于 Astro 组件开发，提供本地化字段和文本翻译功能","ja":"intl は多言語対応とローカライズのためのソリューション，Astro コンポーネント開発に最適，ローカライズされたフィールドとテキスト翻訳機能を提供","ko":"intl은 다국어 지원과 지역화 솔루션을 제공하는 기술로, Astro 컴포넌트 개발을 위해 지역화된 필드와 텍스트 번역 기능을 제공합니다","es":"intl es una monorepositorio para el frontend y el sistema de gestión de contenido de JHB Website","fr":"intl est une monorepository pour le frontend et le système de gestion de contenu du site Web JHB","de":"intl ist eine Monorepository für das Frontend und das Content-Management-System der JHB-Website","pt":"O Intl é um monorepositório para o frontend e sistema de gerenciamento de conteúdo do JHB Website, com regras de internacionalização para desenvolvedores","ru":"Интл - это монорепозиторий для frontend и системы управления контентом сайта JHB, с правилами интернационализации для разработчиков","ar":"Intl هو مونوريبوزيتوري لجبهة وسيطة وتحكم المحتوى لموقع JHB، مع قوانين التدويل للطورين"},"seo":{"title":{"en":"intl: Monorepo Setup Guide for AI Agents","zh":"intl 多语言支持 Setup Guide","ja":"intl 多言語対応 Best Practices","ko":"intl 다국어 지원 가이드","es":"intl: Guía de Configuración para Herramientas de AI","fr":"intl: Guide de Configuration pour les Outils d''IA","de":"intl: Konfigurationsleitfaden für KI-Tools","pt":"Intl: Guia de Configuração de Internacionalização","ru":"ИИ Агенты: Intl - Настройка Многоязычного Сайта","ar":"Intl: دليل إعداد التدويل للويب"},"description":{"en":"Discover how to implement internationalization rules in your JHB Website frontend and CMS with the intl skill - get started now and optimize your multi-langu...","zh":"了解 intl 技术，实现多语言支持和本地化解决方案，适用于 Astro 组件开发","ja":"intl 技術の詳細，多言語対応とローカライズの実現方法，Astro コンポーネント開発に最適","ko":"intl 기술을 통해 다국어 지원과 지역화 솔루션을 구현하세요. Astro 컴포넌트 개발을 위한 최적의 가이드","es":"Aprenda a configurar intl para sitios web multilingües con Astro y CMS","fr":"Découvrez comment configurer intl pour les sites web multilingues avec Astro et CMS","de":"Erfahren Sie, wie Sie intl für mehrsprachige Websites mit Astro und CMS konfigurieren","pt":"Aprenda a configurar a internacionalização no monorepositório do JHB Website com dicas e melhores práticas para desenvolvedores","ru":"Узнайте, как настроить многоязычный сайт с помощью ИИ Агентов и монорепозитория JHB Website","ar":"اكتشف كيفية إعداد التدويل للويب مع دليل Intl الشامل لتنمية التطبيقات"},"definition":{"en":"intl is a monorepository skill for managing internationalization rules in a website''s frontend and content management system","zh":"intl 是一个多语言支持和本地化解决方案","ja":"intl は多言語対応とローカライズのためのソリューション","ko":"intl은 다국어 지원과 지역화 솔루션을 제공하는 기술","es":"intl es un conjunto de reglas para la internacionalización de sitios web","fr":"intl est un ensemble de règles pour l''internationalisation des sites web","de":"intl ist eine Sammlung von Regeln für die Internationalisierung von Websites","pt":"Intl é um conjunto de regras para internacionalização de sites, incluindo campos localizados e traduções","ru":"Интл - это набор правил для интернационализации сайтов, включая локализованные поля и переводы","ar":"Intl هو مجموعة من القواعد للتدويل المواقع، بما في ذلك الحقول المُحَلَّلة والترجمات"},"features":{"en":["Enforces localized fields with `localized: true`","Supports multi-language websites with translatable text strings","Updates CMS labels globally via `/cms/src/globals/labels.ts`","Prevents hardcoded text strings in Astro components","Utilizes the `global` group for common site-wide labels"],"zh":["支持多语言文本翻译","提供本地化字段功能","适用于 Astro 组件开发","支持多语言网站开发","提供全局标签和翻译功能"],"ja":["多言語対応のテキスト翻訳をサポート","ローカライズされたフィールド機能を提供","Astro コンポーネント開発に最適","多言語対応のウェブサイト開発をサポート","グローバルラベルと翻訳機能を提供"],"ko":["다국어 텍스트 번역 지원","지역화된 필드 기능 제공","Astro 컴포넌트 개발을 위한 최적의 솔루션","다국어 지원 웹사이트 개발을 지원","전역 레이블과 번역 기능 제공"],"es":["Soporte para sitios web multilingües con Astro","Campos localizados en el CMS","Traducciones y etiquetas personalizables","Integración con el sistema de gestión de contenido","Reglas de internacionalización para textos y etiquetas"],"fr":["Prise en charge des sites web multilingues avec Astro","Champs localisés dans le CMS","Traductions et libellés personnalisables","Intégration avec le système de gestion de contenu","Règles d''internationalisation pour les textes et les libellés"],"de":["Unterstützung für mehrsprachige Websites mit Astro","Lokalisierte Felder im CMS","Anpassbare Übersetzungen und Bezeichnungen","Integration mit dem Content-Management-System","Internationalisierungsregeln für Texte und Bezeichnungen"],"pt":["Campos localizados com `localized: true`","Traduções para texto de usuário","Atualização de rótulos globais no CMS","Suporte a múltiplos idiomas","Integração com Astro components"],"ru":["Локализованные поля с `localized: true`","Переводы для текста пользователя","Обновление глобальных меток в CMS","Поддержка多язычности","Интеграция с Astro components"],"ar":["الحقول المُحَلَّلة مع `localized: true`","ترجمات للنصوص المستخدمة","تحديث العلامات العالمية في نظام إدارة المحتوى","دعم اللغات المتعددة","التكامل مع مكونات Astro"]},"keywords":{"en":["how to use intl","intl setup guide","intl alternative","intl vs CMS","intl install","what is intl","intl monorepo","internationalization rules"],"zh":["intl 多语言支持","Astro 组件开发","本地化解决方案","多语言网站开发","AIエージェント","intl 技术","多语言支持 Setup Guide"],"ja":["intl 多言語対応","Astro コンポーネント開発","ローカライズの実現方法","多言語対応のウェブサイト開発","AIエージェント","intl 技術","多言語対応 Best Practices"],"ko":["intl 다국어 지원","Astro 컴포넌트 개발","지역화 솔루션","다국어 지원 웹사이트 개발","AI 에이전트","intl 기술","다국어 지원 가이드"],"es":["intl","sitios web multilingües","Astro","CMS","internacionalización","traducciones","etiquetas personalizables","herramientas de AI","desarrollo web"],"fr":["intl","sites web multilingues","Astro","CMS","internationalisation","traductions","libellés personnalisables","outils d''IA","développement web"],"de":["intl","mehrsprachige Websites","Astro","CMS","Internationalisierung","Übersetzungen","anpassbare Bezeichnungen","KI-Tools","Webentwicklung"],"pt":["intl","internacionalização","monorepositório","frontend","CMS"," Astro components","traduções","campos localizados","desenvolvimento web"],"ru":["ИИ Агенты","интернационализация","монорепозиторий","frontend","CMS"," Astro components","переводы","локализованные поля","веб-разработка"],"ar":["التدويل","مونوريبوزيتوري","جبهة وسيطة","نظام إدارة المحتوى","مكونات Astro","ترجمات","حقول محللة","تطوير الويب"]}},"owner":"jhb-software","repo":"website","repoPath":"jhb-software/website","stars":1,"forks":0,"updatedAt":"2026-02-13T07:21:20Z","topics":[],"category":"community","skillMd":{"name":"intl","description":"Internationalization rules for multi-language websites. Use when working on localized text fields in the CMS, Intl formatting (dates, numbers, currencies, lists) in Astro components, or any locale-aware code.","bodyPreview":"# Internationalization Rules\n\n## CMS: Localized Fields\n\n- All text fields (e.g. labels, titles) should have `localized: true`\n\n## Web: Labels & Translations\n\nThis is a multi-language website. When adding labels or text to Astro components:\n\n1. **Never hardcode text strings** - All user-facing text must be translatable\n2. **Update the CMS labels global** - Add necessary fields to `/cms/src/globals/labels.ts`\n   - Use the `global` group for common, site-wide labels (e.g., \"show-more\", \"close\", \"lo","body":"# Internationalization Rules\n\n## CMS: Localized Fields\n\n- All text fields (e.g. labels, titles) should have `localized: true`\n\n## Web: Labels & Translations\n\nThis is a multi-language website. When adding labels or text to Astro components:\n\n1. **Never hardcode text strings** - All user-facing text must be translatable\n2. **Update the CMS labels global** - Add necessary fields to `/cms/src/globals/labels.ts`\n   - Use the `global` group for common, site-wide labels (e.g., \"show-more\", \"close\", \"loading\")\n   - Use specific groups for scoped labels (e.g., `articles` for article-related text, `contact` for contact forms)\n3. **Access labels in components** - Use `const { labels } = globalState`\n4. **Example usage**: `labels.articles[''written-by'']` or `labels.global[''show-more'']`\n\n- When adding labels to the CMS, ensure you use all of them. Delete unused labels after implementation.\n\n## Web: Formatting with Intl APIs\n\nUse the built-in JavaScript `Intl` APIs for locale-aware formatting. Never use third-party libraries or manual string concatenation.\n\nThe active locale **must come from the global state** (`const { locale } = globalState`). Never hardcode a locale string.\n\n### Date & Time\n\n```ts\nconst formatDate = (date: Date | string) =>\n  new Intl.DateTimeFormat(locale, {\n    day: ''2-digit'',\n    month: ''long'',\n    year: ''numeric'',\n  }).format(new Date(date));\n```\n\n### Lists\n\n```ts\nconst formatList = (items: string[], type: Intl.ListFormatType = ''conjunction'') =>\n  new Intl.ListFormat(locale, { type }).format(items);\n```\n\n### Currency & Numbers\n\n```ts\nconst formatCurrency = (value: number, currency = ''EUR'') =>\n  new Intl.NumberFormat(locale, {\n    style: ''currency'',\n    currency,\n    minimumFractionDigits: 2,\n  }).format(value);\n```\n"},"lastSynced":"2026-03-07T12:50:35.920Z","agentAnalysis":{"suitability":{"en":"Perfect for Multilingual AI Agents needing efficient content management and localization capabilities.","zh":"适合需要高效内容管理和本地化功能的多语言AI代理。","ja":"多言語AIエージェントが効率的なコンテンツ管理とローカライズ機能を必要とする場合に適しています。","ko":"효율적인 콘텐츠 관리 및 지역화 기능이 필요한 다국어 AI 에이전트에게 적합합니다.","es":"Perfecto para Agentes de IA Multilingües que necesitan una gestión de contenido eficiente y capacidades de localización.","fr":"Parfait pour les Agents de IA Multilingues ayant besoin d''une gestion de contenu efficace et de capacités de localisation.","de":"Perfekt für multilinguale KI-Agents, die eine effiziente Inhaltsverwaltung und Lokalisierungsfunktionen benötigen.","pt":"Perfeito para Agentes de IA Multilíngues que precisam de gerenciamento de conteúdo eficiente e capacidades de localização.","ru":"Идеально подходит для многоязычных агентов ИИ, которым необходим эффективный менеджмент контента и возможности локализации.","ar":"مثالي للوكلاء الذكيين المتعددة اللغات الذين يحتاجون إلى إدارة المحتوى الفعالة وخصائص الترجمة المحلية."},"recommendation":{"en":"Empowers agents to manage localized fields and translations efficiently using a monorepository, ensuring all user-facing text is translatable and updatable through the CMS labels global, with support for multiple languages and Astro components.","zh":"赋予代理管理本地化字段和翻译的能力，使用单一仓库，确保所有用户面向文本可翻译和通过CMS全局标签更新，支持多语言和Astro组件。","ja":"エージェントがローカライズされたフィールドと翻訳を効率的に管理できるようにし、モノリポジトリを使用して、すべてのユーザー向けテキストが翻訳可能で、CMSラベルのグローバルを介して更新可能となるようにします。さらに、複数の言語とAstroコンポーネントをサポートします。","ko":"에이전트가 로컬라이즈된 필드와 번역을 효율적으로 관리할 수 있도록 하여, 하나의 저장소를 사용하여 모든 사용자向け 텍스트가 번역 가능하고, CMS 레이블의 글로벌을 통해 업데이트할 수 있도록 합니다. 또한 다중 언어와 Astro 컴포넌트를 지원합니다.","es":"Habilita a los agentes a gestionar campos localizados y traducciones de forma eficiente utilizando un monorepositorio, asegurando que todo el texto que enfrenta al usuario sea translatable y actualizable a través de las etiquetas globales de CMS, con soporte para múltiples idiomas y componentes Astro.","fr":"Permet aux agents de gérer les champs localisés et les traductions de manière efficace en utilisant un monorepository, en garantissant que tout le texte destiné aux utilisateurs soit translatable et mettable à jour via les étiquettes globales de CMS, avec une prise en charge de plusieurs langues et de composants Astro.","de":"Ermächtigt die Agenten, lokalisierte Felder und Übersetzungen effizient mithilfe eines Monorepositorys zu verwalten, wodurch sichergestellt wird, dass alle benutzerfacing-Texte übersetzbar und über das CMS-Label-Global aktualisierbar sind, mit Unterstützung für mehrere Sprachen und Astro-Komponenten.","pt":"Habilita os agentes a gerenciar campos localizados e traduções de forma eficiente usando um monorepositório, garantindo que todo o texto voltado para o usuário seja transponível e atualizável por meio das etiquetas globais do CMS, com suporte a vários idiomas e componentes Astro.","ru":"Наделяет агентов возможностью эффективно управлять локализованными полями и переводами с помощью монорепозитория, гарантируя, что весь текст, обращенный к пользователю, является переводимым и обновляемым через глобальные метки CMS, с поддержкой нескольких языков и компонентов Astro.","ar":"يمنح الوكلاء القدرة على إدارة الحقول المحلية والترجمات بفعالية باستخدام مستودع واحد، مما يضمن أن يكون كل نص موجه للمستخدم قابلًا للترجمة والتحديث من خلال علامات CMS العالمية، مع دعم لعدة لغات ومكونات Astro."},"useCases":{"en":["Automating translation updates for multilingual websites","Generating localized content for global audiences","Debugging internationalization issues in Astro components"],"zh":["自动为多语言网站更新翻译","为全球受众生成本地化内容","在Astro组件中调试国际化问题"],"ja":["多言語Webサイトの翻訳を自動更新する","グローバルオーディエンスのためにローカライズされたコンテンツを生成する","Astroコンポーネントの国際化問題をデバッグする"],"ko":["다국어 웹사이트의 번역을 자동으로 업데이트하는 것","글로벌 대상에게 지역화된 콘텐츠를 생성하는 것","Astro 컴포넌트의 국제화 문제를 디버깅하는 것"],"es":["Automatizar actualizaciones de traducciones para sitios web multilingües","Generar contenido localizado para audiencias globales","Depurar problemas de internacionalización en componentes Astro"],"fr":["Automatiser les mises à jour de traductions pour les sites web multilingues","Générer du contenu localisé pour les audiences mondiales","Déboguer les problèmes d''internationalisation dans les composants Astro"],"de":["Automatisieren von Übersetzungs-Updates für mehrsprachige Websites","Erstellen von lokalisierten Inhalten für globale Zielgruppen","Fehlerbehebung bei Internationalisierungsproblemen in Astro-Komponenten"],"pt":["Automatizar atualizações de traduções para sites multilíngues","Gerar conteúdo localizado para públicos globais","Depurar problemas de internacionalização em componentes Astro"],"ru":["Автоматизировать обновления переводов для многоязычных веб-сайтов","Генерировать локализованный контент для глобальной аудитории","Отлаживать проблемы интернационализации в компонентах Astro"],"ar":["تأتمتة تحديثات الترجمة لمواقع متعددة اللغات","генерировать محتوى محلي لمجموعات عالمية","تصحيح أخطاء العولمة في مكونات Astro"]},"limitations":{"en":["Requires CMS integration","Limited to Astro components","Needs manual updates to CMS labels global"],"zh":["需要CMS集成","仅限Astro组件","需要手动更新CMS全局标签"],"ja":["CMS統合が必要","Astroコンポーネントのみ","CMSラベルのグローバルを手動で更新する必要がある"],"ko":["CMS 통합이 필요합니다.","Astro 컴포넌트만 해당합니다.","CMS 레이블의 글로벌을 수동으로 업데이트해야 합니다."],"es":["Requiere integración con CMS","Limitado a componentes Astro","Necesita actualizaciones manuales a las etiquetas globales de CMS"],"fr":["Nécessite une intégration avec CMS","Limité aux composants Astro","Nécessite des mises à jour manuelles des étiquettes globales de CMS"],"de":["Benötigt CMS-Integration","Begrenzt auf Astro-Komponenten","Benötigt manuelle Updates der CMS-Label-Global"],"pt":["Requer integração com CMS","Limitado a componentes Astro","Necessita de atualizações manuais para etiquetas globais do CMS"],"ru":["Требует интеграции с CMS","Ограничен компонентами Astro","Требует ручных обновлений глобальных меток CMS"],"ar":["يتطلب تكاملًا مع CMS","محدود بمكونات Astro","يحتاج إلى تحديثات يدوية للعلامات العالمية ل CMS"]},"version":4},"contentHash":"8870f03ffe5e0449c2e66aaff76cad849be7b769792159f5e15bad2698eb3371","qualityScore":36}');
