INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jhb-software/website/intl', 'intl', 'jhb-software', 'website', 'community', 'intl jhb-software website community The intl skill provides a monorepository for the JHB Website frontend and content management system, enabling developers to manage localized fields and translations efficiently. intl 是一个多语言支持和本地化解决方案，适用于 Astro 组件开发，提供本地化字段和文本翻译功能 intl は多言語対応とローカライズのためのソリューション，Astro コンポーネント開発に最適，ローカライズされたフィールドとテキスト翻訳機能を提供 intl은 다국어 지원과 지역화 솔루션을 제공하는 기술로, Astro 컴포넌트 개발을 위해 지역화된 필드와 텍스트 번역 기능을 제공합니다 intl es una monorepositorio para el frontend y el sistema de gestión de contenido de JHB Website intl est une monorepository pour le frontend et le système de gestion de contenu du site Web JHB intl ist eine Monorepository für das Frontend und das Content-Management-System der JHB-Website O Intl é um monorepositório para o frontend e sistema de gerenciamento de conteúdo do JHB Website, com regras de internacionalização para desenvolvedores Интл - это монорепозиторий для frontend и системы управления контентом сайта JHB, с правилами интернационализации для разработчиков Intl هو مونوريبوزيتوري لجبهة وسيطة وتحكم المحتوى لموقع JHB، مع قوانين التدويل للطورين how to use intl intl setup guide intl alternative intl vs CMS intl install what is intl intl monorepo internationalization rules intl 多语言支持 Astro 组件开发 本地化解决方案 多语言网站开发 AIエージェント intl 技术 多语言支持 Setup Guide Enforces localized fields with `localized: true` Supports multi-language websites with translatable text strings Updates CMS labels globally via `/cms/src/globals/labels.ts` Prevents hardcoded text strings in Astro components Utilizes the `global` group for common site-wide labels intl is a monorepository skill for managing internationalization rules in a website''s frontend and content management system');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Smarter-Dev/smarter-dev/skrift', 'community', 'Smarter-Dev', 'smarter-dev', 'Smarter-Dev/smarter-dev', 'skrift', 1, 2, 36, '2026-03-07T03:15:18Z', '2026-03-07T12:51:19.979Z', 'df675d2d62ead0e3d671e6dda6f13aa783511053a6f9062f471c6dad16d022cf', '{"id":"Smarter-Dev/smarter-dev/skrift","name":"skrift","description":{"en":"Skrift is a Python CMS built on Litestar, offering WordPress-style template resolution and a hook/filter extensibility system for the Smarter Dev community.","zh":"Skrift是一个轻量级的异步Python CMS，基于Litestar，具有WordPress风格的模板解析和钩子/过滤器扩展系统","ja":"Skriftは、Litestarベースの軽量級Python CMSです。WordPressスタイルのテンプレート解析とフック/フィルターエクステンションシステムを備えています","ko":"Skrift는 Litestar 기반의 경량급 Python CMS로 WordPress 스타일의 템플릿 해석과 후크/필터 확장 시스템을 제공합니다","es":"Skrift es un CMS de Python asíncrono que ofrece resolución de plantillas de estilo WordPress y acceso a bases de datos asincrónicas con SQLAlchemy","fr":"Skrift est un CMS Python asynchrone qui propose une résolution de modèles de style WordPress et un accès aux bases de données asynchrones avec SQLAlchemy","de":"Skrift ist ein asynchrones Python-CMS, das eine WordPress-ähnliche Template-Auflösung und asynchronen Datenbankzugriff mit SQLAlchemy bietet","pt":"Skrift é um CMS leve e assíncrono em Python, projetado para desenvolvedores. Oferece resolução de templates estilo WordPress e acesso a banco de dados async com SQLAlchemy.","ru":"Skrift - легкий асинхронный CMS на Python, предназначенный для разработчиков. Предоставляет разрешение шаблонов в стиле WordPress и асинхронный доступ к базе данных с помощью SQLAlchemy.","ar":"Skrift هو نظام إدارة المحتوى الخفيف والموازي في Python، مصمم لملائم المطورين. يقدم حلول قوالب الشكل والوصول إلى قاعدة البيانات بشكل متوازي باستخدام SQLAlchemy."},"seo":{"title":{"en":"Skrift: Async Python CMS Setup Guide | AI Agent Skill","zh":"SkriftSetup Guide：轻量级Python CMS开发","ja":"Skrift設定ガイド：軽量級Python CMS開発","ko":"Skrift설치 가이드: 경량급 Python CMS 개발","es":"Guía de configuración de Skrift: CMS de Python asíncrono","fr":"Guide de mise en place de Skrift: CMS Python asynchrone","de":"Skrift-Setup-Anleitung: Asynchrones Python-CMS","pt":"Guia de Configuração Skrift: Desenvolvimento de CMS com L...","ru":"ИИ Агент Skrift: Руководство по настройке CMS на основе L...","ar":"دليل إعداد Skrift: تطوير نظام إدارة المحتوى باستخدام Lite..."},"description":{"en":"Unlock the power of Skrift, a lightweight async Python CMS for Smarter Dev community. Discover how to configure and extend Skrift with WordPress-style templa...","zh":"了解Skrift的特点和功能，包括Litestar、WordPress风格模板解析、钩子/过滤器扩展系统和SQLAlchemy异步数据库访问","ja":"Skriftの特徴と機能について学びます。Litestar、WordPressスタイルのテンプレート解析、フック/フィルターエクステンションシステム、SQLAlchemyアシンクロナスデータベースアクセスなど","ko":"Skrift의 특징과 기능을 알아보세요. Litestar, WordPress 스타일 템플릿 해석, 후크/필터 확장 시스템, SQLAlchemy 비동기 데이터베이스 액세스 등","es":"Descubre cómo configurar Skrift, un CMS de Python asíncrono con resolución de plantillas de estilo WordPress y acceso a bases de datos asincrónicas con SQLAl...","fr":"Découvrez comment configurer Skrift, un CMS Python asynchrone avec une résolution de modèles de style WordPress et un accès aux bases de données asynchrones ...","de":"Erfahren Sie, wie Sie Skrift konfigurieren, ein asynchrones Python-CMS mit WordPress-ähnlicher Template-Auflösung und asynchronem Datenbankzugriff mit SQLAlc...","pt":"Aprenda a configurar o Skrift, um CMS leve e assíncrono em Python, com resolução de templates estilo WordPress e acesso a banco de dados async com SQLAlchemy","ru":"Изучите, как настроить Skrift, легкий асинхронный CMS на Python, с разрешением шаблонов в стиле WordPress и асинхронным доступом к базе данных с помощью SQLA...","ar":"تعرف على كيفية إعداد Skrift، نظام إدارة المحتوى الخفيف والموازي في Python، مع حلول قوالب الشكل والوصول إلى قاعدة البيانات بشكل متوازي باستخدام SQLAlchemy"},"definition":{"en":"Skrift is a lightweight async Python CMS featuring Litestar, WordPress-style template resolution, and SQLAlchemy async database access.","zh":"Skrift是一种AI工具，提供轻量级Python CMS开发解决方案","ja":"Skriftは、AIエージェントの一種で、軽量級Python CMS開発ソリューションを提供します","ko":"Skrift는 AI 에이전트 중 하나로 경량급 Python CMS 개발 솔루션을 제공합니다","es":"Skrift es un CMS de Python asíncrono que utiliza Litestar y ofrece características como resolución de plantillas y acceso a bases de datos asincrónicas","fr":"Skrift est un CMS Python asynchrone qui utilise Litestar et propose des fonctionnalités telles que la résolution de modèles et l''accès aux bases de données asynchrones","de":"Skrift ist ein asynchrones Python-CMS, das Litestar verwendet und Funktionen wie Template-Auflösung und asynchronen Datenbankzugriff bietet","pt":"Skrift é um CMS em Python que oferece resolução de templates e acesso a banco de dados async","ru":"Skrift - это CMS на Python, который предоставляет разрешение шаблонов и асинхронный доступ к базе данных","ar":"Skrift هو نظام إدارة المحتوى على Python الذي يقدم حلول قوالب الشكل والوصول إلى قاعدة البيانات بشكل متوازي"},"features":{"en":["WordPress-style template resolution for customizable layouts","Hook/filter extensibility system for seamless integration","SQLAlchemy async database access for efficient data management","Litestar framework for building high-performance applications","Async Python CMS for scalable and concurrent request handling","Configuration via app.yaml file for easy setup and deployment"],"zh":["基于Litestar的轻量级Python CMS","WordPress风格的模板解析","钩子/过滤器扩展系统","SQLAlchemy异步数据库访问","支持异步Python开发"],"ja":["Litestarベースの軽量級Python CMS","WordPressスタイルのテンプレート解析","フック/フィルターエクステンションシステム","SQLAlchemyアシンクロナスデータベースアクセス","非同期Python開発のサポート"],"ko":["Litestar 기반의 경량급 Python CMS","WordPress 스타일의 템플릿 해석","후크/필터 확장 시스템","SQLAlchemy 비동기 데이터베이스 액세스","비동기 Python 개발 지원"],"es":["Resolución de plantillas de estilo WordPress","Acceso a bases de datos asincrónicas con SQLAlchemy","Sistema de extensiones con hooks y filtros","Desarrollo asíncrono con Litestar","Soporte para controladores y modelos personalizados","Integración con Discord y otros servicios"],"fr":["Résolution de modèles de style WordPress","Accès aux bases de données asynchrones avec SQLAlchemy","Système d''extensions avec hooks et filtres","Développement asynchrone avec Litestar","Prise en charge de contrôleurs et de modèles personnalisés","Intégration avec Discord et d''autres services"],"de":["WordPress-ähnliche Template-Auflösung","Asynchroner Datenbankzugriff mit SQLAlchemy","Erweiterungssystem mit Hooks und Filtern","Asynchrones Entwicklung mit Litestar","Unterstützung für benutzerdefinierte Controller und Modelle","Integration mit Discord und anderen Diensten"],"pt":["Desenvolvimento de CMS com Litestar","Resolução de templates estilo WordPress","Acesso a banco de dados async com SQLAlchemy","Sistema de extensibilidade com hooks e filters","Controle de configuração com app.yaml"],"ru":["Разработка CMS на основе Litestar","Разрешение шаблонов в стиле WordPress","Асинхронный доступ к базе данных с помощью SQLAlchemy","Система расширения с помощью хуков и фильтров","Управление конфигурацией с помощью app.yaml"],"ar":["تطوير نظام إدارة المحتوى باستخدام Litestar","حلول قوالب الشكل بالشكل المعتاد في WordPress","الوصول إلى قاعدة البيانات بشكل متوازي باستخدام SQLAlchemy","نظام التوسعة باستخدام الحلقات والمرشحات","التحكم في الإعدادات باستخدام app.yaml"]},"keywords":{"en":["how to use Skrift","Skrift vs Litestar","Skrift install guide","what is Skrift","Skrift alternative CMS","Skrift setup tutorial","Skrift async Python","Skrift Smarter Dev community","Skrift SQLAlchemy database"],"zh":["Skrift","轻量级Python CMS","Litestar","WordPress风格模板解析","钩子/过滤器扩展系统","SQLAlchemy异步数据库访问","Python开发","AI工具","CMS开发"],"ja":["Skrift","軽量級Python CMS","Litestar","WordPressスタイルのテンプレート解析","フック/フィルターエクステンションシステム","SQLAlchemyアシンクロナスデータベースアクセス","Python開発","AIエージェント","CMS開発"],"ko":["Skrift","경량급 Python CMS","Litestar","WordPress 스타일 템플릿 해석","후크/필터 확장 시스템","SQLAlchemy 비동기 데이터베이스 액세스","Python 개발","AI 에이전트","CMS 개발"],"es":["Skrift","CMS de Python asíncrono","Litestar","SQLAlchemy","Resolución de plantillas","Acceso a bases de datos asincrónicas","Desarrollo de CMS","Herramientas de desarrollo de Python","Integración con Discord"],"fr":["Skrift","CMS Python asynchrone","Litestar","SQLAlchemy","Résolution de modèles","Accès aux bases de données asynchrones","Développement de CMS","Outils de développement Python","Intégration avec Discord"],"de":["Skrift","Asynchrones Python-CMS","Litestar","SQLAlchemy","Template-Auflösung","Asynchroner Datenbankzugriff","CMS-Entwicklung","Python-Entwicklungstools","Integration mit Discord"],"pt":["Skrift","CMS Python","Litestar","WordPress estilo","SQLAlchemy","Desenvolvimento de CMS","Acesso a banco de dados async","Sistema de extensibilidade"],"ru":["Skrift","CMS на Python","Litestar","WordPress стиль","SQLAlchemy","Разработка CMS","Асинхронный доступ к базе данных","Система расширения"],"ar":["Skrift","نظام إدارة المحتوى على Python","Litestar","الشكل المعتاد في WordPress","SQLAlchemy","تطوير نظام إدارة المحتوى","الوصول إلى قاعدة البيانات بشكل متوازي","نظام التوسعة"]}},"owner":"Smarter-Dev","repo":"smarter-dev","repoPath":"Smarter-Dev/smarter-dev","stars":1,"forks":2,"updatedAt":"2026-03-07T03:15:18Z","topics":[],"category":"community","skillMd":{"name":"skrift","description":"Help working with Skrift CMS codebases - a Python async CMS built on Litestar with WordPress-style conventions. Use for creating controllers, models, hooks, pages, and templates.","bodyPreview":"# Skrift CMS Development Guide\n\nSkrift is a lightweight async Python CMS built on Litestar, featuring WordPress-style template resolution, a hook/filter extensibility system, and SQLAlchemy async database access.\n\n## Current Project State\n\n**Configuration:**\n!`cat app.yaml 2>/dev/null || echo \"No app.yaml found\"`\n\n**Controllers:**\n!`ls skrift/controllers/*.py 2>/dev/null | head -10`\n\n**Models:**\n!`ls skrift/db/models/*.py 2>/dev/null | head -10`\n\n**Services:**\n!`ls skrift/db/services/*.py 2>/dev","body":"# Skrift CMS Development Guide\n\nSkrift is a lightweight async Python CMS built on Litestar, featuring WordPress-style template resolution, a hook/filter extensibility system, and SQLAlchemy async database access.\n\n## Current Project State\n\n**Configuration:**\n!`cat app.yaml 2>/dev/null || echo \"No app.yaml found\"`\n\n**Controllers:**\n!`ls skrift/controllers/*.py 2>/dev/null | head -10`\n\n**Models:**\n!`ls skrift/db/models/*.py 2>/dev/null | head -10`\n\n**Services:**\n!`ls skrift/db/services/*.py 2>/dev/null | head -10`\n\n**Templates:**\n!`ls templates/*.html 2>/dev/null | head -10 || echo \"No custom templates\"`\n\n## Quick Reference\n\n### Core Architecture\n\n- **Framework**: Litestar (async Python web framework)\n- **Database**: SQLAlchemy async with Advanced Alchemy\n- **Templates**: Jinja2 with WordPress-style template hierarchy + optional themes (see `/skrift-theming`)\n- **Config**: YAML (app.yaml) + environment variables (.env)\n- **Auth**: OAuth providers + role-based permissions (see `/skrift-auth`)\n- **Forms**: Pydantic-backed with CSRF (see `/skrift-forms`)\n- **Hooks**: WordPress-style extensibility (see `/skrift-hooks`)\n- **Notifications**: Real-time SSE with pluggable backends (see `/skrift-notifications`)\n- **Observability**: Optional Logfire tracing and structured logging (see `/skrift-observability`)\n- **OAuth2 Server**: Hub/spoke identity federation (see `/skrift-oauth2`)\n\n### AppDispatcher Pattern\n\n```\n                    ┌─────────────────────────────┐\n                    │      AppDispatcher          │\n                    │  (skrift/asgi.py)           │\n                    └─────────────┬───────────────┘\n                                  │\n              ┌───────────────────┼───────────────────┐\n              │                   │                   │\n              ▼                   ▼                   ▼\n     ┌────────────────┐   ┌────────────┐   ┌────────────────┐\n     │   Setup App    │   │  /static   │   │   Main App     │\n     │  (/setup/*)    │   │   Files    │   │  (everything)  │\n     └────────────────┘   └────────────┘   └────────────────┘\n```\n\n- `setup_locked=False`: /setup/* routes active, checks DB for setup completion\n- `setup_locked=True`: All traffic goes to main app, /setup/* returns 404\n- Main app is lazily created after setup completes (no restart needed)\n- Entry point: `skrift.asgi:app` (created by `create_dispatcher()`)\n\n### Key Files\n\n| File | Purpose |\n|------|---------|\n| `skrift/asgi.py` | AppDispatcher, app creation, middleware loading |\n| `skrift/config.py` | Settings management, YAML config loading |\n| `skrift/cli.py` | CLI commands (serve, secret, db) |\n| `skrift/middleware/` | Security headers middleware |\n| `skrift/lib/hooks.py` | WordPress-like hook/filter system |\n| `skrift/lib/template.py` | Template resolution with fallbacks and theme support |\n| `skrift/lib/theme.py` | Theme discovery, metadata parsing |\n| `skrift/db/base.py` | SQLAlchemy Base class (UUIDAuditBase) |\n| `skrift/forms/` | Form system (CSRF, validation, rendering) |\n| `skrift/auth/` | Guards, roles, permissions |\n| `skrift/lib/notifications.py` | Real-time notification service (SSE) |\n| `skrift/lib/notification_backends.py` | Pluggable backends (InMemory, Redis, PgNotify) |\n| `skrift/lib/observability.py` | Logfire observability facade (tracing, logging) |\n| `skrift/db/models/notification.py` | StoredNotification model for DB-backed backends |\n\n### Configuration System\n\n```\n.env (loaded early) → app.yaml (with $VAR interpolation) → Settings (Pydantic)\n```\n\nEnvironment-specific: `app.yaml` (production), `app.dev.yaml` (development), `app.test.yaml` (testing). Set via `SKRIFT_ENV`.\n\n```yaml\ndb:\n  url: $DATABASE_URL\n  pool_size: 5\n  echo: false\n  schema: myschema  # optional; PostgreSQL only — prefixes all tables\n\nauth:\n  redirect_base_url: \"https://example.com\"\n  providers:\n    google:\n      client_id: $GOOGLE_CLIENT_ID\n      client_secret: $GOOGLE_CLIENT_SECRET\n      scopes: [\"openid\", \"email\", \"profile\"]\n\nsession:\n  cookie_domain: null\n\ntheme: my-theme  # default theme (overridden by admin UI)\n\ncontrollers:\n  - skrift.controllers.auth:AuthController\n  - skrift.controllers.web:WebController\n\nredis:\n  url: $REDIS_URL\n  prefix: \"myapp\"\n\nnotifications:\n  backend: \"\"  # empty = InMemoryBackend; or \"module:ClassName\"\n\nlogfire:\n  enabled: true\n  service_name: my-site\n  console: true  # prints spans to console\n\nsecurity_headers:\n  content_security_policy: \"default-src ''self''\"\n\nmiddleware:\n  - myapp.middleware:create_logging_middleware\n```\n\n### CLI Commands\n\n```bash\nskrift serve --reload --port 8080\nskrift serve --subdomain blog --port 8081  # serve single subdomain site\nskrift secret --write .env\nskrift db upgrade head\nskrift db downgrade -1\nskrift db revision -m \"desc\" --autogenerate\n```\n\n## Database Layer\n\nAll models inherit from `skrift.db.base.Base` (provides `id` UUID, `created_at`, `updated_at`):\n\n```python\nfrom sqlalchemy import String, Text\nfrom sqlalchemy.orm import Mapped, mapped_column\nfrom skrift.db.base import Base\n\nclass MyModel(Base):\n    __tablename__ = \"my_models\"\n    name: Mapped[str] = mapped_column(String(255), nullable=False)\n    description: Mapped[str | None] = mapped_column(Text, nullable=True)\n```\n\n### Core Models\n\n| Model | Table | Purpose |\n|-------|-------|---------|\n| `User` | `users` | User accounts |\n| `OAuthAccount` | `oauth_accounts` | Linked OAuth providers (`access_token`, `refresh_token`) |\n| `Role` | `roles` | Permission roles |\n| `Page` | `pages` | Content pages |\n| `PageRevision` | `page_revisions` | Content history |\n| `Setting` | `settings` | Key-value site settings |\n| `StoredNotification` | `stored_notifications` | Persistent notifications with `mode` column (Redis/PgNotify backends) |\n\nSessions injected via `db_session: AsyncSession` parameter in handlers.\n\n### Content Negotiation\n\nPage views support `Accept: text/markdown` — returns raw `page.content` instead of rendered HTML. Works for all page types (WebController and page type factory routes).\n\n## Creating a Controller\n\n```python\nfrom litestar import Controller, get, post\nfrom litestar.response import Template as TemplateResponse\nfrom sqlalchemy.ext.asyncio import AsyncSession\n\nclass MyController(Controller):\n    path = \"/my-path\"\n\n    @get(\"/\")\n    async def list_items(self, db_session: AsyncSession) -> TemplateResponse:\n        items = await item_service.list_items(db_session)\n        return TemplateResponse(\"items/list.html\", context={\"items\": items})\n```\n\nRegister in `app.yaml`:\n```yaml\ncontrollers:\n  - myapp.controllers:MyController\n```\n\n## Creating a Service\n\n```python\nfrom sqlalchemy import select\nfrom sqlalchemy.ext.asyncio import AsyncSession\n\nasync def get_by_id(db_session: AsyncSession, item_id: UUID) -> MyModel | None:\n    result = await db_session.execute(select(MyModel).where(MyModel.id == item_id))\n    return result.scalar_one_or_none()\n\nasync def create_item(db_session: AsyncSession, name: str) -> MyModel:\n    item = MyModel(name=name)\n    db_session.add(item)\n    await db_session.commit()\n    await db_session.refresh(item)\n    return item\n```\n\n## Template Resolution\n\nWordPress-style hierarchy with fallbacks and optional theme support:\n\n```python\nfrom skrift.lib.template import Template\n\n# Tries: page-about.html -> page.html\ntemplate = Template(\"page\", \"about\")\n\n# Tries: post-news-2024.html -> post-news.html -> post.html\ntemplate = Template(\"post\", \"news\", \"2024\")\n\n# Without theme\nreturn template.render(TEMPLATE_DIR, page=page)\n\n# With theme (searches theme dirs first)\nreturn template.render(TEMPLATE_DIR, theme_name=\"my-theme\", page=page)\n```\n\nSearch order (with active theme):\n1. `themes/<active>/templates/` (active theme)\n2. `./templates/` (project root — user overrides)\n3. `skrift/templates/` (package — defaults)\n\nTemplate globals: `now()`, `site_name()`, `site_tagline()`, `site_copyright_holder()`, `site_copyright_start_year()`, `active_theme()`, `themes_available()`. Filter: `markdown`.\n\nFor full theming details, see `/skrift-theming`.\n\n## Middleware\n\n```python\nfrom litestar.middleware import AbstractMiddleware\n\nclass LoggingMiddleware(AbstractMiddleware):\n    async def __call__(self, scope, receive, send):\n        if scope[\"type\"] == \"http\":\n            print(f\"Request: {scope[''method'']} {scope[''path'']}\")\n        await self.app(scope, receive, send)\n\ndef create_logging_middleware(app):\n    return LoggingMiddleware(app=app)\n```\n\nRegister in `app.yaml`:\n```yaml\nmiddleware:\n  - myapp.middleware:create_logging_middleware\n  - factory: myapp.middleware:create_rate_limit\n    kwargs:\n      requests_per_minute: 100\n```\n\n## Security\n\n`skrift/middleware/security.py` — ASGI middleware injecting CSP, HSTS, X-Frame-Options, etc. Configured via `SecurityHeadersConfig`. Pre-encoded at creation time. HSTS excluded in debug mode.\n\nStatic files: `/static/` with same priority as templates (project root, then package).\n\n## Error Handling\n\nCustom exception handlers in `skrift/lib/exceptions.py`. Templates: `error.html`, `error-404.html`, `error-500.html`.\n\n## Testing\n\n```python\nfrom litestar.testing import TestClient\n\nasync def test_list_items(client, db_session):\n    item = await item_service.create(db_session, name=\"Test\")\n    response = client.get(\"/items\")\n    assert response.status_code == 200\n    assert \"Test\" in response.text\n```\n\n## Related Skills\n\nFor deep-dive guidance on specific subsystems:\n- **`/skrift-hooks`** — Hook/filter extensibility, custom hook points, built-in hooks\n- **`/skrift-forms`** — Form system, CSRF, field customization, template rendering\n- **`/skrift-auth`** — OAuth flow, guard system, roles, permissions\n- **`/skrift-theming`** — Theme discovery, template/static resolution, per-request switching, RESOLVE_THEME hook\n- **`/skrift-notifications`** — SSE protocol, pluggable backends, group keys, dismiss patterns\n- **`/skrift-observability`** — Logfire integration, structured tracing, instrumentation\n- **`/skrift-oauth2`** — OAuth2 Authorization Server, hub/spoke identity federation, Skrift provider\n"},"lastSynced":"2026-03-07T12:51:19.979Z","agentAnalysis":{"suitability":{"en":"Ideal for Python-based AI Agents requiring advanced async content management capabilities with Litestar and SQLAlchemy","zh":"适用于需要使用Litestar和SQLAlchemy进行高级异步内容管理的Python基于AI Agents","ja":"LitestarとSQLAlchemyを使用した高度な非同期コンテンツ管理機能を必要とするPythonベースのAIエージェントに適しています","ko":"Litestar와 SQLAlchemy를 사용한 고급 비동기 콘텐츠 관리 기능을 필요로 하는 Python 기반 AI 에이전트에 적합합니다","es":"Ideal para agentes de inteligencia artificial basados en Python que requieren capacidades de administración de contenido asíncrono avanzadas con Litestar y SQLAlchemy","fr":"Idéal pour les agents d''intelligence artificielle basés sur Python nécessitant des capacités de gestion de contenu asynchrone avancées avec Litestar et SQLAlchemy","de":"Ideal für Python-basierte KI-Agents, die erweiterte asynchrone Inhaltsverwaltungsfunktionen mit Litestar und SQLAlchemy benötigen","pt":"Ideal para Agentes de IA baseados em Python que requerem capacidades avançadas de gerenciamento de conteúdo assíncrono com Litestar e SQLAlchemy","ru":"Идеально для агентов ИИ на основе Python, требующих расширенных возможностей асинхронного управления контентом с Litestar и SQLAlchemy","ar":"مثالي لعميل الوكيل الذكي المبني على بيثون الذي يتطلب إمكانيات متقدمة لإدارة المحتوى غير المتزامن مع Litestar و SQLAlchemy"},"recommendation":{"en":"Empowers agents to leverage WordPress-style template resolution, hook/filter extensibility systems, and async database access with SQLAlchemy, streamlining content management and customization through Python","zh":"赋予代理使用WordPress风格的模板解析、hook/filter可扩展系统和SQLAlchemy的异步数据库访问，通过Python简化内容管理和自定义","ja":"WordPressスタイルのテンプレート解決、hook/filter拡張システム、およびSQLAlchemyの非同期データベースアクセスを使用してエージェントを強化し、Pythonを介してコンテンツ管理とカスタマイズを容易にします","ko":"WordPress 스타일의 템플릿 해석, hook/filter 확장 시스템 및 SQLAlchemy의 비동기 데이터베이스 액세스를 사용하여 에이전트를 강화하여 Python을 통해 콘텐츠 관리 및 사용자 정의를 간소화합니다","es":"Permite a los agentes aprovechar la resolución de plantillas estilo WordPress, sistemas de extensibilidad de ganchos/filtros y acceso a bases de datos asíncronas con SQLAlchemy, lo que simplifica la administración de contenido y la personalización a través de Python","fr":"Permet aux agents d''exploiter la résolution de modèles de style WordPress, les systèmes d''extensibilité de hooks/filtres et l''accès aux bases de données asynchrone avec SQLAlchemy, ce qui rationalise la gestion de contenu et la personnalisation via Python","de":"Ermöglicht es Agents, WordPress-Style-Vorlagenauflösung, Hook/Filter-Erweiterungssysteme und asynchrone Datenbankzugriffe mit SQLAlchemy zu nutzen, wodurch die Inhaltsverwaltung und Anpassung durch Python rationalisiert wird","pt":"Habilita os agentes a aproveitar a resolução de modelos de estilo WordPress, sistemas de extensibilidade de ganchos/filtros e acesso assíncrono ao banco de dados com SQLAlchemy, simplificando o gerenciamento de conteúdo e personalização por meio do Python","ru":"Наделяет агентов возможностью использовать систему разрешения шаблонов в стиле WordPress, системы расширения крючков/фильтров и асинхронный доступ к базе данных с помощью SQLAlchemy, оптимизируя управление контентом и настройку через Python","ar":"يمنح الوكلاء إمكانية استخدام نظام حل النماذج على طريقة ووردبريس، ونظم التمديد لتقنيات الإشارة والمرشحات، والوصول غير المتزامن إلى قاعدة البيانات مع SQLAlchemy، وبذلك يبسط إدارة المحتوى والتخصيص من خلال بيثون"},"useCases":{"en":["Developing custom CMS solutions with Litestar","Extending Skrift with hooks and filters for tailored functionality","Managing async database interactions with SQLAlchemy"],"zh":["使用Litestar开发自定义CMS解决方案","使用hook和filter扩展Skrift以实现定制功能","使用SQLAlchemy管理异步数据库交互"],"ja":["Litestarを使用してカスタムCMSソリューションを開発する","hookとfilterを使用してSkriftを拡張してカスタマイズされた機能を実現する","SQLAlchemyを使用して非同期データベースのやり取りを管理する"],"ko":["Litestar를 사용하여 맞춤형 CMS 솔루션 개발","hook 및 filter를 사용하여 Skrift 확장 및 맞춤형 기능 구현","SQLAlchemy를 사용하여 비동기 데이터베이스 상호 작용 관리"],"es":["Desarrollar soluciones de CMS personalizadas con Litestar","Ampliar Skrift con ganchos y filtros para funcionalidades personalizadas","Administrar interacciones de bases de datos asíncronas con SQLAlchemy"],"fr":["Développer des solutions de CMS personnalisées avec Litestar","Étendre Skrift avec des hooks et des filtres pour des fonctionnalités personnalisées","Gérer les interactions de bases de données asynchrones avec SQLAlchemy"],"de":["Entwickeln von benutzerdefinierten CMS-Lösungen mit Litestar","Erweitern von Skrift mit Hooks und Filtern für maßgeschneiderte Funktionalitäten","Verwalten von asynchronen Datenbankinteraktionen mit SQLAlchemy"],"pt":["Desenvolver soluções de CMS personalizadas com Litestar","Estender Skrift com ganchos e filtros para funcionalidades personalizadas","Gerenciar interações de banco de dados assíncronas com SQLAlchemy"],"ru":["Разработка индивидуальных решений CMS с Litestar","Расширение Skrift с помощью крючков и фильтров для индивидуальной функциональности","Управление асинхронными взаимодействиями с базой данных с помощью SQLAlchemy"],"ar":["إنشاء حلول إدارة المحتوى المخصصة مع Litestar","تمديد Skrift باستخدام تقنيات الإشارة والمرشحات من أجل وظيفة مخصصة","إدارة التفاعلات غير المتزامنة لقاعدة البيانات مع SQLAlchemy"]},"limitations":{"en":["Requires Python environment","Litestar and SQLAlchemy dependencies","Async database access limitations apply"],"zh":["需要Python环境","依赖Litestar和SQLAlchemy","异步数据库访问限制适用"],"ja":["Python環境が必要","LitestarとSQLAlchemyに依存","非同期データベースアクセス制限が適用される"],"ko":["Python 환경 필요","Litestar 및 SQLAlchemy 종속성","비동기 데이터베이스 액세스 제한 적용"],"es":["Requiere entorno de Python","Dependencias de Litestar y SQLAlchemy","Se aplican limitaciones de acceso a bases de datos asíncronas"],"fr":["Nécessite un environnement Python","Dépendances de Litestar et SQLAlchemy","Des limitations d''accès aux bases de données asynchrones s''appliquent"],"de":["Benötigt Python-Umgebung","Litestar- und SQLAlchemy-Abhängigkeiten","Asynchrone Datenbankzugriffsbeschränkungen sind anwendbar"],"pt":["Requer ambiente Python","Dependências de Litestar e SQLAlchemy","Limitações de acesso ao banco de dados assíncrono se aplicam"],"ru":["Требуется среда Python","Зависимости Litestar и SQLAlchemy","Применяются ограничения асинхронного доступа к базе данных"],"ar":["يتطلب بيئة بيثون","اعتماديات Litestar و SQLAlchemy","تطبق قيود الوصول غير المتزامن إلى قاعدة البيانات"]},"version":4},"contentHash":"df675d2d62ead0e3d671e6dda6f13aa783511053a6f9062f471c6dad16d022cf","qualityScore":36}');
