INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('FlexNetOS/ripple-env/Kubernetes & Container Orchestration', 'Kubernetes & Container Orchestration', 'FlexNetOS', 'ripple-env', 'community', 'Kubernetes & Container Orchestration FlexNetOS ripple-env community Kubernetes & Container Orchestration helps developers deploy, scale, and manage containerized applications. It benefits DevOps teams and developers working with containerized apps. Kubernetes是一种容器编排平台，用于部署、缩放和管理容器化应用程序 Kubernetesは、コンテナ化されたアプリケーションの展開、スケーリング、管理を自動化するコンテナオーケストレーションプラットフォームです Kubernetes는 컨테이너화된 애플리케이션을 배포, 확장, 관리하는 컨테이너 오케스트레이션 플랫폼입니다 Kubernetes es una plataforma de orquestación de contenedores para implementar, escalar y gestionar aplicaciones contenerizadas Kubernetes est une plateforme d''orchestration de conteneurs pour déployer, mettre à l''échelle et gérer des applications conteneurisées Kubernetes ist eine Container-Orchestrierungsplattform für die Bereitstellung, Skalierung und Verwaltung von contenerisierten Anwendungen O Kubernetes é uma plataforma de orquestração de contêineres para deploy, escalonamento e gerenciamento de aplicações em contêineres. Kubernetes — это платформа оркестрации контейнеров для развертывания, масштабирования и управления контейнерными приложениями. كيوبيرنتس هو منصة لتنسيق الحاويات لتحديث وتصغير وتنظيم التطبيقات في الحاويات Kubernetes & Container Orchestration tutorial how to use Kubernetes & Container Orchestration Kubernetes & Container Orchestration vs Docker Swarm Kubernetes & Container Orchestration setup guide Kubernetes & Container Orchestration installation what is Kubernetes & Container Orchestration Kubernetes & Container Orchestration alternative Kubernetes & Container Orchestration best practices Kubernetes & Container Orchestration for DevOps Kubernetes & Container Orchestration deployment strategies Kubernetes容器编排 容器化应用程序部署 自动化容器管理 Pod和Deployment Service和ConfigMap Secret和Ingress 容器运行时环境 网络和存储管理 安全和认证 Manages ReplicaSets using Deployments Provides network endpoints with Services (svc) Stores sensitive data with Secrets Configures applications using ConfigMaps (cm) Enables external access with Ingress (ing) Deploys and manages containerized applications using Pods (po) Kubernetes & Container Orchestration is a platform for deploying, scaling, and managing containerized applications using resources like Pods, Deployments, and Services.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dohernandez/claude-project-skills-template/claude-md', 'community', 'dohernandez', 'claude-project-skills-template', 'dohernandez/claude-project-skills-template', 'claude-md', 0, 0, 36, '2026-02-24T14:20:23Z', '2026-03-07T03:42:44.826Z', 'c015ee2657b6d214308a42ce938b8f0584b8f5dbb1efccc7aaec4c00cae29fbb', '{"id":"dohernandez/claude-project-skills-template/claude-md","name":"claude-md","description":{"en":"claude-md is a methodology for editing CLAUDE.md files, ensuring they remain concise and structurally sound. It benefits developers and technical writers who need to maintain high-quality documentation.","zh":"claude-md是一种保持文档简洁、结构完整的方法，包括目录结构、自动生成表格和命令行工具","ja":"claude-mdは、ディレクトリ構造、自動生成テーブル、コマンドラインツールなどを含む、文書を簡潔に保つための方法","ko":"claude-md는 문서를 간결하게 유지하고 구조를 완성하는 방법으로, 디렉토리 구조, 자동 생성 테이블 및 명령줄 도구를 포함","es":"claude-md es una metodología para editar archivos markdown de manera concisa y estructurada, incluyendo un linter para garantizar la calidad del código","fr":"claude-md est une méthodologie pour éditer des fichiers markdown de manière concise et structurée, incluant un linter pour assurer la qualité du code","de":"claude-md ist eine Methode zur Bearbeitung von Markdown-Dateien in konciser und strukturierter Weise, einschließlich eines Linters zur Gewährleistung der Codequalität","pt":"O CLAUDE.md é uma metodologia para edição que mantém a concisão e a estrutura. Aprenda a usá-lo com nossas dicas","ru":"CLAUDE.md - это методология для редактирования, которая поддерживает краткость и структуру. Узнайте, как использовать его с нашими советами","ar":"CLAUDE.md هو منهجية لتحرير تحتفظ بالconcisão والهيكل. تعلم كيفية استخدامها مع نصائحنا"},"seo":{"title":{"en":"claude-md: Structured Authoring Setup Guide | AI Agent Skill","zh":"claude-md Setup Guide: AI工具最佳实践","ja":"claude-md設定ガイド: AIエージェントのベストプラクティス","ko":"claude-md 설정 가이드: AI 에이전트 개발 최적화","es":"Guía de configuración de claude-md para desarrolladores","fr":"Configurer claude-md : Meilleures pratiques pour les déve...","de":"Einrichtung von claude-md: Entwicklerhandbuch und beste P...","pt":"Guia de Configuração do CLAUDE.md: Melhores Práticas para...","ru":"Настройка CLAUDE.md: Руководство по Лучшим Практикам для ...","ar":"دليل إعداد CLAUDE.md: أفضل الممارسات للعاملين في مجال الذ..."},"description":{"en":"Discover how to keep your CLAUDE.md concise and high-signal with our expert guide, featuring lint-claude-md.sh and skill.yaml best practices.","zh":"了解claude-md的编写方法和最佳实践，包括目录结构、自动生成表格和命令行工具","ja":"claude-mdの書き方とベストプラクティスを学ぶ、ディレクトリ構造、自動生成テーブル、コマンドラインツールなど","ko":"claude-md 작성 방법과 최적화된 개발 환경 구성을 위한베스트 프랙티스, 디렉토리 구조, 자동 생성 테이블 및 명령줄 도구","es":"Aprende a configurar y utilizar claude-md de manera efectiva con nuestra guía para desarrolladores, incluyendo consejos sobre estructura y linter","fr":"Découvrez comment configurer et utiliser claude-md avec succès grâce à notre guide dédié aux développeurs, incluant des conseils sur la structure et le linter","de":"Erfahren Sie, wie Sie claude-md effektiv konfigurieren und verwenden können, mit unserem Entwicklerhandbuch, das Tipps zur Struktur und zum Linter enthält","pt":"Aprenda a configurar o CLAUDE.md com nossas melhores práticas e melhore a estrutura do seu projeto com ferramentas como o linter","ru":"Узнайте, как настроить CLAUDE.md с помощью наших лучших практик и улучшите структуру вашего проекта с помощью инструментов, таких как линтер","ar":"تعلم كيفية إعداد CLAUDE.md باستخدام أفضل الممارسات لدينا و تحسين هيكل مشروعك باستخدام أدوات مثل لينتر"},"definition":{"en":"claude-md is a set of guidelines for authoring CLAUDE.md files, focusing on concise and high-signal content with a structured approach.","zh":"claude-md是一种保持文档简洁、结构完整的方法","ja":"claude-mdは、文書を簡潔に保つための方法","ko":"claude-md는 문서를 간결하게 유지하고 구조를 완성하는 방법","es":"claude-md es una herramienta de autoría de markdown que ayuda a los desarrolladores a crear contenido de alta calidad","fr":"claude-md est un outil d''authoring de markdown qui aide les développeurs à créer du contenu de haute qualité","de":"claude-md ist ein Werkzeug für die Erstellung von Markdown-Inhalten, das Entwicklern hilft, hochwertigen Inhalt zu erstellen","pt":"CLAUDE.md é uma metodologia de edição que visa manter a concisão e a estrutura em projetos de desenvolvimento","ru":"CLAUDE.md - это методология редактирования, целью которой является поддержание краткости и структуры в проектах разработки","ar":"CLAUDE.md هو منهجية لتحرير تهدف إلى الحفاظ على Concisão والهيكل في مشاريع التطوير"},"features":{"en":["Enforces a structured approach using Title, behavioral, and dirs-only structure","Utilizes lint-claude-md.sh as a safety net for quantifiable rules","Generates auto-gen tables for easy reference","Supports commands and conventions for consistent documentation","Keeps reference material organized in docs"],"zh":["目录结构优化","自动生成表格","命令行工具集成","文档简洁性保证","结构完整性检查","lint-claude-md.sh安全网"],"ja":["ディレクトリ構造最適化","自動生成テーブル","コマンドラインツール統合","文書簡潔性保証","構造完全性チェック","lint-claude-md.sh安全網"],"ko":["디렉토리 구조 최적화","자동 생성 테이블","명령줄 도구 통합","문서 간결성 보장","구조 완전성 검사","lint-claude-md.sh 안전망"],"es":["Estructura de directorios simplificada","Tabla de contenido automática","Comandos personalizados","Convenciones de nombramiento claras","Linter para garantizar la calidad del código","Integración con herramientas de desarrollo"],"fr":["Structure de répertoire simplifiée","Table des matières automatique","Commandes personnalisées","Conventions de nommage claires","Linter pour assurer la qualité du code","Intégration avec les outils de développement"],"de":["Vereinfachte Verzeichnisstruktur","Automatische Inhaltsverzeichnis","Benutzerdefinierte Befehle","Klare Benennungskonventionen","Linter zur Gewährleistung der Codequalität","Integration mit Entwicklungstools"],"pt":["Metodologia de edição concisa e estruturada","Uso de linter para garantir a qualidade do código","Estrutura de diretórios simplificada","Tabela de comandos automática","Convenções de codificação claras"],"ru":["Методология редактирования, поддерживающая краткость и структуру","Использование линтера для обеспечения качества кода","Упрощенная структура директорий","Автоматическая таблица команд","Ясные конвенции кодирования"],"ar":["منهجية تحرير تحتفظ بالconcisão والهيكل","استخدام لينتر لضمان جودة الكود","هيكل مجلدات مبسط","جدول أوامر 자동","اتفاقيات ترميز واضحة"]},"keywords":{"en":["how to use claude-md","what is claude-md","claude-md alternative","claude-md setup guide","claude-md install","claude-md vs markdown","structured authoring","CLAUDE.md best practices","lint-claude-md.sh tutorial"],"zh":["claude-md","AI工具","文档最佳实践","目录结构优化","自动生成表格","命令行工具集成","lint-claude-md.sh","开发环境配置"],"ja":["claude-md","AIエージェント","文書ベストプラクティス","ディレクトリ構造最適化","自動生成テーブル","コマンドラインツール統合","lint-claude-md.sh","開発環境構成"],"ko":["claude-md","AI 에이전트","문서 개발 최적화","디렉토리 구조 최적화","자동 생성 테이블","명령줄 도구 통합","lint-claude-md.sh","개발 환경 구성"],"es":["claude-md","herramientas de desarrollo","markdown","linter","estructura de directorios","tabla de contenido","comandos personalizados","convenciones de nombramiento","calidad del código","desarrollo de software"],"fr":["claude-md","outils de développement","markdown","linter","structure de répertoire","table des matières","commandes personnalisées","conventions de nommage","qualité du code","développement de logiciels"],"de":["claude-md","Entwicklungstools","Markdown","Linter","Verzeichnisstruktur","Inhaltsverzeichnis","benutzerdefinierte Befehle","Benennungskonventionen","Codequalität","Softwareentwicklung"],"pt":["CLAUDE.md","metodologia de edição","linter","desenvolvimento de software","concisão","estrutura","ferramentas de desenvolvimento","melhores práticas"],"ru":["CLAUDE.md","методология редактирования","линтер","разработка программного обеспечения","краткость","структура","инструменты разработки","лучшие практики"],"ar":["CLAUDE.md","منهجية تحرير","لينتر","تطوير البرمجيات","concisão","هيكل","أدوات التطوير","أفضل الممارسات"]}},"owner":"dohernandez","repo":"claude-project-skills-template","repoPath":"dohernandez/claude-project-skills-template","stars":0,"forks":0,"updatedAt":"2026-02-24T14:20:23Z","topics":[],"category":"community","skillMd":{"name":"claude-md","description":"Methodology for authoring and maintaining CLAUDE.md. Enforces brevity, relevance, and structure.","bodyPreview":"# CLAUDE.md Authoring\n\n## Purpose\n\nMethodology for editing CLAUDE.md that keeps it concise, high-signal, and structurally sound. The guide (patterns/anti-patterns in `skill.yaml`) is the primary value; the linter (`lint-claude-md.sh`) is a safety net for quantifiable rules.\n\n## Quick Reference\n\n- **Target:** <120 lines, 80% relevance per line\n- **Structure:** Title, behavioral, \"Built with:\", dirs-only structure, auto-gen table, commands, conventions\n- **Rule:** Reference material lives in `docs","body":"# CLAUDE.md Authoring\n\n## Purpose\n\nMethodology for editing CLAUDE.md that keeps it concise, high-signal, and structurally sound. The guide (patterns/anti-patterns in `skill.yaml`) is the primary value; the linter (`lint-claude-md.sh`) is a safety net for quantifiable rules.\n\n## Quick Reference\n\n- **Target:** <120 lines, 80% relevance per line\n- **Structure:** Title, behavioral, \"Built with:\", dirs-only structure, auto-gen table, commands, conventions\n- **Rule:** Reference material lives in `docs/` — CLAUDE.md links to it\n\n```bash\ntask docs:lint-claude-md    # Validate CLAUDE.md structure\n```\n\n## Key Principle\n\nEvery line in CLAUDE.md must be useful in 80%+ of sessions. If it''s reference material, move it to `docs/` and link. If Claude can discover it with tools, omit it.\n\n## Automation\n\nSee `skill.yaml` for patterns, anti-patterns, and editing procedure.\nSee `collaboration.yaml` for boundaries with `docs-refresh`.\nSee `sharp-edges.yaml` for common pitfalls.\n"},"lastSynced":"2026-03-07T03:42:44.826Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing structured documentation editing with CLAUDE.md files","zh":"非常适合需要使用结构化文档编辑的技术写作代理，特别是编辑CLAUDE.md文件","ja":"技術文書エージェントが構造化された文書編集を必要とする場合に最適で、特にCLAUDE.mdファイルの編集に適しています","ko":"기술 작성 에이전트가 구조화된 문서 편집을 필요한 경우에 완벽하며, 특히 CLAUDE.md 파일 편집에 적합합니다","es":"Perfecto para agentes de escritura técnica que necesitan edición de documentación estructurada con archivos CLAUDE.md","fr":"Parfait pour les agents de rédaction technique ayant besoin d''une édition de documentation structurée avec des fichiers CLAUDE.md","de":"Perfekt für technische Schreibagenten, die eine strukturierte Dokumentenbearbeitung mit CLAUDE.md-Dateien benötigen","pt":"Perfeito para Agentes de Escrita Técnica que necessitam de edição de documentação estruturada com arquivos CLAUDE.md","ru":"Идеально подходит для агентов технической документации, которым требуется структурированное редактирование документов с файлами CLAUDE.md","ar":"مثالي لعمليات الكتابة الفنية التي تحتاج إلى تحرير وثائق منظم مع ملفات CLAUDE.md"},"recommendation":{"en":"Empowers agents to maintain concise and high-signal documentation using CLAUDE.md methodology, ensuring structurally sound files with features like linting and quantifiable rules, while adhering to specific guidelines such as the 120-line limit and 80% relevance per line","zh":"赋予代理维护简洁和高信号文档的能力，使用CLAUDE.md方法论，确保文件结构合理，具有linting和可量化规则等功能，同时遵守特定的指导方针，例如每行120字符限制和每行80%的相关性","ja":"エージェントが簡潔で高信号の文書を維持できるようにしてくれる、CLAUDE.md方法論を使用し、構造的に整ったファイルを保証する、lintingや量化可能なルールなどの機能を備え、特定のガイドラインに従う、たとえば1行あたり120文字の制限や1行あたり80%の関連性","ko":"에이전트가 간결하고 높은 신호의 문서를 유지할 수 있도록 해 줌, CLAUDE.md 방법론을 사용하여 구조적으로 정리된 파일을 보장하고, linting이나 측정 가능한 규칙 등의 기능을 제공하며, 특정 가이드라인을 준수함, 예를 들어 1행당 120자 제한이나 1행당 80%의 관련성","es":"Habilita a los agentes a mantener documentación concisa y de alta señal de calidad utilizando la metodología CLAUDE.md, asegurando archivos estructuralmente sólidos con características como linting y reglas cuantificables, mientras se adhiere a pautas específicas como el límite de 120 líneas y 80% de relevancia por línea","fr":"Permet aux agents de maintenir une documentation concise et à haute teneur en signal en utilisant la méthodologie CLAUDE.md, garantissant des fichiers structurellement solides avec des fonctionnalités comme linting et règles quantifiables, tout en respectant des lignes directrices spécifiques telles que la limite de 120 lignes et 80% de pertinence par ligne","de":"Ermächtigt die Agenten, präzise und hochwertige Dokumentation mithilfe der CLAUDE.md-Methodik zu pflegen, indem sie strukturell solide Dateien mit Funktionen wie Linting und quantifizierbaren Regeln sicherstellt, während sie spezifischen Richtlinien wie dem 120-Zeilen-Limit und 80% Relevanz pro Zeile entspricht","pt":"Habilita os agentes a manter documentação concisa e de alta qualidade, utilizando a metodologia CLAUDE.md, garantindo arquivos estruturalmente sólidos com recursos como linting e regras quantificáveis, enquanto adere a diretrizes específicas, como o limite de 120 linhas e 80% de relevância por linha","ru":"Наделяет агентов возможностью поддерживать краткую и высококачественную документацию, используя методологию CLAUDE.md, обеспечивая структурированность файлов с функциями, такими как linting и количественные правила, при этом придерживаясь определенных руководящих принципов, таких как ограничение в 120 строк и 80% релевантности на строку","ar":"تمكّن الوكيل من الحفاظ على وثائق مدققة وذات إشارات عالية باستخدام منهجية CLAUDE.md، مما يضمن ملفات صحيحة من الناحية الهيكلية مع ميزات مثل linting و قواعد قابلة للقياس، مع اتباع إرشادات محددة مثل حد 120 سطرا و 80% صلة لكل سطر"},"useCases":{"en":["Editing CLAUDE.md files for clarity and conciseness","Validating documentation structure against predefined patterns and anti-patterns","Enforcing documentation conventions with `lint-claude-md.sh`"],"zh":["编辑CLAUDE.md文件以提高清晰度和简洁性","验证文档结构是否符合预定义的模式和反模式","使用`lint-claude-md.sh`强制执行文档约定"],"ja":["CLAUDE.mdファイルを編集して明確性と簡潔性を高める","文書構造が予め定義されたパターンやアンチパターンに従っているかを検証する","`lint-claude-md.sh`を使用して文書約定を強制する"],"ko":["CLAUDE.md 파일을 편집하여 명확성과 간결성을 높임","문서 구조가 미리 정의된 패턴이나 반 패턴을 따르는지 검증함","`lint-claude-md.sh`를 사용하여 문서 규약을 강제함"],"es":["Edición de archivos CLAUDE.md para claridad y concisión","Validación de la estructura de documentación contra patrones y anti-patrones predefinidos","Aplicación de convenciones de documentación con `lint-claude-md.sh`"],"fr":["Édition de fichiers CLAUDE.md pour clarté et concision","Validation de la structure de documentation contre des modèles et anti-modèles prédéfinis","Application des conventions de documentation avec `lint-claude-md.sh`"],"de":["Bearbeitung von CLAUDE.md-Dateien für Klarheit und Präzision","Validierung der Dokumentenstruktur gegen vordefinierte Muster und Antimuster","Durchsetzung von Dokumentationskonventionen mit `lint-claude-md.sh`"],"pt":["Edição de arquivos CLAUDE.md para clareza e concisão","Validação da estrutura da documentação contra padrões e anti-padrões predefinidos","Aplicação de convenções de documentação com `lint-claude-md.sh`"],"ru":["Редактирование файлов CLAUDE.md для ясности и краткости","Проверка структуры документации на соответствие предопределенным шаблонам и анти-шаблонам","Применение соглашений о документации с помощью `lint-claude-md.sh`"],"ar":["تحرير ملفات CLAUDE.md من أجل وضوح ودقة","التحقق من بنية الوثائق مقابل الأنماط والمعايير المحددة مسبقا","تطبيق اتفاقيات توثيق باستخدام `lint-claude-md.sh`"]},"limitations":{"en":["Requires adherence to CLAUDE.md file structure and guidelines","Limited to editing and validating CLAUDE.md files only"],"zh":["需要遵守CLAUDE.md文件结构和指南","仅限编辑和验证CLAUDE.md文件"],"ja":["CLAUDE.mdファイル構造とガイドラインに従う必要がある","CLAUDE.mdファイルの編集と検証のみに限定される"],"ko":["CLAUDE.md 파일 구조와 가이드라인을 따라야 함","CLAUDE.md 파일 편집과 검증에만 제한됨"],"es":["Requiere adherencia a la estructura y pautas de archivos CLAUDE.md","Limitado a la edición y validación de archivos CLAUDE.md solamente"],"fr":["Nécessite l''adhésion à la structure et aux lignes directrices des fichiers CLAUDE.md","Limité à l''édition et à la validation des fichiers CLAUDE.md uniquement"],"de":["Erfordert die Einhaltung der Struktur und Richtlinien von CLAUDE.md-Dateien","Begrenzt auf die Bearbeitung und Validierung von CLAUDE.md-Dateien nur"],"pt":["Exige aderência à estrutura e diretrizes do arquivo CLAUDE.md","Limitado à edição e validação de arquivos CLAUDE.md apenas"],"ru":["Требует соблюдения структуры и руководящих принципов файла CLAUDE.md","Ограничен редактированием и проверкой файлов CLAUDE.md только"],"ar":["يتطلب اتباع هيكل ملف CLAUDE.md و إرشاداته","محدود بالتحرير والتحقق من صحة ملفات CLAUDE.md فقط"]},"version":4},"contentHash":"c015ee2657b6d214308a42ce938b8f0584b8f5dbb1efccc7aaec4c00cae29fbb","qualityScore":36}');
