INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dohernandez/claude-project-skills-template/claude-md', 'claude-md', 'dohernandez', 'claude-project-skills-template', 'community', 'claude-md dohernandez claude-project-skills-template community claude-md is a methodology for editing CLAUDE.md files, ensuring they remain concise and structurally sound. It benefits developers and technical writers who need to maintain high-quality documentation. claude-md是一种保持文档简洁、结构完整的方法，包括目录结构、自动生成表格和命令行工具 claude-mdは、ディレクトリ構造、自動生成テーブル、コマンドラインツールなどを含む、文書を簡潔に保つための方法 claude-md는 문서를 간결하게 유지하고 구조를 완성하는 방법으로, 디렉토리 구조, 자동 생성 테이블 및 명령줄 도구를 포함 claude-md es una metodología para editar archivos markdown de manera concisa y estructurada, incluyendo un linter para garantizar la calidad del código claude-md est une méthodologie pour éditer des fichiers markdown de manière concise et structurée, incluant un linter pour assurer la qualité du code claude-md ist eine Methode zur Bearbeitung von Markdown-Dateien in konciser und strukturierter Weise, einschließlich eines Linters zur Gewährleistung der Codequalität O CLAUDE.md é uma metodologia para edição que mantém a concisão e a estrutura. Aprenda a usá-lo com nossas dicas CLAUDE.md - это методология для редактирования, которая поддерживает краткость и структуру. Узнайте, как использовать его с нашими советами CLAUDE.md هو منهجية لتحرير تحتفظ بالconcisão والهيكل. تعلم كيفية استخدامها مع نصائحنا how to use claude-md what is claude-md claude-md alternative claude-md setup guide claude-md install claude-md vs markdown structured authoring CLAUDE.md best practices lint-claude-md.sh tutorial claude-md AI工具 文档最佳实践 目录结构优化 自动生成表格 命令行工具集成 lint-claude-md.sh 开发环境配置 Enforces a structured approach using Title, behavioral, and dirs-only structure Utilizes lint-claude-md.sh as a safety net for quantifiable rules Generates auto-gen tables for easy reference Supports commands and conventions for consistent documentation Keeps reference material organized in docs claude-md is a set of guidelines for authoring CLAUDE.md files, focusing on concise and high-signal content with a structured approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pcortellezzi/rs_trader/doc', 'community', 'pcortellezzi', 'rs_trader', 'pcortellezzi/rs_trader', 'doc', 0, 1, 36, '2026-02-21T14:45:18Z', '2026-03-07T03:43:23.885Z', '5bffb0663c887829ca7fccc99f4f2291763351dbb946fa6a3f72016d74c2e772', '{"id":"pcortellezzi/rs_trader/doc","name":"doc","description":{"en":"The doc skill generates or updates documentation pages based on current specs and codebase, benefiting developers and users alike.","zh":"文档生成器可以根据当前规格和代码库生成或更新文档，支持特定章节或全部更新","ja":"ドキュメントジェネレーターは、現在の仕様とコードベースに基づいて文書を生成または更新できます","ko":"문서 생성기는 현재의 사양과 코드베이스를 기반으로 문서를 생성하거나 업데이트할 수 있습니다","es":"El generador de documentación crea o actualiza páginas de documentación según las especificaciones actuales y el código base. Puedes generar documentación para usuarios o desarrolladores.","fr":"Le générateur de documentation crée ou met à jour les pages de documentation en fonction des spécifications actuelles et du code base. Vous pouvez générer de la documentation pour les utilisateurs ou les développeurs.","de":"Der Dokumentations-Generator erstellt oder aktualisiert Dokumentationsseiten basierend auf den aktuellen Spezifikationen und dem Codebase. Sie können Dokumentationen für Benutzer oder Entwickler generieren.","pt":"O gerador de documentação doc gera ou atualiza páginas de documentação com base nas specs e código atuais","ru":"Генератор документации doc генерирует или обновляет страницы документации на основе текущих спецификаций и кода","ar":"أداة الوثائق doc تُحدث أو تحدث صفحات الوثائق بناءً على المواصفات والكود الحاليين"},"seo":{"title":{"en":"doc: Automated Documentation Generator for AI Agents","zh":"文档生成器 Setup Guide - 通过代码库自动生成文档","ja":"ドキュメントジェネレーター Setup Guide - コードベースを使用した自動文書化","ko":"문서 생성기 Setup Guide - 코드베이스를 사용한 자동 문서화","es":"Generador de Documentación: Guía de Configuración para De...","fr":"Générateur de Documentation: Guide d''Installation pour le...","de":"Dokumentations-Generator: Einrichtungs-Anleitung für Entw...","pt":"Guia de Configuração do Gerador de Documentação doc","ru":"Инструмент ИИ Агентов: Настройка Генератора Документации doc","ar":"دليل إعداد أداة الوثائق doc"},"description":{"en":"Discover how to automate documentation with doc. Learn to regenerate user guides, developer guides, and more with this AI agent skill.","zh":"使用文档生成器自动化文档更新，支持特定章节或全部更新，提高开发效率","ja":"ドキュメントジェネレーターを使用して文書を自動更新し、開発効率を向上させる","ko":"문서 생성기를 사용하여 문서를 자동으로 업데이트하고 개발 효율성을 높여보세요","es":"Aprende a utilizar el generador de documentación para actualizar tus páginas de specs y código. Descubre cómo generar documentación para usuarios y desarroll...","fr":"Découvrez comment utiliser le générateur de documentation pour mettre à jour vos pages de specs et de code. Apprenez à générer de la documentation pour les u...","de":"Erfahren Sie, wie Sie den Dokumentations-Generator verwenden können, um Ihre Spezifikations- und Code-Seiten zu aktualisieren. Entdecken Sie, wie Sie Dokumen...","pt":"Aprenda a configurar o gerador de documentação doc para atualizar páginas de specs e código","ru":"Узнайте, как настроить генератор документации doc для обновления страниц спецификаций и кода","ar":"تعلم كيفية إعداد أداة الوثائق doc لتحديث صفحات المواصفات والكود"},"definition":{"en":"doc is a documentation generator that automates the creation of user guides, developer guides, and other documentation pages.","zh":"文档生成器是一种自动化工具，用于根据代码库生成或更新文档","ja":"ドキュメントジェネレーターは、コードベースに基づいて文書を自動生成または更新するツールです","ko":"문서 생성기는 코드베이스를 기반으로 문서를 자동으로 생성하거나 업데이트하는 툴입니다","es":"Un generador de documentación es una herramienta que crea o actualiza páginas de documentación automáticamente.","fr":"Un générateur de documentation est un outil qui crée ou met à jour des pages de documentation de manière automatique.","de":"Ein Dokumentations-Generator ist ein Werkzeug, das Dokumentationsseiten automatisch erstellt oder aktualisiert.","pt":"O que é doc? Um gerador de documentação que atualiza páginas de specs e código","ru":"Что такое doc? Генератор документации, который обновляет страницы спецификаций и кода","ar":"ما هي أداة الوثائق doc؟ أداة لإنشاء وتحديث صفحات الوثائق بناءً على المواصفات والكود"},"features":{"en":["Generates user guide pages based on current specs and codebase","Regenerates developer guide pages with updated information","Targets specific sections, such as chart-related user pages or architecture pages","Supports regeneration of all documentation pages at once using the ''all'' argument","Allows for customization of generated documentation using the ''$ARGUMENTS'' specifier"],"zh":["支持特定章节或全部更新","根据当前规格和代码库生成或更新文档","可用于用户指南和开发者指南的生成","支持特定页面的更新，例如用户/图表页面","支持全部文档的更新"],"ja":["特定セクションまたは全体の更新をサポート","現在の仕様とコードベースに基づいて文書を生成または更新","ユーザーガイドと開発者ガイドの生成に使用できます","特定のページの更新をサポート，例：ユーザー/チャートページ","全体の文書の更新をサポート"],"ko":["특정 섹션 또는 전체 업데이트를 지원","현재의 사양과 코드베이스를 기반으로 문서를 생성하거나 업데이트","사용자 가이드와 개발자 가이드의 생성에 사용할 수 있습니다","특정 페이지의 업데이트를 지원, 예: 사용자/차트 페이지","전체 문서의 업데이트를 지원"],"es":["Generación de documentación para usuarios y desarrolladores","Actualización de páginas de specs y código","Posibilidad de generar documentación para secciones específicas","Compatibilidad con argumentos como ''user'' y ''dev'' para generar documentación","Opción para regenerar toda la documentación con el argumento ''all''"],"fr":["Génération de documentation pour les utilisateurs et les développeurs","Mise à jour des pages de specs et de code","Possibilité de générer de la documentation pour des sections spécifiques","Compatibilité avec des arguments tels que ''user'' et ''dev'' pour générer de la documentation","Option pour régénérer toute la documentation avec l''argument ''all''"],"de":["Erstellung von Dokumentationen für Benutzer und Entwickler","Aktualisierung von Spezifikations- und Code-Seiten","Möglichkeit, Dokumentationen für spezifische Abschnitte zu generieren","Unterstützung von Argumenten wie ''user'' und ''dev'' zur Generierung von Dokumentationen","Option, die gesamte Dokumentation mit dem Argument ''all'' neu zu generieren"],"pt":["Gera páginas de documentação para guias de usuário e desenvolvedor","Atuliza páginas específicas ou regenera todas as páginas","Suporta argumentos para especificar o que gerar, como ''user'' ou ''dev''","Permite a regeneração de páginas relacionadas a gráficos ou ferramentas de desenho","Suporta a regeneração da página de arquitetura","Permite a regeneração de todas as páginas com o argumento ''all''"],"ru":["Генерирует страницы документации для руководств пользователя и разработчика","Обновляет отдельные страницы или регенерирует все страницы","Поддерживает аргументы для указания того, что генерировать, например ''user'' или ''dev''","Позволяет регенерировать страницы, связанные с графиками или инструментами рисования","Поддерживает регенерацию страницы архитектуры","Позволяет регенерировать все страницы с помощью аргумента ''all''"],"ar":["تُحدث صفحات الوثائق لمرشدي المستخدم والمطور","تحديث صفحات محددة أو إعادة إنشاء جميع الصفحات","تدعم الحجج لتحديد ما يُحدث، مثل ''مستخدم'' أو ''مطور''","تمكن من إعادة إنشاء صفحات متعلقة بالرسومات أو أدوات الرسم","تدعم إعادة إنشاء صفحة الهندسة المعمارية","تمكن من إعادة إنشاء جميع الصفحات باستخدام الحجة ''all''"]},"keywords":{"en":["how to use doc","doc setup guide","automated documentation generation","doc alternative","doc vs documentation tools","regenerating user guides with doc","doc install","what is doc","doc for AI agents","documentation generator for developers"],"zh":["文档生成器","自动文档更新","代码库","开发者工具","AIエージェント","文档自动化","代码生成","开发效率"],"ja":["ドキュメントジェネレーター","自動文書更新","コードベース","開発者ツール","AIエージェント","文書自動化","コード生成","開発効率"],"ko":["문서 생성기","자동 문서 업데이트","코드베이스","개발자 툴","AI 에이전트","문서 자동화","코드 생성","개발 효율성"],"es":["generador de documentación","herramientas de documentación","desarrollo de software","documentación para usuarios","documentación para desarrolladores","actualización de documentación","generación de documentación automática","documentación de código"],"fr":["générateur de documentation","outils de documentation","développement de logiciels","documentation pour les utilisateurs","documentation pour les développeurs","mise à jour de documentation","génération de documentation automatique","documentation de code"],"de":["Dokumentations-Generator","Dokumentations-Tools","Software-Entwicklung","Dokumentation für Benutzer","Dokumentation für Entwickler","Aktualisierung von Dokumentationen","automatische Dokumentations-Generierung","Code-Dokumentation"],"pt":["gerador de documentação","documentação de specs","código de documentação","guia de usuário","guia de desenvolvedor","argumentos de documentação","regeneração de páginas","documentação de arquitetura"],"ru":["генератор документации","документация спецификаций","код документации","руководство пользователя","руководство разработчика","аргументы документации","регенерация страниц","документация архитектуры"],"ar":["أداة الوثائق","وثائق المواصفات","كود الوثائق","مرشد المستخدم","مرشد المطور","حجج الوثائق","إعادة إنشاء الصفحات","وثائق الهندسة المعمارية"]}},"owner":"pcortellezzi","repo":"rs_trader","repoPath":"pcortellezzi/rs_trader","stars":0,"forks":1,"updatedAt":"2026-02-21T14:45:18Z","topics":[],"category":"community","skillMd":{"name":"doc","description":"Generate or update documentation pages from specs and code.","bodyPreview":"# Documentation Generator\n\nGenerates or updates documentation pages based on the current specs and codebase. Can target specific sections or regenerate everything.\n\n## Argument\n\n`$ARGUMENTS` specifies what to generate. Examples:\n- `user` — regenerate all user guide pages\n- `dev` — regenerate all developer guide pages\n- `user/chart` — regenerate chart-related user pages\n- `user/tools` — regenerate drawing tools pages\n- `dev/architecture` — regenerate the architecture page\n- `all` — regenerate eve","body":"# Documentation Generator\n\nGenerates or updates documentation pages based on the current specs and codebase. Can target specific sections or regenerate everything.\n\n## Argument\n\n`$ARGUMENTS` specifies what to generate. Examples:\n- `user` — regenerate all user guide pages\n- `dev` — regenerate all developer guide pages\n- `user/chart` — regenerate chart-related user pages\n- `user/tools` — regenerate drawing tools pages\n- `dev/architecture` — regenerate the architecture page\n- `all` — regenerate everything\n- (empty) — show current doc coverage status\n\n## Procedure\n\n### 1. If no argument: show doc coverage\n\nList all pages in `docs/src/SUMMARY.md` and check which files exist and which are missing or empty.\n\nReport format:\n```\n=== DOCUMENTATION COVERAGE ===\n\nUser Guide:\n  ✅ user/getting_started.md (exists, 45 lines)\n  ✅ user/chart/navigation.md (exists, 62 lines)\n  ⚠️  user/chart/multi_pane.md (empty or missing)\n\nDev Guide:\n  ✅ dev/architecture.md (exists, 180 lines)\n  ⚠️  dev/plugin_guide.md (empty or missing)\n\nCoverage: 28/35 pages present (80%)\n```\n\n### 2. If argument provided: generate pages\n\nFor each page in scope:\n\na. **Identify the spec source**: find the matching spec file(s) in `specs/`\nb. **Read the spec**: extract behaviors, states, descriptions\nc. **Read the current code**: understand what''s actually implemented\nd. **Write the doc page**:\n   - **User pages**: plain language, no code, explain what and how to use. Add `> Spec source: specs/...` at the bottom.\n   - **Dev pages**: technical language, code examples, architecture diagrams. Reference actual crate names and trait names.\ne. **Verify**: run `mdbook build docs` to check for broken links or formatting errors\n\n### 3. Update SUMMARY.md if needed\n\nIf new pages were created that aren''t in SUMMARY.md, add them in the appropriate section.\n\n### 4. Final verification\n\n```bash\nmdbook build docs\n```\n\nReport any build errors.\n\n## Rules\n\n- **User docs are for non-developers** — no Rust code, no technical jargon\n- **Dev docs are for Rust developers** — include code snippets, API references, trait names\n- **Always reference the spec source** at the bottom of user pages\n- **Language**: English only\n- **Do not invent features** — only document what exists in specs or code\n- Build must pass after changes\n"},"lastSynced":"2026-03-07T03:43:23.885Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing automated documentation generation based on current specs and codebase.","zh":"非常适合需要根据当前规格和代码库生成自动化文档的开发者代理。","ja":"現在の仕様とコードベースに基づいて自動生成されたドキュメントが必要なデベロッパーエージェントに最適です。","ko":"현재 규격 및 코드베이스를 기반으로 자동 생성 된 문서가 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan generación de documentación automatizada basada en las especificaciones actuales y la base de código.","fr":"Parfait pour les Agents de Développeur ayant besoin d''une génération de documentation automatique basée sur les spécifications actuelles et la base de code.","de":"Perfekt für Entwickler-Agenten, die eine automatisierte Generierung von Dokumentationen auf der Grundlage der aktuellen Spezifikationen und des Codebestands benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de geração automática de documentação com base nas especificações atuais e na base de código.","ru":"Идеально подходит для агентов разработчиков, которым требуется автоматизированная генерация документации на основе текущих спецификаций и кодовой базы.","ar":"مثالي لعميل المطور الذي يحتاج إلى توليد وثائق آلي بناءً على المواصفات الحالية وقاعدة الشفرة."},"recommendation":{"en":"Empowers agents to regenerate documentation pages targeting specific sections or entire codebases using specs, benefiting developers and users with updated user guides and developer guides in formats like HTML or Markdown, leveraging arguments such as ''user'' or ''dev'' to customize output.","zh":"赋予代理重新生成文档页面的能力，针对特定部分或整个代码库，使用规格来为开发者和用户提供更新的用户指南和开发者指南，格式如HTML或Markdown，利用诸如''用户''或''开发者''的参数来自定义输出。","ja":"エージェントが、特定のセクションまたはコード全体を対象とするドキュメントページの再生成を可能にし、仕様を使用して、開発者とユーザーに最新のユーザーガイドと開発者ガイドを提供することができます。HTML または Markdown のような形式で、''ユーザー'' または ''開発者'' などの引数を使用して出力をカスタマイズすることができます。","ko":"에이전트가 특정 섹션 또는 전체 코드베이스를 대상으로 하는 문서 페이지를 다시 생성할 수 있도록 하여 개발자와 사용자에게 최신 사용자 가이드와 개발자 가이드를 제공할 수 있습니다. HTML 또는 Markdown와 같은 형식으로 ''사용자'' 또는 ''개발자''와 같은 인수를 사용하여 출력을 사용자 지정할 수 있습니다.","es":"Habilita a los agentes a regenerar páginas de documentación dirigidas a secciones específicas o a toda la base de código utilizando especificaciones, lo que beneficia a los desarrolladores y a los usuarios con guías de usuario y guías de desarrollador actualizadas en formatos como HTML o Markdown, utilizando argumentos como ''usuario'' o ''desarrollador'' para personalizar la salida.","fr":"Permet aux agents de régénérer des pages de documentation ciblant des sections spécifiques ou l''ensemble de la base de code en utilisant des spécifications, ce qui profite aux développeurs et aux utilisateurs avec des guides d''utilisateur et des guides de développeur mis à jour dans des formats tels que HTML ou Markdown, en utilisant des arguments tels que ''utilisateur'' ou ''développeur'' pour personnaliser la sortie.","de":"Ermöglicht es Agenten, Dokumentationsseiten für bestimmte Abschnitte oder den gesamten Codebestand mithilfe von Spezifikationen zu regenerieren, was Entwicklern und Benutzern mit aktualisierten Benutzerhandbüchern und Entwicklerhandbüchern in Formaten wie HTML oder Markdown zugutekommt, indem Argumente wie ''Benutzer'' oder ''Entwickler'' verwendet werden, um die Ausgabe anzupassen.","pt":"Habilita os agentes a regenerar páginas de documentação visando seções específicas ou toda a base de código usando especificações, beneficiando os desenvolvedores e os usuários com guias de usuário e guias de desenvolvedor atualizados em formatos como HTML ou Markdown, utilizando argumentos como ''user'' ou ''dev'' para personalizar a saída.","ru":"Наделяет агентов возможностью регенерировать страницы документаци