GUMENTS'' specifier doc is a documentation generator that automates the creation of user guides, developer guides, and other documentation pages.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anasahmed07/doit/minikube', 'community', 'anasahmed07', 'doit', 'anasahmed07/doit', 'minikube', 0, 0, 36, '2026-03-07T01:49:01.758Z', '2026-03-07T03:05:35.691Z', 'f409094ab18876d8c9e56e445b1d8bf812d8cfd75b534451c9efaba1b6827d68', '{"id":"anasahmed07/doit/minikube","name":"minikube","description":{"en":"Minikube runs a local Kubernetes cluster for development and testing, supporting multiple container runtimes. It benefits developers and testers who need a local environment.","zh":"Minikube 是一个用于运行单节点 Kubernetes 集群的工具，支持多种容器运行时","ja":"Minikube はシングルノード Kubernetes クラスターを実行するためのツールで、複数のコンテナランタイムをサポート","ko":"Minikube는 단일 노드 Kubernetes 클러스터를 실행하는 도구로, 여러 컨테이너 런타임을 지원","es":"Minikube es una herramienta para ejecutar clústeres de Kubernetes de un solo nodo de forma local para pruebas y desarrollo","fr":"Minikube est un outil pour exécuter des clusters Kubernetes à un seul nœud en local pour les tests et le développement","de":"Minikube ist ein Tool zum Ausführen von Kubernetes-Clustern mit einem einzigen Knoten für lokale Tests und Entwicklung","pt":"O Minikube é uma ferramenta para executar clusters Kubernetes locais para desenvolvimento e teste.","ru":"Minikube - это инструмент для запуска локальных кластеров Kubernetes для разработки и тестирования.","ar":"ميني كيوب هو أداة لتشغيل مجموعات كيوبيرنتس المحلية للاستخدامات التطويرية والاختبارية"},"seo":{"title":{"en":"Minikube: Local Kubernetes Setup Guide | AI Agent Skill","zh":"Minikube 本地开发环境搭建指南","ja":"Minikube ローカル開発環境設定ガイド - AIエージェント","ko":"Minikube 로컬 개발 환경 설정하기 - AI 도구","es":"Guía de configuración de Minikube para desarrolladores","fr":"Guide de configuration de Minikube pour les développeurs","de":"Minikube-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Minikube para Desenvolvedores","ru":"ИИ Агенты: Руководство по настройке Minikube","ar":"